window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["LUK"]={"book":"LUK","editions":{"dan-1819":[[1,1,"Efterdi Mange have taget sig for at forfatte en Historie om de Ting, som vitterligen ere fuldbyrdede iblandt os,","Efterdi Mange have taget sig for at forfatte en Historie om de Ting, som vitterligen ere fuldbyrdede iblandt os,"],[1,2,"saaledes som de have overantvordet os det, som fra Begyndelsen have været Øienvidner og Ordets Tjenere:","saaledes som de have overantvordet os det, som fra Begyndelsen have været Øienvidner og Ordets Tjenere:"],[1,3,"saa haver ogsaa jeg anseet for godt, efter nøie at have udforsket Alt forfra, i Sammenhæng at skrive dig derom, ædle Theophilus!","saa haver ogsaa jeg anseet for godt, efter nøie at have udforsket Alt forfra, i Sammenhæng at skrive dig derom, ædle Theophilus!"],[1,4,"paa det du kan indsee Visheden af de Ting, hvorom du er bleven mundtligen underviist.","paa det du kan indsee Visheden af de Ting, hvorom du er bleven mundtligen underviist."],[1,5,"I Herodes’, Judæas Konges, Dage var der en Præst af Abias Skifte ved Navn Zacharias; og hans Hustru var af Arons Døttre, og hendes Navn var Elisabeth.","I Herodes’, Judæas Konges, Dage var der en Præst af Abias Skifte ved Navn Zacharias; og hans Hustru var af Arons Døttre, og hendes Navn var Elisabeth."],[1,6,"Men de vare begge retfærdige for Gud, og vandrede ustraffelige i alle Herrens Bud og Anordninger","Men de vare begge retfærdige for Gud, og vandrede ustraffelige i alle Herrens Bud og Anordninger"],[1,7,"Og de havde intet Barn; thi Elisabeth var ufrugtbar, og de vare begge bedagede.","Og de havde intet Barn; thi Elisabeth var ufrugtbar, og de vare begge bedagede."],[1,8,"Men det begav sig, der han forrettede Præsteembede i sin Skiftes Orden for Gud,","Men det begav sig, der han forrettede Præsteembede i sin Skiftes Orden for Gud,"],[1,9,"tilfaldt Røgningen ham efter Præstedommets Sædvane, og han gik ind i Herrens Tempel.","tilfaldt Røgningen ham efter Præstedommets Sædvane, og han gik ind i Herrens Tempel."],[1,10,"Og al Folkets Mangfoldighed bad udenfor under Røgningen.","Og al Folkets Mangfoldighed bad udenfor under Røgningen."],[1,11,"Men Herrens Engel aabenbaredes for ham, og stod ved den høire Side af Røgelsealteret.","Men Herrens Engel aabenbaredes for ham, og stod ved den høire Side af Røgelsealteret."],[1,12,"Og da Zacharias saae ham, forfærdedes han, og Frygt faldt paa ham.","Og da Zacharias saae ham, forfærdedes han, og Frygt faldt paa ham."],[1,13,"Men Engelen sagde til ham: frygt ikke, Zacharias! thi din Bøn er hørt, og din Hustru Elisabeth skal føde dig en Søn, og du skal kalde hans Navn Johannes.","Men Engelen sagde til ham: frygt ikke, Zacharias! thi din Bøn er hørt, og din Hustru Elisabeth skal føde dig en Søn, og du skal kalde hans Navn Johannes."],[1,14,"Og du skal have Glæde og Fryd af ham, og Mange skulle glædes over hans Fødsel.","Og du skal have Glæde og Fryd af ham, og Mange skulle glædes over hans Fødsel."],[1,15,"Thi han skal være stor for Herren: Viin og stærk Drik skal han ei drikke, og han skal fyldes med den Hellig Aand, alt fra Moders Liv,","Thi han skal være stor for Herren: Viin og stærk Drik skal han ei drikke, og han skal fyldes med den Hellig Aand, alt fra Moders Liv,"],[1,16,"og omvende mange af Israels Børn til Herren deres Gud.","og omvende mange af Israels Børn til Herren deres Gud."],[1,17,"Og han skal gaae frem for ham i Elias’ Aand og Kraft, at vende Fædrenes Hjerter til Børnene, og de Gjenstridige til de Retfærdiges Sind, at berede Herren et velskikket Folk.","Og han skal gaae frem for ham i Elias’ Aand og Kraft, at vende Fædrenes Hjerter til Børnene, og de Gjenstridige til de Retfærdiges Sind, at berede Herren et velskikket Folk."],[1,18,"Og Zacharias sagde til Engelen: hvorpaa skal jeg kjende dette? thi jeg er gammel, og min Hustru er bedaget.","Og Zacharias sagde til Engelen: hvorpaa skal jeg kjende dette? thi jeg er gammel, og min Hustru er bedaget."],[1,19,"Og Engelen svarede og sagde til ham: jeg er Gabriel, som staaer for Gud, og jeg er udsendt, at tale til dig og at forkynde dig dette til Glæde.","Og Engelen svarede og sagde til ham: jeg er Gabriel, som staaer for Gud, og jeg er udsendt, at tale til dig og at forkynde dig dette til Glæde."],[1,20,"Og see, du skal vorde stum og ikke kunne tale indtil den Dag, da dette skeer, fordi du ikke troede mine Ord, hvilke skulle fuldkommes i deres Tid.","Og see, du skal vorde stum og ikke kunne tale indtil den Dag, da dette skeer, fordi du ikke troede mine Ord, hvilke skulle fuldkommes i deres Tid."],[1,21,"Og Folket biede efter Zacharias, og de forundrede sig, at han tøvede i Templet.","Og Folket biede efter Zacharias, og de forundrede sig, at han tøvede i Templet."],[1,22,"Og der han gik ud, kunde han ikke tale til dem, og de mærkede, at han havde seet et Syn i Templet; og han nikkede ad dem, og forblev stum.","Og der han gik ud, kunde han ikke tale til dem, og de mærkede, at han havde seet et Syn i Templet; og han nikkede ad dem, og forblev stum."],[1,23,"Og det begav sig, der hans Tjenestes Dage vare fuldendte, gik han hjem til sit Huus.","Og det begav sig, der hans Tjenestes Dage vare fuldendte, gik han hjem til sit Huus."],[1,24,"Men efter de Dage blev hans Hustru Elisabeth frugtsommelig, og skjulte sig fem Maaneder, og sagde:","Men efter de Dage blev hans Hustru Elisabeth frugtsommelig, og skjulte sig fem Maaneder, og sagde:"],[1,25,"saaledes haver Herren gjort imod mig i de Dage, da han saae til mig, for at borttage min Forsmædelse iblandt Menneskene.","saaledes haver Herren gjort imod mig i de Dage, da han saae til mig, for at borttage min Forsmædelse iblandt Menneskene."],[1,26,"Men i den sjette Maaned blev Engelen Gabriel sendt af Gud til en Stad i Galilæa, som hedder Nazareth,","Men i den sjette Maaned blev Engelen Gabriel sendt af Gud til en Stad i Galilæa, som hedder Nazareth,"],[1,27,"til en Jomfru, som var trolovet en Mand ved Navn Joseph, af Davids Huus; og Jomfruen hedte Maria.","til en Jomfru, som var trolovet en Mand ved Navn Joseph, af Davids Huus; og Jomfruen hedte Maria."],[1,28,"Og Engelen kom ind til hende og sagde: hil være dig, du Benaadede! Herren er med dig, du Velsignede iblandt Kvinderne!","Og Engelen kom ind til hende og sagde: hil være dig, du Benaadede! Herren er med dig, du Velsignede iblandt Kvinderne!"],[1,29,"Men der hun saae ham, forfærdedes hun over hans Tale, og hun tænkte, hvad denne skulle være for en Hilsen.","Men der hun saae ham, forfærdedes hun over hans Tale, og hun tænkte, hvad denne skulle være for en Hilsen."],[1,30,"Og Engelen sagde til hende: frygt ikke, Maria! thi du haver fundet Naade hos Gud.","Og Engelen sagde til hende: frygt ikke, Maria! thi du haver fundet Naade hos Gud."],[1,31,"Og see, du skal undfange og føde en Søn, og du skal kalde hans Navn Jesus.","Og see, du skal undfange og føde en Søn, og du skal kalde hans Navn Jesus."],[1,32,"Han skal blive stor, og kaldes den Høiestes Søn; og Gud Herren skal give ham Davids, hans Faders, Throne.","Han skal blive stor, og kaldes den Høiestes Søn; og Gud Herren skal give ham Davids, hans Faders, Throne."],[1,33,"Og han skal være Konge over Jakobs Huus evindelig, og der skal ikke være Ende paa hans Kongerige.","Og han skal være Konge over Jakobs Huus evindelig, og der skal ikke være Ende paa hans Kongerige."],[1,34,"Men Maria sagde til Engelen: hvorledes skal dette gaae til, efterdi jeg veed af ingen Mand?","Men Maria sagde til Engelen: hvorledes skal dette gaae til, efterdi jeg veed af ingen Mand?"],[1,35,"Og Engelen svarede og sagde til hende: den Hellig Aand skal komme over dig, og den Høiestes Kraft skal overskygge dig; derfor skal ogsaa det Hellige, som skal fødes af dig, kaldes Guds Søn.","Og Engelen svarede og sagde til hende: den Hellig Aand skal komme over dig, og den Høiestes Kraft skal overskygge dig; derfor skal ogsaa det Hellige, som skal fødes af dig, kaldes Guds Søn."],[1,36,"Og see, Elisabeth din Frænke, hun haver og undfanget en Søn i hendes Alderdom, og denne Maaned er den sjette for hende, som kaldes ufrugtbar.","Og see, Elisabeth din Frænke, hun haver og undfanget en Søn i hendes Alderdom, og denne Maaned er den sjette for hende, som kaldes ufrugtbar."],[1,37,"Thi Intet kan være umuligt for Gud.","Thi Intet kan være umuligt for Gud."],[1,38,"Men Maria sagde: see, jeg er Herrens Tjenerinde, mig skee efter dit Ord! Og Engelen skiltes fra hende.","Men Maria sagde: see, jeg er Herrens Tjenerinde, mig skee efter dit Ord! Og Engelen skiltes fra hende."],[1,39,"Men Maria stod op i de samme Dage, og drog hastelig hen til Bjergegnen, til en Stad i Juda.","Men Maria stod op i de samme Dage, og drog hastelig hen til Bjergegnen, til en Stad i Juda."],[1,40,"Og hun kom ind i Zacharias’ Huus og hilsede Elisabeth.","Og hun kom ind i Zacharias’ Huus og hilsede Elisabeth."],[1,41,"Og det begav sig, der Elisabeth hørte Marias Hilsen, sprang Fosteret i hendes Liv; og Elisabeth blev fyldt med den Hellig Aand,","Og det begav sig, der Elisabeth hørte Marias Hilsen, sprang Fosteret i hendes Liv; og Elisabeth blev fyldt med den Hellig Aand,"],[1,42,"og raabte med stor Røst og sagde: velsignet er du iblandt Kvinderne! og velsignet er dit Livs Frugt.","og raabte med stor Røst og sagde: velsignet er du iblandt Kvinderne! og velsignet er dit Livs Frugt."],[1,43,"Og hveden hændes mig dette, at min Herres Moder kommer til mig?","Og hveden hændes mig dette, at min Herres Moder kommer til mig?"],[1,44,"Thi see, der din Hilsens Røst kom mig til Øren, sprang Fosteret i mit Liv med Fryd.","Thi see, der din Hilsens Røst kom mig til Øren, sprang Fosteret i mit Liv med Fryd."],[1,45,"Og salig er hun, som troede; thi det skal fuldkommes, som hende er sagt af Herren.","Og salig er hun, som troede; thi det skal fuldkommes, som hende er sagt af Herren."],[1,46,"Og Maria sagde: min Sjæl ophøier Herren;","Og Maria sagde: min Sjæl ophøier Herren;"],[1,47,"og min Aand fryder sig i Gud, min Frelser;","og min Aand fryder sig i Gud, min Frelser;"],[1,48,"thi han haver seet til sin Tjenerindes Ringhed. Thi see, nu herefter skulle alle Slægter prise mig salig;","thi han haver seet til sin Tjenerindes Ringhed. Thi see, nu herefter skulle alle Slægter prise mig salig;"],[1,49,"thi han, den Mægtige, haver gjort store Ting imod mig, og hans Navn er helligt;","thi han, den Mægtige, haver gjort store Ting imod mig, og hans Navn er helligt;"],[1,50,"og hans Barmhjertighed varer fra Slægt til Slægt over dem, som frygte ham.","og hans Barmhjertighed varer fra Slægt til Slægt over dem, som frygte ham."],[1,51,"Han haver øvet Magt med sin Arm; han haver adspredt dem, som ere hovmodige i deres Hjertes Tanke.","Han haver øvet Magt med sin Arm; han haver adspredt dem, som ere hovmodige i deres Hjertes Tanke."],[1,52,"Han haver nedstødt de Mægtige af Thronerne, og ophøiet de Ringe.","Han haver nedstødt de Mægtige af Thronerne, og ophøiet de Ringe."],[1,53,"De Hungrige haver han opfyldt med gode Gaver, og de Rige haver han afviist tomme.","De Hungrige haver han opfyldt med gode Gaver, og de Rige haver han afviist tomme."],[1,54,"Han haver antaget sig sin Tjener Israel, og ihukommet sin Barmhjertighed,","Han haver antaget sig sin Tjener Israel, og ihukommet sin Barmhjertighed,"],[1,55,"(som han tilsagde vore Fædre), mod Abraham og hans Sæd til evig Tid.","(som han tilsagde vore Fædre), mod Abraham og hans Sæd til evig Tid."],[1,56,"Men Maria blev hos hende ved tre Maaneder, og hun drog til sit Huus igjen.","Men Maria blev hos hende ved tre Maaneder, og hun drog til sit Huus igjen."],[1,57,"Men Elisabeths Tid fuldkommedes, at hun skulde føde, og hun fødte en Søn.","Men Elisabeths Tid fuldkommedes, at hun skulde føde, og hun fødte en Søn."],[1,58,"Og hendes Naboer og Slægtninge hørte, at Herren havde gjort sin Barmhjertighed stor imod hende, og de glædte sig med hende.","Og hendes Naboer og Slægtninge hørte, at Herren havde gjort sin Barmhjertighed stor imod hende, og de glædte sig med hende."],[1,59,"Og det begav sig paa den ottende Dag, da kom de at omskære Barnet; og de kaldte det efter Faderens Navn Zacharias.","Og det begav sig paa den ottende Dag, da kom de at omskære Barnet; og de kaldte det efter Faderens Navn Zacharias."],[1,60,"Men hans Moder svarede og sagde: ingenlunde, men han skal kaldes Johannes.","Men hans Moder svarede og sagde: ingenlunde, men han skal kaldes Johannes."],[1,61,"Og de sagde til hende: der er dog Ingen i din Slægt, som kaldes med dette Navn.","Og de sagde til hende: der er dog Ingen i din Slægt, som kaldes med dette Navn."],[1,62,"Men de nikkede ad hans Fader, hvad han vilde, han skulde kaldes.","Men de nikkede ad hans Fader, hvad han vilde, han skulde kaldes."],[1,63,"Og han begjerede en Tavle, og skrev disse Ord, og sagde: Johannes er hans Navn. Og de forundrede sig alle.","Og han begjerede en Tavle, og skrev disse Ord, og sagde: Johannes er hans Navn. Og de forundrede sig alle."],[1,64,"Men strax oplodes hans Mund og hans Tunge, og han talede og prisede Gud.","Men strax oplodes hans Mund og hans Tunge, og han talede og prisede Gud."],[1,65,"Og der kom en Frygt over Alle, som boede omkring dem, og alt dette rygtedes over hele Judæas Bjergegn.","Og der kom en Frygt over Alle, som boede omkring dem, og alt dette rygtedes over hele Judæas Bjergegn."],[1,66,"Og Alle, som det hørte, lagde det paa deres Hjerte og sagde: hvad monne der skal blive af dette Barn? Og Herrens Haand var med ham.","Og Alle, som det hørte, lagde det paa deres Hjerte og sagde: hvad monne der skal blive af dette Barn? Og Herrens Haand var med ham."],[1,67,"Og Zacharias, hans Fader, blev fyldt med den Hellig Aand, og han spaaede og sagde:","Og Zacharias, hans Fader, blev fyldt med den Hellig Aand, og han spaaede og sagde:"],[1,68,"Lovet være Herren, Israels Gud! at han haver besøgt og forløst sit Folk,","Lovet være Herren, Israels Gud! at han haver besøgt og forløst sit Folk,"],[1,69,"og haver opreist os et Frelses Horn i Davids sin Tjeners Huus,","og haver opreist os et Frelses Horn i Davids sin Tjeners Huus,"],[1,70,"som han talede ved sine hellige Propheters Mund fra fordums Tid;","som han talede ved sine hellige Propheters Mund fra fordums Tid;"],[1,71,"en Frelse fra vore Fjender og fra alle deres Haand, som os hade;","en Frelse fra vore Fjender og fra alle deres Haand, som os hade;"],[1,72,"at gjøre Barmhjertighed mod vore Fædre, og tænke paa sin hellige Pagt,","at gjøre Barmhjertighed mod vore Fædre, og tænke paa sin hellige Pagt,"],[1,73,"efter den Ed, som han svoer vor Fader Abraham, at han vilde give os,","efter den Ed, som han svoer vor Fader Abraham, at han vilde give os,"],[1,74,"at vi friede fra vore Fjenders Haand, skulde tjene ham uden Frygt,","at vi friede fra vore Fjenders Haand, skulde tjene ham uden Frygt,"],[1,75,"i Hellighed og Retfærdighed for ham, alle vort Livs Dage.","i Hellighed og Retfærdighed for ham, alle vort Livs Dage."],[1,76,"Og du, Barnlille! skal kaldes den Høiestes Prophet; thi du skal gaae frem for Herrens Aasyn, at berede hans Veie,","Og du, Barnlille! skal kaldes den Høiestes Prophet; thi du skal gaae frem for Herrens Aasyn, at berede hans Veie,"],[1,77,"at give hans Folk Kundskab om Saliggjørelse ved deres Synders Forladelse,","at give hans Folk Kundskab om Saliggjørelse ved deres Synders Forladelse,"],[1,78,"formedelst vor Guds inderlige Barmhjertighed, ved hvilken Lyset fra det Høie haver besøgt os,","formedelst vor Guds inderlige Barmhjertighed, ved hvilken Lyset fra det Høie haver besøgt os,"],[1,79,"for at skinne for dem, som sidde i Mørke og i Dødens Skygge, at styre vore Fødder paa Fredens Vei.","for at skinne for dem, som sidde i Mørke og i Dødens Skygge, at styre vore Fødder paa Fredens Vei."],[1,80,"Men Barnet voxte og blev styrket i Aanden, og var udi Ørkenerne indtil den Dag, han fremstillede sig for Israel.","Men Barnet voxte og blev styrket i Aanden, og var udi Ørkenerne indtil den Dag, han fremstillede sig for Israel."],[2,1,"Men det begav sig i de Dage, at en Befaling udgik fra Keiser Augustus, at al Verden skulde skrives i Mandtal.","Men det begav sig i de Dage, at en Befaling udgik fra Keiser Augustus, at al Verden skulde skrives i Mandtal."],[2,2,"(Denne første Indskrivning skete, der Qvirinius var Landsherre i Syrien).","(Denne første Indskrivning skete, der Qvirinius var Landsherre i Syrien)."],[2,3,"Og Alle gik at lade sig indskrive, hver til sin Stad.","Og Alle gik at lade sig indskrive, hver til sin Stad."],[2,4,"Men Joseph gik ogsaa op fra Galilæa, fra den Stad Nazareth, til Judæa til Davids Stad, som kaldes Bethlehem, (fordi han var af Davids Huus og Slægt),","Men Joseph gik ogsaa op fra Galilæa, fra den Stad Nazareth, til Judæa til Davids Stad, som kaldes Bethlehem, (fordi han var af Davids Huus og Slægt),"],[2,5,"at lade sig indskrive tilligemed Maria, sin trolovede Hustru, som var frugtsommelig.","at lade sig indskrive tilligemed Maria, sin trolovede Hustru, som var frugtsommelig."],[2,6,"Men det skete, der de vare der, blev Tiden fuldkommet, at hun skulde føde.","Men det skete, der de vare der, blev Tiden fuldkommet, at hun skulde føde."],[2,7,"Og hun fødte sin Søn, den førstefødte, og svøbte ham, og lagde ham i en Krybbe; thi de havde ikke Rum i Herberget.","Og hun fødte sin Søn, den førstefødte, og svøbte ham, og lagde ham i en Krybbe; thi de havde ikke Rum i Herberget."],[2,8,"Og der vare Hyrder i den samme Egn, som laae ude paa Marken, og holdt Nattevagt over deres Hjord.","Og der vare Hyrder i den samme Egn, som laae ude paa Marken, og holdt Nattevagt over deres Hjord."],[2,9,"Og see, Herrens Engel stod for dem, og Herrens Klarhed skinnede om dem, og de frygtede saare.","Og see, Herrens Engel stod for dem, og Herrens Klarhed skinnede om dem, og de frygtede saare."],[2,10,"Og Engelen sagde til dem: frygter ikke; thi see, jeg forkynder Eder en stor Glæde, som skal vederfares alt Folket.","Og Engelen sagde til dem: frygter ikke; thi see, jeg forkynder Eder en stor Glæde, som skal vederfares alt Folket."],[2,11,"Thi Eder er i Dag en Frelser født, som er den Herre Christus i Davids Stad.","Thi Eder er i Dag en Frelser født, som er den Herre Christus i Davids Stad."],[2,12,"Og det skal være Eder et Tegn: I skulle finde et Barn svøbt, liggende i en Krybbe.","Og det skal være Eder et Tegn: I skulle finde et Barn svøbt, liggende i en Krybbe."],[2,13,"Og strax var med Engelen en himmelsk Hærskares Mangfoldighed, som lovede Gud, og sagde:","Og strax var med Engelen en himmelsk Hærskares Mangfoldighed, som lovede Gud, og sagde:"],[2,14,"Ære være Gud i det Høieste! og Fred paa Jorden! og i Mennesker en Velbehagelighed!","Ære være Gud i det Høieste! og Fred paa Jorden! og i Mennesker en Velbehagelighed!"],[2,15,"Og det skete, der Englene fore fra dem til Himmelen, da sagde disse Mennesker, Hyrderne, til hverandre: lader os dog gaae til Bethlehem, og see det, som Herren haver kundgjort os.","Og det skete, der Englene fore fra dem til Himmelen, da sagde disse Mennesker, Hyrderne, til hverandre: lader os dog gaae til Bethlehem, og see det, som Herren haver kundgjort os."],[2,16,"Og de kom hastelig, og fandt baade Maria og Joseph, og Barnet liggende i Krybben.","Og de kom hastelig, og fandt baade Maria og Joseph, og Barnet liggende i Krybben."],[2,17,"Men der de havde seet det, kundgjorde de, hvad der var talet til dem om dette Barn.","Men der de havde seet det, kundgjorde de, hvad der var talet til dem om dette Barn."],[2,18,"Og Alle, som det hørte, forundrede sig over det, som Hyrderne sagde til dem.","Og Alle, som det hørte, forundrede sig over det, som Hyrderne sagde til dem."],[2,19,"Men Maria bevarede alle disse Ord, og overveiede dem i sit Hjerte.","Men Maria bevarede alle disse Ord, og overveiede dem i sit Hjerte."],[2,20,"Og Hyrderne vendte tilbage, prisede og lovede Gud for alt det, som de havde hørt og seet, efter hvad der var sagt til dem.","Og Hyrderne vendte tilbage, prisede og lovede Gud for alt det, som de havde hørt og seet, efter hvad der var sagt til dem."],[2,21,"Og der otte Dage vare fuldkommede, at Barnet skulde omskæres, da blev hans Navn kaldet Jesus, som det var kaldet af Engelen, før han blev undfangen i Moders Liv.","Og der otte Dage vare fuldkommede, at Barnet skulde omskæres, da blev hans Navn kaldet Jesus, som det var kaldet af Engelen, før han blev undfangen i Moders Liv."],[2,22,"Og der hendes Renselsesdage efter Mose Lov vare fuldkommede, førte de ham op til Jerusalem, at fremstille ham for Herren,","Og der hendes Renselsesdage efter Mose Lov vare fuldkommede, førte de ham op til Jerusalem, at fremstille ham for Herren,"],[2,23,"(som der er skrevet i Herrens Lov, at alt Mandskjøn, som aabner Moders Liv, skal kaldes Herren helligt),","(som der er skrevet i Herrens Lov, at alt Mandskjøn, som aabner Moders Liv, skal kaldes Herren helligt),"],[2,24,"og at bringe Offer efter det, som sagt er i Herrens Lov, et Par Turtelduer eller to unge Duer.","og at bringe Offer efter det, som sagt er i Herrens Lov, et Par Turtelduer eller to unge Duer."],[2,25,"Og see, der var en Mand i Jerusalem, som hedte Simeon, og denne Mand var retfærdig og gudfrygtig, han ventede Israels Trøst, og den Hellig Aand var over ham.","Og see, der var en Mand i Jerusalem, som hedte Simeon, og denne Mand var retfærdig og gudfrygtig, han ventede Israels Trøst, og den Hellig Aand var over ham."],[2,26,"Og det var ham aabenbaret af den Hellig Aand, at han ikke skulde see Døden, førend han havde seet Herrens Salvede.","Og det var ham aabenbaret af den Hellig Aand, at han ikke skulde see Døden, førend han havde seet Herrens Salvede."],[2,27,"Og han kom i Templet af Aandens Drift; og der Forældrene bragte Barnet Jesus ind, at gjøre for ham, hvad der var Skik efter Loven,","Og han kom i Templet af Aandens Drift; og der Forældrene bragte Barnet Jesus ind, at gjøre for ham, hvad der var Skik efter Loven,"],[2,28,"da tog han ham paa sine Arme, og prisede Gud og sagde:","da tog han ham paa sine Arme, og prisede Gud og sagde:"],[2,29,"Herre! nu lader du din Tjener fare i Fred, ligesom du haver sagt.","Herre! nu lader du din Tjener fare i Fred, ligesom du haver sagt."],[2,30,"Thi mine Øine have seet din Frelse,","Thi mine Øine have seet din Frelse,"],[2,31,"hvilken du beredte for alle Folks Aasyn,","hvilken du beredte for alle Folks Aasyn,"],[2,32,"et Lys til at oplyse Hedningerne, og en Herlighed for sit Folk Israel.","et Lys til at oplyse Hedningerne, og en Herlighed for sit Folk Israel."],[2,33,"Og Joseph og hans Moder forundrede sig over de Ting, som bleve sagte om ham.","Og Joseph og hans Moder forundrede sig over de Ting, som bleve sagte om ham."],[2,34,"Og Simeon velsignede dem, og sagde til hans Moder Maria: see, denne er sat Mange i Israel til Fald og Opreisning, og til et Tegn, som imodsiges,","Og Simeon velsignede dem, og sagde til hans Moder Maria: see, denne er sat Mange i Israel til Fald og Opreisning, og til et Tegn, som imodsiges,"],[2,35,"(ogsaa din egen Sjæl skal et Sværd gjennemtrænge!) at mange Hjerters Tanker skulle aabenbares.","(ogsaa din egen Sjæl skal et Sværd gjennemtrænge!) at mange Hjerters Tanker skulle aabenbares."],[2,36,"Og der var en Prophetinde Anna, Phanuels Datter, af Asers Stamme; hun var meget bedaget, og havde levet syv Aar med sin Mand efter sin Jomfrustand,","Og der var en Prophetinde Anna, Phanuels Datter, af Asers Stamme; hun var meget bedaget, og havde levet syv Aar med sin Mand efter sin Jomfrustand,"],[2,37,"og var nu en Enke ved fire og fiirsindstyve Aar, som ikke veg fra Templet, tjenende Gud med Fasten og Beden Nat og Dag.","og var nu en Enke ved fire og fiirsindstyve Aar, som ikke veg fra Templet, tjenende Gud med Fasten og Beden Nat og Dag."],[2,38,"Og hun traadte til i den samme Stund, og iligemaade prisede Herren, og talede om ham til Alle, som forventede Forløsning i Jerusalem.","Og hun traadte til i den samme Stund, og iligemaade prisede Herren, og talede om ham til Alle, som forventede Forløsning i Jerusalem."],[2,39,"Og der de havde fuldkommet alle Ting efter Herrens Lov, droge de til Galilæa igjen, til deres Stad Nazareth.","Og der de havde fuldkommet alle Ting efter Herrens Lov, droge de til Galilæa igjen, til deres Stad Nazareth."],[2,40,"Men Barnet voxte og blev stærk i Aanden, fuld med Viisdom; og Guds Naade var over ham.","Men Barnet voxte og blev stærk i Aanden, fuld med Viisdom; og Guds Naade var over ham."],[2,41,"Og hans Forældre gik hvert Aar til Jerusalem, paa Paaskehøitiden.","Og hans Forældre gik hvert Aar til Jerusalem, paa Paaskehøitiden."],[2,42,"Og der han var tolv Aar gammel, gik de op til Jerusalem efter Høitidens Sædvane.","Og der han var tolv Aar gammel, gik de op til Jerusalem efter Høitidens Sædvane."],[2,43,"Og der de havde tilendebragt de Dage, og de droge hjem igjen, blev Barnet Jesus i Jerusalem, og Joseph og hans Moder vidste det ikke.","Og der de havde tilendebragt de Dage, og de droge hjem igjen, blev Barnet Jesus i Jerusalem, og Joseph og hans Moder vidste det ikke."],[2,44,"Men da de meente, at han var i Reiseselskabet, kom de en Dags Reise frem, og de ledte efter ham iblandt Slægtninge og Kyndige.","Men da de meente, at han var i Reiseselskabet, kom de en Dags Reise frem, og de ledte efter ham iblandt Slægtninge og Kyndige."],[2,45,"Og der de ikke fandt ham, gik de tilbage til Jerusalem og ledte efter ham.","Og der de ikke fandt ham, gik de tilbage til Jerusalem og ledte efter ham."],[2,46,"Og det begav sig efter tre Dage, da fandt de ham i Templet, siddende midt iblandt Lærerne, hvor han baade hørte dem og adspurgte dem.","Og det begav sig efter tre Dage, da fandt de ham i Templet, siddende midt iblandt Lærerne, hvor han baade hørte dem og adspurgte dem."],[2,47,"Men Alle, som hørte ham, forundrede sig saare over hans Forstand og Svar.","Men Alle, som hørte ham, forundrede sig saare over hans Forstand og Svar."],[2,48,"Og der de saae ham, bleve de forfærdede; og hans Moder sagde til ham: Søn! hvi gjorde du os dette? See, din Fader og jeg ledte efter dig med Smerte.","Og der de saae ham, bleve de forfærdede; og hans Moder sagde til ham: Søn! hvi gjorde du os dette? See, din Fader og jeg ledte efter dig med Smerte."],[2,49,"Og han sagde til dem: hvi ledte I efter mig? vidste I ikke, at mig bør at være i min Faders Gjerning?","Og han sagde til dem: hvi ledte I efter mig? vidste I ikke, at mig bør at være i min Faders Gjerning?"],[2,50,"Og de forstode ikke det Ord, som han talede til dem.","Og de forstode ikke det Ord, som han talede til dem."],[2,51,"Og han drog ned med dem, og kom til Nazareth, og var dem underdanig. Og hans Moder bevarede alle disse Ord i sit Hjerte.","Og han drog ned med dem, og kom til Nazareth, og var dem underdanig. Og hans Moder bevarede alle disse Ord i sit Hjerte."],[2,52,"Og Jesus forfremmedes i Viisdom og Alder og Naade hos Gud og Menneskene.","Og Jesus forfremmedes i Viisdom og Alder og Naade hos Gud og Menneskene."],[3,1,"Men i Keiser Tiberius’ femtende Regjeringsaar, der Pontius Pilatus var Landshøvding i Judæa, og Herodes var Fjerdingsfyrste i Galilæa, men hans Broder Philippus var Fjerdingsfyrste i Ituræa og Trachonitis’ Land, og Lysanias Fjerdingsfyrste i Abilene;","Men i Keiser Tiberius’ femtende Regjeringsaar, der Pontius Pilatus var Landshøvding i Judæa, og Herodes var Fjerdingsfyrste i Galilæa, men hans Broder Philippus var Fjerdingsfyrste i Ituræa og Trachonitis’ Land, og Lysanias Fjerdingsfyrste i Abilene;"],[3,2,"der Annas og Caiphas vare Ypperstepræster: skete Guds Ord til Johannes, Zacharias’ Søn, i Ørken.","der Annas og Caiphas vare Ypperstepræster: skete Guds Ord til Johannes, Zacharias’ Søn, i Ørken."],[3,3,"Og han kom i den hele Egn omkring Jordan og prædikede Omvendelses Daab til Syndernes Forladelse,","Og han kom i den hele Egn omkring Jordan og prædikede Omvendelses Daab til Syndernes Forladelse,"],[3,4,"som skrevet er i Esaias den Prophets Talers Bog, hvor han siger: det er hans Røst, som raaber i Ørken: bereder Herrens Vei, gjører hans Stier jævne;","som skrevet er i Esaias den Prophets Talers Bog, hvor han siger: det er hans Røst, som raaber i Ørken: bereder Herrens Vei, gjører hans Stier jævne;"],[3,5,"hver Dal skal opfyldes, og hvert Bjerg og Høi skal nedtrykkes, og det Krumme skal gjøres lige, og de ujævne Veie skulle slettes;","hver Dal skal opfyldes, og hvert Bjerg og Høi skal nedtrykkes, og det Krumme skal gjøres lige, og de ujævne Veie skulle slettes;"],[3,6,"og alt Kjød skal see Guds Frelse.","og alt Kjød skal see Guds Frelse."],[3,7,"Derfor sagde han til Folket, som gik ud at døbes af ham: I Øgleunger! hvo viste Eder, at flye fra den tilkommende Vrede?","Derfor sagde han til Folket, som gik ud at døbes af ham: I Øgleunger! hvo viste Eder, at flye fra den tilkommende Vrede?"],[3,8,"Bærer da Omvendelsens værdige Frugter, og begynder ikke at sige ved Eder selv: vi have Abraham til Fader; thi jeg siger Eder, at Gud kan opvække Abraham Børn af disse Stene.","Bærer da Omvendelsens værdige Frugter, og begynder ikke at sige ved Eder selv: vi have Abraham til Fader; thi jeg siger Eder, at Gud kan opvække Abraham Børn af disse Stene."],[3,9,"Men Øxen ligger allerede ved Roden af Træerne; derfor skal hvert Træ, som ikke bærer god Frugt, afhugges og kastes i Ilden.","Men Øxen ligger allerede ved Roden af Træerne; derfor skal hvert Træ, som ikke bærer god Frugt, afhugges og kastes i Ilden."],[3,10,"Og Folket adspurgte ham sigende: hvad skulle vi da gjøre?","Og Folket adspurgte ham sigende: hvad skulle vi da gjøre?"],[3,11,"Men han svarede og sagde til dem: hvo som haver to Kjortler, dele med den, som ingen haver; og hvo som haver Mad, gjøre ligesaa.","Men han svarede og sagde til dem: hvo som haver to Kjortler, dele med den, som ingen haver; og hvo som haver Mad, gjøre ligesaa."],[3,12,"Ogsaa Toldere kom at døbes, og de sagde til ham: Mester! hvad skulle vi gjøre?","Ogsaa Toldere kom at døbes, og de sagde til ham: Mester! hvad skulle vi gjøre?"],[3,13,"Men han sagde til dem: kræver intet mere, end Eder er forordnet.","Men han sagde til dem: kræver intet mere, end Eder er forordnet."],[3,14,"Men og Stridsmændene spurgte ham og sagde: hvad skulle da vi gjøre? og han sagde til dem: gjører ikke Vold, bruger ikke Underfundighed; og lader Eder nøie med Eders Sold.","Men og Stridsmændene spurgte ham og sagde: hvad skulle da vi gjøre? og han sagde til dem: gjører ikke Vold, bruger ikke Underfundighed; og lader Eder nøie med Eders Sold."],[3,15,"Men da Folket var i Forventning, og Alle tænkte i deres Hjerter om Johannes, om han ikke skulde være den Christus,","Men da Folket var i Forventning, og Alle tænkte i deres Hjerter om Johannes, om han ikke skulde være den Christus,"],[3,16,"da svarede Johannes og sagde til Alle: jeg døber Eder vel med Vand, men den kommer, som er stærkere end jeg, hvis Skotvinge jeg ikke er værdig at løse; han skal døbe Eder med den Hellig Aand og Ild.","da svarede Johannes og sagde til Alle: jeg døber Eder vel med Vand, men den kommer, som er stærkere end jeg, hvis Skotvinge jeg ikke er værdig at løse; han skal døbe Eder med den Hellig Aand og Ild."],[3,17,"Hans Kasteskovl er i hans Haand, og han skal gjennemrense sin Lo og kaste Hveden i sin Lade, men Avnerne skal han opbrænde med uslukkelig Ild.","Hans Kasteskovl er i hans Haand, og han skal gjennemrense sin Lo og kaste Hveden i sin Lade, men Avnerne skal han opbrænde med uslukkelig Ild."],[3,18,"Ogsaa meget Andet lærte og forkyndte han Folket.","Ogsaa meget Andet lærte og forkyndte han Folket."],[3,19,"Men der Fjerdingsfyrsten Herodes blev straffet af ham for Herodias’, hans Broder Philippus’ Hustrues Skyld, og for alt det Onde, som Herodes gjorde,","Men der Fjerdingsfyrsten Herodes blev straffet af ham for Herodias’, hans Broder Philippus’ Hustrues Skyld, og for alt det Onde, som Herodes gjorde,"],[3,20,"saa lagde han til alt det Øvrige ogsaa dette, at han kastede Johannes i Fængsel.","saa lagde han til alt det Øvrige ogsaa dette, at han kastede Johannes i Fængsel."],[3,21,"Men de begav sig, der alt Folket lod sig døbe, og Jesus ogsaa blev døbt og bad, at Himmelen aabnedes,","Men de begav sig, der alt Folket lod sig døbe, og Jesus ogsaa blev døbt og bad, at Himmelen aabnedes,"],[3,22,"og at den Hellig Aand foer ned i legemlig Skikkelse, som en Due, over ham, og at en Røst skete fra Himmelen, som sagde: du er min Søn, den Elskelige, i dig haver jeg Behagelighed.","og at den Hellig Aand foer ned i legemlig Skikkelse, som en Due, over ham, og at en Røst skete fra Himmelen, som sagde: du er min Søn, den Elskelige, i dig haver jeg Behagelighed."],[3,23,"Og Jesus var ved tredive Aar, der han begyndte, og var, som man holdt for, en Søn af Joseph, Elis Søn,","Og Jesus var ved tredive Aar, der han begyndte, og var, som man holdt for, en Søn af Joseph, Elis Søn,"],[3,24,"Matthats Søn, Levis Søn, Melchis Søn, Jannas Søn, Josephs Søn,","Matthats Søn, Levis Søn, Melchis Søn, Jannas Søn, Josephs Søn,"],[3,25,"Mattathias’ Søn, Amos’ Søn, Naums Søn, Eslis Søn, Naggais Søn,","Mattathias’ Søn, Amos’ Søn, Naums Søn, Eslis Søn, Naggais Søn,"],[3,26,"Maaths Søn, Mattathias’ Søn, Semeis Søn, Josephs Søn, Judas Søn,","Maaths Søn, Mattathias’ Søn, Semeis Søn, Josephs Søn, Judas Søn,"],[3,27,"Johannas’ Søn, Refas Søn, Zorobabels Søn, Salathiels Søn, Neris Søn,","Johannas’ Søn, Refas Søn, Zorobabels Søn, Salathiels Søn, Neris Søn,"],[3,28,"Melchis Søn, Addis Søn, Kosams Søn, Elmodams Søn, Ers Søn,","Melchis Søn, Addis Søn, Kosams Søn, Elmodams Søn, Ers Søn,"],[3,29,"Joses’ Søn, Eliesers Søn, Jorims Søn, Matthats Søn, Levis Søn,","Joses’ Søn, Eliesers Søn, Jorims Søn, Matthats Søn, Levis Søn,"],[3,30,"Simeons Søn, Judas Søn, Josephs Søn, Jonans Søn, Eliakims Søn,","Simeons Søn, Judas Søn, Josephs Søn, Jonans Søn, Eliakims Søn,"],[3,31,"Meleas’ Søn, Mainans Søn, Mattathas Søn, Nathans Søn, Davids Søn,","Meleas’ Søn, Mainans Søn, Mattathas Søn, Nathans Søn, Davids Søn,"],[3,32,"Jesais Søn, Obeds Søn, Booz’ Søn, Salmons Søn, Naassons Søn,","Jesais Søn, Obeds Søn, Booz’ Søn, Salmons Søn, Naassons Søn,"],[3,33,"Aminadabs Søn, Arams Søn, Esroms Søn, Phares’ Søn, Judas Søn,","Aminadabs Søn, Arams Søn, Esroms Søn, Phares’ Søn, Judas Søn,"],[3,34,"Jakobs Søn, Isaaks Søn, Abrahams Søn, Tharas Søn, Nachors Søn,","Jakobs Søn, Isaaks Søn, Abrahams Søn, Tharas Søn, Nachors Søn,"],[3,35,"Saruchs Søn, Ragahus Søn, Phaleks Søn, Ebers Søn, Salas Søn,","Saruchs Søn, Ragahus Søn, Phaleks Søn, Ebers Søn, Salas Søn,"],[3,36,"Cainans Søn, Arphachsads Søn, Sems Søn, Noes Søn, Lamechs Søn,","Cainans Søn, Arphachsads Søn, Sems Søn, Noes Søn, Lamechs Søn,"],[3,37,"Methusalas Søn, Enochs Søn, Jareds Søn, Maleleels Søn, Cainans Søn,","Methusalas Søn, Enochs Søn, Jareds Søn, Maleleels Søn, Cainans Søn,"],[3,38,"Eno’s Søn, Seths Søn, Adams Søn, Guds Søn.","Eno’s Søn, Seths Søn, Adams Søn, Guds Søn."],[4,1,"Men Jesus, fuld af den Hellig Aand, kom tilbage fra Jordan, og blev ført af Aanden i Ørken;","Men Jesus, fuld af den Hellig Aand, kom tilbage fra Jordan, og blev ført af Aanden i Ørken;"],[4,2,"og han blev fristet fyrretyve Dage af Djævelen. Og han aad Intet i de Dage; og der de havde Ende, hungrede han omsider.","og han blev fristet fyrretyve Dage af Djævelen. Og han aad Intet i de Dage; og der de havde Ende, hungrede han omsider."],[4,3,"Og Djævelen sagde til ham: dersom du er Guds Søn, da siig til denne Steen, at den bliver Brød.","Og Djævelen sagde til ham: dersom du er Guds Søn, da siig til denne Steen, at den bliver Brød."],[4,4,"Og Jesus svarede og sagde til ham: der er skrevet: Mennesket lever ikke aleneste af Brød, men af hvert Guds Ord.","Og Jesus svarede og sagde til ham: der er skrevet: Mennesket lever ikke aleneste af Brød, men af hvert Guds Ord."],[4,5,"Og Djævelen førte ham op paa et høit Bjerg, og viste ham alle Verdens Riger i et Øieblik.","Og Djævelen førte ham op paa et høit Bjerg, og viste ham alle Verdens Riger i et Øieblik."],[4,6,"Og Djævelen sagde til ham: jeg vil give dig al denne Magt og disse Rigers Herlighed; thi den er mig overantvordet, og jeg giver den, hvem jeg vil.","Og Djævelen sagde til ham: jeg vil give dig al denne Magt og disse Rigers Herlighed; thi den er mig overantvordet, og jeg giver den, hvem jeg vil."],[4,7,"Dersom du vil tilbede mig, skal det altsammen høre dig til.","Dersom du vil tilbede mig, skal det altsammen høre dig til."],[4,8,"Jesus svarede ham og sagde: vig bort bag mig, Satan! thi der er skrevet: du skal tilbede Herren din Gud, og tjene ham alene.","Jesus svarede ham og sagde: vig bort bag mig, Satan! thi der er skrevet: du skal tilbede Herren din Gud, og tjene ham alene."],[4,9,"Og han førte ham til Jerusalem, og satte ham paa Tindingen af Templet, og sagde til ham: dersom du er Guds Søn, da kast dig ned herfra;","Og han førte ham til Jerusalem, og satte ham paa Tindingen af Templet, og sagde til ham: dersom du er Guds Søn, da kast dig ned herfra;"],[4,10,"thi der er skrevet: han skal give sine Engle Befaling om dig, at bevare dig;","thi der er skrevet: han skal give sine Engle Befaling om dig, at bevare dig;"],[4,11,"og at de skulle bære dig paa Hænderne, paa det du ikke skal støde din Fod paa nogen Steen.","og at de skulle bære dig paa Hænderne, paa det du ikke skal støde din Fod paa nogen Steen."],[4,12,"Og Jesus svarede og sagde til ham: der er sagt, du skal ikke friste Herren din Gud.","Og Jesus svarede og sagde til ham: der er sagt, du skal ikke friste Herren din Gud."],[4,13,"Og der Djævelen havde gjort Ende paa Fristelsen, veg han fra ham til en Tid.","Og der Djævelen havde gjort Ende paa Fristelsen, veg han fra ham til en Tid."],[4,14,"Og Jesus kom tilbage i Aandens Kraft til Galilæa, og Rygtet om ham kom ud i alt det omkringliggende Land.","Og Jesus kom tilbage i Aandens Kraft til Galilæa, og Rygtet om ham kom ud i alt det omkringliggende Land."],[4,15,"Og han lærte i deres Synagoger, og blev priset af Alle.","Og han lærte i deres Synagoger, og blev priset af Alle."],[4,16,"Og han kom til Nazareth, hvor han var opfødt, og gik i Synagogen efter sin Sædvane paa Sabbatsdagen, og stod op at forelæse.","Og han kom til Nazareth, hvor han var opfødt, og gik i Synagogen efter sin Sædvane paa Sabbatsdagen, og stod op at forelæse."],[4,17,"Da gave de ham Esaias’ Prophetens Bog, og der han slog Bogen op, fandt han det Sted, hvor der staaer skrevet:","Da gave de ham Esaias’ Prophetens Bog, og der han slog Bogen op, fandt han det Sted, hvor der staaer skrevet:"],[4,18,"Herrens Aand er over mig, derfor salvede han mig; han haver sendt mig til at kundgjøre Evangelium for de Fattige, at helbrede dem, som have et sønderknuset Hjerte, at forkynde de Fangne, at de skulle lades løs, og at de Blinde skulle faae Syn, at udlade de Plagede i Frihed,","Herrens Aand er over mig, derfor salvede han mig; han haver sendt mig til at kundgjøre Evangelium for de Fattige, at helbrede dem, som have et sønderknuset Hjerte, at forkynde de Fangne, at de skulle lades løs, og at de Blinde skulle faae Syn, at udlade de Plagede i Frihed,"],[4,19,"at forkynde et Naade-Aar fra Herren.","at forkynde et Naade-Aar fra Herren."],[4,20,"Og han lukte Bogen sammen, og gav Tjeneren den igjen, og satte sig; og Alles Øine i Synagogen stirrede paa ham.","Og han lukte Bogen sammen, og gav Tjeneren den igjen, og satte sig; og Alles Øine i Synagogen stirrede paa ham."],[4,21,"Men han begyndte at sige til dem: i Dag er denne Skrift gaaet i Opfyldelse for Eders Øren.","Men han begyndte at sige til dem: i Dag er denne Skrift gaaet i Opfyldelse for Eders Øren."],[4,22,"Og de gave ham alle Priis og forundrede sig over de livsalige Ord, som udgik af hans Mund, og sagde: er ikke denne Josephs Søn?","Og de gave ham alle Priis og forundrede sig over de livsalige Ord, som udgik af hans Mund, og sagde: er ikke denne Josephs Søn?"],[4,23,"Og han sagde til dem: I ville sikkerligen sige mig dette Ordsprog: Læge! læg dig selv; saa store Ting, som vi have hørt at være skete i Capernaum, gjør ogsaa her i dit Fædreneland!","Og han sagde til dem: I ville sikkerligen sige mig dette Ordsprog: Læge! læg dig selv; saa store Ting, som vi have hørt at være skete i Capernaum, gjør ogsaa her i dit Fædreneland!"],[4,24,"Men han sagde: sandelig siger jeg Eder, at ingen Prophet er vel antagen i sit Fædreneland!","Men han sagde: sandelig siger jeg Eder, at ingen Prophet er vel antagen i sit Fædreneland!"],[4,25,"Men jeg siger Eder i Sandhed: der var mange Enker i Israel i Elias’ Dage, der Himmelen var lukt i tre Aar og sex Maaneder, den Gang der var en stor Hunger i det ganske Land;","Men jeg siger Eder i Sandhed: der var mange Enker i Israel i Elias’ Dage, der Himmelen var lukt i tre Aar og sex Maaneder, den Gang der var en stor Hunger i det ganske Land;"],[4,26,"og til ingen af dem blev Elias sendt uden til Sarepta ved Sidon, til en Enke.","og til ingen af dem blev Elias sendt uden til Sarepta ved Sidon, til en Enke."],[4,27,"Og der vare mange Spedalske i Israel udi Elifæus Prophetens Tid, og Ingen af dem blev renset, uden Naaman den Syrer.","Og der vare mange Spedalske i Israel udi Elifæus Prophetens Tid, og Ingen af dem blev renset, uden Naaman den Syrer."],[4,28,"Da bleve Alle, som vare i Synagogen, fulde af Vrede, der de hørte dette.","Da bleve Alle, som vare i Synagogen, fulde af Vrede, der de hørte dette."],[4,29,"Og de stode op, og stødte ham ud af Staden, og førte ham til Skrænten af Bjerget, paa hvilket deres Stad var bygt, for at styrte ham ned.","Og de stode op, og stødte ham ud af Staden, og førte ham til Skrænten af Bjerget, paa hvilket deres Stad var bygt, for at styrte ham ned."],[4,30,"Men han gik midt igjennem dem, og drog bort.","Men han gik midt igjennem dem, og drog bort."],[4,31,"Og han kom ned til Capernaum, en Stad i Galilæa, og lærte dem paa Sabbaterne.","Og han kom ned til Capernaum, en Stad i Galilæa, og lærte dem paa Sabbaterne."],[4,32,"Og de forundrede sig saare over hans Lærdom, thi hans Tale var med Myndighed.","Og de forundrede sig saare over hans Lærdom, thi hans Tale var med Myndighed."],[4,33,"Og der var et Menneske i Synagogen, som havde en ureen Djævels Aand og raabte med stor Røst,","Og der var et Menneske i Synagogen, som havde en ureen Djævels Aand og raabte med stor Røst,"],[4,34,"og sagde: ak! hvad have vi med dig at skaffe, Jesus af Nazareth? er du kommen at fordærve os? Jeg kjender dig, hvo du er, den Guds Hellige.","og sagde: ak! hvad have vi med dig at skaffe, Jesus af Nazareth? er du kommen at fordærve os? Jeg kjender dig, hvo du er, den Guds Hellige."],[4,35,"Og Jesus truede ham og sagde: ti, og far ud af ham! Og Djævelen kastede ham midt iblandt dem, og gjorde ham ingen Skade.","Og Jesus truede ham og sagde: ti, og far ud af ham! Og Djævelen kastede ham midt iblandt dem, og gjorde ham ingen Skade."],[4,36,"Og der kom en Rædsel over Alle; og de talede med hverandre og sagde: hvad er dog dette, at han byder de urene Aander med Myndighed og Magt, og de fare ud?","Og der kom en Rædsel over Alle; og de talede med hverandre og sagde: hvad er dog dette, at han byder de urene Aander med Myndighed og Magt, og de fare ud?"],[4,37,"Og Rygtet om ham udbredtes allevegne i det omkringliggende Land.","Og Rygtet om ham udbredtes allevegne i det omkringliggende Land."],[4,38,"Men han stod op og gik fra Synagogen til Simons Huus; og Simons Hustrus Moder var betagen af en svar Feber; og de bade ham for hende.","Men han stod op og gik fra Synagogen til Simons Huus; og Simons Hustrus Moder var betagen af en svar Feber; og de bade ham for hende."],[4,39,"Og han traadte hen for hende og truede Feberen, og den forlod hende. Men hun stod strax op og tjente dem.","Og han traadte hen for hende og truede Feberen, og den forlod hende. Men hun stod strax op og tjente dem."],[4,40,"Men der Solen gik ned, førte alle de, som havde Syge af allehaande Svagheder, dem til ham; men han lagde Hænderne paa enhver af dem og helbredte dem.","Men der Solen gik ned, førte alle de, som havde Syge af allehaande Svagheder, dem til ham; men han lagde Hænderne paa enhver af dem og helbredte dem."],[4,41,"Ogsaa fore Djævle ud af Mange, raabte og sagde: du er Christus, den Guds Søn; og han truede dem og lod dem ikke tale; thi de vidste, at han var den Christus.","Ogsaa fore Djævle ud af Mange, raabte og sagde: du er Christus, den Guds Søn; og han truede dem og lod dem ikke tale; thi de vidste, at han var den Christus."],[4,42,"Men der det var blevet Dag, gik han ud og drog til et øde Sted; og Folket ledte efter ham, og de kom hen til ham, og de holdt paa ham, at han ikke skulde gaae fra dem.","Men der det var blevet Dag, gik han ud og drog til et øde Sted; og Folket ledte efter ham, og de kom hen til ham, og de holdt paa ham, at han ikke skulde gaae fra dem."],[4,43,"Men han sagde til dem: mig bør og for andre Stæder at forkynde Guds Rige, thi dertil er jeg udsendt.","Men han sagde til dem: mig bør og for andre Stæder at forkynde Guds Rige, thi dertil er jeg udsendt."],[4,44,"Og han prædikede i Galilæas Synagoger.","Og han prædikede i Galilæas Synagoger."],[5,1,"Men det begav sig, der Folket trængte sig til ham, for at høre Guds Ord, og han stod ved Genezareths Sø,","Men det begav sig, der Folket trængte sig til ham, for at høre Guds Ord, og han stod ved Genezareths Sø,"],[5,2,"og saae to Skibe ligge paa Søen, som Fiskerne vare bortgangne fra for at toe deres Garn:","og saae to Skibe ligge paa Søen, som Fiskerne vare bortgangne fra for at toe deres Garn:"],[5,3,"traadte han ind i eet af Skibene, som var Simons, og bad ham at lægge lidet fra Landet; og han satte sig og lærte Folket af Skibet.","traadte han ind i eet af Skibene, som var Simons, og bad ham at lægge lidet fra Landet; og han satte sig og lærte Folket af Skibet."],[5,4,"Men der han lod af at tale, sagde han til Simon: far ud paa Dybet, og kaster Eders Garn ud til en Dræt.","Men der han lod af at tale, sagde han til Simon: far ud paa Dybet, og kaster Eders Garn ud til en Dræt."],[5,5,"Og Simon svarede og sagde til ham: Mester! vi have arbeidet den ganske Nat og fik Intet; men paa dit Ord vil jeg udkaste Garnet.","Og Simon svarede og sagde til ham: Mester! vi have arbeidet den ganske Nat og fik Intet; men paa dit Ord vil jeg udkaste Garnet."],[5,6,"Og der de gjorde det, fangede de en stor Hob Fiske; men deres Garn sønderreves.","Og der de gjorde det, fangede de en stor Hob Fiske; men deres Garn sønderreves."],[5,7,"Og de vinkede ad deres Medbrødre, som vare i det andet Skib, at de skulde komme og hjælpe dem; og de kom og fyldte begge Skibene, saa at de vare nær ved at synke.","Og de vinkede ad deres Medbrødre, som vare i det andet Skib, at de skulde komme og hjælpe dem; og de kom og fyldte begge Skibene, saa at de vare nær ved at synke."],[5,8,"Men der Simon Peter saae det, faldt han ned for Jesu Knæ og sagde: Herre! gak ud fra mig, thi jeg er en syndig Mand.","Men der Simon Peter saae det, faldt han ned for Jesu Knæ og sagde: Herre! gak ud fra mig, thi jeg er en syndig Mand."],[5,9,"Thi en Rædsel var paakommen ham og alle dem, som vare med ham, for den Fiskedræt, som de havde fanget med hverandre;","Thi en Rædsel var paakommen ham og alle dem, som vare med ham, for den Fiskedræt, som de havde fanget med hverandre;"],[5,10,"desligeste ogsaa Jakob og Johannes, Zebedæus’ Sønner, som vare Simons Stalbrødre. Og Jesus sagde til Simon: frygt ikke, fra nu af skal du fange Mennesker.","desligeste ogsaa Jakob og Johannes, Zebedæus’ Sønner, som vare Simons Stalbrødre. Og Jesus sagde til Simon: frygt ikke, fra nu af skal du fange Mennesker."],[5,11,"Og de førte Skibene til Landet og forlode alle Ting og fulgte ham.","Og de førte Skibene til Landet og forlode alle Ting og fulgte ham."],[5,12,"Og det begav sig, der han var i een af Stæderne, see, da var der en Mand fuld af Spedalskhed; og der han saae Jesus, faldt han paa sit Ansigt, bad ham og sagde: Herre! om du vil, kan du rense mig.","Og det begav sig, der han var i een af Stæderne, see, da var der en Mand fuld af Spedalskhed; og der han saae Jesus, faldt han paa sit Ansigt, bad ham og sagde: Herre! om du vil, kan du rense mig."],[5,13,"Og han udrakte sin Haand, og rørte ved ham og sagde: jeg vil; vorde reen! Og strax gik Spedalskheden bort af ham.","Og han udrakte sin Haand, og rørte ved ham og sagde: jeg vil; vorde reen! Og strax gik Spedalskheden bort af ham."],[5,14,"Og han bød ham, at han skulde Ingen sige det, men sagde: gak bort, og betee dig for Præsten, og offre for din Renselse, som Moses haver befalet, dem til Vidnesbyrd.","Og han bød ham, at han skulde Ingen sige det, men sagde: gak bort, og betee dig for Præsten, og offre for din Renselse, som Moses haver befalet, dem til Vidnesbyrd."],[5,15,"Men Rygtet om ham udbredte sig end mere, og meget Folk kom sammen at høre og at helbredes af ham for deres Sygdomme.","Men Rygtet om ham udbredte sig end mere, og meget Folk kom sammen at høre og at helbredes af ham for deres Sygdomme."],[5,16,"Men han veg bort i Ørknerne, og bad.","Men han veg bort i Ørknerne, og bad."],[5,17,"Og det begav sig paa een af Dagene, at han lærte, og der sadde Pharisæer og Lovlærere, som vare komne fra alle Byer i Galilæa og Judæa, og fra Jerusalem, og Herrens Kraft viste sig i at helbrede.","Og det begav sig paa een af Dagene, at han lærte, og der sadde Pharisæer og Lovlærere, som vare komne fra alle Byer i Galilæa og Judæa, og fra Jerusalem, og Herrens Kraft viste sig i at helbrede."],[5,18,"Og see, nogle Mænd bare paa en Seng et Menneske, som var værkbruden, og denne søgte de at bringe ind og lægge for ham.","Og see, nogle Mænd bare paa en Seng et Menneske, som var værkbruden, og denne søgte de at bringe ind og lægge for ham."],[5,19,"Og der de formedelst Folket ikke kunde finde, hvorledes de skulde bringe ham ind, stege de op paa Taget, og lode ham tilligemed Sengen ned imellem Tagstenene midt iblandt Folket for Jesus.","Og der de formedelst Folket ikke kunde finde, hvorledes de skulde bringe ham ind, stege de op paa Taget, og lode ham tilligemed Sengen ned imellem Tagstenene midt iblandt Folket for Jesus."],[5,20,"Og der han saae deres Tro, sagde han til ham: Menneske! dine Synder ere dig forladne.","Og der han saae deres Tro, sagde han til ham: Menneske! dine Synder ere dig forladne."],[5,21,"Og de Skriftkloge og Pharisæerne begyndte at tænke, og sagde: hvo er denne, som taler Gudsbespottelser? hvo kan forlade Synder, uden Gud alene?","Og de Skriftkloge og Pharisæerne begyndte at tænke, og sagde: hvo er denne, som taler Gudsbespottelser? hvo kan forlade Synder, uden Gud alene?"],[5,22,"Men der Jesus fornam deres Tanker, svarede han og sagde til dem: hvad tænkte I udi Eders Hjerter?","Men der Jesus fornam deres Tanker, svarede han og sagde til dem: hvad tænkte I udi Eders Hjerter?"],[5,23,"Hvilket er lettere, at sige: dig ere dine Synder forladne? eller at sige: staa op og vandre?","Hvilket er lettere, at sige: dig ere dine Synder forladne? eller at sige: staa op og vandre?"],[5,24,"Men at I skulle vide, at Menneskens Søn haver Magt paa Jorden at forlade Synder, (sagde han til den Værkbrudne): jeg siger dig, staa op, tag din Seng op og gak til dit Huus.","Men at I skulle vide, at Menneskens Søn haver Magt paa Jorden at forlade Synder, (sagde han til den Værkbrudne): jeg siger dig, staa op, tag din Seng op og gak til dit Huus."],[5,25,"Og han stod strax op for deres Øine, og tog op det, som han laae paa, og gik hen til sit Huus, og prisede Gud.","Og han stod strax op for deres Øine, og tog op det, som han laae paa, og gik hen til sit Huus, og prisede Gud."],[5,26,"Og en stor Forfærdelse betog dem alle, og de prisede Gud; og de bleve fulde af Frygt og sagde: vi have i Dag seet utrolige Ting.","Og en stor Forfærdelse betog dem alle, og de prisede Gud; og de bleve fulde af Frygt og sagde: vi have i Dag seet utrolige Ting."],[5,27,"Derefter gik han ud og saae en Tolder, som hedte Levi, siddende i Toldboden, og sagde til ham: følg mig!","Derefter gik han ud og saae en Tolder, som hedte Levi, siddende i Toldboden, og sagde til ham: følg mig!"],[5,28,"Og han forlod alle Ting, og stod op og fulgte ham.","Og han forlod alle Ting, og stod op og fulgte ham."],[5,29,"Og samme Levi gjorde et stort Gjestebud for ham i sit Huus; og der var en stor Hob af Toldere og Andre, som sadde med dem tilbords.","Og samme Levi gjorde et stort Gjestebud for ham i sit Huus; og der var en stor Hob af Toldere og Andre, som sadde med dem tilbords."],[5,30,"Og deres Skriftkloge og Pharisæerne knurrede imod hans Disciple og sagde: hvorfor æde og drikke I med Toldere og Syndere?","Og deres Skriftkloge og Pharisæerne knurrede imod hans Disciple og sagde: hvorfor æde og drikke I med Toldere og Syndere?"],[5,31,"Og Jesus svarede og sagde til dem: de Karske have ikke Læge behov, men de, som lide ilde.","Og Jesus svarede og sagde til dem: de Karske have ikke Læge behov, men de, som lide ilde."],[5,32,"Jeg er ikke kommen at kalde Retfærdige, men Syndere til Omvendelse.","Jeg er ikke kommen at kalde Retfærdige, men Syndere til Omvendelse."],[5,33,"Men de sagde til ham: hvorfor faste Johannes’ Disciple saa ofte og holde Bønner, og Pharisæernes ligesaa; men dine æde og drikke?","Men de sagde til ham: hvorfor faste Johannes’ Disciple saa ofte og holde Bønner, og Pharisæernes ligesaa; men dine æde og drikke?"],[5,34,"Men han sagde til dem: kunne I komme Bryllupsfolket til at faste, saa længe Brudgommen er hos dem?","Men han sagde til dem: kunne I komme Bryllupsfolket til at faste, saa længe Brudgommen er hos dem?"],[5,35,"De Dage skulle komme, naar Brudgommen skal tages fra dem, da skulle de faste i de samme Dage.","De Dage skulle komme, naar Brudgommen skal tages fra dem, da skulle de faste i de samme Dage."],[5,36,"Men han sagde og en Lignelse til dem: Ingen sætter en Klud af nyt Klæde paa et gammelt Klædebon, ellers river baade det nye det gamle sønder, og Kluden af det nye skikker sig ikke paa det gamle.","Men han sagde og en Lignelse til dem: Ingen sætter en Klud af nyt Klæde paa et gammelt Klædebon, ellers river baade det nye det gamle sønder, og Kluden af det nye skikker sig ikke paa det gamle."],[5,37,"Og Ingen lader ny Viin i gamle Læderflasker; ellers sønderriver den nye Viin Læderflaskerne, og den spildes, og Læderflaskerne fordærves.","Og Ingen lader ny Viin i gamle Læderflasker; ellers sønderriver den nye Viin Læderflaskerne, og den spildes, og Læderflaskerne fordærves."],[5,38,"Men man skal lade ny Viin i nye Læderflasker, saa blive de begge bevarede.","Men man skal lade ny Viin i nye Læderflasker, saa blive de begge bevarede."],[5,39,"Og Ingen, som drikker den gamle, vil strax drikke den nye; thi han siger: den gamle er bedre.","Og Ingen, som drikker den gamle, vil strax drikke den nye; thi han siger: den gamle er bedre."],[6,1,"Men det begav sig paa den næstførste Sabbat, at han gik igjennem Sæden, og hans Disciple plukkede Ax og gnede dem med Hænderne og aade.","Men det begav sig paa den næstførste Sabbat, at han gik igjennem Sæden, og hans Disciple plukkede Ax og gnede dem med Hænderne og aade."],[6,2,"Men nogle af Pharisæerne sagde til dem: hvi gjøre I, hvad ikke er tilladt at gjøre paa Sabbaterne?","Men nogle af Pharisæerne sagde til dem: hvi gjøre I, hvad ikke er tilladt at gjøre paa Sabbaterne?"],[6,3,"Og Jesus svarede og sagde til dem: have I da ikke læst det, som David gjorde, der han hungrede, og de, som vare med ham?","Og Jesus svarede og sagde til dem: have I da ikke læst det, som David gjorde, der han hungrede, og de, som vare med ham?"],[6,4,"Hvorledes han gik ind i Guds Huus og tog Skue-Brødene og aad og gav ogsaa dem, som vare med ham, hvoraf det dog ikke er Nogen tilladt at æde, uden Præsterne alene.","Hvorledes han gik ind i Guds Huus og tog Skue-Brødene og aad og gav ogsaa dem, som vare med ham, hvoraf det dog ikke er Nogen tilladt at æde, uden Præsterne alene."],[6,5,"Og han sagde til dem: Menneskens Søn er Herre ogsaa over Sabbaten.","Og han sagde til dem: Menneskens Søn er Herre ogsaa over Sabbaten."],[6,6,"Men det skete paa en anden Sabbat, at han gik ind i Synagogen og lærte; og der var et Menneske, hvis høire Haand var vissen.","Men det skete paa en anden Sabbat, at han gik ind i Synagogen og lærte; og der var et Menneske, hvis høire Haand var vissen."],[6,7,"Men de Skriftkloge og Pharisæerne toge vare paa ham, om han vilde helbrede paa Sabbaten, paa det de kunde finde Klagemaal imod ham.","Men de Skriftkloge og Pharisæerne toge vare paa ham, om han vilde helbrede paa Sabbaten, paa det de kunde finde Klagemaal imod ham."],[6,8,"Men han vidste deres Tanker og sagde til det Menneske, som havde den visne Haand: reis dig, og staa frem iblandt os! Men han reiste sig og stod frem.","Men han vidste deres Tanker og sagde til det Menneske, som havde den visne Haand: reis dig, og staa frem iblandt os! Men han reiste sig og stod frem."],[6,9,"Da sagde Jesus til dem: jeg vil spørge Eder: hvad er tilladt paa Sabbaterne? at gjøre godt, eller at gjøre ondt? at frelse Liv, eller at fordærve det?","Da sagde Jesus til dem: jeg vil spørge Eder: hvad er tilladt paa Sabbaterne? at gjøre godt, eller at gjøre ondt? at frelse Liv, eller at fordærve det?"],[6,10,"Og han saae omkring paa dem alle og sagde til Mennesket: ræk din Haand ud; men han gjorde saa; da blev hans Haand karsk igjen som den anden.","Og han saae omkring paa dem alle og sagde til Mennesket: ræk din Haand ud; men han gjorde saa; da blev hans Haand karsk igjen som den anden."],[6,11,"Men de bleve fulde af Raseri og talede med hverandre om, hvad de skulde gjøre ved Jesus.","Men de bleve fulde af Raseri og talede med hverandre om, hvad de skulde gjøre ved Jesus."],[6,12,"Men det begav sig i de Dage, at han gik ud til et Bjerg at bede; og han blev der Natten over i Bøn til Gud.","Men det begav sig i de Dage, at han gik ud til et Bjerg at bede; og han blev der Natten over i Bøn til Gud."],[6,13,"Og der det blev Dag, kaldte han sine Disciple frem, og udvalgte tolv af dem, hvilke han og kaldte Apostler:","Og der det blev Dag, kaldte han sine Disciple frem, og udvalgte tolv af dem, hvilke han og kaldte Apostler:"],[6,14,"Simon, hvilken han og kaldte Petrus, og Andreas, han Broder, Jacobus og Johannes, Philippus og Bartholomæus,","Simon, hvilken han og kaldte Petrus, og Andreas, han Broder, Jacobus og Johannes, Philippus og Bartholomæus,"],[6,15,"Matthæus og Thomas, Jacobus, Alphæus’ Søn, og Simon, som kaldes Zelotes.","Matthæus og Thomas, Jacobus, Alphæus’ Søn, og Simon, som kaldes Zelotes."],[6,16,"Judas, Jacobus’ Broder, og Judas Ischariotes, den Samme, som blev Forræder.","Judas, Jacobus’ Broder, og Judas Ischariotes, den Samme, som blev Forræder."],[6,17,"Og han gik ned med dem og stod paa et jævnt Sted, og hans Disciples Skare og en stor Hob Folk fra hele Judæa og Jerusalem og Kysten ved Tyrus og Sidon,","Og han gik ned med dem og stod paa et jævnt Sted, og hans Disciples Skare og en stor Hob Folk fra hele Judæa og Jerusalem og Kysten ved Tyrus og Sidon,"],[6,18,"som vare komne at høre ham og helbredes af deres Sygdomme, og saadanne, som vare plagede af urene Aander; og de bleve helbredte.","som vare komne at høre ham og helbredes af deres Sygdomme, og saadanne, som vare plagede af urene Aander; og de bleve helbredte."],[6,19,"Og alt Folket søgte at røre ved ham; thi en Kraft gik ud fra ham og helbredte Alle.","Og alt Folket søgte at røre ved ham; thi en Kraft gik ud fra ham og helbredte Alle."],[6,20,"Og han opløftede sine Øine paa sine Disciple og sagde: salige ere I Fattige, thi Eders er Guds Rige.","Og han opløftede sine Øine paa sine Disciple og sagde: salige ere I Fattige, thi Eders er Guds Rige."],[6,21,"Salige ere I, som nu hungre, thi I skulle mættes. Salige ere I, som nu græde, thi I skulle lee.","Salige ere I, som nu hungre, thi I skulle mættes. Salige ere I, som nu græde, thi I skulle lee."],[6,22,"Salige ere I, naar Menneskene hade Eder, og naar de udstøde Eder og bespotte Eder og forskyde Eders Navn som ondt, for Menneskens Søns Skyld.","Salige ere I, naar Menneskene hade Eder, og naar de udstøde Eder og bespotte Eder og forskyde Eders Navn som ondt, for Menneskens Søns Skyld."],[6,23,"Glæder Eder paa den samme Dag, og jubler; thi see, Eders Løn er stor i Himmelen. Lige det Samme gjorde deres Fædre ved Propheterne.","Glæder Eder paa den samme Dag, og jubler; thi see, Eders Løn er stor i Himmelen. Lige det Samme gjorde deres Fædre ved Propheterne."],[6,24,"Men vee Eder, I Rige, thi I have Eders Trøst borte.","Men vee Eder, I Rige, thi I have Eders Trøst borte."],[6,25,"Vee Eder, I, som ere fyldte, thi I skulle hungre. Vee Eder, I, som nu lee, thi I skulle sørge og græde.","Vee Eder, I, som ere fyldte, thi I skulle hungre. Vee Eder, I, som nu lee, thi I skulle sørge og græde."],[6,26,"Vee Eder, naar alle Mennesker tale vel om Eder; lige det Samme gjorde deres Fædre ved de falske Propheter.","Vee Eder, naar alle Mennesker tale vel om Eder; lige det Samme gjorde deres Fædre ved de falske Propheter."],[6,27,"Men jeg siger Eder, I, som høre mig: elsker Eders Fjender, gjører dem godt, som Eder hade;","Men jeg siger Eder, I, som høre mig: elsker Eders Fjender, gjører dem godt, som Eder hade;"],[6,28,"velsigner dem, som Eder forbande, og beder for dem, som gjøre Eder Skade.","velsigner dem, som Eder forbande, og beder for dem, som gjøre Eder Skade."],[6,29,"Hvo som slaaer dig paa det ene Kindbeen, byd ham og det andet til, og hvo som tager Kappen fra dig, formeen ham heller ikke Kjortelen.","Hvo som slaaer dig paa det ene Kindbeen, byd ham og det andet til, og hvo som tager Kappen fra dig, formeen ham heller ikke Kjortelen."],[6,30,"Giv hver den, som beder dig; og af den, som tager dit fra dig, kræv det ikke igjen.","Giv hver den, som beder dig; og af den, som tager dit fra dig, kræv det ikke igjen."],[6,31,"Og som I ville, at Menneskene skulle gjøre mod Eder, ligesaa gjører og I mod dem.","Og som I ville, at Menneskene skulle gjøre mod Eder, ligesaa gjører og I mod dem."],[6,32,"Og dersom I elske dem, som Eder elske, hvad Tak have I derfor? Thi Syndere elske og dem, som dem elske.","Og dersom I elske dem, som Eder elske, hvad Tak have I derfor? Thi Syndere elske og dem, som dem elske."],[6,33,"Og dersom I gjøre vel mod dem, der gjøre vel mod Eder, hvad Tak have I derfor? Thi Syndere gjøre det Samme.","Og dersom I gjøre vel mod dem, der gjøre vel mod Eder, hvad Tak have I derfor? Thi Syndere gjøre det Samme."],[6,34,"Og dersom I laane dem, af hvilke I haabe at faae igjen, hvad Tak have I derfor? Thi Syndere laane ogsaa Syndere, paa det de skulle faae lige igjen.","Og dersom I laane dem, af hvilke I haabe at faae igjen, hvad Tak have I derfor? Thi Syndere laane ogsaa Syndere, paa det de skulle faae lige igjen."],[6,35,"Men elsker Eders Fjender og gjører vel, og laaner, ventende Intet derfor, saa skal Eders Løn være stor, og I skulle være den Høiestes Børn; thi han er miskundelig mod de Utaknemmelige og Onde.","Men elsker Eders Fjender og gjører vel, og laaner, ventende Intet derfor, saa skal Eders Løn være stor, og I skulle være den Høiestes Børn; thi han er miskundelig mod de Utaknemmelige og Onde."],[6,36,"Saa værer da barmhjertige, som Eders Fader og er barmhjertig.","Saa værer da barmhjertige, som Eders Fader og er barmhjertig."],[6,37,"Og dømmer ikke, saa skulle og I ikke dømmes; fordømmer ikke, saa skulle I ikke fordømmes; forlader, saa skal Eder forlades;","Og dømmer ikke, saa skulle og I ikke dømmes; fordømmer ikke, saa skulle I ikke fordømmes; forlader, saa skal Eder forlades;"],[6,38,"giver, saa skal Eder gives; en god, knuget og skuddet og overflødig Maade skulle de give i Eders Skjød; thi med den samme Maade, som I maale med, skal Eder maales igjen.","giver, saa skal Eder gives; en god, knuget og skuddet og overflødig Maade skulle de give i Eders Skjød; thi med den samme Maade, som I maale med, skal Eder maales igjen."],[6,39,"Men han sagde dem en Lignelse: monne en Blind kunne lede en Blind? ville de ikke begge falde i Graven?","Men han sagde dem en Lignelse: monne en Blind kunne lede en Blind? ville de ikke begge falde i Graven?"],[6,40,"Discipelen er ikke over sin Mester; men hver, som er fuldkommen, skal være som hans Mester.","Discipelen er ikke over sin Mester; men hver, som er fuldkommen, skal være som hans Mester."],[6,41,"Men hvi seer du Skjæven, som er i din Broders Øie, men Bjelken, som er i dit eget Øie, bliver du ikke vaer.","Men hvi seer du Skjæven, som er i din Broders Øie, men Bjelken, som er i dit eget Øie, bliver du ikke vaer."],[6,42,"Eller hvorledes kan du sige til din Broder: holdt, Broder! jeg vil drage Skjæven ud, som er i dit Øie, du, som ikke seer Bjelken i dit eget Øie? Du Øienskalk! uddrag først Bjelken af dit Øie, og da kan du see til at uddrage Skjæven, som er i din Broders Øie.","Eller hvorledes kan du sige til din Broder: holdt, Broder! jeg vil drage Skjæven ud, som er i dit Øie, du, som ikke seer Bjelken i dit eget Øie? Du Øienskalk! uddrag først Bjelken af dit Øie, og da kan du see til at uddrage Skjæven, som er i din Broders Øie."],[6,43,"Thi der er intet godt Træ, som bærer raadden Frugt, og intet raaddent Træ, som bærer god Frugt.","Thi der er intet godt Træ, som bærer raadden Frugt, og intet raaddent Træ, som bærer god Frugt."],[6,44,"Thi hvert Træ kjendes paa sin egen Frugt; thi man sanker ikke Figen af Torne, man plukker og ikke Viindruer af Tornebuske.","Thi hvert Træ kjendes paa sin egen Frugt; thi man sanker ikke Figen af Torne, man plukker og ikke Viindruer af Tornebuske."],[6,45,"Et godt Menneske fremfører Godt af sit Hjertes gode Forraad, og et ondt Menneske fremfører Ondt af sit Hjertes onde Forraad; thi hans Mund taler af Hjertets Overflødighed.","Et godt Menneske fremfører Godt af sit Hjertes gode Forraad, og et ondt Menneske fremfører Ondt af sit Hjertes onde Forraad; thi hans Mund taler af Hjertets Overflødighed."],[6,46,"Men hvi kalde I mig Herre, Herre! og gjøre ikke, hvad jeg siger?","Men hvi kalde I mig Herre, Herre! og gjøre ikke, hvad jeg siger?"],[6,47,"Hver, som kommer til mig, og hører mine Ord, og gjør dem, den vil jeg vise Eder, hvem han er lig.","Hver, som kommer til mig, og hører mine Ord, og gjør dem, den vil jeg vise Eder, hvem han er lig."],[6,48,"Han er lig et Menneske, der byggede et Huus, og grov dybt, og lagde Grundvolden paa en Klippe; men der et Vandløb kom, stødte Strømmen paa samme Huus, og kunde ikke rokke det; thi det var grundfæstet paa Klippen.","Han er lig et Menneske, der byggede et Huus, og grov dybt, og lagde Grundvolden paa en Klippe; men der et Vandløb kom, stødte Strømmen paa samme Huus, og kunde ikke rokke det; thi det var grundfæstet paa Klippen."],[6,49,"Men hvo som hører, og ikke gjør derefter, er ligesom et Menneske, der byggede et Huus paa Jorden, uden Grundvold; og Strømmen stødte derpaa, og det faldt strax, og samme Huses Fald blev stort.","Men hvo som hører, og ikke gjør derefter, er ligesom et Menneske, der byggede et Huus paa Jorden, uden Grundvold; og Strømmen stødte derpaa, og det faldt strax, og samme Huses Fald blev stort."],[7,1,"Men der han havde fuldendt al sin Tale i Folkets Paahør, gik han ind i Capernaum.","Men der han havde fuldendt al sin Tale i Folkets Paahør, gik han ind i Capernaum."],[7,2,"Men en Høvedsmands Tjener, som denne holdt meget af, var syg og nær ved at døe.","Men en Høvedsmands Tjener, som denne holdt meget af, var syg og nær ved at døe."],[7,3,"Men der han hørte om Jesus, sendte han nogle af Jødernes Ældste til ham, at han vilde komme og helbrede hans Tjener.","Men der han hørte om Jesus, sendte han nogle af Jødernes Ældste til ham, at han vilde komme og helbrede hans Tjener."],[7,4,"Men der de kom til Jesus, bade de ham flitteligen og sagde: han er vel værd, at du gjør ham dette;","Men der de kom til Jesus, bade de ham flitteligen og sagde: han er vel værd, at du gjør ham dette;"],[7,5,"thi han elsker vort Folk og haver bygget os vor Synagoge.","thi han elsker vort Folk og haver bygget os vor Synagoge."],[7,6,"Da gik Jesus med dem; men der han nu ikke var langt fra Huset, sendte Høvedsmanden nogle af sine Venner til ham, og lod ham sige: Herre! umag dig ikke; thi jeg er ikke værd, at du gaaer ind under mit Tag.","Da gik Jesus med dem; men der han nu ikke var langt fra Huset, sendte Høvedsmanden nogle af sine Venner til ham, og lod ham sige: Herre! umag dig ikke; thi jeg er ikke værd, at du gaaer ind under mit Tag."],[7,7,"Derfor agtede jeg heller ikke mig selv værdig at komme til dig; men siig det med et Ord, da bliver min Dreng helbredet.","Derfor agtede jeg heller ikke mig selv værdig at komme til dig; men siig det med et Ord, da bliver min Dreng helbredet."],[7,8,"Thi jeg er og et Menneske, Øvrigheden undergiven, som haver Stridsmænd under mig; og siger jeg til denne: gak! saa gaaer han; og til den anden; kom! saa kommer han; og til min Tjener: gjør det! saa gjør han det.","Thi jeg er og et Menneske, Øvrigheden undergiven, som haver Stridsmænd under mig; og siger jeg til denne: gak! saa gaaer han; og til den anden; kom! saa kommer han; og til min Tjener: gjør det! saa gjør han det."],[7,9,"Men der Jesus hørte det, forundrede han sig over ham; og han vendte sig om og sagde til Folket, som ham fulgte: jeg siger Eder, saa stor en Tro haver jeg end ikke fundet i Israel.","Men der Jesus hørte det, forundrede han sig over ham; og han vendte sig om og sagde til Folket, som ham fulgte: jeg siger Eder, saa stor en Tro haver jeg end ikke fundet i Israel."],[7,10,"Og der de, som vare udsendte kom tilbage til Huset, fandt de den syge Tjener karsk.","Og der de, som vare udsendte kom tilbage til Huset, fandt de den syge Tjener karsk."],[7,11,"Og det begav sig Dagen derefter, at han gik til en Stad, som hedte Nain, og der gik mange af hans Disciple med ham og meget Folk.","Og det begav sig Dagen derefter, at han gik til en Stad, som hedte Nain, og der gik mange af hans Disciple med ham og meget Folk."],[7,12,"Men der han kom nær til Stadens Port, see, da blev en Død udbaaren, som var sin Moders eenbaarne Søn, og hun var en Enke; og meget Folk af Staden gik med hende.","Men der han kom nær til Stadens Port, see, da blev en Død udbaaren, som var sin Moders eenbaarne Søn, og hun var en Enke; og meget Folk af Staden gik med hende."],[7,13,"Og der Herren saae hende, ynkedes han inderligen over hende og sagde til hende: græd ikke.","Og der Herren saae hende, ynkedes han inderligen over hende og sagde til hende: græd ikke."],[7,14,"Og han traadte til og rørte ved Baaren, (men de, som bare, stode stille), og han sagde: du unge Karl, jeg siger dig, staae op!","Og han traadte til og rørte ved Baaren, (men de, som bare, stode stille), og han sagde: du unge Karl, jeg siger dig, staae op!"],[7,15,"Og den Døde reiste sig op, og begyndte at tale; og han gav hans Moder ham.","Og den Døde reiste sig op, og begyndte at tale; og han gav hans Moder ham."],[7,16,"Men en Frygt betog Alle, og de prisede Gud og sagde: der er en stor Prophet opreist iblandt os, og Gud haver besøgt sit Folk.","Men en Frygt betog Alle, og de prisede Gud og sagde: der er en stor Prophet opreist iblandt os, og Gud haver besøgt sit Folk."],[7,17,"Og denne Tale om ham kom ud i det ganske Judæa og i alt det omkringliggende Land.","Og denne Tale om ham kom ud i det ganske Judæa og i alt det omkringliggende Land."],[7,18,"Og Johannes’ Disciple forkyndte ham om alt dette. Og Johannes kaldte to af sine Disciple til sig,","Og Johannes’ Disciple forkyndte ham om alt dette. Og Johannes kaldte to af sine Disciple til sig,"],[7,19,"og sendte dem til Jesus, og lod sige: er du den, som kommer, eller skulle vi vente en Anden?","og sendte dem til Jesus, og lod sige: er du den, som kommer, eller skulle vi vente en Anden?"],[7,20,"Men der disse Mænd kom til ham, sagde de: Johannes den Døber haver sendt os til dig, og lader sige: er du den, som kommer, eller skulle vi vente en Anden?","Men der disse Mænd kom til ham, sagde de: Johannes den Døber haver sendt os til dig, og lader sige: er du den, som kommer, eller skulle vi vente en Anden?"],[7,21,"Men i den samme Time helbredte han Mange fra Sygdomme og Plager og onde Aander, og skjenkte mange Blinde Synet.","Men i den samme Time helbredte han Mange fra Sygdomme og Plager og onde Aander, og skjenkte mange Blinde Synet."],[7,22,"Og Jesus svarede og sagde til dem: gaaer bort, og forkynder Johannes, hvad I have seet og hørt: Blinde see, Halte gaae, Spedalske renses, Døve høre, Døde staae op, Evangelium prædikes for de Fattige;","Og Jesus svarede og sagde til dem: gaaer bort, og forkynder Johannes, hvad I have seet og hørt: Blinde see, Halte gaae, Spedalske renses, Døve høre, Døde staae op, Evangelium prædikes for de Fattige;"],[7,23,"og salig er den, som ikke forarges paa mig.","og salig er den, som ikke forarges paa mig."],[7,24,"Men der Johannes’ Bud gik bort, begyndte han at tale til Folket om Johannes: hvad ere I udgangne i Ørken at see? et Rør, som bevæges af Veiret?","Men der Johannes’ Bud gik bort, begyndte han at tale til Folket om Johannes: hvad ere I udgangne i Ørken at see? et Rør, som bevæges af Veiret?"],[7,25,"Eller hvad ere I udgangne at see? et Menneske, iført bløde Klæder? See, de, som leve i herlige Klæder og i Vellyst, ere i Kongers Gaarde.","Eller hvad ere I udgangne at see? et Menneske, iført bløde Klæder? See, de, som leve i herlige Klæder og i Vellyst, ere i Kongers Gaarde."],[7,26,"Eller hvad ere I udgangne at see? en Prophet? Ja, jeg siger Eder, mere end en Prophet.","Eller hvad ere I udgangne at see? en Prophet? Ja, jeg siger Eder, mere end en Prophet."],[7,27,"Han er den, om hvem der er skrevet: see, jeg sender min Engel for dit Ansigt; han skal berede din Vei for dig.","Han er den, om hvem der er skrevet: see, jeg sender min Engel for dit Ansigt; han skal berede din Vei for dig."],[7,28,"Thi jeg siger Eder: iblandt dem, som ere fødte af Kvinder, er ingen større Prophet end Johannes den Døber; men den Mindste i Guds Rige er større end han.","Thi jeg siger Eder: iblandt dem, som ere fødte af Kvinder, er ingen større Prophet end Johannes den Døber; men den Mindste i Guds Rige er større end han."],[7,29,"Og alt Folket, som han hørte, endog Tolderne, gave Gud Æren, og bleve døbte med Johannes’ Daab.","Og alt Folket, som han hørte, endog Tolderne, gave Gud Æren, og bleve døbte med Johannes’ Daab."],[7,30,"Men Pharisæerne og de Lovkyndige foragtede Guds Raad med dem, og bleve ikke døbte af ham.","Men Pharisæerne og de Lovkyndige foragtede Guds Raad med dem, og bleve ikke døbte af ham."],[7,31,"Men Herren sagde: hvem skal jeg derfor ligne denne Slægts Mennesker ved? og hvem ere de lige?","Men Herren sagde: hvem skal jeg derfor ligne denne Slægts Mennesker ved? og hvem ere de lige?"],[7,32,"De ere de smaa Børn lige, som sidde paa Torvet og raabe til hverandre og sige: vi fløitede for Eder, og I vilde ikke danse, vi sang klageligen for Eder, og I vilde ikke græde.","De ere de smaa Børn lige, som sidde paa Torvet og raabe til hverandre og sige: vi fløitede for Eder, og I vilde ikke danse, vi sang klageligen for Eder, og I vilde ikke græde."],[7,33,"Thi Johannes den Døber kom, og hverken aad Brød, ei heller drak Viin, og I sige: han haver Djævelen.","Thi Johannes den Døber kom, og hverken aad Brød, ei heller drak Viin, og I sige: han haver Djævelen."],[7,34,"Menneskens Søn er kommen, æder og drikker, og I sige: see, en Fraadser og en Viindranker, Tolderes og Synderes Ven!","Menneskens Søn er kommen, æder og drikker, og I sige: see, en Fraadser og en Viindranker, Tolderes og Synderes Ven!"],[7,35,"Dog Viisdommen er retfærdiggjort af alle sine Børn.","Dog Viisdommen er retfærdiggjort af alle sine Børn."],[7,36,"Men En af Pharisæerne bad ham, at han vilde æde med ham; og han gik ind i Pharisæerens Huus, og sad tilbords.","Men En af Pharisæerne bad ham, at han vilde æde med ham; og han gik ind i Pharisæerens Huus, og sad tilbords."],[7,37,"Og see, der var en Kvinde i Staden, som var en Synderinde; der hun fornam, at han sad tilbords i Pharisæerens Huus, hentede hun en Alabaster-Krukke med Salve;","Og see, der var en Kvinde i Staden, som var en Synderinde; der hun fornam, at han sad tilbords i Pharisæerens Huus, hentede hun en Alabaster-Krukke med Salve;"],[7,38,"og hun stod bagved hos hans Fødder, græd og begyndte at væde hans Fødder med Taarer, og aftørrede dem med sit Hovedhaar, og kyssede hans Fødder, og salvede dem med Salve.","og hun stod bagved hos hans Fødder, græd og begyndte at væde hans Fødder med Taarer, og aftørrede dem med sit Hovedhaar, og kyssede hans Fødder, og salvede dem med Salve."],[7,39,"Men der Pharisæeren, som havde budet ham, saae det, talede han ved sig selv og sagde: dersom denne var en Prophet, vidste han jo, hvo og hvordan en Kvinde denne er, som rører ved ham; thi hun er en Synderinde.","Men der Pharisæeren, som havde budet ham, saae det, talede han ved sig selv og sagde: dersom denne var en Prophet, vidste han jo, hvo og hvordan en Kvinde denne er, som rører ved ham; thi hun er en Synderinde."],[7,40,"Og Jesus svarede og sagde til ham: Simon! jeg haver Noget at sige dig. Men han sagde: Mester! siig frem.","Og Jesus svarede og sagde til ham: Simon! jeg haver Noget at sige dig. Men han sagde: Mester! siig frem."],[7,41,"Jesus sagde: en Mand, som udlaante Penge, havde to Skyldnere; den ene var ham fem hundrede Penninge skyldig, men den anden halvtredsindstyve.","Jesus sagde: en Mand, som udlaante Penge, havde to Skyldnere; den ene var ham fem hundrede Penninge skyldig, men den anden halvtredsindstyve."],[7,42,"Men der de havde ikke at betale med, gav han dem begge det efter. Siig: hvilken af dem skal derfor elske ham meest?","Men der de havde ikke at betale med, gav han dem begge det efter. Siig: hvilken af dem skal derfor elske ham meest?"],[7,43,"Men Simon svarede og sagde: jeg holder for, den, som han eftergav meest. Men han sagde til ham: du dømte ret.","Men Simon svarede og sagde: jeg holder for, den, som han eftergav meest. Men han sagde til ham: du dømte ret."],[7,44,"Og han vendte sig til Kvinden, og sagde til Simon: seer du denne Kvinde? Jeg kom ind i dit Huus; du haver ikke givet mig Vand til mine Fødder; men denne vædede mine Fødder med Graad, og tørrede dem af med sit Hovedhaar.","Og han vendte sig til Kvinden, og sagde til Simon: seer du denne Kvinde? Jeg kom ind i dit Huus; du haver ikke givet mig Vand til mine Fødder; men denne vædede mine Fødder med Graad, og tørrede dem af med sit Hovedhaar."],[7,45,"Du gav mig intet Kys; men denne aflod ikke, fra hun kom ind, at kysse mine Fødder.","Du gav mig intet Kys; men denne aflod ikke, fra hun kom ind, at kysse mine Fødder."],[7,46,"Du salvede ikke mit Hoved med Olie; men hun salvede mine Fødder med Salve.","Du salvede ikke mit Hoved med Olie; men hun salvede mine Fødder med Salve."],[7,47,"Derfor siger jeg dig, ere hendes mange Synder hende forladne; thi hun elskede meget; men hvem Lidet forlades, elsker lidet.","Derfor siger jeg dig, ere hendes mange Synder hende forladne; thi hun elskede meget; men hvem Lidet forlades, elsker lidet."],[7,48,"Men han sagde til hende: dine Synder ere forladne!","Men han sagde til hende: dine Synder ere forladne!"],[7,49,"Da begyndte de, som sadde tilbords med ham, at sige ved sig selv: hvo er denne, som endog forlader Synder?","Da begyndte de, som sadde tilbords med ham, at sige ved sig selv: hvo er denne, som endog forlader Synder?"],[7,50,"Men han sagde til Kvinden: din Tro haver frelst dig, gak bort med Fred.","Men han sagde til Kvinden: din Tro haver frelst dig, gak bort med Fred."],[8,1,"Og det begav sig derefter, at han reiste igjennem Stæder og Byer, og prædikede og forkyndte Guds Riges Evangelium, og de Tolv med ham,","Og det begav sig derefter, at han reiste igjennem Stæder og Byer, og prædikede og forkyndte Guds Riges Evangelium, og de Tolv med ham,"],[8,2,"saa og nogle Kvinder, som vare helbredte fra onde Aander og Sygdomme, nemlig: Maria, der kaldtes Magdalene, af hvem syv Djævle vare udfarne;","saa og nogle Kvinder, som vare helbredte fra onde Aander og Sygdomme, nemlig: Maria, der kaldtes Magdalene, af hvem syv Djævle vare udfarne;"],[8,3,"og Johanna, Chuzas’, Herodes’ Fogeds, Hustru, og Susanne og mange Andre, som kom ham til Hjælp med deres Gods.","og Johanna, Chuzas’, Herodes’ Fogeds, Hustru, og Susanne og mange Andre, som kom ham til Hjælp med deres Gods."],[8,4,"Men da meget Folk kom tilsammen, og de droge til ham fra alle Stæder, sagde han ved en Lignelse:","Men da meget Folk kom tilsammen, og de droge til ham fra alle Stæder, sagde han ved en Lignelse:"],[8,5,"der gik en Sædemand ud at saae sin Sæd; og idet han saaede, faldt Noget ved Veien, og blev nedtraadt, og Himmelens Fugle aade det op.","der gik en Sædemand ud at saae sin Sæd; og idet han saaede, faldt Noget ved Veien, og blev nedtraadt, og Himmelens Fugle aade det op."],[8,6,"Og Noget faldt paa en Klippe; og der det voxte op, visnede det, fordi det ikke havde Vædske.","Og Noget faldt paa en Klippe; og der det voxte op, visnede det, fordi det ikke havde Vædske."],[8,7,"Og Noget faldt midt iblandt Torne, og Tornene voxte op med og kvalte det.","Og Noget faldt midt iblandt Torne, og Tornene voxte op med og kvalte det."],[8,8,"Og Noget faldt i god Jord, og det voxte op og bar hundredefold Frugt. Der han dette sagde, raabte han: hvo som haver Øren at høre med, han høre!","Og Noget faldt i god Jord, og det voxte op og bar hundredefold Frugt. Der han dette sagde, raabte han: hvo som haver Øren at høre med, han høre!"],[8,9,"Men hans Disciple spurgte ham, hvad denne Lignelse skulle betyde?","Men hans Disciple spurgte ham, hvad denne Lignelse skulle betyde?"],[8,10,"Men han sagde: Eder er det givet at vide Guds Riges Hemmeligheder, men de Andre ved Lignelser, at de Seende skulle ikke see, og de Hørende ikke forstaae.","Men han sagde: Eder er det givet at vide Guds Riges Hemmeligheder, men de Andre ved Lignelser, at de Seende skulle ikke see, og de Hørende ikke forstaae."],[8,11,"Men dette er Lignelsen: Sæden er Guds Ord.","Men dette er Lignelsen: Sæden er Guds Ord."],[8,12,"Men de ved Veien ere de, som det høre; derefter kommer Djævelen og tager Ordet af deres Hjerte, at de ikke skulle troe og blive salige.","Men de ved Veien ere de, som det høre; derefter kommer Djævelen og tager Ordet af deres Hjerte, at de ikke skulle troe og blive salige."],[8,13,"Men de paa Klippen ere de, som annamme Ordet med Glæde, naar de høre det, og disse have ikke Rod; de troe til en Tid og falde fra i Fristelsens Tid.","Men de paa Klippen ere de, som annamme Ordet med Glæde, naar de høre det, og disse have ikke Rod; de troe til en Tid og falde fra i Fristelsens Tid."],[8,14,"Men det, som faldt iblandt Torne, ere de, som det høre; og de gaae hen og kvæles under dette Livs Bekymringer og Rigdom og Vellyster, og bære ingen fuldkommen Frugt.","Men det, som faldt iblandt Torne, ere de, som det høre; og de gaae hen og kvæles under dette Livs Bekymringer og Rigdom og Vellyster, og bære ingen fuldkommen Frugt."],[8,15,"Men det i den gode Jord ere de, hvilke, naar de høre Ordet, beholde det i et smukt og godt Hjerte, og bære Frugt i Taalmodighed.","Men det i den gode Jord ere de, hvilke, naar de høre Ordet, beholde det i et smukt og godt Hjerte, og bære Frugt i Taalmodighed."],[8,16,"Men Ingen, som tænder et Lys skjuler det med et Kar, eller sætter det under en Bænk; men han sætter det paa en Lysestage, at de, som komme ind, kunne see Lyset.","Men Ingen, som tænder et Lys skjuler det med et Kar, eller sætter det under en Bænk; men han sætter det paa en Lysestage, at de, som komme ind, kunne see Lyset."],[8,17,"Thi der er Intet skjult, som jo skal blive aabenbaret; og Intet er hemmeligt, som jo skal blive kjendt og komme for Lyset.","Thi der er Intet skjult, som jo skal blive aabenbaret; og Intet er hemmeligt, som jo skal blive kjendt og komme for Lyset."],[8,18,"Seer derfor til, hvorledes I høre; thi hvo som haver, ham skal gives; og hvo som ikke haver, fra ham skal og tages det, han synes at have.","Seer derfor til, hvorledes I høre; thi hvo som haver, ham skal gives; og hvo som ikke haver, fra ham skal og tages det, han synes at have."],[8,19,"Men hans Moder og Brødre kom til ham, og kunde ikke komme ham i Tale for Folket.","Men hans Moder og Brødre kom til ham, og kunde ikke komme ham i Tale for Folket."],[8,20,"Og det blev ham tilkjendegivet af Nogle, som sagde: din Moder og dine Brødre staae udenfor, og begjere at see dig.","Og det blev ham tilkjendegivet af Nogle, som sagde: din Moder og dine Brødre staae udenfor, og begjere at see dig."],[8,21,"Men han svarede og sagde til dem: min Moder og mine Brødre ere disse, som høre Guds Ord og gjøre det.","Men han svarede og sagde til dem: min Moder og mine Brødre ere disse, som høre Guds Ord og gjøre det."],[8,22,"Og det begav sig en Dag, at han traadte i et Skib tilligemed sine Disciple, og han sagde til dem: lader os fare over Søen; og de fore ud.","Og det begav sig en Dag, at han traadte i et Skib tilligemed sine Disciple, og han sagde til dem: lader os fare over Søen; og de fore ud."],[8,23,"Men der de seilede, faldt han i Søvn, og en Storm reiste sig paa Søen, og Skibet blev fuldt af Vand, og de vare i Fare.","Men der de seilede, faldt han i Søvn, og en Storm reiste sig paa Søen, og Skibet blev fuldt af Vand, og de vare i Fare."],[8,24,"Da traadte de til ham, og vakte ham og sagde: Mester, Mester! vi forgaae. Men han stod op og truede Veiret og Vandets Bølger; og de lagde sig, og det blev blikstille.","Da traadte de til ham, og vakte ham og sagde: Mester, Mester! vi forgaae. Men han stod op og truede Veiret og Vandets Bølger; og de lagde sig, og det blev blikstille."],[8,25,"Da sagde han til dem: hvor er Eders Tro? Men de forfærdedes, og forundrede sig og sagde til hverandre: hvo er dog denne? Thi han byder baade over Veir og Vand, og de ere ham lydige.","Da sagde han til dem: hvor er Eders Tro? Men de forfærdedes, og forundrede sig og sagde til hverandre: hvo er dog denne? Thi han byder baade over Veir og Vand, og de ere ham lydige."],[8,26,"Og de seilede frem til Gadarenernes Egn, hvilken er tvert over for Galilæa.","Og de seilede frem til Gadarenernes Egn, hvilken er tvert over for Galilæa."],[8,27,"Men der han traadte ud paa Landet, mødte han en Mand af Staden, som i lang Tid havde været besat af Djævle, som ikke tog Klæder paa og ikke blev i Huus, men iblandt Gravene.","Men der han traadte ud paa Landet, mødte han en Mand af Staden, som i lang Tid havde været besat af Djævle, som ikke tog Klæder paa og ikke blev i Huus, men iblandt Gravene."],[8,28,"Men der han saae Jesus, raabte han og faldt ned for ham og sagde med høi Røst: hvad haver jeg med dig at skaffe, Jesus, den allerhøieste Guds Søn? jeg beder dig, at du ikke vil pine mig.","Men der han saae Jesus, raabte han og faldt ned for ham og sagde med høi Røst: hvad haver jeg med dig at skaffe, Jesus, den allerhøieste Guds Søn? jeg beder dig, at du ikke vil pine mig."],[8,29,"Thi han bød den urene Aand at fare ud af Mennesket; thi i lang Tid havde den sledet ham, og han havde været bunden med Lænker og Bøier og bevogtet, og han havde sønderrevet Baandene, og var dreven af Djævelen i Ørknerne.","Thi han bød den urene Aand at fare ud af Mennesket; thi i lang Tid havde den sledet ham, og han havde været bunden med Lænker og Bøier og bevogtet, og han havde sønderrevet Baandene, og var dreven af Djævelen i Ørknerne."],[8,30,"Men Jesus spurgte ham og sagde: hvad hedder du? Men han sagde: Legion; thi mange Djævle vare farne i ham.","Men Jesus spurgte ham og sagde: hvad hedder du? Men han sagde: Legion; thi mange Djævle vare farne i ham."],[8,31,"Og de bade ham, at han ikke vilde byde dem fare hen i Afgrunden.","Og de bade ham, at han ikke vilde byde dem fare hen i Afgrunden."],[8,32,"Men der var sammesteds en stor Hjord Sviin, som græssede paa Bjerget; og de bade ham, at han vilde tilstede dem at fare i dem; og han tilstedte dem det.","Men der var sammesteds en stor Hjord Sviin, som græssede paa Bjerget; og de bade ham, at han vilde tilstede dem at fare i dem; og han tilstedte dem det."],[8,33,"Men Djævelene fore ud af Mennesket og fore i Svinene, og Hjorden styrtede sig ned af Brinken og druknede.","Men Djævelene fore ud af Mennesket og fore i Svinene, og Hjorden styrtede sig ned af Brinken og druknede."],[8,34,"Men der Hyrderne saae det, som var skeet, flyede de og gik hen og kundgjorde det i Staden og paa Landet.","Men der Hyrderne saae det, som var skeet, flyede de og gik hen og kundgjorde det i Staden og paa Landet."],[8,35,"Da gik de ud, at see det, som var skeet, og kom til Jesus og fandt det Menneske, af hvem Djævelene vare uddrevne, siddende ved Jesu Fødder, paaklædt og ved Sands; og de forfærdedes.","Da gik de ud, at see det, som var skeet, og kom til Jesus og fandt det Menneske, af hvem Djævelene vare uddrevne, siddende ved Jesu Fødder, paaklædt og ved Sands; og de forfærdedes."],[8,36,"Men de, som havde seet det, kundgjorde dem ogsaa, hvorledes den Besatte var bleven frelst.","Men de, som havde seet det, kundgjorde dem ogsaa, hvorledes den Besatte var bleven frelst."],[8,37,"Og den hele Mængde af Gadarenernes Land bade ham, at han vilde gaae bort; thi de vare betagne med stor Frygt. Men han traadte i Skibet, og vendte tilbage igjen.","Og den hele Mængde af Gadarenernes Land bade ham, at han vilde gaae bort; thi de vare betagne med stor Frygt. Men han traadte i Skibet, og vendte tilbage igjen."],[8,38,"Men Manden, af hvem Djævelene vare udfarne, bad ham, at han maatte være hos ham; men Jesus lod ham fare og sagde:","Men Manden, af hvem Djævelene vare udfarne, bad ham, at han maatte være hos ham; men Jesus lod ham fare og sagde:"],[8,39,"vend tilbage til dit Huus, og fortæl, hvor store Ting Gud haver gjort dig. Og han gik bort og forkyndte igjennem den ganske Stad, hvor store Ting Jesus havde gjort ham.","vend tilbage til dit Huus, og fortæl, hvor store Ting Gud haver gjort dig. Og han gik bort og forkyndte igjennem den ganske Stad, hvor store Ting Jesus havde gjort ham."],[8,40,"Men det begav sig, der Jesus kom tilbage, kom Folket imod ham; thi de forventede ham alle.","Men det begav sig, der Jesus kom tilbage, kom Folket imod ham; thi de forventede ham alle."],[8,41,"Og see, der kom en Mand, som hedte Jairus, og han var Forstander for Synagogen; og han faldt ned for Jesu Fødder, og bad ham at komme ind i hans Huus;","Og see, der kom en Mand, som hedte Jairus, og han var Forstander for Synagogen; og han faldt ned for Jesu Fødder, og bad ham at komme ind i hans Huus;"],[8,42,"Thi han havde en eenbaaren Datter ved tolv Aar gammel, og hun droges med Døden. Men idet han gik, trængte Folket ham.","Thi han havde en eenbaaren Datter ved tolv Aar gammel, og hun droges med Døden. Men idet han gik, trængte Folket ham."],[8,43,"Og en Kvinde, som havde havt Blodflod i tolv Aar, og havde kostet al sin Formue paa Læger, og kunde ikke blive helbredt af Nogen.","Og en Kvinde, som havde havt Blodflod i tolv Aar, og havde kostet al sin Formue paa Læger, og kunde ikke blive helbredt af Nogen."],[8,44,"Hun gik til bagfra, og rørte ved Sømmen af hans Klædebon, og strax stilledes hendes Blodflod.","Hun gik til bagfra, og rørte ved Sømmen af hans Klædebon, og strax stilledes hendes Blodflod."],[8,45,"Og Jesus sagde: hvo var det, som rørte ved mig? Men der Alle negtede det, sagde Peter og de, som vare med ham: Mester! Folket trykker og trænger dig, og du siger: hvo var det, som rørte ved mig?","Og Jesus sagde: hvo var det, som rørte ved mig? Men der Alle negtede det, sagde Peter og de, som vare med ham: Mester! Folket trykker og trænger dig, og du siger: hvo var det, som rørte ved mig?"],[8,46,"Men Jesus sagde: der rørte Nogen ved mig; thi jeg fornam, at der udgik en Kraft fra mig.","Men Jesus sagde: der rørte Nogen ved mig; thi jeg fornam, at der udgik en Kraft fra mig."],[8,47,"Men der Kvinden saae, at det ikke var skjult, kom hun bævende, og faldt ned for ham, og bekjendte for ham i alt Folkets Paahør, af hvad Aarsag hun havde rørt ved ham, og hvorledes hun strax var bleven helbredet.","Men der Kvinden saae, at det ikke var skjult, kom hun bævende, og faldt ned for ham, og bekjendte for ham i alt Folkets Paahør, af hvad Aarsag hun havde rørt ved ham, og hvorledes hun strax var bleven helbredet."],[8,48,"Men han sagde til hende: vær frimodig, min Datter! din Tro haver frelst dig; gak bort med Fred.","Men han sagde til hende: vær frimodig, min Datter! din Tro haver frelst dig; gak bort med Fred."],[8,49,"Der han endnu talede, kom En fra Synagogforstanderens Huus og sagde til ham: din Datter er død; umag ikke Mesteren.","Der han endnu talede, kom En fra Synagogforstanderens Huus og sagde til ham: din Datter er død; umag ikke Mesteren."],[8,50,"Men der Jesus det hørte, svarede han ham og sagde: frygt ikke; tro ikkun, saa skal hun blive frelst.","Men der Jesus det hørte, svarede han ham og sagde: frygt ikke; tro ikkun, saa skal hun blive frelst."],[8,51,"Men der han kom i Huset, lod han han Ingen gaae ind, uden Peter og Jakob og Johannes og Pigens Fader og Moder.","Men der han kom i Huset, lod han han Ingen gaae ind, uden Peter og Jakob og Johannes og Pigens Fader og Moder."],[8,52,"Men de græd alle og holdt Veeklage over hende; men han sagde græder ikke; hun er ikke død, men sover.","Men de græd alle og holdt Veeklage over hende; men han sagde græder ikke; hun er ikke død, men sover."],[8,53,"Og de beloe ham; thi de vidste, at hun var død.","Og de beloe ham; thi de vidste, at hun var død."],[8,54,"Men han drev dem alle ud, og tog fat paa hendes Haand, og raabte og sagde: Pige, staa op!","Men han drev dem alle ud, og tog fat paa hendes Haand, og raabte og sagde: Pige, staa op!"],[8,55,"Og hendes Aand kom igjen, og hun stod strax op; og han befoel, at han skulde give hende at æde.","Og hendes Aand kom igjen, og hun stod strax op; og han befoel, at han skulde give hende at æde."],[8,56,"Og hendes Forældre bleve saare forfærdede; men han bød dem, at de ikke skulde sige Nogen det, som var skeet.","Og hendes Forældre bleve saare forfærdede; men han bød dem, at de ikke skulde sige Nogen det, som var skeet."],[9,1,"Men han kaldte sine tolv Disciple tilsammen, og gav dem Magt og Myndighed over alle Djævle og til at helbrede Sygdomme,","Men han kaldte sine tolv Disciple tilsammen, og gav dem Magt og Myndighed over alle Djævle og til at helbrede Sygdomme,"],[9,2,"og sendte dem ud at prædike Guds Rige og at helbrede de Syge.","og sendte dem ud at prædike Guds Rige og at helbrede de Syge."],[9,3,"Og han sagde til dem: tager Intet med paa Veien, hverken Stave, ei heller Taske, ei heller Brød, ei heller Penge, ei heller skal hver have to Kjortler.","Og han sagde til dem: tager Intet med paa Veien, hverken Stave, ei heller Taske, ei heller Brød, ei heller Penge, ei heller skal hver have to Kjortler."],[9,4,"Og i hvilket Huus I gaae ind, bliver der, og drager derfra bort.","Og i hvilket Huus I gaae ind, bliver der, og drager derfra bort."],[9,5,"Og hvorsomhelst de ikke ville annamme Eder, gaaer ud af den Stad, og afryster endog Støvet af Eders Fødder til et Vidnesbyrd imod dem.","Og hvorsomhelst de ikke ville annamme Eder, gaaer ud af den Stad, og afryster endog Støvet af Eders Fødder til et Vidnesbyrd imod dem."],[9,6,"Men de gik ud og droge fra By til By, prædikede Evangelium og helbredte allevegne.","Men de gik ud og droge fra By til By, prædikede Evangelium og helbredte allevegne."],[9,7,"Men Herodes den Fjerdingsfyrste hørte alt det, som han gjorde; og han kom i Tvivl, fordi Nogle sagde, at Johannes var opvakt fra de Døde;","Men Herodes den Fjerdingsfyrste hørte alt det, som han gjorde; og han kom i Tvivl, fordi Nogle sagde, at Johannes var opvakt fra de Døde;"],[9,8,"men nogle, at Elias var aabenbaret; men Andre, at en Prophet, een af de gamle, var opstanden.","men nogle, at Elias var aabenbaret; men Andre, at en Prophet, een af de gamle, var opstanden."],[9,9,"Og Herodes sagde: Johannes haver jeg ladet halshugge; men hvo er denne, om hvilken jeg hører saadant? Og han søgte at faae ham at see.","Og Herodes sagde: Johannes haver jeg ladet halshugge; men hvo er denne, om hvilken jeg hører saadant? Og han søgte at faae ham at see."],[9,10,"Og Apostlerne kom tilbage og fortalte ham, hvor store Ting de havde gjort; og han tog dem til sig og veg bort afsides til et øde Sted ved en Stad, som kaldtes Bethsaida.","Og Apostlerne kom tilbage og fortalte ham, hvor store Ting de havde gjort; og han tog dem til sig og veg bort afsides til et øde Sted ved en Stad, som kaldtes Bethsaida."],[9,11,"Men der Folket fik det at vide, fulgte de efter ham; og han tog imod dem og talede til dem om Guds Rige, og helbredte dem, som havde Lægedom behov.","Men der Folket fik det at vide, fulgte de efter ham; og han tog imod dem og talede til dem om Guds Rige, og helbredte dem, som havde Lægedom behov."],[9,12,"Men Dagen begyndte at helde; da traadte de Tolv til og sagde til ham: lad Folket fare, at de kunne gaae herfra til de omliggende Byer og Landsbyer, og faae Herberge og finde Føde, thi vi ere her paa et øde Sted.","Men Dagen begyndte at helde; da traadte de Tolv til og sagde til ham: lad Folket fare, at de kunne gaae herfra til de omliggende Byer og Landsbyer, og faae Herberge og finde Føde, thi vi ere her paa et øde Sted."],[9,13,"Men han sagde til dem: giver I dem at æde. Men de sagde: vi have ikke mere end fem Brød og to Fiske, medmindre vi skulle gaae bort og kjøbe Mad til al denne Mængde.","Men han sagde til dem: giver I dem at æde. Men de sagde: vi have ikke mere end fem Brød og to Fiske, medmindre vi skulle gaae bort og kjøbe Mad til al denne Mængde."],[9,14,"Thi der vare ved fem tusinde Mænd. Men han sagde til sine Disciple: lader dem sætte sig ned i Hobe, halvtredsindstyve i hver.","Thi der vare ved fem tusinde Mænd. Men han sagde til sine Disciple: lader dem sætte sig ned i Hobe, halvtredsindstyve i hver."],[9,15,"Og de gjorde saa; og de lode dem alle sætte sig ned.","Og de gjorde saa; og de lode dem alle sætte sig ned."],[9,16,"Men han tog de fem Brød og de to Fiske og saae op mod Himmelen og velsignede dem, og han brød dem og gav Disciplene dem at lægge dem for Folket.","Men han tog de fem Brød og de to Fiske og saae op mod Himmelen og velsignede dem, og han brød dem og gav Disciplene dem at lægge dem for Folket."],[9,17,"Og de aade, og bleve alle mætte; og der optoges af Stykkerne, som bleve tilovers fra dem, tolv Kurve.","Og de aade, og bleve alle mætte; og der optoges af Stykkerne, som bleve tilovers fra dem, tolv Kurve."],[9,18,"Og det begav sig, der han var alene og bad, at hans Disciple vare hos ham; og han spurgte dem ad og sagde: hvem siger Folket mig at være?","Og det begav sig, der han var alene og bad, at hans Disciple vare hos ham; og han spurgte dem ad og sagde: hvem siger Folket mig at være?"],[9,19,"Men de svarede og sagde: de sige, du er Johannes den Døber; men Andre, Elias; men Andre, at en Prophet af de gamle er opstanden.","Men de svarede og sagde: de sige, du er Johannes den Døber; men Andre, Elias; men Andre, at en Prophet af de gamle er opstanden."],[9,20,"Men han sagde til dem: men I, hvem sige I mig at være? Da svarede Peter og sagde: Guds Christus.","Men han sagde til dem: men I, hvem sige I mig at være? Da svarede Peter og sagde: Guds Christus."],[9,21,"Men han bød dem strengeligen, at de skulde Ingen sige dette.","Men han bød dem strengeligen, at de skulde Ingen sige dette."],[9,22,"Og han sagde: det bør Menneskens Søn at lide meget og at forskydes af de Ældste og Ypperstepræster og Skriftkloge, og ihjelslaaes, og opstaae paa tredie Dag.","Og han sagde: det bør Menneskens Søn at lide meget og at forskydes af de Ældste og Ypperstepræster og Skriftkloge, og ihjelslaaes, og opstaae paa tredie Dag."],[9,23,"Men Men han sagde til dem alle: hvo som vil komme efter mig, skal fornegte sig selv og tage sit Kors op daglig og følge mig;","Men Men han sagde til dem alle: hvo som vil komme efter mig, skal fornegte sig selv og tage sit Kors op daglig og følge mig;"],[9,24,"thi hvo som vil frelse sit Liv, skal miste det; men hvo som mister sit Liv for min Skyld, han skal frelse det.","thi hvo som vil frelse sit Liv, skal miste det; men hvo som mister sit Liv for min Skyld, han skal frelse det."],[9,25,"Thi hvad gavner det Mennesket, om han vandt den ganske Verden, men tabte sig selv eller led Skade paa sig selv?","Thi hvad gavner det Mennesket, om han vandt den ganske Verden, men tabte sig selv eller led Skade paa sig selv?"],[9,26,"Thi hvo som skammer sig ved mig og mine Ord, ved ham skal Menneskens Søn skamme sig, naar han kommer i sin Herlighed og Faderens og de helliges Engles.","Thi hvo som skammer sig ved mig og mine Ord, ved ham skal Menneskens Søn skamme sig, naar han kommer i sin Herlighed og Faderens og de helliges Engles."],[9,27,"Men sandelig siger jeg Eder: der er Nogle af dem, som her staae, der ingenlunde skulle smage Døden, førend de see Guds Rige.","Men sandelig siger jeg Eder: der er Nogle af dem, som her staae, der ingenlunde skulle smage Døden, førend de see Guds Rige."],[9,28,"Men det begav sig ved otte Dage efter denne tale, at han tog Peter og Johannes og Jakob til sig, og gik op paa et Bjerg at bede.","Men det begav sig ved otte Dage efter denne tale, at han tog Peter og Johannes og Jakob til sig, og gik op paa et Bjerg at bede."],[9,29,"Og der han bad, blev hans Ansigts Skikkelse anderledes, og hans Klædebon blev hvidt og skinnede.","Og der han bad, blev hans Ansigts Skikkelse anderledes, og hans Klædebon blev hvidt og skinnede."],[9,30,"Og see, to Mænd talede med ham, hvilke vare Moses og Elias,","Og see, to Mænd talede med ham, hvilke vare Moses og Elias,"],[9,31,"som bleve sete i Herlighed, og talede om hans Udgang, som han skulde fuldende i Jerusalem.","som bleve sete i Herlighed, og talede om hans Udgang, som han skulde fuldende i Jerusalem."],[9,32,"Men Peter og de, som vare med ham, vare betyngede med Søvn; men der de vaagnede op, saae de hans Herlighed og de to Mænd, som stode hos ham.","Men Peter og de, som vare med ham, vare betyngede med Søvn; men der de vaagnede op, saae de hans Herlighed og de to Mænd, som stode hos ham."],[9,33,"Og det begav sig, der disse skiltes fra ham, sagde Peter til Jesus: Mester! her er godt for os at være; lader os gjøre tre Boliger, dig een, Moses een, og Elias een; dog han vidste ikke, hvad han sagde.","Og det begav sig, der disse skiltes fra ham, sagde Peter til Jesus: Mester! her er godt for os at være; lader os gjøre tre Boliger, dig een, Moses een, og Elias een; dog han vidste ikke, hvad han sagde."],[9,34,"Men idet han talede saadant, kom en Sky og overskyggede dem; men de forfærdedes, der de kom ind i Skyen.","Men idet han talede saadant, kom en Sky og overskyggede dem; men de forfærdedes, der de kom ind i Skyen."],[9,35,"Og en Røst kom af Skyen, som sagde: denne er min Søn, den Elskelige, hører ham.","Og en Røst kom af Skyen, som sagde: denne er min Søn, den Elskelige, hører ham."],[9,36,"Og idet Røsten skete, blev Jesus funden alene, og de taug og forkyndte i de Dage Ingen Noget af det, de havde seet.","Og idet Røsten skete, blev Jesus funden alene, og de taug og forkyndte i de Dage Ingen Noget af det, de havde seet."],[9,37,"Men det begav sig Dagen derefter, der de kom ned af Bjerget, da gik meget Folk ham imøde.","Men det begav sig Dagen derefter, der de kom ned af Bjerget, da gik meget Folk ham imøde."],[9,38,"Og see, en Mand iblandt Folket raabte og sagde: Mester! jeg beder dig, see til min Søn; thi han er min eenbaarne.","Og see, en Mand iblandt Folket raabte og sagde: Mester! jeg beder dig, see til min Søn; thi han er min eenbaarne."],[9,39,"Og see, en Aand griber ham, og strax skriger han, og den slider ham saa, at han fraader, og med Nød viger den fra ham, naar den haver piint ham;","Og see, en Aand griber ham, og strax skriger han, og den slider ham saa, at han fraader, og med Nød viger den fra ham, naar den haver piint ham;"],[9,40,"og jeg bad dine Disciple, at de skulde uddrive den; og de kunde ikke.","og jeg bad dine Disciple, at de skulde uddrive den; og de kunde ikke."],[9,41,"Men Jesus svarede og sagde: o du vantro og forvendte Slægt! hvorlænge skal jeg være hos Eder og taale Eder? Før din Søn herhid.","Men Jesus svarede og sagde: o du vantro og forvendte Slægt! hvorlænge skal jeg være hos Eder og taale Eder? Før din Søn herhid."],[9,42,"Men der han kom til ham, rev og sled Djævelen ham. Men Jesus truede den urene Aand, og helbredte Drengen, og gav hans Fader ham igjen.","Men der han kom til ham, rev og sled Djævelen ham. Men Jesus truede den urene Aand, og helbredte Drengen, og gav hans Fader ham igjen."],[9,43,"Men de bleve alle saare forfærdede over Guds Majestæt.","Men de bleve alle saare forfærdede over Guds Majestæt."],[9,44,"Men der de alle forundrede sig over alt det, Jesus gjorde, sagde han til sine Disciple: gjemmer I udi Eders Øren disse Ord: Menneskens Søn skal overantvordes i Menneskers Hænder.","Men der de alle forundrede sig over alt det, Jesus gjorde, sagde han til sine Disciple: gjemmer I udi Eders Øren disse Ord: Menneskens Søn skal overantvordes i Menneskers Hænder."],[9,45,"Men dette Ord forstode de ikke, og det var skjult for dem, saa at de ikke begrebe det, og de frygtede at spørge ham om dette Ord.","Men dette Ord forstode de ikke, og det var skjult for dem, saa at de ikke begrebe det, og de frygtede at spørge ham om dette Ord."],[9,46,"Men der opstod den Tanke hos dem, hvo af dem vel skulde være den Største.","Men der opstod den Tanke hos dem, hvo af dem vel skulde være den Største."],[9,47,"Men der Jesus saae deres Hjerters Tanke, tog han et Barn og stillede det hos sig.","Men der Jesus saae deres Hjerters Tanke, tog han et Barn og stillede det hos sig."],[9,48,"Og han sagde til dem: hvo som annammer dette lidet Barn i mit Navn, annammer mig; og hvo mig annammer, annammer den, som mig udsendte; thi hvo som er den Mindste iblandt Eder alle, han skal være stor.","Og han sagde til dem: hvo som annammer dette lidet Barn i mit Navn, annammer mig; og hvo mig annammer, annammer den, som mig udsendte; thi hvo som er den Mindste iblandt Eder alle, han skal være stor."],[9,49,"Men Johannes svarede og sagde: Mester! vi saae Een, som uddrev Djævle i dit Navn; og vi forbøde ham det, fordi han ikke følger med os.","Men Johannes svarede og sagde: Mester! vi saae Een, som uddrev Djævle i dit Navn; og vi forbøde ham det, fordi han ikke følger med os."],[9,50,"Og Jesus sagde til ham: forbyder ham det ikke; thi hvo som ikke er imod os, er med os.","Og Jesus sagde til ham: forbyder ham det ikke; thi hvo som ikke er imod os, er med os."],[9,51,"Men det begav sig, der de Dage fuldkommedes, at han skulde optages, da vendte han stadelig sit Ansigt at vandre til Jerusalem.","Men det begav sig, der de Dage fuldkommedes, at han skulde optages, da vendte han stadelig sit Ansigt at vandre til Jerusalem."],[9,52,"Og han sendte Bud for sig, og de gik bort og kom ind i en af Samaritanernes Byer, at berede ham Herberge.","Og han sendte Bud for sig, og de gik bort og kom ind i en af Samaritanernes Byer, at berede ham Herberge."],[9,53,"Og de annammede ham ikke, fordi hans Ansigt var vendt mod Jerusalem.","Og de annammede ham ikke, fordi hans Ansigt var vendt mod Jerusalem."],[9,54,"Men der hans Disciple, Johannes og Jakob, saae det, sagde de: Herre! vil du, at vi skulle byde Ild falde ned af Himmelen og fortære dem, ligesom og Elias gjorde?","Men der hans Disciple, Johannes og Jakob, saae det, sagde de: Herre! vil du, at vi skulle byde Ild falde ned af Himmelen og fortære dem, ligesom og Elias gjorde?"],[9,55,"Men han vendte sig og straffede dem, og sagde: I vide ikke, af hvad Aand I ere.","Men han vendte sig og straffede dem, og sagde: I vide ikke, af hvad Aand I ere."],[9,56,"thi Menneskens Søn er ikke kommen at fordærve Menneskers Sjæle, men at frelse dem. Og de gik til en anden By.","thi Menneskens Søn er ikke kommen at fordærve Menneskers Sjæle, men at frelse dem. Og de gik til en anden By."],[9,57,"Men det begav sig, der de gik paa Veien, sagde En til ham: Herre! jeg vil følge dig, i hvor du gaaer hen.","Men det begav sig, der de gik paa Veien, sagde En til ham: Herre! jeg vil følge dig, i hvor du gaaer hen."],[9,58,"Men Jesus sagde til ham: Ræve have Huler, og Himmelens Fugle Reder; men Menneskens Søn haver ikke det, han kan helde sit Hoved til.","Men Jesus sagde til ham: Ræve have Huler, og Himmelens Fugle Reder; men Menneskens Søn haver ikke det, han kan helde sit Hoved til."],[9,59,"Men han sagde til en Anden: følg mig. Men denne sagde: Herre! tilsted mig, at jeg først gaaer hen at begrave min Fader.","Men han sagde til en Anden: følg mig. Men denne sagde: Herre! tilsted mig, at jeg først gaaer hen at begrave min Fader."],[9,60,"Men Jesus sagde til ham: lad de Døde begrave deres Døde; men gak du hen, og forkynd Guds Rige.","Men Jesus sagde til ham: lad de Døde begrave deres Døde; men gak du hen, og forkynd Guds Rige."],[9,61,"Men og en Anden sagde: Herre! jeg vil følge dig; men tilsted mig først at tage Afsked fra dem, som ere i mit Huus.","Men og en Anden sagde: Herre! jeg vil følge dig; men tilsted mig først at tage Afsked fra dem, som ere i mit Huus."],[9,62,"Men Jesus sagde til ham: Ingen, som lægger sin Haand paa Ploven, og seer tilbage, er vel skikket til Guds Rige.","Men Jesus sagde til ham: Ingen, som lægger sin Haand paa Ploven, og seer tilbage, er vel skikket til Guds Rige."],[10,1,"Men derefter beskikkede Herren og halvfjerdsindstyve Andre, og sendte dem ud to og to for sig, til hver Stad og hvert Sted, hvorhen han selv vilde komme.","Men derefter beskikkede Herren og halvfjerdsindstyve Andre, og sendte dem ud to og to for sig, til hver Stad og hvert Sted, hvorhen han selv vilde komme."],[10,2,"Og han sagde til dem: Høsten er vel stor, men Arbeiderne ere faa; beder derfor Høstens Herre, at han udsender Arbeidere i sin Høst.","Og han sagde til dem: Høsten er vel stor, men Arbeiderne ere faa; beder derfor Høstens Herre, at han udsender Arbeidere i sin Høst."],[10,3,"Gaaer bort! See, jeg sender Eder som Lam midt iblandt Ulve.","Gaaer bort! See, jeg sender Eder som Lam midt iblandt Ulve."],[10,4,"Bærer ikke Pung ei heller Taske, ei heller Skoe; og hilser Ingen paa Veien!","Bærer ikke Pung ei heller Taske, ei heller Skoe; og hilser Ingen paa Veien!"],[10,5,"Men hvor som I komme ind i et Huus, der siger først: Fred være med dette Huus.","Men hvor som I komme ind i et Huus, der siger først: Fred være med dette Huus."],[10,6,"Og er der sammesteds et Fredens Barn, skal Eders Fred hvile paa ham; men er der ingen, da skal den vende til Eder igjen.","Og er der sammesteds et Fredens Barn, skal Eders Fred hvile paa ham; men er der ingen, da skal den vende til Eder igjen."],[10,7,"Men bliver i det samme Huus, æder og drikker, hvad de have; thi en Arbeider er sin Løn værd. I skulle ikke gaae fra Huus til Huus.","Men bliver i det samme Huus, æder og drikker, hvad de have; thi en Arbeider er sin Løn værd. I skulle ikke gaae fra Huus til Huus."],[10,8,"Og hvor I komme ind i en Stad, og de annamme Eder, da æder, hvad Eder foresættes;","Og hvor I komme ind i en Stad, og de annamme Eder, da æder, hvad Eder foresættes;"],[10,9,"og helbreder de Syge, som deri ere, og siger dem: Guds Rige er kommet nær til Eder.","og helbreder de Syge, som deri ere, og siger dem: Guds Rige er kommet nær til Eder."],[10,10,"Men hvor I komme ind i en Stad, og de ikke annamme Eder, da gaaer ud paa dens Gader og siger:","Men hvor I komme ind i en Stad, og de ikke annamme Eder, da gaaer ud paa dens Gader og siger:"],[10,11,"vi afstryge for Eder endog det Støv, som hænger ved os af Eders Stad; dog skulle I vide dette, at Guds Rige haver været nær hos Eder.","vi afstryge for Eder endog det Støv, som hænger ved os af Eders Stad; dog skulle I vide dette, at Guds Rige haver været nær hos Eder."],[10,12,"Men jeg siger Eder, det skal gaae Sodoma lideligere paa hiin Dag, end denne Stad.","Men jeg siger Eder, det skal gaae Sodoma lideligere paa hiin Dag, end denne Stad."],[10,13,"Vee dig, Chorazin! vee dig, Bethsaida! thi vare de kraftige Gjerninger skete i Thyrus og Sidon, som ere skete hos Eder, havde de længe siden siddet i Sæk og Aske og omvendt sig.","Vee dig, Chorazin! vee dig, Bethsaida! thi vare de kraftige Gjerninger skete i Thyrus og Sidon, som ere skete hos Eder, havde de længe siden siddet i Sæk og Aske og omvendt sig."],[10,14,"Dog skal det gaae Thyrus og Sidon lideligere i Dommen end Eder.","Dog skal det gaae Thyrus og Sidon lideligere i Dommen end Eder."],[10,15,"Og du, Capernaum! som er ophøiet indtil Himmelen, du skal nedstødes indtil Helvede.","Og du, Capernaum! som er ophøiet indtil Himmelen, du skal nedstødes indtil Helvede."],[10,16,"Hvo som Eder hører, hører mig, og hvo som Eder foragter, foragter mig; men hvo mig foragter, foragter den, som mig udsendte.","Hvo som Eder hører, hører mig, og hvo som Eder foragter, foragter mig; men hvo mig foragter, foragter den, som mig udsendte."],[10,17,"Men de Halvfjerdsindstyve kom igjen med Glæde og sagde: Herre! ogsaa Djævelene ere os underdanige i dit Navn.","Men de Halvfjerdsindstyve kom igjen med Glæde og sagde: Herre! ogsaa Djævelene ere os underdanige i dit Navn."],[10,18,"Men han sagde til dem: jeg saae, at Satanas faldt ned af Himmelen, som et Lyn.","Men han sagde til dem: jeg saae, at Satanas faldt ned af Himmelen, som et Lyn."],[10,19,"See, jeg giver Eder Magt at træde paa Slanger og Skorpioner og over al Fjendens Kraft, og slet Intet skal skade Eder.","See, jeg giver Eder Magt at træde paa Slanger og Skorpioner og over al Fjendens Kraft, og slet Intet skal skade Eder."],[10,20,"Dog glæder Eder ikke derover, at Aanderne ere Eder underdanige: men glæder Eder mere, at Eders Navne ere Skrevne i Himlene.","Dog glæder Eder ikke derover, at Aanderne ere Eder underdanige: men glæder Eder mere, at Eders Navne ere Skrevne i Himlene."],[10,21,"I den samme Stund frydede Jesus sig i Aanden og sagde: jeg priser dig, Fader, Himmelens og Jordens Herre! at du haver skjult disse Ting for de Vise og Forstandige, og aabenbaret de Umyndige dem. Ja, Fader! thi det var saaledes behageligt for dig.","I den samme Stund frydede Jesus sig i Aanden og sagde: jeg priser dig, Fader, Himmelens og Jordens Herre! at du haver skjult disse Ting for de Vise og Forstandige, og aabenbaret de Umyndige dem. Ja, Fader! thi det var saaledes behageligt for dig."],[10,22,"Alle Ting ere mig overgivne af min Fader; og Ingen kjender, hvo Sønnen er, uden Faderen, og hvo Faderen er, uden Sønnen, og hvem Sønnen vil aabenbare det.","Alle Ting ere mig overgivne af min Fader; og Ingen kjender, hvo Sønnen er, uden Faderen, og hvo Faderen er, uden Sønnen, og hvem Sønnen vil aabenbare det."],[10,23,"Og han vendte sig til Disciplene i Særdeleshed og sagde til dem: salige ere de Øine, som see det, I see.","Og han vendte sig til Disciplene i Særdeleshed og sagde til dem: salige ere de Øine, som see det, I see."],[10,24,"Thi jeg siger Eder, at mange Propheter og Konger vilde seet det, I see, og have det ikke seet; og hørt det, I høre, og have det ikke hørt.","Thi jeg siger Eder, at mange Propheter og Konger vilde seet det, I see, og have det ikke seet; og hørt det, I høre, og have det ikke hørt."],[10,25,"Og see, en Lovkyndig stod op, og fristede ham, og sagde: Mester! hvad skal jeg gjøre, at jeg kan arve et evigt Liv?","Og see, en Lovkyndig stod op, og fristede ham, og sagde: Mester! hvad skal jeg gjøre, at jeg kan arve et evigt Liv?"],[10,26,"Men han sagde til ham: hvad er skrevet i Loven, hvorledes læser du?","Men han sagde til ham: hvad er skrevet i Loven, hvorledes læser du?"],[10,27,"Men han svarede og sagde til ham: du skal elske Herren din Gud af dit ganske Hjerte, og af din ganske Sjæl, og af din ganske Styrke, og af dit ganske Sind, og din Næste som dig selv.","Men han svarede og sagde til ham: du skal elske Herren din Gud af dit ganske Hjerte, og af din ganske Sjæl, og af din ganske Styrke, og af dit ganske Sind, og din Næste som dig selv."],[10,28,"Men han sagde til ham: du svarede ret; gjør dette, saa skal du leve.","Men han sagde til ham: du svarede ret; gjør dette, saa skal du leve."],[10,29,"Men han vilde gjøre sig selv retfærdig, og sagde til Jesus: hvo er da min Næste?","Men han vilde gjøre sig selv retfærdig, og sagde til Jesus: hvo er da min Næste?"],[10,30,"Men Jesus svarede og sagde: et Menneske gik fra Jerusalem til Jericho, og faldt iblandt Røvere, hvilke baade klædte ham af, og sloge ham, og gik bort, og lode ham ligge halvdød.","Men Jesus svarede og sagde: et Menneske gik fra Jerusalem til Jericho, og faldt iblandt Røvere, hvilke baade klædte ham af, og sloge ham, og gik bort, og lode ham ligge halvdød."],[10,31,"Men ved en Hændelse drog en Præst den samme Vei ned, og der han saae ham, gik han forbi.","Men ved en Hændelse drog en Præst den samme Vei ned, og der han saae ham, gik han forbi."],[10,32,"Desligeste ogsaa en Levit, der han kom til Stedet, gik han til, og saae ham, og gik forbi.","Desligeste ogsaa en Levit, der han kom til Stedet, gik han til, og saae ham, og gik forbi."],[10,33,"Men en Samaritan reiste, og kom til ham, og der han saae ham, ynkedes han inderligen.","Men en Samaritan reiste, og kom til ham, og der han saae ham, ynkedes han inderligen."],[10,34,"Og han gik til ham, forbandt hans Saar og gød Olie og Viin derudi, løftede ham paa sit eget Dyr og førte ham til Herberge og røgtede ham.","Og han gik til ham, forbandt hans Saar og gød Olie og Viin derudi, løftede ham paa sit eget Dyr og førte ham til Herberge og røgtede ham."],[10,35,"Og den anden Dag, der han reiste bort, tog han to Penge ud og gav Værten dem og sagde til ham: røgt ham! og hvad du udlægger mere, vil jeg betale dig, naar jeg kommer igjen.","Og den anden Dag, der han reiste bort, tog han to Penge ud og gav Værten dem og sagde til ham: røgt ham! og hvad du udlægger mere, vil jeg betale dig, naar jeg kommer igjen."],[10,36,"Hvilken af disse Tre tykkes dig nu at have været hans Næste, der var falden iblandt Røvere?","Hvilken af disse Tre tykkes dig nu at have været hans Næste, der var falden iblandt Røvere?"],[10,37,"Men han sagde: den, som gjorde Barmhjertighed imod ham. Derfor sagde Jesus til ham: gak bort, og gjør du ligesaa!","Men han sagde: den, som gjorde Barmhjertighed imod ham. Derfor sagde Jesus til ham: gak bort, og gjør du ligesaa!"],[10,38,"Men det begav sig, der de vandrede, gik han ind i en By; men der var en Kvinde, som hedte Martha, hun annammede ham i sit Huus.","Men det begav sig, der de vandrede, gik han ind i en By; men der var en Kvinde, som hedte Martha, hun annammede ham i sit Huus."],[10,39,"Og hun havde en Søster, som hedte Maria, og hun satte sig ved Jesu Fødder og hørte hans Tale.","Og hun havde en Søster, som hedte Maria, og hun satte sig ved Jesu Fødder og hørte hans Tale."],[10,40,"Men Martha syslede med megen Opvartning; og hun traadte til og sagde: Herre! agter du ikke paa, at min Søster lader mig opvarte ene? Siig hende dog, at hun kommer mig til Hjælp.","Men Martha syslede med megen Opvartning; og hun traadte til og sagde: Herre! agter du ikke paa, at min Søster lader mig opvarte ene? Siig hende dog, at hun kommer mig til Hjælp."],[10,41,"Men Jesus svarede og sagde til hende: Martha! Martha! du gjør dig Bekymring og Uro med mange Ting;","Men Jesus svarede og sagde til hende: Martha! Martha! du gjør dig Bekymring og Uro med mange Ting;"],[10,42,"men Eet er fornødent. Maria haver udvalgt den gode Deel, som ikke skal borttages fra hende.","men Eet er fornødent. Maria haver udvalgt den gode Deel, som ikke skal borttages fra hende."],[11,1,"Og det begav sig, der han var paa et Sted og bad, at en af hans Disciple sagde til ham, der han lod af: Herre! lær os at bede, som Johannes og lærte sine Disciple.","Og det begav sig, der han var paa et Sted og bad, at en af hans Disciple sagde til ham, der han lod af: Herre! lær os at bede, som Johannes og lærte sine Disciple."],[11,2,"Da sagde han til dem: naar I bede da siger: Vor Fader, du som er i Himlene! helliget vorde dit Navn; komme dit Rige; skee din Villie, som i Himmelen, saa og paa Jorden;","Da sagde han til dem: naar I bede da siger: Vor Fader, du som er i Himlene! helliget vorde dit Navn; komme dit Rige; skee din Villie, som i Himmelen, saa og paa Jorden;"],[11,3,"giv os hver Dag vort daglige Brød;","giv os hver Dag vort daglige Brød;"],[11,4,"og forlad os vore Synder, thi og vi forlade hver, som os er skyldig; og led os ikke i Fristelse; men fri os fra det Onde.","og forlad os vore Synder, thi og vi forlade hver, som os er skyldig; og led os ikke i Fristelse; men fri os fra det Onde."],[11,5,"Og han sagde til dem: om Nogen af Eder haver en Ven, og vilde gaae til ham om Midnat og sige til ham: Kjære! laan mig tre Brød,","Og han sagde til dem: om Nogen af Eder haver en Ven, og vilde gaae til ham om Midnat og sige til ham: Kjære! laan mig tre Brød,"],[11,6,"efterdi min Ven er kommen til mig fra Reisen, og jeg haver Intet at sætte for ham;","efterdi min Ven er kommen til mig fra Reisen, og jeg haver Intet at sætte for ham;"],[11,7,"og han derinde skulde svare og sige: gjør mig ikke Uro; Døren er nu tillukt, og mine Børn ere med mig i Senge, jeg kan ikke staae op og give dig:","og han derinde skulde svare og sige: gjør mig ikke Uro; Døren er nu tillukt, og mine Børn ere med mig i Senge, jeg kan ikke staae op og give dig:"],[11,8,"da siger jeg Eder, dersom han og ikke staaer op og giver ham, fordi han er hans Ven, saa staaer han dog op for hans Ubluheds Skyld, og giver ham saa mange, som han haver behov.","da siger jeg Eder, dersom han og ikke staaer op og giver ham, fordi han er hans Ven, saa staaer han dog op for hans Ubluheds Skyld, og giver ham saa mange, som han haver behov."],[11,9,"Og jeg siger Eder: beder, saa skal Eder gives; leder, saa skulle I finde; banker, saa skal Eder oplades.","Og jeg siger Eder: beder, saa skal Eder gives; leder, saa skulle I finde; banker, saa skal Eder oplades."],[11,10,"Thi hver den, som beder, han faaer, og hvo som leder, han finder, og den, som banker paa, ham skal oplades.","Thi hver den, som beder, han faaer, og hvo som leder, han finder, og den, som banker paa, ham skal oplades."],[11,11,"Men dersom iblandt Eder en Søn beder sin Fader om et Brød, monne han da give ham en Steen? og dersom han beder om en Fisk, monne han for Fisken give ham en Slange?","Men dersom iblandt Eder en Søn beder sin Fader om et Brød, monne han da give ham en Steen? og dersom han beder om en Fisk, monne han for Fisken give ham en Slange?"],[11,12,"Eller og dersom han beder om et Æg, monne han give ham en Skorpion?","Eller og dersom han beder om et Æg, monne han give ham en Skorpion?"],[11,13,"Dersom da I, som ere onde, vide at give Eders Børn gode Gaver, hvor meget mere skal den himmelske Fader give dem den Hellig Aand, som han bede?","Dersom da I, som ere onde, vide at give Eders Børn gode Gaver, hvor meget mere skal den himmelske Fader give dem den Hellig Aand, som han bede?"],[11,14,"Og han uddrev en Djævel, og den var stum; men det skete, der Djævelen var udfaren, talede den Stumme, og Folket forundrede sig.","Og han uddrev en Djævel, og den var stum; men det skete, der Djævelen var udfaren, talede den Stumme, og Folket forundrede sig."],[11,15,"Men Nogle af dem sagde: han uddriver Djævle ved Beelzebul, Djævlenes Øverste.","Men Nogle af dem sagde: han uddriver Djævle ved Beelzebul, Djævlenes Øverste."],[11,16,"Men Andre fristede ham og begjerede Tegn af ham fra Himmelen.","Men Andre fristede ham og begjerede Tegn af ham fra Himmelen."],[11,17,"Men der han fornam deres Tanker, sagde ham til dem: hvert Rige, som er splidagtigt med sig selv, bliver øde, og et Huus, som er splidagtigt med sig selv, falder.","Men der han fornam deres Tanker, sagde ham til dem: hvert Rige, som er splidagtigt med sig selv, bliver øde, og et Huus, som er splidagtigt med sig selv, falder."],[11,18,"Men er og Satanas bleven splidagtig med sig selv, hvorledes skal hans Rige da blive bestandigt? Thi I sige, jeg uddriver Djævle ved Beelzebul.","Men er og Satanas bleven splidagtig med sig selv, hvorledes skal hans Rige da blive bestandigt? Thi I sige, jeg uddriver Djævle ved Beelzebul."],[11,19,"Men om jeg uddriver Djævle ved Beelzebul, ved hvem uddrive da Eders Sønner dem? Derfor skulle de vare Eders Dommere.","Men om jeg uddriver Djævle ved Beelzebul, ved hvem uddrive da Eders Sønner dem? Derfor skulle de vare Eders Dommere."],[11,20,"Men dersom jeg uddriver Djævle ved Guds Finger, da er jo Guds Rige kommet til Eder.","Men dersom jeg uddriver Djævle ved Guds Finger, da er jo Guds Rige kommet til Eder."],[11,21,"Naar den Stærke bevæbnet vogter sit Pallads, bliver det, han haver, med Fred.","Naar den Stærke bevæbnet vogter sit Pallads, bliver det, han haver, med Fred."],[11,22,"Men naar en Stærkere end han kommer over ham og overvinder ham, da borttager han hans fulde Rustning, som han forlod sig paa, og uddeler hans Bytte.","Men naar en Stærkere end han kommer over ham og overvinder ham, da borttager han hans fulde Rustning, som han forlod sig paa, og uddeler hans Bytte."],[11,23,"Hvo som ikke er med mig, er imod mig; og hvo som ikke sanker med mig, adspreder.","Hvo som ikke er med mig, er imod mig; og hvo som ikke sanker med mig, adspreder."],[11,24,"Naar den urene Aand udfarer af Mennesket, vandrer han igjennem tørre Steder og søger Hvile; og Naar han ikke finder den, da siger han: jeg vil vende om til mit Huus, som jeg gik ud af.","Naar den urene Aand udfarer af Mennesket, vandrer han igjennem tørre Steder og søger Hvile; og Naar han ikke finder den, da siger han: jeg vil vende om til mit Huus, som jeg gik ud af."],[11,25,"Og naar han kommer, finder han det feiet og prydet.","Og naar han kommer, finder han det feiet og prydet."],[11,26,"Da gaaer han bort, og tager syv andre Aander med sig, som ere værre end han selv, og naar de komme ind, boe de der; og det Sidste bliver værre med dette Menneske end det Første.","Da gaaer han bort, og tager syv andre Aander med sig, som ere værre end han selv, og naar de komme ind, boe de der; og det Sidste bliver værre med dette Menneske end det Første."],[11,27,"Men det begav sig, der han sagde disse Ting, opløftede en Kvinde af Folket Røsten og sagde til ham: saligt er det Liv, som bar dig, og de Bryster, som du diede.","Men det begav sig, der han sagde disse Ting, opløftede en Kvinde af Folket Røsten og sagde til ham: saligt er det Liv, som bar dig, og de Bryster, som du diede."],[11,28,"Men han sagde: ja, salige ere de, som høre Guds Ord, og bevare det.","Men han sagde: ja, salige ere de, som høre Guds Ord, og bevare det."],[11,29,"Men der Folket forsamledes til ham, begyndte han at sige: denne Slægt er ond, den begjerer et Tegn, og den skal intet Tegn gives, uden Jonas’ Prophetens Tegn.","Men der Folket forsamledes til ham, begyndte han at sige: denne Slægt er ond, den begjerer et Tegn, og den skal intet Tegn gives, uden Jonas’ Prophetens Tegn."],[11,30,"Thi ligesom Jonas var de Niniviter et Tegn, saa skal og Menneskens Søn være for denne Slægt.","Thi ligesom Jonas var de Niniviter et Tegn, saa skal og Menneskens Søn være for denne Slægt."],[11,31,"Dronningen fra Sønden skal opstaae ved Dommen imod Mændene af denne Slægt og skal fordømme den; thi hun kom fra Jordens Grændser, at høre Salomons Viisdom; og see, her er mere end Salomon.","Dronningen fra Sønden skal opstaae ved Dommen imod Mændene af denne Slægt og skal fordømme den; thi hun kom fra Jordens Grændser, at høre Salomons Viisdom; og see, her er mere end Salomon."],[11,32,"De Mænd af Ninive skulle opstaae ved Dommen imod denne Slægt, og fordømme den; thi de omvendte sig ved Jonas’ Prædiken; og see, her er mere end Jonas.","De Mænd af Ninive skulle opstaae ved Dommen imod denne Slægt, og fordømme den; thi de omvendte sig ved Jonas’ Prædiken; og see, her er mere end Jonas."],[11,33,"Ingen tænder et Lys, og sætter det i Skjul, ei heller under en Skjeppe, men paa en Lysestage, at de, som gaae ind, kunne see dets Skin.","Ingen tænder et Lys, og sætter det i Skjul, ei heller under en Skjeppe, men paa en Lysestage, at de, som gaae ind, kunne see dets Skin."],[11,34,"Øiet er Legemets Lys; naar dit Øie derfor er sundt, er og dit ganske Legeme lyst, men dersom det er ondt, er og dit Legeme mørkt.","Øiet er Legemets Lys; naar dit Øie derfor er sundt, er og dit ganske Legeme lyst, men dersom det er ondt, er og dit Legeme mørkt."],[11,35,"See derfor til, at det Lys, der er i dig, ikke er Mørke.","See derfor til, at det Lys, der er i dig, ikke er Mørke."],[11,36,"Dersom da dit ganske Legeme er lyst, saa at ingen Deel deraf er mørkt, bliver det hele lyst, som naar Lyset med sin Glands bestraaler dig.","Dersom da dit ganske Legeme er lyst, saa at ingen Deel deraf er mørkt, bliver det hele lyst, som naar Lyset med sin Glands bestraaler dig."],[11,37,"Men idet han talede, bad en Pharisæer ham, at han vilde æde Middagsmaaltid med ham; og han gik ind og satte sig tilbords.","Men idet han talede, bad en Pharisæer ham, at han vilde æde Middagsmaaltid med ham; og han gik ind og satte sig tilbords."],[11,38,"Men Pharisæeren forundrede sig, da han saae, at han ikke toede sig først, før Maaltid.","Men Pharisæeren forundrede sig, da han saae, at han ikke toede sig først, før Maaltid."],[11,39,"Men Herren sagde til ham: I Pharisæer rense nu Bægere og Fade udvortes, men det Indvortes i Eder er fuldt af Rov og Ondskab.","Men Herren sagde til ham: I Pharisæer rense nu Bægere og Fade udvortes, men det Indvortes i Eder er fuldt af Rov og Ondskab."],[11,40,"I Daarer! den, som gjorde det Udvortes, gjorde han ikke ogsaa det Indvortes?","I Daarer! den, som gjorde det Udvortes, gjorde han ikke ogsaa det Indvortes?"],[11,41,"Men af det Indvortes giver Almisse; see, saa ere alle Ting Eder rene.","Men af det Indvortes giver Almisse; see, saa ere alle Ting Eder rene."],[11,42,"Men vee Eder, I Pharisæer! at I give Tiende af Mynte og Rude og allehaande Urter og forbigaae Dom og Guds Kjærlighed; disse Ting burde man at gjøre, og ikke forsømme de andre.","Men vee Eder, I Pharisæer! at I give Tiende af Mynte og Rude og allehaande Urter og forbigaae Dom og Guds Kjærlighed; disse Ting burde man at gjøre, og ikke forsømme de andre."],[11,43,"Vee Eder, I Pharisæer! at I ville gjerne sidde paa det fornemste Sæde i Synagogerne og være hilsede paa Torvene.","Vee Eder, I Pharisæer! at I ville gjerne sidde paa det fornemste Sæde i Synagogerne og være hilsede paa Torvene."],[11,44,"Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I ere som ukjendelige Grave, og Menneskene, som gaae over dem, vide det ikke.","Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I ere som ukjendelige Grave, og Menneskene, som gaae over dem, vide det ikke."],[11,45,"Men en af de Lovkyndige svarede og sagde til ham: Mester! idet du siger saadant, forhaaner du og os.","Men en af de Lovkyndige svarede og sagde til ham: Mester! idet du siger saadant, forhaaner du og os."],[11,46,"Men han sagde: vee og Eder, I Lovkyndige! thi I besvære Menneskene med Byrder, vanskelige at bære, og selv røre I Byrderne ikke med en een af Eders Fingre.","Men han sagde: vee og Eder, I Lovkyndige! thi I besvære Menneskene med Byrder, vanskelige at bære, og selv røre I Byrderne ikke med en een af Eders Fingre."],[11,47,"Vee Eder! at I bygge Pharisæernes Grave, men Eders Fædre sloge dem ihjel.","Vee Eder! at I bygge Pharisæernes Grave, men Eders Fædre sloge dem ihjel."],[11,48,"Saaledes vidne I med Eders Fædres Gjerninger og samtykke dem; thi de sloge dem ihjel, og I bygge deres Grave.","Saaledes vidne I med Eders Fædres Gjerninger og samtykke dem; thi de sloge dem ihjel, og I bygge deres Grave."],[11,49,"Derfor har og Guds Viisdom sagt: jeg vil sende Propheter og Apostler til dem, og nogle af dem skulle de slaae ihjel, og forfølge andre.","Derfor har og Guds Viisdom sagt: jeg vil sende Propheter og Apostler til dem, og nogle af dem skulle de slaae ihjel, og forfølge andre."],[11,50,"paa det at alle Propheternes Blod, som er udøst fra Verdens Begyndelse, skal kræves af denne Slægt,","paa det at alle Propheternes Blod, som er udøst fra Verdens Begyndelse, skal kræves af denne Slægt,"],[11,51,"fra Abels Blod indtil Zacharias’ Blod, som blev omkommet imellem Alteret og Templet; ja, jeg siger Eder: det skal kræves af denne Slægt,","fra Abels Blod indtil Zacharias’ Blod, som blev omkommet imellem Alteret og Templet; ja, jeg siger Eder: det skal kræves af denne Slægt,"],[11,52,"Vee Eder, I lovkyndige! at I have taget Kundskabens Nøgle; selv gaae I ikke ind, og dem, som ville gaae ind, formene I det.","Vee Eder, I lovkyndige! at I have taget Kundskabens Nøgle; selv gaae I ikke ind, og dem, som ville gaae ind, formene I det."],[11,53,"Men der han sagde dette til dem, begyndte de Skriftkloge og Pharisæerne at trænge hardt ind paa ham og at lokke Ord af hans Mund om mange Ting.","Men der han sagde dette til dem, begyndte de Skriftkloge og Pharisæerne at trænge hardt ind paa ham og at lokke Ord af hans Mund om mange Ting."],[11,54,"Thi de lurede paa ham, og søgte at opfange Noget af hans Mund, at de kunde anklage ham.","Thi de lurede paa ham, og søgte at opfange Noget af hans Mund, at de kunde anklage ham."],[12,1,"Idet Folket var forsamlet ved mange Tusinde, saa at de traadte paa hverandre, begyndte han at sige til sine Disciple: fornemmeligen tager Eder vare for Pharisæernes Suurdeig, som er Øienskalkhed.","Idet Folket var forsamlet ved mange Tusinde, saa at de traadte paa hverandre, begyndte han at sige til sine Disciple: fornemmeligen tager Eder vare for Pharisæernes Suurdeig, som er Øienskalkhed."],[12,2,"Men Intet er skjult, som jo skal aabenbares, og Intet hemmeligt, som man jo skal faae at vide.","Men Intet er skjult, som jo skal aabenbares, og Intet hemmeligt, som man jo skal faae at vide."],[12,3,"Derfor, hvad I sige i Mørket, skal høres i Lyset; og hvad I tale i Øret i Kamrene, skal forkyndes paa Tagene.","Derfor, hvad I sige i Mørket, skal høres i Lyset; og hvad I tale i Øret i Kamrene, skal forkyndes paa Tagene."],[12,4,"Men jeg siger Eder, mine Venner! frygter ikke for dem, som slaae Legemet ihjel, og derefter ikke formaae at gjøre mere.","Men jeg siger Eder, mine Venner! frygter ikke for dem, som slaae Legemet ihjel, og derefter ikke formaae at gjøre mere."],[12,5,"Men jeg vil vise Eder, for hvem I skulle frygte: frygter for den, som haver Magt til, efterat have slaget ihjel, at kaste i Helvede; ja, jeg siger Eder: frygter for ham.","Men jeg vil vise Eder, for hvem I skulle frygte: frygter for den, som haver Magt til, efterat have slaget ihjel, at kaste i Helvede; ja, jeg siger Eder: frygter for ham."],[12,6,"Sælges ikke fem Spurve for to Penninge? og ikke een af dem er glemt af Gud.","Sælges ikke fem Spurve for to Penninge? og ikke een af dem er glemt af Gud."],[12,7,"Ja og Haarene paa Eders Hoved ere alle talte; derfor frygter ikke, I ere bedre end mange Spurve.","Ja og Haarene paa Eders Hoved ere alle talte; derfor frygter ikke, I ere bedre end mange Spurve."],[12,8,"Men jeg siger Eder: hver den, som bekjender mig for Menneskene, den skal og Menneskens Søn bekjende for Guds Engle.","Men jeg siger Eder: hver den, som bekjender mig for Menneskene, den skal og Menneskens Søn bekjende for Guds Engle."],[12,9,"Og hvo mig fornegter for Menneskene, skal fornegtes for Guds Engle.","Og hvo mig fornegter for Menneskene, skal fornegtes for Guds Engle."],[12,10,"Og hver den, som taler et Ord imod Menneskens Søn, ham skal det forlades; men hvo som taler bespottelig imod den Hellig Aand, ham skal det ikke forlades.","Og hver den, som taler et Ord imod Menneskens Søn, ham skal det forlades; men hvo som taler bespottelig imod den Hellig Aand, ham skal det ikke forlades."],[12,11,"Men naar de føre Eder frem for Synagoger og Øvrigheder og de Vældige, da bekymrer Eder ikke, hvorledes eller hvad I skulle tale til Eders forsvar, eller hvad I skulle sige;","Men naar de føre Eder frem for Synagoger og Øvrigheder og de Vældige, da bekymrer Eder ikke, hvorledes eller hvad I skulle tale til Eders forsvar, eller hvad I skulle sige;"],[12,12,"thi den Hellig Aand skal lære Eder i den samme Stund, hvad I bør sige.","thi den Hellig Aand skal lære Eder i den samme Stund, hvad I bør sige."],[12,13,"Men En af Folket sagde til ham: Mester! siig min Broder, at han skifter Arv med mig.","Men En af Folket sagde til ham: Mester! siig min Broder, at han skifter Arv med mig."],[12,14,"Men han sagde til ham: Menneske! hvo haver sat mig til Dommer eller Deler imellem Eder?","Men han sagde til ham: Menneske! hvo haver sat mig til Dommer eller Deler imellem Eder?"],[12,15,"Og han sagde til dem: seer til og vogter Eder for Gjerrighed; thi Ingens Liv bestaaer i at have overflødigt Gods.","Og han sagde til dem: seer til og vogter Eder for Gjerrighed; thi Ingens Liv bestaaer i at have overflødigt Gods."],[12,16,"Men han talede en Lignelse til dem og sagde: der var en rig Mand, hvis Land havde baaret vel.","Men han talede en Lignelse til dem og sagde: der var en rig Mand, hvis Land havde baaret vel."],[12,17,"Og han tænkte ved sig selv og sagde: hvad skal jeg gjøre? thi jeg haver ikke Rum, hvorudi jeg kan samle mine Frugter.","Og han tænkte ved sig selv og sagde: hvad skal jeg gjøre? thi jeg haver ikke Rum, hvorudi jeg kan samle mine Frugter."],[12,18,"Og han sagde: dette vil jeg gjøre: jeg vil nedbryde mine Lader og bygge dem større, og jeg vil samle derudi alt det, som mig er voxet, og mit Gods;","Og han sagde: dette vil jeg gjøre: jeg vil nedbryde mine Lader og bygge dem større, og jeg vil samle derudi alt det, som mig er voxet, og mit Gods;"],[12,19,"og jeg vil sige til min Sjæl: Sjæl! du haver meget Godt i Forraad til mange Aar; giv dig til Ro, æd, drik, vær glad.","og jeg vil sige til min Sjæl: Sjæl! du haver meget Godt i Forraad til mange Aar; giv dig til Ro, æd, drik, vær glad."],[12,20,"Men Gud sagde til ham: du Daare! i denne Nat kræves din Sjæl af dig: men hvem skal det høre til, som du haver beredt?","Men Gud sagde til ham: du Daare! i denne Nat kræves din Sjæl af dig: men hvem skal det høre til, som du haver beredt?"],[12,21,"Saaledes den, som samler sig Liggendefæ og er ikke rig i Gud.","Saaledes den, som samler sig Liggendefæ og er ikke rig i Gud."],[12,22,"Men han sagde til sine Disciple: derfor siger jeg Eder: bekymrer Eder ikke for Eders Liv, hvad I skulle æde; ikke heller for Legemet, hvad I skulle iføres.","Men han sagde til sine Disciple: derfor siger jeg Eder: bekymrer Eder ikke for Eders Liv, hvad I skulle æde; ikke heller for Legemet, hvad I skulle iføres."],[12,23,"Livet er mere end Maden, og Legemet end Klæderne.","Livet er mere end Maden, og Legemet end Klæderne."],[12,24,"Giver Agt paa Ravnene, de saae ikke, høste og ikke, de have ingen Kjelder og ei Lade, og Gud føder dem alligevel; hvor meget ere I bedre end Fuglene?","Giver Agt paa Ravnene, de saae ikke, høste og ikke, de have ingen Kjelder og ei Lade, og Gud føder dem alligevel; hvor meget ere I bedre end Fuglene?"],[12,25,"Men hvo er iblandt Eder, som kan sætte een Alen til sin Væxt, enddog han bekymrer sig derfor?","Men hvo er iblandt Eder, som kan sætte een Alen til sin Væxt, enddog han bekymrer sig derfor?"],[12,26,"Formaae I da ei engang det Mindste, hvi bekymre I Eder for det Øvrige?","Formaae I da ei engang det Mindste, hvi bekymre I Eder for det Øvrige?"],[12,27,"Giver Agt paa Lilierne, hvorledes de voxe; de arbeide ikke, spinde ei heller; men jeg siger Eder: end ikke Salomon i al sin Herlighed var klædt som een af dem.","Giver Agt paa Lilierne, hvorledes de voxe; de arbeide ikke, spinde ei heller; men jeg siger Eder: end ikke Salomon i al sin Herlighed var klædt som een af dem."],[12,28,"Klæder da Gud Græsset saa, som i Dag staaer paa Marken og i Morgen kastes i Ovnen, hvor meget mere Eder, I lidet Troende!","Klæder da Gud Græsset saa, som i Dag staaer paa Marken og i Morgen kastes i Ovnen, hvor meget mere Eder, I lidet Troende!"],[12,29,"Derfor spørger og I ikke med Bekymring om, hvad I skulle æde, eller hvad I skulle drikke; og værer ikke vankelmodige.","Derfor spørger og I ikke med Bekymring om, hvad I skulle æde, eller hvad I skulle drikke; og værer ikke vankelmodige."],[12,30,"Thi efter alt Saadant søge Hedningerne i Verden; men Eders Fader veed, at I have det behov.","Thi efter alt Saadant søge Hedningerne i Verden; men Eders Fader veed, at I have det behov."],[12,31,"Søger heller Guds Rige, saa skulle alle disse Ting tillægges Eder.","Søger heller Guds Rige, saa skulle alle disse Ting tillægges Eder."],[12,32,"Frygt ikke, du lille Hjord! thi det er Eders Fader behageligt at give Eder Riget.","Frygt ikke, du lille Hjord! thi det er Eders Fader behageligt at give Eder Riget."],[12,33,"Sælger hvad I have, og giver Almisse! Gjører Eder Poser, som ikke bliver gamle, et Liggendefæ, som ikke forgaaer, i Himlene, hvor ingen Tyv kommer til, og intet Møl fordærver.","Sælger hvad I have, og giver Almisse! Gjører Eder Poser, som ikke bliver gamle, et Liggendefæ, som ikke forgaaer, i Himlene, hvor ingen Tyv kommer til, og intet Møl fordærver."],[12,34,"Thi hvor Eders Liggendefæ er, der vil og Eders Hjerte være.","Thi hvor Eders Liggendefæ er, der vil og Eders Hjerte være."],[12,35,"Eders Lænder være ombundne, og Eders Lys brændende.","Eders Lænder være ombundne, og Eders Lys brændende."],[12,36,"Og værer ligesom de Mennesker, der vente deres Herre, naar han bryder op fra Brylluppet, paa det, nar han kommer og banker paa, og de strax kunne lade op for ham.","Og værer ligesom de Mennesker, der vente deres Herre, naar han bryder op fra Brylluppet, paa det, nar han kommer og banker paa, og de strax kunne lade op for ham."],[12,37,"Salige ere de Tjenere, som Herren finder vaagne, naar han kommer. Sandelig siger jeg Eder, at han skal binde op om sig, og sætte dem tilbords, og gaae frem og tjene dem.","Salige ere de Tjenere, som Herren finder vaagne, naar han kommer. Sandelig siger jeg Eder, at han skal binde op om sig, og sætte dem tilbords, og gaae frem og tjene dem."],[12,38,"Og dersom han kommer i den anden Vagt, og kommer i den tredie Vagt, og finder det saaledes, da ere disse Tjenere salige.","Og dersom han kommer i den anden Vagt, og kommer i den tredie Vagt, og finder det saaledes, da ere disse Tjenere salige."],[12,39,"Men dette skulle I vide, at dersom Huusbonden vidste, hvad for en Time Tyven vilde komme, da vaagede han og lod ikke bryde ind i sit Huus.","Men dette skulle I vide, at dersom Huusbonden vidste, hvad for en Time Tyven vilde komme, da vaagede han og lod ikke bryde ind i sit Huus."],[12,40,"Derfor værer og I beredte; thi Menneskens Søn kommer paa den Time, som I ikke mene.","Derfor værer og I beredte; thi Menneskens Søn kommer paa den Time, som I ikke mene."],[12,41,"Men Peter sagde til ham: Herre! siger du denne Lignelse til os eller ogsaa til Alle?","Men Peter sagde til ham: Herre! siger du denne Lignelse til os eller ogsaa til Alle?"],[12,42,"Men Herren sagde: hvo er vel den troe og snilde Huusholder, som Herren vil sætte over sit Tyende, at give dem deres tillagte Spise i rette Tid?","Men Herren sagde: hvo er vel den troe og snilde Huusholder, som Herren vil sætte over sit Tyende, at give dem deres tillagte Spise i rette Tid?"],[12,43,"Salig er den Tjener, hvilken hans Herre, naar han kommer, finder at gjøre saaledes.","Salig er den Tjener, hvilken hans Herre, naar han kommer, finder at gjøre saaledes."],[12,44,"Sandelig siger jeg Eder: han skal sætte ham over alt sit Gods.","Sandelig siger jeg Eder: han skal sætte ham over alt sit Gods."],[12,45,"Men dersom samme Tjener siger i sit Hjerte: min Herre tøver at komme; og han begynder at slaae Drengene og Pigerne, og at æde og drikke og blive drukken;","Men dersom samme Tjener siger i sit Hjerte: min Herre tøver at komme; og han begynder at slaae Drengene og Pigerne, og at æde og drikke og blive drukken;"],[12,46,"da skal samme Tjeners Herre komme paa den Dag, som han ikke tænker, og paa den Time, som han ikke veed, og hugge ham i to, og skal give ham hans Deel med de Utroe.","da skal samme Tjeners Herre komme paa den Dag, som han ikke tænker, og paa den Time, som han ikke veed, og hugge ham i to, og skal give ham hans Deel med de Utroe."],[12,47,"Men den Tjener, som veed sin Herres Villie, og ikke bereder sig, og ikke gjør efter hans Villie, skal faae mange Hug;","Men den Tjener, som veed sin Herres Villie, og ikke bereder sig, og ikke gjør efter hans Villie, skal faae mange Hug;"],[12,48,"men den, som ikke veed det, og gjør, hvad der er Hug værd, skal faae lidet Hug. Thi enhver, hvem Meget er givet, hos ham skal man søge Meget; og hvem Meget er betroet, af ham skal man kræve Mere.","men den, som ikke veed det, og gjør, hvad der er Hug værd, skal faae lidet Hug. Thi enhver, hvem Meget er givet, hos ham skal man søge Meget; og hvem Meget er betroet, af ham skal man kræve Mere."],[12,49,"Ild er jeg kommen at kaste paa Jorden, og hvor vilde jeg, at den var optændt allerede!","Ild er jeg kommen at kaste paa Jorden, og hvor vilde jeg, at den var optændt allerede!"],[12,50,"En Daab skal jeg døbes med, og hvor ængstes jeg, indtil den er fuldbragt!","En Daab skal jeg døbes med, og hvor ængstes jeg, indtil den er fuldbragt!"],[12,51,"Mene I, at jeg er kommen at give Fred paa Jorden? Nei, jeg siger Eder, men Tvedragt.","Mene I, at jeg er kommen at give Fred paa Jorden? Nei, jeg siger Eder, men Tvedragt."],[12,52,"Thi fra nu af skulle fem i eet Huus være splidagtige, tre imod to og to imod tre.","Thi fra nu af skulle fem i eet Huus være splidagtige, tre imod to og to imod tre."],[12,53,"Faderen skal være splidagtig imod Sønnen, og Sønnen imod Faderen; Moderen imod Datteren, og Datteren imod Moderen; Mandens Moder imod sin Søns Hustru, og Sønnens Hustru imod sin Mands Moder.","Faderen skal være splidagtig imod Sønnen, og Sønnen imod Faderen; Moderen imod Datteren, og Datteren imod Moderen; Mandens Moder imod sin Søns Hustru, og Sønnens Hustru imod sin Mands Moder."],[12,54,"Men han sagde og til Folket: naar I see Skyen opgaae i Vester, sige I strax: der kommer Regn; og det skeer saaledes.","Men han sagde og til Folket: naar I see Skyen opgaae i Vester, sige I strax: der kommer Regn; og det skeer saaledes."],[12,55,"Og naar I see Søndenveir blæse, sige I: der kommer Hede; og det skeer.","Og naar I see Søndenveir blæse, sige I: der kommer Hede; og det skeer."],[12,56,"I Øienskalke! Jordens og Himmelens Skikkelse vide I at skjønne, men hvi skjønne I ikke denne Tid?","I Øienskalke! Jordens og Himmelens Skikkelse vide I at skjønne, men hvi skjønne I ikke denne Tid?"],[12,57,"Men hvorfor dømme I ikke og af Eder selv, hvad ret er?","Men hvorfor dømme I ikke og af Eder selv, hvad ret er?"],[12,58,"Thi medens du gaaer hen med din Modstander for Øvrigheden, da gjør din Flid paa Veien, at du kan gaae forligt fra ham, paa det han ikke skal drage dig for Dommeren, og Dommeren skal overantvorde Slutteren dig, og Slutteren skal kaste dig i Fængsel.","Thi medens du gaaer hen med din Modstander for Øvrigheden, da gjør din Flid paa Veien, at du kan gaae forligt fra ham, paa det han ikke skal drage dig for Dommeren, og Dommeren skal overantvorde Slutteren dig, og Slutteren skal kaste dig i Fængsel."],[12,59,"Jeg siger dig: du skal slet ikke komme derudfra, før end du betaler endog den sidste Skjerv.","Jeg siger dig: du skal slet ikke komme derudfra, før end du betaler endog den sidste Skjerv."],[13,1,"Men paa den samme Tid vare Nogle tilstede, som forkyndte ham om de Galilæer, hvis Blod Pilatus havde blandet med deres Offer.","Men paa den samme Tid vare Nogle tilstede, som forkyndte ham om de Galilæer, hvis Blod Pilatus havde blandet med deres Offer."],[13,2,"Og Jesus svarede og sagde til dem: mene I, at disse Galilæer vare Syndere fremfor alle Galilæer, fordi de lede dette?","Og Jesus svarede og sagde til dem: mene I, at disse Galilæer vare Syndere fremfor alle Galilæer, fordi de lede dette?"],[13,3,"Nei, siger jeg Eder; Men dersom I ikke omvende Eder, skulle I alle ligesaa omkomme.","Nei, siger jeg Eder; Men dersom I ikke omvende Eder, skulle I alle ligesaa omkomme."],[13,4,"Eller de Atten, som taarnet i Siloam faldt paa og ihjelslog, mene I, at de vare skyldige fremfor alle Mennesker, som boe i Jerusalem?","Eller de Atten, som taarnet i Siloam faldt paa og ihjelslog, mene I, at de vare skyldige fremfor alle Mennesker, som boe i Jerusalem?"],[13,5,"Nei, siger jeg Eder; men dersom I ikke omvende Eder, skulle I alle ligesaa omkomme.","Nei, siger jeg Eder; men dersom I ikke omvende Eder, skulle I alle ligesaa omkomme."],[13,6,"Men han sagde denne Lignelse: En havde et Figentræ, som var plantet i hans Viingaard; og han kom, og ledte efter Frugt derpaa, og fandt ingen.","Men han sagde denne Lignelse: En havde et Figentræ, som var plantet i hans Viingaard; og han kom, og ledte efter Frugt derpaa, og fandt ingen."],[13,7,"Men han sagde til Viingaardsmanden: see, jeg er nu i tre Aar kommen og har ledt efter Frugt paa dette Figentræ, og finder ingen; hug det om, hvi skal det og gjøre Jorden unyttig?","Men han sagde til Viingaardsmanden: see, jeg er nu i tre Aar kommen og har ledt efter Frugt paa dette Figentræ, og finder ingen; hug det om, hvi skal det og gjøre Jorden unyttig?"],[13,8,"Men han svarede og sagde til ham: Herre! lad det staae endnu dette Aar, indtil jeg faaer gravet om det og gjødet det,","Men han svarede og sagde til ham: Herre! lad det staae endnu dette Aar, indtil jeg faaer gravet om det og gjødet det,"],[13,9,"om det da vil bære Frugt; men hvis ikke, da hug det siden om.","om det da vil bære Frugt; men hvis ikke, da hug det siden om."],[13,10,"Men han lærte i een af Synagogerne paa Sabbaten.","Men han lærte i een af Synagogerne paa Sabbaten."],[13,11,"Og see, der var en Kvinde, som havde havt en Sygdoms Aand i atten Aar, og hun var kroget og kunde aldeles ikke rette sig op.","Og see, der var en Kvinde, som havde havt en Sygdoms Aand i atten Aar, og hun var kroget og kunde aldeles ikke rette sig op."],[13,12,"Men der Jesus saae hende, kaldte han ad hende og sagde til hende: Kvinde, du er løst fra din Sygdom.","Men der Jesus saae hende, kaldte han ad hende og sagde til hende: Kvinde, du er løst fra din Sygdom."],[13,13,"Og han lagde Hænderne paa hende; og strax rettede hun sig op og prisede Gud.","Og han lagde Hænderne paa hende; og strax rettede hun sig op og prisede Gud."],[13,14,"Da svarede Synagogforstanderen, som var vred, fordi Jesus helbredte paa Sabbaten, og sagde til Folket: der ere sex Dage, paa hvilke man bør arbeide; kommer derfor paa dem og lader Eder helbrede, og ikke paa Sabbatsdagen.","Da svarede Synagogforstanderen, som var vred, fordi Jesus helbredte paa Sabbaten, og sagde til Folket: der ere sex Dage, paa hvilke man bør arbeide; kommer derfor paa dem og lader Eder helbrede, og ikke paa Sabbatsdagen."],[13,15,"Da svarede Herren ham og sagde: du Øienskalk! løser ikke hver iblandt Eder sin Oxe eller sit Asen fra Krybben paa Sabbaten og fører dem til Vands?","Da svarede Herren ham og sagde: du Øienskalk! løser ikke hver iblandt Eder sin Oxe eller sit Asen fra Krybben paa Sabbaten og fører dem til Vands?"],[13,16,"Men denne, som er en Abrahams Datter, hvilken Satanas havde bundet, see, i atten Aar, burde hun ikke løses af dette Baand paa Sabbatsdagen?","Men denne, som er en Abrahams Datter, hvilken Satanas havde bundet, see, i atten Aar, burde hun ikke løses af dette Baand paa Sabbatsdagen?"],[13,17,"Og der han dette sagde, bleve Alle beskæmmede, som vare ham imod; og alt Folket glædte sig over alle de herlige Gjerninger, som gjordes af ham.","Og der han dette sagde, bleve Alle beskæmmede, som vare ham imod; og alt Folket glædte sig over alle de herlige Gjerninger, som gjordes af ham."],[13,18,"Men han sagde: hvad er Guds Rige ligt? og hvorved skal jeg ligne det?","Men han sagde: hvad er Guds Rige ligt? og hvorved skal jeg ligne det?"],[13,19,"Det er ligt et Senepskorn, hvilket et Menneske tog og lagde i sin Have; og det voxte og blev et stort Træ, og Himmelens Fugle gjorde Rede i dets Grene.","Det er ligt et Senepskorn, hvilket et Menneske tog og lagde i sin Have; og det voxte og blev et stort Træ, og Himmelens Fugle gjorde Rede i dets Grene."],[13,20,"Og han sagde atter: hvorved skal jeg ligne Guds Rige?","Og han sagde atter: hvorved skal jeg ligne Guds Rige?"],[13,21,"Det er ligt en Suurdeig, hvilken en Kvinde tog og nedlagde i tre Maader Meel, indtil det blev syret altsammen.","Det er ligt en Suurdeig, hvilken en Kvinde tog og nedlagde i tre Maader Meel, indtil det blev syret altsammen."],[13,22,"Og han gik igjennem Stæder og Byer, og lærte og tog Veien til Jerusalem.","Og han gik igjennem Stæder og Byer, og lærte og tog Veien til Jerusalem."],[13,23,"Men En sagde til ham: Herre! mon de ere faa, som blive salige? Da sagde han til dem:","Men En sagde til ham: Herre! mon de ere faa, som blive salige? Da sagde han til dem:"],[13,24,"Stræber alvorligen at indgaae igjennem den snevre Port; thi Mange, siger jeg Eder, skulle søge at komme ind, og skulle ikke kunne.","Stræber alvorligen at indgaae igjennem den snevre Port; thi Mange, siger jeg Eder, skulle søge at komme ind, og skulle ikke kunne."],[13,25,"Efterat Huusbonden er staaet op og haver tillukt Døren, og I da komme til at staae udenfor og banke paa Døren og sige: Herre, Herre, lad op for os! da skal han svare og sige til Eder: jeg kjender Eder ikke, hveden I ere.","Efterat Huusbonden er staaet op og haver tillukt Døren, og I da komme til at staae udenfor og banke paa Døren og sige: Herre, Herre, lad op for os! da skal han svare og sige til Eder: jeg kjender Eder ikke, hveden I ere."],[13,26,"Da skulle I begynde at sige: vi aade og drak for dine Øine, og du lærte paa vore Gader.","Da skulle I begynde at sige: vi aade og drak for dine Øine, og du lærte paa vore Gader."],[13,27,"Og han skal svare: jeg siger Eder, jeg kjender Eder ikke, hveden I ere; viger fra mig, alle I, som gjøre Uret!","Og han skal svare: jeg siger Eder, jeg kjender Eder ikke, hveden I ere; viger fra mig, alle I, som gjøre Uret!"],[13,28,"Der skal være Graad og Tænders Gnidsel, naar I faae at see Abraham og Isaak og Jakob og alle Propheter i Guds Rige, men Eder at være udstødte udenfor.","Der skal være Graad og Tænders Gnidsel, naar I faae at see Abraham og Isaak og Jakob og alle Propheter i Guds Rige, men Eder at være udstødte udenfor."],[13,29,"Og de skulle komme fra Øster og Vester, og fra Nord og Sønder, og sidde tilbords i Guds Rige.","Og de skulle komme fra Øster og Vester, og fra Nord og Sønder, og sidde tilbords i Guds Rige."],[13,30,"Og see, der ere Sidste, som skulle være de Første, og der ere Første, som skulle være de Sidste.","Og see, der ere Sidste, som skulle være de Første, og der ere Første, som skulle være de Sidste."],[13,31,"Paa den samme Dag kom nogle Pharisæer og sagde til ham: gak bort, og drag herfra! thi Herodes vil ihjelslaae dig.","Paa den samme Dag kom nogle Pharisæer og sagde til ham: gak bort, og drag herfra! thi Herodes vil ihjelslaae dig."],[13,32,"Og han sagde til dem: gaaer hen og siger den Ræv: see, jeg uddriver Djævle, og fuldfører Helbredelser i Dag og i Morgen, og paa den tredie Dag fuldendes jeg.","Og han sagde til dem: gaaer hen og siger den Ræv: see, jeg uddriver Djævle, og fuldfører Helbredelser i Dag og i Morgen, og paa den tredie Dag fuldendes jeg."],[13,33,"Dog bør det mig at vandre i Dag og i Morgen og den Dag derefter; thi det skeer ikke, at en Prophet omkommes udenfor Jerusalem.","Dog bør det mig at vandre i Dag og i Morgen og den Dag derefter; thi det skeer ikke, at en Prophet omkommes udenfor Jerusalem."],[13,34,"Jerusalem! Jerusalem! som ihjelslaaer Propheter og stener dem, som ere sendte til dig: hvor ofte vilde jeg forsamlet dine Børn, ligerviis som en Høne forsamler sine Kyllinger under Vingerne; men I vilde ikke.","Jerusalem! Jerusalem! som ihjelslaaer Propheter og stener dem, som ere sendte til dig: hvor ofte vilde jeg forsamlet dine Børn, ligerviis som en Høne forsamler sine Kyllinger under Vingerne; men I vilde ikke."],[13,35,"See, Eders Huus skal lades Eder øde. Men sandelig siger jeg Eder: I skulle ikke see mig, indtil Tiden kommer, naar I skulle sige: velsignet være den, som kommer i Herrens Navn!","See, Eders Huus skal lades Eder øde. Men sandelig siger jeg Eder: I skulle ikke see mig, indtil Tiden kommer, naar I skulle sige: velsignet være den, som kommer i Herrens Navn!"],[14,1,"Og det begav sig, der han kom i en af de øverste Pharisæers Huus paa en Sabbat for at holde Maaltid, at de toge vare paa ham.","Og det begav sig, der han kom i en af de øverste Pharisæers Huus paa en Sabbat for at holde Maaltid, at de toge vare paa ham."],[14,2,"Og see, der var et vattersottigt Menneske for ham.","Og see, der var et vattersottigt Menneske for ham."],[14,3,"Og Jesus begyndte at tale til de Lovkyndige og Pharisæerne, og sagde: mon det er tilladt at helbrede paa Sabbaten?","Og Jesus begyndte at tale til de Lovkyndige og Pharisæerne, og sagde: mon det er tilladt at helbrede paa Sabbaten?"],[14,4,"Men de taug. Og han tog paa ham, og helbredte ham, og lod ham gaae.","Men de taug. Og han tog paa ham, og helbredte ham, og lod ham gaae."],[14,5,"Og han svarede og sagde til dem: hvo er iblandt Eder, som, naar hans Oxe eller Asen falder i en Brønd, ikke strax drager det op paa Sabbatsdagen?","Og han svarede og sagde til dem: hvo er iblandt Eder, som, naar hans Oxe eller Asen falder i en Brønd, ikke strax drager det op paa Sabbatsdagen?"],[14,6,"Og de kunde ikke give ham Svar derpaa.","Og de kunde ikke give ham Svar derpaa."],[14,7,"Men han sagde en Lignelse til Gjesterne, der han gav Agt paa, hvorledes de udvalgte de øverste Sæder ved Bordet, og sagde til dem:","Men han sagde en Lignelse til Gjesterne, der han gav Agt paa, hvorledes de udvalgte de øverste Sæder ved Bordet, og sagde til dem:"],[14,8,"Naar du er buden af Nogen til Bryllup, da sæt dig ikke øverst tilbords, at ikke en Hæderligere end du maatte være buden af ham;","Naar du er buden af Nogen til Bryllup, da sæt dig ikke øverst tilbords, at ikke en Hæderligere end du maatte være buden af ham;"],[14,9,"og den, som indbød dig og ham, maatte komme og sige til dig: giv denne Plads; og du da med Blusel komme til at sidde nederst.","og den, som indbød dig og ham, maatte komme og sige til dig: giv denne Plads; og du da med Blusel komme til at sidde nederst."],[14,10,"Men naar du er buden, gak hen og sæt dig nederst, at, naar han kommer, som indbød dig, han da maa sige til dig: Ven! sæt dig høiere op; og da skal du have Ære for dem, som sidde med dig tilbords.","Men naar du er buden, gak hen og sæt dig nederst, at, naar han kommer, som indbød dig, han da maa sige til dig: Ven! sæt dig høiere op; og da skal du have Ære for dem, som sidde med dig tilbords."],[14,11,"Thi hver den, sig selv ophøier, skal fornedres; og hvo sig selv fornedrer, skal ophøies.","Thi hver den, sig selv ophøier, skal fornedres; og hvo sig selv fornedrer, skal ophøies."],[14,12,"Men han sagde og til den, som han havde budet: naar du gjør Middags- eller Aftensmaaltid, byd ikke dine Venner, ei heller dine Brødre, ei heller dine Frænder, ei heller rige Naboer, paa det de ikke skulle indbyde dig igjen, og dig skee Vederlag.","Men han sagde og til den, som han havde budet: naar du gjør Middags- eller Aftensmaaltid, byd ikke dine Venner, ei heller dine Brødre, ei heller dine Frænder, ei heller rige Naboer, paa det de ikke skulle indbyde dig igjen, og dig skee Vederlag."],[14,13,"Men naar du gjør et Gjestebud, da byd Fattige, Krøblinger, Halte, Blinde:","Men naar du gjør et Gjestebud, da byd Fattige, Krøblinger, Halte, Blinde:"],[14,14,"saa skal du være salig; thi de have Intet at betale derfor; men det skal igjengives dig i de Retfærdiges Opstandelse.","saa skal du være salig; thi de have Intet at betale derfor; men det skal igjengives dig i de Retfærdiges Opstandelse."],[14,15,"Men der En af dem, som sadde med tilbords, hørte det, sagde han til ham: salig er den, som kommer tilbords i Guds Rige.","Men der En af dem, som sadde med tilbords, hørte det, sagde han til ham: salig er den, som kommer tilbords i Guds Rige."],[14,16,"Men han sagde til ham: der var et Menneske, som gjorde en stor Nadvere og bød Mange.","Men han sagde til ham: der var et Menneske, som gjorde en stor Nadvere og bød Mange."],[14,17,"Og han udsendte sin Tjener paa Nadverens Time, at sige til de Budne: kommer; thi nu ere alle Ting beredte.","Og han udsendte sin Tjener paa Nadverens Time, at sige til de Budne: kommer; thi nu ere alle Ting beredte."],[14,18,"Og de begyndte alle eendrægteligen at undskylde sig. Den Første sagde til ham: jeg haver kjøbt en Ager, og haver fornøden at gaae ud og see den; jeg beder dig, hav mig undskyldt.","Og de begyndte alle eendrægteligen at undskylde sig. Den Første sagde til ham: jeg haver kjøbt en Ager, og haver fornøden at gaae ud og see den; jeg beder dig, hav mig undskyldt."],[14,19,"Og en Anden sagde: jeg haver kjøbt fem Par Øxen, og gaaer hen at prøve dem; jeg beder dig, hav mig undskyldt.","Og en Anden sagde: jeg haver kjøbt fem Par Øxen, og gaaer hen at prøve dem; jeg beder dig, hav mig undskyldt."],[14,20,"Og en Anden sagde: jeg tog mig en Hustru til Ægte, og derfor kan jeg ikke komme.","Og en Anden sagde: jeg tog mig en Hustru til Ægte, og derfor kan jeg ikke komme."],[14,21,"Og den Tjener kom og forkyndte sin Herre det; da blev Huusbonden vred, og sagde til sin Tjener: gak hurtig ud paa Stadens Stræder og Gader, og før hid ind Fattige og Krøblinger og Halte og Blinde.","Og den Tjener kom og forkyndte sin Herre det; da blev Huusbonden vred, og sagde til sin Tjener: gak hurtig ud paa Stadens Stræder og Gader, og før hid ind Fattige og Krøblinger og Halte og Blinde."],[14,22,"Og Tjeneren sagde: Herre! det er gjort, som du befoel, og der er endnu Rum.","Og Tjeneren sagde: Herre! det er gjort, som du befoel, og der er endnu Rum."],[14,23,"Og Herren sagde til Tjeneren: gak ud paa Veiene og ved Gjerderne, og nød dem at gaae ind, paa det mit Huus kan vorde fuldt.","Og Herren sagde til Tjeneren: gak ud paa Veiene og ved Gjerderne, og nød dem at gaae ind, paa det mit Huus kan vorde fuldt."],[14,24,"Thi jeg siger Eder, at ingen af de Mænd, som vare budne, skal smage min Nadvere.","Thi jeg siger Eder, at ingen af de Mænd, som vare budne, skal smage min Nadvere."],[14,25,"Men meget Folk gik med ham, og han vendte sig og sagde til dem:","Men meget Folk gik med ham, og han vendte sig og sagde til dem:"],[14,26,"dersom Nogen kommer til mig, og hader ikke sin Fader og Moder og Hustru og Børn og Brødre og Søstre, og tilmed sit eget Liv, han kan ikke være min Discipel.","dersom Nogen kommer til mig, og hader ikke sin Fader og Moder og Hustru og Børn og Brødre og Søstre, og tilmed sit eget Liv, han kan ikke være min Discipel."],[14,27,"Og hvo som ikke bærer sit Kors og kommer efter mig, kan ikke være min Discipel.","Og hvo som ikke bærer sit Kors og kommer efter mig, kan ikke være min Discipel."],[14,28,"Thi hvo iblandt Eder, som vil bygge et Taarn, sidder ikke først og beregner Bekostningen, om han haver, hvad der hører til at fuldføre det med,","Thi hvo iblandt Eder, som vil bygge et Taarn, sidder ikke først og beregner Bekostningen, om han haver, hvad der hører til at fuldføre det med,"],[14,29,"at ikke, naar han faaer lagt Grundvold, og ei kan fuldende det, Alle, som see det, skulle begynde at spotte ham og sige:","at ikke, naar han faaer lagt Grundvold, og ei kan fuldende det, Alle, som see det, skulle begynde at spotte ham og sige:"],[14,30,"dette Menneske begyndte at bygge og kunde ikke fuldende det.","dette Menneske begyndte at bygge og kunde ikke fuldende det."],[14,31,"Eller hvilken Konge, som drager i Krig at stride imod en anden Konge, sidder ikke først og beraader sig, om han er mægtig til, med ti Tusinde at møde den, som kommer mod ham med tyve Tusinde?","Eller hvilken Konge, som drager i Krig at stride imod en anden Konge, sidder ikke først og beraader sig, om han er mægtig til, med ti Tusinde at møde den, som kommer mod ham med tyve Tusinde?"],[14,32,"Men hvis ikke, udskikker han Sendebud, medens den Anden endnu er langt borte, og handler om Fred.","Men hvis ikke, udskikker han Sendebud, medens den Anden endnu er langt borte, og handler om Fred."],[14,33,"Saaledes og hver af Eder, som ikke forsager alt det, han haver, kan ikke være min Discipel.","Saaledes og hver af Eder, som ikke forsager alt det, han haver, kan ikke være min Discipel."],[14,34,"Saltet er godt; men dersom Saltet mister sin Kraft, hvormed skal det saltes?","Saltet er godt; men dersom Saltet mister sin Kraft, hvormed skal det saltes?"],[14,35,"Det tjener hverken til Jord eller til Gjødning; de kaste det ud. Hvo som haver Øren at høre med, han høre!","Det tjener hverken til Jord eller til Gjødning; de kaste det ud. Hvo som haver Øren at høre med, han høre!"],[15,1,"Men alle Toldere og Syndere holdt sig nær til ham, for at høre ham.","Men alle Toldere og Syndere holdt sig nær til ham, for at høre ham."],[15,2,"Og Pharisæerne og de Skriftkloge knurrede og sagde: denne annammer Syndere, og æder med dem.","Og Pharisæerne og de Skriftkloge knurrede og sagde: denne annammer Syndere, og æder med dem."],[15,3,"Men han talede denne Lignelse til dem og sagde:","Men han talede denne Lignelse til dem og sagde:"],[15,4,"hvilket Menneske af Eder, som haver hundrede Faar, og haver tabt eet af dem, forlader ei de ni og halvfemsindstyve i Ørken, og gaaer bort efter det tabte, indtil han finder det?","hvilket Menneske af Eder, som haver hundrede Faar, og haver tabt eet af dem, forlader ei de ni og halvfemsindstyve i Ørken, og gaaer bort efter det tabte, indtil han finder det?"],[15,5,"Og naar han haver fundet det, lægger han det paa sine Skuldre med Glæde.","Og naar han haver fundet det, lægger han det paa sine Skuldre med Glæde."],[15,6,"Og naar han kommer hjem, sammenkalder han Venner og Naboer, og siger til dem: glæder Eder med mig; thi jeg haver fundet mit Faar, som var tabt.","Og naar han kommer hjem, sammenkalder han Venner og Naboer, og siger til dem: glæder Eder med mig; thi jeg haver fundet mit Faar, som var tabt."],[15,7,"Jeg siger Eder: saaledes skal der være Glæde i Himmelen over een Synder, som omvender sig, mere end over ni og halvfemsindstyve Retfærdige, hvilke ikke have Omvendelse behov.","Jeg siger Eder: saaledes skal der være Glæde i Himmelen over een Synder, som omvender sig, mere end over ni og halvfemsindstyve Retfærdige, hvilke ikke have Omvendelse behov."],[15,8,"Eller hvilken Kvinde, som haver ti Penninge, om hun taber een Penning, tænder ikke et Lys og feier Huset, og søger med Flid, indtil hun finder den?","Eller hvilken Kvinde, som haver ti Penninge, om hun taber een Penning, tænder ikke et Lys og feier Huset, og søger med Flid, indtil hun finder den?"],[15,9,"Og naar hun haver fundet den, sammenkalder hun Veninder og Naboersker og siger: glæder Eder med mig; thi jeg haver fundet den Penning, som jeg tabte.","Og naar hun haver fundet den, sammenkalder hun Veninder og Naboersker og siger: glæder Eder med mig; thi jeg haver fundet den Penning, som jeg tabte."],[15,10,"Saaledes, siger jeg Eder, bliver der Glæde hos Guds Engle over een Synder, som omvender sig.","Saaledes, siger jeg Eder, bliver der Glæde hos Guds Engle over een Synder, som omvender sig."],[15,11,"Men han sagde: en Mand havde to Sønner.","Men han sagde: en Mand havde to Sønner."],[15,12,"Og den Yngste af dem sagde til Faderen: Fader! giv mig den Deel af Eiendommen, som mig tilfalder. Og han skiftede Godset mellem dem.","Og den Yngste af dem sagde til Faderen: Fader! giv mig den Deel af Eiendommen, som mig tilfalder. Og han skiftede Godset mellem dem."],[15,13,"Og ikke mange Dage derefter samlede den yngre Søn alt Sit, og drog udenlands, til et Land langt borte, og ødte der sit Gods i et overdaadigt Levned.","Og ikke mange Dage derefter samlede den yngre Søn alt Sit, og drog udenlands, til et Land langt borte, og ødte der sit Gods i et overdaadigt Levned."],[15,14,"Men der han havde fortæret alt det, han eiede, blev en svar Hunger i det samme Land; og han begyndte at lide Mangel.","Men der han havde fortæret alt det, han eiede, blev en svar Hunger i det samme Land; og han begyndte at lide Mangel."],[15,15,"Og han gik hen og holdt sig til een af Borgerne der i Landet, og denne sendte ham paa sine Agre og vogte Sviin.","Og han gik hen og holdt sig til een af Borgerne der i Landet, og denne sendte ham paa sine Agre og vogte Sviin."],[15,16,"Og han begjerede at fylde sin Bug med Mask, som Svinene aade; og Ingen gav ham Noget.","Og han begjerede at fylde sin Bug med Mask, som Svinene aade; og Ingen gav ham Noget."],[15,17,"Men han gik i sig selv og sagde; hvormange Daglønnere hos min Fader have overflødigt Brød? men jeg omkommer af Hunger.","Men han gik i sig selv og sagde; hvormange Daglønnere hos min Fader have overflødigt Brød? men jeg omkommer af Hunger."],[15,18,"Jeg vil staae op, og gaae til min Fader, og sige til ham: Fader! jeg haver syndet mod Himmelen, og for dig,","Jeg vil staae op, og gaae til min Fader, og sige til ham: Fader! jeg haver syndet mod Himmelen, og for dig,"],[15,19,"og er ikke længer værd at kaldes din Søn, gjør mig som een af dine Daglønnere.","og er ikke længer værd at kaldes din Søn, gjør mig som een af dine Daglønnere."],[15,20,"Og han stod op, og kom til sin Fader. Men der han endnu var langt borte, saae hans Fader ham, og ynkedes inderligen, og løb til og faldt om hans Hals og kyssede ham.","Og han stod op, og kom til sin Fader. Men der han endnu var langt borte, saae hans Fader ham, og ynkedes inderligen, og løb til og faldt om hans Hals og kyssede ham."],[15,21,"Men Sønnen sagde til ham: Fader! jeg haver syndet imod Himmelen og for dig, og er ikke længere værd at kaldes din Søn.","Men Sønnen sagde til ham: Fader! jeg haver syndet imod Himmelen og for dig, og er ikke længere værd at kaldes din Søn."],[15,22,"Men Faderen sagde til sine Tjenere: bærer frem det bedste Klædebon, ifører ham det og giver ham en Ring paa hans Haand og Skoe paa Fødderne;","Men Faderen sagde til sine Tjenere: bærer frem det bedste Klædebon, ifører ham det og giver ham en Ring paa hans Haand og Skoe paa Fødderne;"],[15,23,"og henter den fedede Kalv hid og slagter den, og lader os æde og være lystige.","og henter den fedede Kalv hid og slagter den, og lader os æde og være lystige."],[15,24,"Thi denne min Søn var død, og er bleven levende igjen, og var fortabt, og er funden. Og de begyndte at være lystige.","Thi denne min Søn var død, og er bleven levende igjen, og var fortabt, og er funden. Og de begyndte at være lystige."],[15,25,"Men hans Ældste Søn var paa Marken, og da han kom, og var nær ved Huset, hørte han Musik og Dands.","Men hans Ældste Søn var paa Marken, og da han kom, og var nær ved Huset, hørte han Musik og Dands."],[15,26,"Og han kaldte een af Drengene til sig og udspurgte, hvad det var?","Og han kaldte een af Drengene til sig og udspurgte, hvad det var?"],[15,27,"Men han sagde til ham: din Broder er kommen, og din Fader slagtede den fedede Kalv, fordi han haver faaet ham karsk igjen.","Men han sagde til ham: din Broder er kommen, og din Fader slagtede den fedede Kalv, fordi han haver faaet ham karsk igjen."],[15,28,"Men han blev vred og vilde ikke gaae ind. Derfor gik hans Fader ud og bad ham.","Men han blev vred og vilde ikke gaae ind. Derfor gik hans Fader ud og bad ham."],[15,29,"Men han svarede og sagde til Faderen: see, saa mange Aar tjener jeg dig, og overtraadte end aldrig dit Bud, og du haver aldrig givet mig et Kid, at jeg kunde være lystig med mine Venner.","Men han svarede og sagde til Faderen: see, saa mange Aar tjener jeg dig, og overtraadte end aldrig dit Bud, og du haver aldrig givet mig et Kid, at jeg kunde være lystig med mine Venner."],[15,30,"Men da denne din Søn er kommen, som haver fortæret dit Godt med Skjøger, slagtede du den fedede Kalv til ham.","Men da denne din Søn er kommen, som haver fortæret dit Godt med Skjøger, slagtede du den fedede Kalv til ham."],[15,31,"Men han sagde til ham: min Søn! du er altid hos mig, og alt det, som mit er, er dit.","Men han sagde til ham: min Søn! du er altid hos mig, og alt det, som mit er, er dit."],[15,32,"Men man burde at være lystig og glæde sig, fordi denne din Broder var død, og er bleven levende igjen, og var fortabt, og er funden.","Men man burde at være lystig og glæde sig, fordi denne din Broder var død, og er bleven levende igjen, og var fortabt, og er funden."],[16,1,"Men han sagde og til sine Disciple: der var en rig Mand, som havde en Huusholder, og denne blev beført for ham, at han ødte hans Gods.","Men han sagde og til sine Disciple: der var en rig Mand, som havde en Huusholder, og denne blev beført for ham, at han ødte hans Gods."],[16,2,"Og han kaldte ham og sagde til ham: hvi hører jeg dette om dig? Gjør Regnskab for din Huusholdning; thi du kan ikke længere forstaae Huset.","Og han kaldte ham og sagde til ham: hvi hører jeg dette om dig? Gjør Regnskab for din Huusholdning; thi du kan ikke længere forstaae Huset."],[16,3,"Men Huusholderen sagde ved sig selv: hvad skal jeg gjøre, efterdi min Herre tager Huusholdningen fra mig? Jeg formaaer ikke at grave, jeg skammer mig ved at trygle.","Men Huusholderen sagde ved sig selv: hvad skal jeg gjøre, efterdi min Herre tager Huusholdningen fra mig? Jeg formaaer ikke at grave, jeg skammer mig ved at trygle."],[16,4,"Jeg veed, hvad jeg vil gjøre, at de skulle tage mig i deres Huse, naar jeg bliver sat fra Huusholdningen.","Jeg veed, hvad jeg vil gjøre, at de skulle tage mig i deres Huse, naar jeg bliver sat fra Huusholdningen."],[16,5,"Og han fremkaldte enhver af sin Herres Skyldnere, og sagde til den første: hvor meget er du min Herre skyldig?","Og han fremkaldte enhver af sin Herres Skyldnere, og sagde til den første: hvor meget er du min Herre skyldig?"],[16,6,"Men denne sagde: hundrede Fade Olie. Og han sagde til ham: tag dit Brev, og sæt dig snart ned, og skriv halvtredsindstyve.","Men denne sagde: hundrede Fade Olie. Og han sagde til ham: tag dit Brev, og sæt dig snart ned, og skriv halvtredsindstyve."],[16,7,"Derefter sagde han til en anden: men du, hvor meget er du skyldig? Men denne sagde: hundrede Maader Hvede. Og han sagde til ham: tag dit Brev og skriv fiirsindstyve.","Derefter sagde han til en anden: men du, hvor meget er du skyldig? Men denne sagde: hundrede Maader Hvede. Og han sagde til ham: tag dit Brev og skriv fiirsindstyve."],[16,8,"Og Herren lovede den uretfærdige Huusholder, at han gjorde snildeligen; thi denne Verdens Børn ere klogere end Lysets Børn mod deres Slægt.","Og Herren lovede den uretfærdige Huusholder, at han gjorde snildeligen; thi denne Verdens Børn ere klogere end Lysets Børn mod deres Slægt."],[16,9,"Og jeg siger Eder: gjører Eder Venner ved den urette Mammon, at, naar I skilles herfra, de skulle annamme Eder i de evige Boliger.","Og jeg siger Eder: gjører Eder Venner ved den urette Mammon, at, naar I skilles herfra, de skulle annamme Eder i de evige Boliger."],[16,10,"Hvo som er tro i det Mindste, er og tro i Meget; og hvo som er uretfærdig i det Mindste, er og uretfærdig i Meget.","Hvo som er tro i det Mindste, er og tro i Meget; og hvo som er uretfærdig i det Mindste, er og uretfærdig i Meget."],[16,11,"Dersom I da ikke have været troe i den urette Mammon, hvo vil betroe Eder den sande?","Dersom I da ikke have været troe i den urette Mammon, hvo vil betroe Eder den sande?"],[16,12,"Og dersom I ikke have været troe i det Fremmede, hvo vil give Eder Noget selv at eie?","Og dersom I ikke have været troe i det Fremmede, hvo vil give Eder Noget selv at eie?"],[16,13,"Ingen Huussvend kan tjene to Herrer; thi han skal enten hade den ene og elske den anden, eller holde sig til den ene og foragte den anden; I kunne ikke tjene Gud og Mammon.","Ingen Huussvend kan tjene to Herrer; thi han skal enten hade den ene og elske den anden, eller holde sig til den ene og foragte den anden; I kunne ikke tjene Gud og Mammon."],[16,14,"Men alt dette hørte ogsaa Pharisæerne, som vare pengegjerrige, og de spottede ham.","Men alt dette hørte ogsaa Pharisæerne, som vare pengegjerrige, og de spottede ham."],[16,15,"Og han sagde til dem: I ere de, som retfærdiggjøre Eder selv for Menneskene; men Gud kjender Eders Hjerter; thi hvad som er høit blandt Menneskene, er en Vederstyggelighed for Gud.","Og han sagde til dem: I ere de, som retfærdiggjøre Eder selv for Menneskene; men Gud kjender Eders Hjerter; thi hvad som er høit blandt Menneskene, er en Vederstyggelighed for Gud."],[16,16,"Loven og Propheterne indtil Johannes spaaede; fra den Tid forkyndes Guds Rige ved Evangelium, og hver trænger derind med Magt.","Loven og Propheterne indtil Johannes spaaede; fra den Tid forkyndes Guds Rige ved Evangelium, og hver trænger derind med Magt."],[16,17,"Men det er lettere, at Himmelen og Jorden forgaae, end at een Tøddel af Loven bortfalder.","Men det er lettere, at Himmelen og Jorden forgaae, end at een Tøddel af Loven bortfalder."],[16,18,"Hver, som skiller sig fra sin Hustru og tager en anden til Ægte, bedriver Hoer, og hver, som tager den til Ægte, der er skilt fra Manden, bedriver Hoer.","Hver, som skiller sig fra sin Hustru og tager en anden til Ægte, bedriver Hoer, og hver, som tager den til Ægte, der er skilt fra Manden, bedriver Hoer."],[16,19,"Men der var en rig Mand, og han klædte sig i Purpur og kosteligt Linklæde og levede hver Dag herligen og i Glæde.","Men der var en rig Mand, og han klædte sig i Purpur og kosteligt Linklæde og levede hver Dag herligen og i Glæde."],[16,20,"Der var og en Fattig ved Navn Lazarus, som var lagt for hans Dør, fuld af Saar.","Der var og en Fattig ved Navn Lazarus, som var lagt for hans Dør, fuld af Saar."],[16,21,"Og han begjerede at mættes af de Smuler, som faldt af den Riges Bord; men og Hundene kom, og slikkede hans Saar.","Og han begjerede at mættes af de Smuler, som faldt af den Riges Bord; men og Hundene kom, og slikkede hans Saar."],[16,22,"Men det begav sig, at den Fattige døde, og at han blev henbaaren af Englene i Abrahams Skjød; men den Rige døde ogsaa og blev begraven.","Men det begav sig, at den Fattige døde, og at han blev henbaaren af Englene i Abrahams Skjød; men den Rige døde ogsaa og blev begraven."],[16,23,"Og der han opløftede sine Øine i Helvede, der han var i Pine, saae han Abraham langt borte, og Lazarus i hans Skjød.","Og der han opløftede sine Øine i Helvede, der han var i Pine, saae han Abraham langt borte, og Lazarus i hans Skjød."],[16,24,"Og han raabte og sagde: Fader Abraham! forbarm dig over mig, og send Lazarus, at han dypper det Yderste af sin Finger i Vand, og lædsker min Tunge; thi jeg pines svarligen i denne Lue.","Og han raabte og sagde: Fader Abraham! forbarm dig over mig, og send Lazarus, at han dypper det Yderste af sin Finger i Vand, og lædsker min Tunge; thi jeg pines svarligen i denne Lue."],[16,25,"Men Abraham sagde: Søn! kom ihu, at du haver annammet dit Gode i din Livstid, og Lazarus ligesaa det Onde; men nu trøstes han, og du pines.","Men Abraham sagde: Søn! kom ihu, at du haver annammet dit Gode i din Livstid, og Lazarus ligesaa det Onde; men nu trøstes han, og du pines."],[16,26,"Og foruden alt dette er imellem os og Eder et stort Svælg befæstet, at de, som ville fare herfra ned til Eder, kunne ikke, og de kunne ikke heller fare derfra over til os.","Og foruden alt dette er imellem os og Eder et stort Svælg befæstet, at de, som ville fare herfra ned til Eder, kunne ikke, og de kunne ikke heller fare derfra over til os."],[16,27,"Men han sagde: saa beder jeg dig, Fader! at du sender ham til min Faders Huus;","Men han sagde: saa beder jeg dig, Fader! at du sender ham til min Faders Huus;"],[16,28,"thi jeg haver fem Brødre; paa det han kan vidne for dem, at ikke ogsaa de komme i denne Pines Sted.","thi jeg haver fem Brødre; paa det han kan vidne for dem, at ikke ogsaa de komme i denne Pines Sted."],[16,29,"Abraham sagde til ham: de have Moses og Propheterne, lad dem høre dem.","Abraham sagde til ham: de have Moses og Propheterne, lad dem høre dem."],[16,30,"Men han sagde: ak nei, Fader Abraham! men dersom Nogen fra de Døde gik til dem, da omvendte de sig.","Men han sagde: ak nei, Fader Abraham! men dersom Nogen fra de Døde gik til dem, da omvendte de sig."],[16,31,"Men han sagde til ham: høre de ikke Moses og Propheterne, da troe de ikke heller, om Nogen opstod fra de Døde.","Men han sagde til ham: høre de ikke Moses og Propheterne, da troe de ikke heller, om Nogen opstod fra de Døde."],[17,1,"Men han sagde til Disciplene: det er umuligt, at Foragelser ei skulle komme; men vee den, ved hvilken de komme!","Men han sagde til Disciplene: det er umuligt, at Foragelser ei skulle komme; men vee den, ved hvilken de komme!"],[17,2,"Det var ham bedre, om en Møllesteen blev hængt om hans Hals, og han blev kastet i Havet, end at han skulde forarge een af disse Smaa.","Det var ham bedre, om en Møllesteen blev hængt om hans Hals, og han blev kastet i Havet, end at han skulde forarge een af disse Smaa."],[17,3,"Vogter Eder selv. Men dersom din Broder synder imod dig, straf ham; og dersom han omvender sig, da tilgiv ham.","Vogter Eder selv. Men dersom din Broder synder imod dig, straf ham; og dersom han omvender sig, da tilgiv ham."],[17,4,"Og dersom han syv Gange om Dagen syndede imod dig og syv Gange om Dagen vender tilbage til dig og siger: det fortryder mig, da skal du tilgive ham.","Og dersom han syv Gange om Dagen syndede imod dig og syv Gange om Dagen vender tilbage til dig og siger: det fortryder mig, da skal du tilgive ham."],[17,5,"Og Apostlerne sagde til Herren: forøg os Troen.","Og Apostlerne sagde til Herren: forøg os Troen."],[17,6,"Men Herren sagde: dersom I havde Tro som et Senepskorn, da kunde I sige til dette Morbærtræ: ryk dig op med Rod, og plant dig i Havet; og det skulde være Eder lydigt.","Men Herren sagde: dersom I havde Tro som et Senepskorn, da kunde I sige til dette Morbærtræ: ryk dig op med Rod, og plant dig i Havet; og det skulde være Eder lydigt."],[17,7,"Men hvo af Eder, som haver en Tjener, der pløier eller vogter Kvæg, siger strax til ham, naar han kommer hjem af Marken: gak hen og sæt dig tilbords?","Men hvo af Eder, som haver en Tjener, der pløier eller vogter Kvæg, siger strax til ham, naar han kommer hjem af Marken: gak hen og sæt dig tilbords?"],[17,8,"Mon han ikke snarere sige til ham: bered det, jeg skal have til Nadvere, og bind op om dig, og vart mig op, medens jeg æder og drikker; og derefter maa du æde og drikke?","Mon han ikke snarere sige til ham: bered det, jeg skal have til Nadvere, og bind op om dig, og vart mig op, medens jeg æder og drikker; og derefter maa du æde og drikke?"],[17,9,"Mon han takke denne Tjener, at han gjorde det, som var ham befalet? Jeg mener det ikke.","Mon han takke denne Tjener, at han gjorde det, som var ham befalet? Jeg mener det ikke."],[17,10,"Ligesaa og I, naar I have gjort alle Ting, som Eder ere befalede, siger: vi ere unyttige Tjenere; thi vi gjorde det, som vi vare skyldige at gjøre.","Ligesaa og I, naar I have gjort alle Ting, som Eder ere befalede, siger: vi ere unyttige Tjenere; thi vi gjorde det, som vi vare skyldige at gjøre."],[17,11,"Og det begav sig, der han reiste til Jerusalem, da drog han midt igjennem Samaria og Galilæa.","Og det begav sig, der han reiste til Jerusalem, da drog han midt igjennem Samaria og Galilæa."],[17,12,"Og der han kom til en By, mødte han ti spedalske Mænd, som stode langt borte.","Og der han kom til en By, mødte han ti spedalske Mænd, som stode langt borte."],[17,13,"Og de opløftede Røsten og sagde: Jesus, Mester, forbarm dig over os!","Og de opløftede Røsten og sagde: Jesus, Mester, forbarm dig over os!"],[17,14,"Og der han saae dem, sagde ham til dem: gaaer hen og beteer Eder for Præsterne. Og det skete, der de gik bort, bleve de rensede.","Og der han saae dem, sagde ham til dem: gaaer hen og beteer Eder for Præsterne. Og det skete, der de gik bort, bleve de rensede."],[17,15,"Men een af dem, der han saae, at han var helbredet, vendte tilbage, og prisede Gud med høi Røst.","Men een af dem, der han saae, at han var helbredet, vendte tilbage, og prisede Gud med høi Røst."],[17,16,"Og han faldt paa sit Ansigt for hans Fødder og takkede ham; og denne var en Samaritan.","Og han faldt paa sit Ansigt for hans Fødder og takkede ham; og denne var en Samaritan."],[17,17,"Da svarede Jesus og sagde: bleve ikke de Ti rensede? men hvor ere de Ni?","Da svarede Jesus og sagde: bleve ikke de Ti rensede? men hvor ere de Ni?"],[17,18,"Bleve ellers Ingen fundne, som vendte tilbage at give Gud Ære, uden denne Fremmede?","Bleve ellers Ingen fundne, som vendte tilbage at give Gud Ære, uden denne Fremmede?"],[17,19,"Og han sagde til ham: staa op, gak bort; din Tro haver frelst dig!","Og han sagde til ham: staa op, gak bort; din Tro haver frelst dig!"],[17,20,"Men da han blev adspurgt af Pharisæerne: naar kommer Guds Rige? svarede han dem og sagde: Guds Rige kommer ikke saaledes, at man kan vise derpaa.","Men da han blev adspurgt af Pharisæerne: naar kommer Guds Rige? svarede han dem og sagde: Guds Rige kommer ikke saaledes, at man kan vise derpaa."],[17,21,"De skulle ikke heller sige: see her, eller see der er det; thi see, Guds Rige er inden i Eder.","De skulle ikke heller sige: see her, eller see der er det; thi see, Guds Rige er inden i Eder."],[17,22,"Men han sagde til Disciplene: de Dage skulle komme, da I skulle begjere at see een af Menneskens Søns Dage, og I skulle ikke see den.","Men han sagde til Disciplene: de Dage skulle komme, da I skulle begjere at see een af Menneskens Søns Dage, og I skulle ikke see den."],[17,23,"Og de skulle sige til Eder: see her, eller see der er han; men gaaer ikke hen, og følger ikke heller.","Og de skulle sige til Eder: see her, eller see der er han; men gaaer ikke hen, og følger ikke heller."],[17,24,"Thi ligesom Lynet, som lyner fra den ene Side af Himmelen, skinner til den anden Side af Himmelen, saa skal Menneskens Søn være paa sin Dag.","Thi ligesom Lynet, som lyner fra den ene Side af Himmelen, skinner til den anden Side af Himmelen, saa skal Menneskens Søn være paa sin Dag."],[17,25,"Men ham bør det først at lide meget og forskydes af denne Slægt.","Men ham bør det først at lide meget og forskydes af denne Slægt."],[17,26,"Og som det skete i Noahs Dage, saaledes skal det og skee i Menneskens Søns Dage.","Og som det skete i Noahs Dage, saaledes skal det og skee i Menneskens Søns Dage."],[17,27,"De aade, drak, toge til Ægte, bleve bortgiftede indtil den Dag, der Noah gik ind i Arken, og Syndfloden kom og ødelagde Alle.","De aade, drak, toge til Ægte, bleve bortgiftede indtil den Dag, der Noah gik ind i Arken, og Syndfloden kom og ødelagde Alle."],[17,28,"Desligeste og som det skete i Loths Dage: de aade, drak, kjøbte, solgte, plantede, byggede;","Desligeste og som det skete i Loths Dage: de aade, drak, kjøbte, solgte, plantede, byggede;"],[17,29,"men paa den Dag, der Loth gik ud af Sodoma, regnede Ild og Svovl af Himmelen, og ødelagde dem alle.","men paa den Dag, der Loth gik ud af Sodoma, regnede Ild og Svovl af Himmelen, og ødelagde dem alle."],[17,30,"Saaledes skal det være paa den Dag, Menneskens Søn aabenbares.","Saaledes skal det være paa den Dag, Menneskens Søn aabenbares."],[17,31,"Paa den samme Dag, hvo som er paa Taget og hans Redskaber i Huset, stige ikke ned at tage dem! og desligeste hvo som er paa Marken vende ikke om til det, som er bag ham.","Paa den samme Dag, hvo som er paa Taget og hans Redskaber i Huset, stige ikke ned at tage dem! og desligeste hvo som er paa Marken vende ikke om til det, som er bag ham."],[17,32,"Kommer Loths Hustru ihu.","Kommer Loths Hustru ihu."],[17,33,"Hvo som søger at frelse sit Liv, skal miste det; og hvo som mister det, skal holde det ved Live.","Hvo som søger at frelse sit Liv, skal miste det; og hvo som mister det, skal holde det ved Live."],[17,34,"Jeg siger Eder: i den samme Nat skulle To være i een Seng; den Ene skal annammes, og den Anden skal lades tilbage.","Jeg siger Eder: i den samme Nat skulle To være i een Seng; den Ene skal annammes, og den Anden skal lades tilbage."],[17,35,"To Kvinder skulle male tilsammen; den ene skal annammes, og den anden skal lades tilbage.","To Kvinder skulle male tilsammen; den ene skal annammes, og den anden skal lades tilbage."],[17,36,"To skulle være paa Marken; den Ene skal annammes, og den Anden skal lades tilbage.","To skulle være paa Marken; den Ene skal annammes, og den Anden skal lades tilbage."],[17,37,"Og de svarede og sagde til ham: hvor, Herre? Men han sagde til dem: hvor Kroppen er, der skulle Ørnene forsamles.","Og de svarede og sagde til ham: hvor, Herre? Men han sagde til dem: hvor Kroppen er, der skulle Ørnene forsamles."],[18,1,"Men han sagde dem og en Lignelse derom, at man bør altid bede, og ikke blive træt.","Men han sagde dem og en Lignelse derom, at man bør altid bede, og ikke blive træt."],[18,2,"Og han sagde: der var en Dommer i en Stad, som frygtede ikke Gud, og undsaae sig ikke for noget Menneske.","Og han sagde: der var en Dommer i en Stad, som frygtede ikke Gud, og undsaae sig ikke for noget Menneske."],[18,3,"Men der var en Enke i den samme Stad, og hun kom til ham og sagde: skaf mig Ret over min Modstander.","Men der var en Enke i den samme Stad, og hun kom til ham og sagde: skaf mig Ret over min Modstander."],[18,4,"Og han vilde længe ikke. Men derefter sagde han ved sig selv; alligevel jeg hverken frygter Gud, ei heller undseer mig for noget Menneske,","Og han vilde længe ikke. Men derefter sagde han ved sig selv; alligevel jeg hverken frygter Gud, ei heller undseer mig for noget Menneske,"],[18,5,"dog, efterdi denne Enke gjør mig megen Besvær, vil jeg skaffe hende Ret, at hun ikke uden Ophør skal komme og plage mig.","dog, efterdi denne Enke gjør mig megen Besvær, vil jeg skaffe hende Ret, at hun ikke uden Ophør skal komme og plage mig."],[18,6,"Men Herren sagde: hører, hvad den uretfærdige Dommer siger.","Men Herren sagde: hører, hvad den uretfærdige Dommer siger."],[18,7,"Skulde da Gud ikke skaffe sine Udvalgte Ret, som raabe til ham Dag og Nat, enddog han er langmodig imod dem?","Skulde da Gud ikke skaffe sine Udvalgte Ret, som raabe til ham Dag og Nat, enddog han er langmodig imod dem?"],[18,8,"Jeg siger Eder, at han skal snart skaffe dem Ret. Dog, naar Menneskens Søn kommer, mon han skal finde Troen paa Jorden?","Jeg siger Eder, at han skal snart skaffe dem Ret. Dog, naar Menneskens Søn kommer, mon han skal finde Troen paa Jorden?"],[18,9,"Men han sagde og til Nogle, som stolede paa sig selv, at de vare retfærdige, og foragtede Andre, denne Lignelse:","Men han sagde og til Nogle, som stolede paa sig selv, at de vare retfærdige, og foragtede Andre, denne Lignelse:"],[18,10,"der gik to Mennesker op til Templet at bede; den Ene var en Pharisæer, og den Anden en Tolder.","der gik to Mennesker op til Templet at bede; den Ene var en Pharisæer, og den Anden en Tolder."],[18,11,"Pharisæeren stod for sig selv, og bad saaledes: jeg takker dig, Gud, at jeg ikke er som andre Mennesker, Røvere, Uretfærdige, Hoerkarle eller og som denne Tolder.","Pharisæeren stod for sig selv, og bad saaledes: jeg takker dig, Gud, at jeg ikke er som andre Mennesker, Røvere, Uretfærdige, Hoerkarle eller og som denne Tolder."],[18,12,"Jeg faster to Gange om Ugen, jeg giver Tiende af alt det, jeg eier.","Jeg faster to Gange om Ugen, jeg giver Tiende af alt det, jeg eier."],[18,13,"Og Tolderen stod langt borte, og vilde end ikke opløfte Øinene til Himmelen, men slog sig for sit Bryst og sagde: Gud, vær mig Synder naadig!","Og Tolderen stod langt borte, og vilde end ikke opløfte Øinene til Himmelen, men slog sig for sit Bryst og sagde: Gud, vær mig Synder naadig!"],[18,14,"Jeg siger Eder: denne gik retfærdiggjort hjem til sit Huus fremfor den Anden; thi hvo sig selv ophøier, skal fornedres, men hvo sig selv fornedrer, skal ophøies.","Jeg siger Eder: denne gik retfærdiggjort hjem til sit Huus fremfor den Anden; thi hvo sig selv ophøier, skal fornedres, men hvo sig selv fornedrer, skal ophøies."],[18,15,"Men de bare og smaa Børn til ham, at han skulde røre ved dem; men der Disciplene saae det, truede de dem.","Men de bare og smaa Børn til ham, at han skulde røre ved dem; men der Disciplene saae det, truede de dem."],[18,16,"Men Jesus kaldte dem til sig og sagde: lader de smaa Børn komme til mig, og formener dem det ikke; thi Guds Rige hører saadanne til.","Men Jesus kaldte dem til sig og sagde: lader de smaa Børn komme til mig, og formener dem det ikke; thi Guds Rige hører saadanne til."],[18,17,"Sandelig siger jeg Eder: hvo som ikke annammer Guds Rige som et Barn kommer ingenlunde derind.","Sandelig siger jeg Eder: hvo som ikke annammer Guds Rige som et Barn kommer ingenlunde derind."],[18,18,"Og en af de Øverste spurgte ham og sagde: gode Mester! hvad skal jeg gjøre, at jeg kan arve et evigt Liv?","Og en af de Øverste spurgte ham og sagde: gode Mester! hvad skal jeg gjøre, at jeg kan arve et evigt Liv?"],[18,19,"Men Jesus sagde til ham: hvi kalder du mig god? Ingen er god uden Een, det er Gud.","Men Jesus sagde til ham: hvi kalder du mig god? Ingen er god uden Een, det er Gud."],[18,20,"Du veed Budene: du skal ikke bedrive Hoer; du skal ikke slaae ihjel; du skal ikke stjæle; du skal ikke bære falsk Vidnesbyrd; ær din Fader og din Moder.","Du veed Budene: du skal ikke bedrive Hoer; du skal ikke slaae ihjel; du skal ikke stjæle; du skal ikke bære falsk Vidnesbyrd; ær din Fader og din Moder."],[18,21,"Da sagde han: dette haver jeg holdet altsammen fra min Ungdom af.","Da sagde han: dette haver jeg holdet altsammen fra min Ungdom af."],[18,22,"Men der Jesus det hørte, sagde han til ham: endnu fattes dig Eet: sælg alt det, du haver, og uddeel det til Fattige, saa skal du have et Liggendefæ i Himmelen; og kom, følg mig.","Men der Jesus det hørte, sagde han til ham: endnu fattes dig Eet: sælg alt det, du haver, og uddeel det til Fattige, saa skal du have et Liggendefæ i Himmelen; og kom, følg mig."],[18,23,"Men der han det hørte, blev han heel bedrøvet; thi han var saare rig.","Men der han det hørte, blev han heel bedrøvet; thi han var saare rig."],[18,24,"Men der Jesus saae, at han var bleven heel bedrøvet, sagde han: hvor vanskelig skulle de, som have Rigdom, komme ind i Guds Rige;","Men der Jesus saae, at han var bleven heel bedrøvet, sagde han: hvor vanskelig skulle de, som have Rigdom, komme ind i Guds Rige;"],[18,25,"thi det er lettere, at en Kameel gaaer igjennem et Naaleøie, end at en Rig kommer ind i Guds Rige.","thi det er lettere, at en Kameel gaaer igjennem et Naaleøie, end at en Rig kommer ind i Guds Rige."],[18,26,"Men de, som hørte det, sagde: hvo kan da blive salig?","Men de, som hørte det, sagde: hvo kan da blive salig?"],[18,27,"Men han sagde: hvad som er umuligt for Mennesker, det er muligt for Gud.","Men han sagde: hvad som er umuligt for Mennesker, det er muligt for Gud."],[18,28,"Men Peter sagde: see, vi have forladt Alting og fulgt dig.","Men Peter sagde: see, vi have forladt Alting og fulgt dig."],[18,29,"Men hans sagde til dem: sandelig siger jeg Eder: der er Ingen, som haver forladt Huus eller Forældre eller Brødre eller Hustru eller Børn for Guds Riges Skyld,","Men hans sagde til dem: sandelig siger jeg Eder: der er Ingen, som haver forladt Huus eller Forældre eller Brødre eller Hustru eller Børn for Guds Riges Skyld,"],[18,30,"som jo skal annamme det mange Fold igjen i denne Tid, og i den til kommende Verden et evigt Liv.","som jo skal annamme det mange Fold igjen i denne Tid, og i den til kommende Verden et evigt Liv."],[18,31,"Men han tog de Tolv til sig og sagde til dem: see, vi gaae op til Jerusalem, og alle de Ting, som ere skrevne Ved Propheterne, skulle fuldkommes paa Menneskens Søn.","Men han tog de Tolv til sig og sagde til dem: see, vi gaae op til Jerusalem, og alle de Ting, som ere skrevne Ved Propheterne, skulle fuldkommes paa Menneskens Søn."],[18,32,"Thi han skal overantvordes Hedningerne og bespottes, forhaanes og bespyttes,","Thi han skal overantvordes Hedningerne og bespottes, forhaanes og bespyttes,"],[18,33,"og de skulle hudstryge og ihjelslaae ham; og tredie Dag skal han opstaae.","og de skulle hudstryge og ihjelslaae ham; og tredie Dag skal han opstaae."],[18,34,"Men de fattede Intet deraf, og denne Tale var skjult for dem, og de forstode ikke det, som blev sagt.","Men de fattede Intet deraf, og denne Tale var skjult for dem, og de forstode ikke det, som blev sagt."],[18,35,"Men det skete, der han kom nær til Jericho, sad en Blind ved Veien og tiggede.","Men det skete, der han kom nær til Jericho, sad en Blind ved Veien og tiggede."],[18,36,"Og der denne hørte Folket gaae forbi, spurgte han, hvad dette var?","Og der denne hørte Folket gaae forbi, spurgte han, hvad dette var?"],[18,37,"Men de forkyndte ham, at Jesus af Nazareth kom forbi.","Men de forkyndte ham, at Jesus af Nazareth kom forbi."],[18,38,"Og han raabte og sagde: Jesus, du Davids Søn, forbarm dig over mig!","Og han raabte og sagde: Jesus, du Davids Søn, forbarm dig over mig!"],[18,39,"Og de, som gik foran, truede ham, at han skulle tie; men desto mere raabte han: du Davids Søn, forbarm dig over mig!","Og de, som gik foran, truede ham, at han skulle tie; men desto mere raabte han: du Davids Søn, forbarm dig over mig!"],[18,40,"Da stod Jesus stille og bød ham føres til sig; men der han kom nær til ham, spurgte han ham og sagde:","Da stod Jesus stille og bød ham føres til sig; men der han kom nær til ham, spurgte han ham og sagde:"],[18,41,"hvad vil du, at jeg skal gjøre dig? Men han sagde: Herre! at jeg maa blive seende.","hvad vil du, at jeg skal gjøre dig? Men han sagde: Herre! at jeg maa blive seende."],[18,42,"Og Jesus sagde til ham: bliv seende! din Tro haver frelst dig.","Og Jesus sagde til ham: bliv seende! din Tro haver frelst dig."],[18,43,"Og strax blev han seende, og fulgte ham og prisede Gud; og alt Folket, som saae det, lovede Gud.","Og strax blev han seende, og fulgte ham og prisede Gud; og alt Folket, som saae det, lovede Gud."],[19,1,"Og han kom ind i Jericho og drog derigjennem.","Og han kom ind i Jericho og drog derigjennem."],[19,2,"Og see, der var en Mand, som hedte Zachæus; han var Toldernes Øverste, og han var rig.","Og see, der var en Mand, som hedte Zachæus; han var Toldernes Øverste, og han var rig."],[19,3,"Og han søgte efter at faae Jesus at see, hvo han var, og kunde ikke for Folket, fordi han var liden af Væxt.","Og han søgte efter at faae Jesus at see, hvo han var, og kunde ikke for Folket, fordi han var liden af Væxt."],[19,4,"Og han løb forud og steg op i et Morbærtræ, at han kunde see ham; thi han skulle komme frem ad den Vei.","Og han løb forud og steg op i et Morbærtræ, at han kunde see ham; thi han skulle komme frem ad den Vei."],[19,5,"Og der Jesus kom til Stedet, saae han op og blev ham vaer, og sagde til ham: Zachæus! skynd dig og stig ned; thi det bør mig i Dag at tage ind i dit Huus.","Og der Jesus kom til Stedet, saae han op og blev ham vaer, og sagde til ham: Zachæus! skynd dig og stig ned; thi det bør mig i Dag at tage ind i dit Huus."],[19,6,"Og han skyndte sig og steg ned, og annammede ham med Glæde.","Og han skyndte sig og steg ned, og annammede ham med Glæde."],[19,7,"Og de, som det saae, knurrede alle og sagde: han tager Herberge hos en syndig Mand.","Og de, som det saae, knurrede alle og sagde: han tager Herberge hos en syndig Mand."],[19,8,"Men Zachæus blev staaende og sagde til Herren: see, Herre! Halvdelen af mit Gods giver jeg de Fattige; og dersom jeg haver forfordelet Nogen, da giver jeg det firefold igjen.","Men Zachæus blev staaende og sagde til Herren: see, Herre! Halvdelen af mit Gods giver jeg de Fattige; og dersom jeg haver forfordelet Nogen, da giver jeg det firefold igjen."],[19,9,"Men Jesus sagde til ham: i Dag er dette Huus vederfaret Frelse, efterdi ogsaa han er en Abrahams Søn;","Men Jesus sagde til ham: i Dag er dette Huus vederfaret Frelse, efterdi ogsaa han er en Abrahams Søn;"],[19,10,"thi Menneskens Søn er kommen at søge og frelse det Fortabte.","thi Menneskens Søn er kommen at søge og frelse det Fortabte."],[19,11,"Men der de hørte paa dette, blev han ved og sagde en Lignelse, fordi han var nær Jerusalem, og de meente, at Guds Rige skulle strax aabenbares.","Men der de hørte paa dette, blev han ved og sagde en Lignelse, fordi han var nær Jerusalem, og de meente, at Guds Rige skulle strax aabenbares."],[19,12,"Han sagde da: En høibaaren Mand drog til et Land langt borte, at tage imod et Rige og at komme igjen.","Han sagde da: En høibaaren Mand drog til et Land langt borte, at tage imod et Rige og at komme igjen."],[19,13,"Men han kaldte ti af sine Tjenere, og gav dem ti Pund, og sagde til dem: kjøbslaaer, indtil jeg kommer.","Men han kaldte ti af sine Tjenere, og gav dem ti Pund, og sagde til dem: kjøbslaaer, indtil jeg kommer."],[19,14,"Men hans Borgere hadede ham, og skikkede Sendebud efter ham og lode sige: vi ville ikke, at denne skal regjere over os.","Men hans Borgere hadede ham, og skikkede Sendebud efter ham og lode sige: vi ville ikke, at denne skal regjere over os."],[19,15,"Og det begav sig, der han kom igjen, efterat han havde modtaget Riget, befalede han, at hine Tjenere, hvilke han havde givet Pengene, skulde kaldes til ham, at han kunde vide, hvad hver havde vundet.","Og det begav sig, der han kom igjen, efterat han havde modtaget Riget, befalede han, at hine Tjenere, hvilke han havde givet Pengene, skulde kaldes til ham, at han kunde vide, hvad hver havde vundet."],[19,16,"Da traadte den første frem og sagde: Herre! dit Pund haver forhvervet ti Pund.","Da traadte den første frem og sagde: Herre! dit Pund haver forhvervet ti Pund."],[19,17,"Og han sagde til ham: vel, du gode Tjener! efterdi du haver været tro i det Lidet, skal du have Magt over ti Stæder.","Og han sagde til ham: vel, du gode Tjener! efterdi du haver været tro i det Lidet, skal du have Magt over ti Stæder."],[19,18,"Og den anden kom og sagde: Herre! dit Pund haver indbragt fem Pund.","Og den anden kom og sagde: Herre! dit Pund haver indbragt fem Pund."],[19,19,"Men til denne sagde han ogsaa: og du skal være over fem Stæder.","Men til denne sagde han ogsaa: og du skal være over fem Stæder."],[19,20,"Og en anden kom og sagde: Herre! see, her er dit Pund, hvilket jeg haver havt forvaret i et Klæde.","Og en anden kom og sagde: Herre! see, her er dit Pund, hvilket jeg haver havt forvaret i et Klæde."],[19,21,"Thi jeg frygtede for dig, efterdi du er en streng Mand; du tager det, som du ikke lagde, og høster det, som du ikke saaede.","Thi jeg frygtede for dig, efterdi du er en streng Mand; du tager det, som du ikke lagde, og høster det, som du ikke saaede."],[19,22,"Men han sagde til ham: efter din egen mund dømmer jeg dig, du onde Tjener! Du vidste, at jeg er en streng Mand, som tager det, jeg ikke lagde, og høster det, jeg ikke saaede;","Men han sagde til ham: efter din egen mund dømmer jeg dig, du onde Tjener! Du vidste, at jeg er en streng Mand, som tager det, jeg ikke lagde, og høster det, jeg ikke saaede;"],[19,23,"hvi gav du da ikke mine Penge til Vexelbordet, at jeg ved min Hjemkomst kunde krævet dem med Rente?","hvi gav du da ikke mine Penge til Vexelbordet, at jeg ved min Hjemkomst kunde krævet dem med Rente?"],[19,24,"Og han sagde til dem, som stode hos: tager Pundet fra ham, og giver det til den, som haver de ti Pund.","Og han sagde til dem, som stode hos: tager Pundet fra ham, og giver det til den, som haver de ti Pund."],[19,25,"(Og de sagde til ham: Herre! han haver ti Pund.)","(Og de sagde til ham: Herre! han haver ti Pund.)"],[19,26,"Thi jeg siger Eder, at hver den, som haver, ham skal gives; men fra den, som ikke haver, fra ham skal tages ogsaa det, han haver.","Thi jeg siger Eder, at hver den, som haver, ham skal gives; men fra den, som ikke haver, fra ham skal tages ogsaa det, han haver."],[19,27,"Og nu fører hid hine mine Fjender, som ikke vilde, at jeg skulde regjere over dem, og slaaer dem ihjel for mine Øine.","Og nu fører hid hine mine Fjender, som ikke vilde, at jeg skulde regjere over dem, og slaaer dem ihjel for mine Øine."],[19,28,"Og der han dette havde sagt, drog han frem og reiste op til Jerusalem.","Og der han dette havde sagt, drog han frem og reiste op til Jerusalem."],[19,29,"Og det begav sig, der han kom nær til Bethphage og Bethanien, til det Bjerg, som kaldes Oliebjerget, sendte han to af sine Disciple og sagde:","Og det begav sig, der han kom nær til Bethphage og Bethanien, til det Bjerg, som kaldes Oliebjerget, sendte han to af sine Disciple og sagde:"],[19,30,"gaaer hen til den By, som ligger for Eder; naar I komme derind, skulle I finde et Føl bundet, paa hvilket der aldrig sad noget Menneske; løser det og fører det hid.","gaaer hen til den By, som ligger for Eder; naar I komme derind, skulle I finde et Føl bundet, paa hvilket der aldrig sad noget Menneske; løser det og fører det hid."],[19,31,"Og dersom Nogen spørger Eder: hvi løse I det? da siger saaledes til ham: Herren haver det behov.","Og dersom Nogen spørger Eder: hvi løse I det? da siger saaledes til ham: Herren haver det behov."],[19,32,"Men de Udsendte gik hen og fandt det, ligesom han havde sagt dem.","Men de Udsendte gik hen og fandt det, ligesom han havde sagt dem."],[19,33,"Men der de løste Føllet, sagde dets Herre til dem: hvi løse I Føllet?","Men der de løste Føllet, sagde dets Herre til dem: hvi løse I Føllet?"],[19,34,"Men de sagde: Herren haver det behov.","Men de sagde: Herren haver det behov."],[19,35,"Og de førte det til Jesus, og lagde deres Klæder paa Føllet, og satte Jesus derpaa.","Og de førte det til Jesus, og lagde deres Klæder paa Føllet, og satte Jesus derpaa."],[19,36,"Og der han reiste frem, bredte de deres Klæder under ham paa Veien.","Og der han reiste frem, bredte de deres Klæder under ham paa Veien."],[19,37,"Men der han nu kom nær ved Nedgangen af Oliebjerget, begyndte Disciplenes ganske Hob gladelig at love Gud med høi Røst over alle de kraftige Gjerninger, som de havde seet, og sagde:","Men der han nu kom nær ved Nedgangen af Oliebjerget, begyndte Disciplenes ganske Hob gladelig at love Gud med høi Røst over alle de kraftige Gjerninger, som de havde seet, og sagde:"],[19,38,"Velsignet den, som kommer en Konge i Herrens Navn! Fred i Himmelen, og Ære i det Høieste!","Velsignet den, som kommer en Konge i Herrens Navn! Fred i Himmelen, og Ære i det Høieste!"],[19,39,"Og Nogle Pharisæere af Skaren sagde til ham: Mester straf dine Disciple.","Og Nogle Pharisæere af Skaren sagde til ham: Mester straf dine Disciple."],[19,40,"Og han svarede og sagde til dem: jeg siger Eder, at dersom disse taug, da skulde Stenene raabe.","Og han svarede og sagde til dem: jeg siger Eder, at dersom disse taug, da skulde Stenene raabe."],[19,41,"Og der han kom nær til og saae Staden, græd han over den og sagde:","Og der han kom nær til og saae Staden, græd han over den og sagde:"],[19,42,"vidste du dog, ja end paa denne din Dag, hvad der tjener til din Fred! Men nu er det skjult for dine Øine.","vidste du dog, ja end paa denne din Dag, hvad der tjener til din Fred! Men nu er det skjult for dine Øine."],[19,43,"Derfor skulle de Dage komme over dig, da dine Fjender skulle kaste en Vold op omkring dig og beleire dig rundt omkring og trænge dig allevegne;","Derfor skulle de Dage komme over dig, da dine Fjender skulle kaste en Vold op omkring dig og beleire dig rundt omkring og trænge dig allevegne;"],[19,44,"og de skulle lægge dig slet øde og dine Børn i dig, og ikke lade Steen paa Steen i dig, fordi du ikke kjendte din Besøgelses Tid.","og de skulle lægge dig slet øde og dine Børn i dig, og ikke lade Steen paa Steen i dig, fordi du ikke kjendte din Besøgelses Tid."],[19,45,"Og han gik ind i Templet, og begyndte at uddrive dem, som derudi solgte og kjøbte,","Og han gik ind i Templet, og begyndte at uddrive dem, som derudi solgte og kjøbte,"],[19,46,"og sagde til dem: der er skrevet: mit Huus er et Bedehuus; men I have gjort det til en Røverkule.","og sagde til dem: der er skrevet: mit Huus er et Bedehuus; men I have gjort det til en Røverkule."],[19,47,"Og han lærte daglig i Templet; men de Ypperstepræster og Skriftkloge og de Øverste for Folket søgte at omkomme ham.","Og han lærte daglig i Templet; men de Ypperstepræster og Skriftkloge og de Øverste for Folket søgte at omkomme ham."],[19,48,"Og de fandt ikke, hvad de skulde gjøre; thi alt Folket hængte ved ham og hørte ham.","Og de fandt ikke, hvad de skulde gjøre; thi alt Folket hængte ved ham og hørte ham."],[20,1,"Og det begav sig paa een af de Dage, der han lærte Folket i Templet og prædikede Evangelium, kom med eet de Ypperstepræster og Skriftkloge tilligemed de Ældste.","Og det begav sig paa een af de Dage, der han lærte Folket i Templet og prædikede Evangelium, kom med eet de Ypperstepræster og Skriftkloge tilligemed de Ældste."],[20,2,"Og de talede til ham og sagde: siig os, af hvad Magt gjør du disse Ting? eller hvo er den, som haver givet dig denne Magt?","Og de talede til ham og sagde: siig os, af hvad Magt gjør du disse Ting? eller hvo er den, som haver givet dig denne Magt?"],[20,3,"Men han svarede og sagde til dem: ogsaa jeg vil spørge Eder om een Sag, siger mig og det:","Men han svarede og sagde til dem: ogsaa jeg vil spørge Eder om een Sag, siger mig og det:"],[20,4,"Johannes’ Daab, var den af Himmelen eller af Mennesker?","Johannes’ Daab, var den af Himmelen eller af Mennesker?"],[20,5,"Men de overveiede ved sig selv og sagde: sige vi: af Himmelen, da siger han: hvorfor troede I ham da ikke?","Men de overveiede ved sig selv og sagde: sige vi: af Himmelen, da siger han: hvorfor troede I ham da ikke?"],[20,6,"Men sige vi: af Mennesker, da stener alt Folket os; thi det er fast i den Mening, at Johannes var en Prophet.","Men sige vi: af Mennesker, da stener alt Folket os; thi det er fast i den Mening, at Johannes var en Prophet."],[20,7,"Og de svarede, at de vidste ikke hvorfra.","Og de svarede, at de vidste ikke hvorfra."],[20,8,"Og Jesus sagde til dem: saa siger jeg Eder ikke heller, af hvad Magt jeg gjør disse Ting.","Og Jesus sagde til dem: saa siger jeg Eder ikke heller, af hvad Magt jeg gjør disse Ting."],[20,9,"Men han begyndte at sige til Folket denne Lignelse: Et Menneske plantede en Viingaard og leiede den til Viingaardsmænd, og drog udenlands en Tid lang.","Men han begyndte at sige til Folket denne Lignelse: Et Menneske plantede en Viingaard og leiede den til Viingaardsmænd, og drog udenlands en Tid lang."],[20,10,"Og der Tiden kom, sendte han en Tjener til Viingaardsmændene, at de skulle give ham af Viingaardens Frugt; men Viingaardsmændene sloge ham, og lode ham tomhændet fra sig.","Og der Tiden kom, sendte han en Tjener til Viingaardsmændene, at de skulle give ham af Viingaardens Frugt; men Viingaardsmændene sloge ham, og lode ham tomhændet fra sig."],[20,11,"Og han blev ved, og sendte en anden Tjener; men de sloge ogsaa denne, og forhaanede ham, og lode ham tomhændet fra sig.","Og han blev ved, og sendte en anden Tjener; men de sloge ogsaa denne, og forhaanede ham, og lode ham tomhændet fra sig."],[20,12,"Og han blev ved, og sendte den tredie; men ogsaa denne saarede de, og udstødte ham.","Og han blev ved, og sendte den tredie; men ogsaa denne saarede de, og udstødte ham."],[20,13,"Men Viingaardens Herre sagde: hvad skal jeg gjøre? jeg vil sende min Søn, den Elskelige, maaskee, naar de see ham, skulle de undsee sig.","Men Viingaardens Herre sagde: hvad skal jeg gjøre? jeg vil sende min Søn, den Elskelige, maaskee, naar de see ham, skulle de undsee sig."],[20,14,"Men der Viingaardsmændene saae ham, beraadte de sig indbyrdes og sagde: denne er Arvingen, kommer, lader os slaae ham ihjel, at Arven maa blive vores.","Men der Viingaardsmændene saae ham, beraadte de sig indbyrdes og sagde: denne er Arvingen, kommer, lader os slaae ham ihjel, at Arven maa blive vores."],[20,15,"Og de stødte ham udenfor Viingaarden, og sloge ham ihjel. Hvad skal nu Viingaardens Herre gjøre ved dem?","Og de stødte ham udenfor Viingaarden, og sloge ham ihjel. Hvad skal nu Viingaardens Herre gjøre ved dem?"],[20,16,"Han skal komme og udrydde disse Viingaardsmænd, og leie Viingaarden til andre. Men der de det hørte, sagde de: det skee aldrig!","Han skal komme og udrydde disse Viingaardsmænd, og leie Viingaarden til andre. Men der de det hørte, sagde de: det skee aldrig!"],[20,17,"Men han saae paa dem og sagde: hvad er da dette, som er skrevet: den Steen, som Bygningsmændene forskøde, den er bleven til en Hovedhjørnesteen?","Men han saae paa dem og sagde: hvad er da dette, som er skrevet: den Steen, som Bygningsmændene forskøde, den er bleven til en Hovedhjørnesteen?"],[20,18,"Hver, som falder paa denne Steen, bliver sønderstødt; men hvem den falder paa, ham skal den knuse.","Hver, som falder paa denne Steen, bliver sønderstødt; men hvem den falder paa, ham skal den knuse."],[20,19,"Og de Ypperstepræster og Skriftkloge søgte at lægge Haand paa ham i den samme Time, men de frygtede for Folket; thi de forstode, at han havde sagt denne Lignelse imod dem.","Og de Ypperstepræster og Skriftkloge søgte at lægge Haand paa ham i den samme Time, men de frygtede for Folket; thi de forstode, at han havde sagt denne Lignelse imod dem."],[20,20,"Og de toge vare paa ham, og udsendte Lurere, der anstillede sig, som om de vare retfærdige, for at fange ham i Talen, paa det de kunde overantvorde ham til Øvrigheden og Landshøvdingens Magt.","Og de toge vare paa ham, og udsendte Lurere, der anstillede sig, som om de vare retfærdige, for at fange ham i Talen, paa det de kunde overantvorde ham til Øvrigheden og Landshøvdingens Magt."],[20,21,"Og de spurgte ham og sagde: Mester! vi vide, at du taler og lærer rettelig, og ikke anseer nogen Person, men lærer Guds Vei i Sandhed.","Og de spurgte ham og sagde: Mester! vi vide, at du taler og lærer rettelig, og ikke anseer nogen Person, men lærer Guds Vei i Sandhed."],[20,22,"Er det os tilladt, at give Keiseren Skat, eller ei?","Er det os tilladt, at give Keiseren Skat, eller ei?"],[20,23,"Men da han mærkede deres Trædskhed, sagde han til dem: hvi friste I mig?","Men da han mærkede deres Trædskhed, sagde han til dem: hvi friste I mig?"],[20,24,"Viser mig en Penning; hvis Billede og Overskrift haver den? Men de svarede og sagde: Keiserens.","Viser mig en Penning; hvis Billede og Overskrift haver den? Men de svarede og sagde: Keiserens."],[20,25,"Men han sagde til dem: saa giver da Keiseren det, Keiserens er, og Gud det, Guds er.","Men han sagde til dem: saa giver da Keiseren det, Keiserens er, og Gud det, Guds er."],[20,26,"Og de kunde ikke fange ham i Ord i Folkets Paahør, og de forundrede sig over hans Svar og taug.","Og de kunde ikke fange ham i Ord i Folkets Paahør, og de forundrede sig over hans Svar og taug."],[20,27,"Men nogle af Sadducæerne, hvilke negte, at der er Opstandelse, gik til ham og spurgte ham og sagde:","Men nogle af Sadducæerne, hvilke negte, at der er Opstandelse, gik til ham og spurgte ham og sagde:"],[20,28,"Mester! Moses haver foreskrevet os: dersom Nogen haver en Broder, som er gift, og samme døer barnløs, da skal dennes Broder tage Hustruen, og opreise sin Broder Sæd.","Mester! Moses haver foreskrevet os: dersom Nogen haver en Broder, som er gift, og samme døer barnløs, da skal dennes Broder tage Hustruen, og opreise sin Broder Sæd."],[20,29,"Nu vare her syv Brødre; og den første tog en Hustru, og døde barnløs.","Nu vare her syv Brødre; og den første tog en Hustru, og døde barnløs."],[20,30,"Og den anden tog Hustruen; ogsaa han døde barnløs.","Og den anden tog Hustruen; ogsaa han døde barnløs."],[20,31,"Og den tredie tog hende, og saaledes alle syv; og de døde uden at efterlade Børn.","Og den tredie tog hende, og saaledes alle syv; og de døde uden at efterlade Børn."],[20,32,"Men sidst af dem alle døde ogsaa Kvinden.","Men sidst af dem alle døde ogsaa Kvinden."],[20,33,"I Opstandelsen nu, hvis Hustru af disse skal hun være? thi de have alle syv havt hende til Hustru.","I Opstandelsen nu, hvis Hustru af disse skal hun være? thi de have alle syv havt hende til Hustru."],[20,34,"Og Jesus svarede og sagde til dem: denne Verdens Børn tage til Ægte og bortgiftes.","Og Jesus svarede og sagde til dem: denne Verdens Børn tage til Ægte og bortgiftes."],[20,35,"Men de, som agtes værdige til at faae Deel i hiin Verden og i Opstandelsen fra de Døde, tage hverken til Ægte eller bortgiftes.","Men de, som agtes værdige til at faae Deel i hiin Verden og i Opstandelsen fra de Døde, tage hverken til Ægte eller bortgiftes."],[20,36,"De kunne jo ikke mere døe; thi de ere Engle lige, og ere Guds Børn, efterdi de ere Opstandelsens Børn.","De kunne jo ikke mere døe; thi de ere Engle lige, og ere Guds Børn, efterdi de ere Opstandelsens Børn."],[20,37,"Men at de Døde opvækkes, haver og Moses givet tilkjende i Stedet om Tornebusken, der han kalder Herren: Abrahams Gud og Isaaks Gud og Jakobs Gud.","Men at de Døde opvækkes, haver og Moses givet tilkjende i Stedet om Tornebusken, der han kalder Herren: Abrahams Gud og Isaaks Gud og Jakobs Gud."],[20,38,"Men han er ikke de Dødes Gud, men de Levendes; thi ham leve de alle.","Men han er ikke de Dødes Gud, men de Levendes; thi ham leve de alle."],[20,39,"Men nogle af de Skriftkloge svarede og sagde: Mester! du talede vel.","Men nogle af de Skriftkloge svarede og sagde: Mester! du talede vel."],[20,40,"Og de turde ikke ydermere spørge ham om Noget.","Og de turde ikke ydermere spørge ham om Noget."],[20,41,"Men han sagde til dem: hvorledes siger man Christus at være Davids Søn?","Men han sagde til dem: hvorledes siger man Christus at være Davids Søn?"],[20,42,"da dog David siger i Psalmernes Bog: Herren sagde til min Herre: sid hos min høire Haand,","da dog David siger i Psalmernes Bog: Herren sagde til min Herre: sid hos min høire Haand,"],[20,43,"indtil jeg lægger dine Fjender til dine Fødders Skammel.","indtil jeg lægger dine Fjender til dine Fødders Skammel."],[20,44,"Altsaa kalder David ham en Herre; hvorledes er han da hans Søn?","Altsaa kalder David ham en Herre; hvorledes er han da hans Søn?"],[20,45,"Men i alt Folkets Paahør sagde han til sine Disciple:","Men i alt Folkets Paahør sagde han til sine Disciple:"],[20,46,"vogter Eder for de Skriftkloge, som gjerne gaae omkring i lange Klæder, og lade sig gjerne hilse paa Torvene, og ville gjerne have de fornemste Sæder i Synagogerne, og sidde øverst tilbords ved Nadverne,","vogter Eder for de Skriftkloge, som gjerne gaae omkring i lange Klæder, og lade sig gjerne hilse paa Torvene, og ville gjerne have de fornemste Sæder i Synagogerne, og sidde øverst tilbords ved Nadverne,"],[20,47,"dem, som opæde Enkers Huse, og paa Skrømt bede længe; disse skulle faae des haardere Dom.","dem, som opæde Enkers Huse, og paa Skrømt bede længe; disse skulle faae des haardere Dom."],[21,1,"Men idet han saae op, blev han de Rige vaer, som lagde deres Gaver i Templets Kiste.","Men idet han saae op, blev han de Rige vaer, som lagde deres Gaver i Templets Kiste."],[21,2,"Men han saae og en fattig Enke, som lagde to Skjerve deri.","Men han saae og en fattig Enke, som lagde to Skjerve deri."],[21,3,"Og han sagde: sandelig siger jeg Eder: denne fattige Enke haver lagt Mere end alle.","Og han sagde: sandelig siger jeg Eder: denne fattige Enke haver lagt Mere end alle."],[21,4,"Thi alle disse have lagt af deres Overflod som Gaver for Gud; men denne haver af sin Armod lagt al sin Eiendom.","Thi alle disse have lagt af deres Overflod som Gaver for Gud; men denne haver af sin Armod lagt al sin Eiendom."],[21,5,"Og der Nogle sagde om Templet, at det var prydet med deilige Stene og Klenodier, sagde han:","Og der Nogle sagde om Templet, at det var prydet med deilige Stene og Klenodier, sagde han:"],[21,6,"hvad angaaer disse Ting, som I skue, skulle de Dage komme, paa hvilke der ikke skal lades Steen paa Steen, som jo skal nedbrydes.","hvad angaaer disse Ting, som I skue, skulle de Dage komme, paa hvilke der ikke skal lades Steen paa Steen, som jo skal nedbrydes."],[21,7,"Da spurgte de ham og sagde: Mester! naar skal dette da være? og hvilket er Tegnet, naar dette skal skee?","Da spurgte de ham og sagde: Mester! naar skal dette da være? og hvilket er Tegnet, naar dette skal skee?"],[21,8,"Men han sagde: seer til, I ikke blive forførte; thi Mange skulle komme under mit Navn og sige, at det er mig, og at Tiden er kommen nær. Gaaer derfor ikke efter dem.","Men han sagde: seer til, I ikke blive forførte; thi Mange skulle komme under mit Navn og sige, at det er mig, og at Tiden er kommen nær. Gaaer derfor ikke efter dem."],[21,9,"Men naar I høre om Krig og Oprør, forfærdes ikke; thi dette bør først at skee, men Enden er ikke strax.","Men naar I høre om Krig og Oprør, forfærdes ikke; thi dette bør først at skee, men Enden er ikke strax."],[21,10,"Da, sagde han til dem, skal Folk reise sig mod Folk, og Rige mod Rige.","Da, sagde han til dem, skal Folk reise sig mod Folk, og Rige mod Rige."],[21,11,"Og der skal skee store Jordskjælv her og der, og Hunger og Pestilentse, og skee skrækkelige Ting og store Tegn af Himmelen.","Og der skal skee store Jordskjælv her og der, og Hunger og Pestilentse, og skee skrækkelige Ting og store Tegn af Himmelen."],[21,12,"Men før alt dette skulle de lægge Haand paa Eder, og forfølge og overantvordede Eder i Synagoger og Fængsler, og føre Eder for Konger og Fyrster for mit Navns Skyld.","Men før alt dette skulle de lægge Haand paa Eder, og forfølge og overantvordede Eder i Synagoger og Fængsler, og føre Eder for Konger og Fyrster for mit Navns Skyld."],[21,13,"Men det skal vederfares Eder til et Vidnesbyrd.","Men det skal vederfares Eder til et Vidnesbyrd."],[21,14,"Lægger det da paa Hjerte, at I ikke forud betænkte, hvorledes I skulle forsvare Eder.","Lægger det da paa Hjerte, at I ikke forud betænkte, hvorledes I skulle forsvare Eder."],[21,15,"Thi jeg vil give Eder Mund og Viisdom, hvilken alle Eders Modstandere ikke skulle kunne modsige og ei modstaae.","Thi jeg vil give Eder Mund og Viisdom, hvilken alle Eders Modstandere ikke skulle kunne modsige og ei modstaae."],[21,16,"Men I skulle og forraades af Forældre og Brødre og Frænder og Venner, og de skulle slaae Nogle af Eder ihjel.","Men I skulle og forraades af Forældre og Brødre og Frænder og Venner, og de skulle slaae Nogle af Eder ihjel."],[21,17,"Og I skulle hades af Alle for mit Navns Skyld.","Og I skulle hades af Alle for mit Navns Skyld."],[21,18,"Dog ikke et Haar af Eders Hoved skal forkomme.","Dog ikke et Haar af Eders Hoved skal forkomme."],[21,19,"Ved Eders Bestandighed bevarer Eders Sjæle.","Ved Eders Bestandighed bevarer Eders Sjæle."],[21,20,"Men naar I see Jerusalem rundt omkring beleiret af Krigshære, da mærker, at dens Ødelæggelse er kommen nær.","Men naar I see Jerusalem rundt omkring beleiret af Krigshære, da mærker, at dens Ødelæggelse er kommen nær."],[21,21,"De, som da ere i Judæa, flye til Bjergene; og de, som ere midt i Staden, vige derudfra; og de, som ere paa Landet, komme ikke ind i den!","De, som da ere i Judæa, flye til Bjergene; og de, som ere midt i Staden, vige derudfra; og de, som ere paa Landet, komme ikke ind i den!"],[21,22,"Thi disse ere Hevnens Dage, da Alt, hvad skrevet er, skal fuldkommes.","Thi disse ere Hevnens Dage, da Alt, hvad skrevet er, skal fuldkommes."],[21,23,"Men vee de Frugtsommelige og dem, som give Die, i de Dage; thi der skal være stor Nød paa Jorden og Vrede over dette Folk.","Men vee de Frugtsommelige og dem, som give Die, i de Dage; thi der skal være stor Nød paa Jorden og Vrede over dette Folk."],[21,24,"Og de skulle falde for Sværdets Eg, og føres fangne til alle Hedningerne; og Jerusalem skal nedtrædes af Hedningerne, indtil Hedningernes Tider fuldkommes.","Og de skulle falde for Sværdets Eg, og føres fangne til alle Hedningerne; og Jerusalem skal nedtrædes af Hedningerne, indtil Hedningernes Tider fuldkommes."],[21,25,"Og der skal skee Tegn i Sol og Maane og Stjerner, og paa Jorden skulle Folkene ængstes i Fortvivlelse, naar Havet og Bølgerne bruse,","Og der skal skee Tegn i Sol og Maane og Stjerner, og paa Jorden skulle Folkene ængstes i Fortvivlelse, naar Havet og Bølgerne bruse,"],[21,26,"naar Menneskene forsmægte af Frygt og de Tings Forventelse, som skulle komme over Jorderige; thi Himmelens Kræfter skulle røres.","naar Menneskene forsmægte af Frygt og de Tings Forventelse, som skulle komme over Jorderige; thi Himmelens Kræfter skulle røres."],[21,27,"Og da skulle de see Menneskens Søn komme i Skyen med megen Kraft og Herlighed.","Og da skulle de see Menneskens Søn komme i Skyen med megen Kraft og Herlighed."],[21,28,"Men naar disse Ting begynde at skee, da seer op, og opløfter Eders Hoveder, efterdi Eders Forløsning stunder til.","Men naar disse Ting begynde at skee, da seer op, og opløfter Eders Hoveder, efterdi Eders Forløsning stunder til."],[21,29,"Og han sagde dem en Lignelse: seer Figentræet og alle Træer;","Og han sagde dem en Lignelse: seer Figentræet og alle Træer;"],[21,30,"Naar de springe ud, da skjønne I af Eder selv, at Sommeren nu er nær.","Naar de springe ud, da skjønne I af Eder selv, at Sommeren nu er nær."],[21,31,"Ligesaa og I, naar I see disse Ting at skee, da kjende I, at Guds Rige er nær.","Ligesaa og I, naar I see disse Ting at skee, da kjende I, at Guds Rige er nær."],[21,32,"Sandelig siger jeg Eder, at denne Slægt skal ikke forgaae, førend det skeer altsammen.","Sandelig siger jeg Eder, at denne Slægt skal ikke forgaae, førend det skeer altsammen."],[21,33,"Himmelen og Jorden skulle forgaae; men mine Ord skulle ingenlunde forgaae.","Himmelen og Jorden skulle forgaae; men mine Ord skulle ingenlunde forgaae."],[21,34,"Men vogter Eder, at Eders Hjerter ikke nogen Tid besværes med Fraadseri og Drukkenskab og med Sorrig for Næring, og denne Dag skal komme pludselig over Eder.","Men vogter Eder, at Eders Hjerter ikke nogen Tid besværes med Fraadseri og Drukkenskab og med Sorrig for Næring, og denne Dag skal komme pludselig over Eder."],[21,35,"Thi den skal komme som en Snare over alle dem, som boe paa den ganske Jord.","Thi den skal komme som en Snare over alle dem, som boe paa den ganske Jord."],[21,36,"Derfor vaager og beder til enhver Tid, at I kunne agtes værdige til at undflye alle disse Ting, som skee skulle, og til at bestaae for Menneskens Søn.","Derfor vaager og beder til enhver Tid, at I kunne agtes værdige til at undflye alle disse Ting, som skee skulle, og til at bestaae for Menneskens Søn."],[21,37,"Men han lærte om Dagene i Templet, men om Nætterne gik han ud, og opholdt sig Natten over paa det Bjerg, som kaldes Oliebjerget.","Men han lærte om Dagene i Templet, men om Nætterne gik han ud, og opholdt sig Natten over paa det Bjerg, som kaldes Oliebjerget."],[21,38,"Og alt Folket kom aarle til ham i Templet for at høre ham.","Og alt Folket kom aarle til ham i Templet for at høre ham."],[22,1,"Men de usyrede Brøds Høitid, som kaldes Paaske, nærmede sig.","Men de usyrede Brøds Høitid, som kaldes Paaske, nærmede sig."],[22,2,"Og de Ypperstepræster og Skriftkloge søgte, hvorledes de kunde ihjelslaae ham; thi de frygtede for Folket.","Og de Ypperstepræster og Skriftkloge søgte, hvorledes de kunde ihjelslaae ham; thi de frygtede for Folket."],[22,3,"Men Satanas foer i Judas med Tilnavn Ischariotes, som var en af de Tolv.","Men Satanas foer i Judas med Tilnavn Ischariotes, som var en af de Tolv."],[22,4,"Og han gik hen og talede med de Ypperstepræster og Høvedsmændene, hvorledes han vilde forraade ham til dem.","Og han gik hen og talede med de Ypperstepræster og Høvedsmændene, hvorledes han vilde forraade ham til dem."],[22,5,"Og de bleve glade, og lovede at give ham Penge.","Og de bleve glade, og lovede at give ham Penge."],[22,6,"Og han tilsagde det; og han søgte beleilig Tid til at forraade ham til dem uden Opløb.","Og han tilsagde det; og han søgte beleilig Tid til at forraade ham til dem uden Opløb."],[22,7,"Men de usyrede Brøds Dag kom, paa hvilken man burde slagte Paaskelammet.","Men de usyrede Brøds Dag kom, paa hvilken man burde slagte Paaskelammet."],[22,8,"Og han sendte Peter og Johannes og sagde: gaaer hen og bereder os Paaskelammet, at vi kunne æde det.","Og han sendte Peter og Johannes og sagde: gaaer hen og bereder os Paaskelammet, at vi kunne æde det."],[22,9,"Men de sagde til ham: hvor vil du, at vi skulle berede det?","Men de sagde til ham: hvor vil du, at vi skulle berede det?"],[22,10,"Men han sagde til dem: see, naar I komme ind i Staden, skal et Menneske møde Eder, som bærer en Vandkrukke; følger ham i Huset, hvor han gaaer ind,","Men han sagde til dem: see, naar I komme ind i Staden, skal et Menneske møde Eder, som bærer en Vandkrukke; følger ham i Huset, hvor han gaaer ind,"],[22,11,"og siger til Huusbonden i Huset: Mesteren lader dig sige: hvor er det Herberge, der jeg kan æde Paaskelammet med mine Disciple?","og siger til Huusbonden i Huset: Mesteren lader dig sige: hvor er det Herberge, der jeg kan æde Paaskelammet med mine Disciple?"],[22,12,"Og han skal vise Eder en stor Sal tillavet; der bereder det.","Og han skal vise Eder en stor Sal tillavet; der bereder det."],[22,13,"Men de gik hen og fandt det, ligesom han havde sagt dem; og de beredte Paaskelammet.","Men de gik hen og fandt det, ligesom han havde sagt dem; og de beredte Paaskelammet."],[22,14,"Og der Timen kom, satte han sig tilbords, og de tolv Apostler med ham.","Og der Timen kom, satte han sig tilbords, og de tolv Apostler med ham."],[22,15,"Og han sagde til dem: jeg haver hjerteligen længtes efter at æde dette Paaskelam med Eder, førend jeg lider.","Og han sagde til dem: jeg haver hjerteligen længtes efter at æde dette Paaskelam med Eder, førend jeg lider."],[22,16,"Thi jeg siger Eder, at jeg skal ingenlunde mere æde af det, førend det bliver fuldkommet i Guds Rige.","Thi jeg siger Eder, at jeg skal ingenlunde mere æde af det, førend det bliver fuldkommet i Guds Rige."],[22,17,"Og han tog Kalken, takkede og sagde: tager dette, og deler det imellem Eder.","Og han tog Kalken, takkede og sagde: tager dette, og deler det imellem Eder."],[22,18,"Thi jeg siger Eder, at jeg skal ikke drikke af Viintræets Frugt, førend Guds Rige kommer.","Thi jeg siger Eder, at jeg skal ikke drikke af Viintræets Frugt, førend Guds Rige kommer."],[22,19,"Og han tog Brødet, takkede og brød det, og gav dem det og sagde: dette er mit Legeme, hvilket gives for Eder; dette gjører til min Ihukommelse.","Og han tog Brødet, takkede og brød det, og gav dem det og sagde: dette er mit Legeme, hvilket gives for Eder; dette gjører til min Ihukommelse."],[22,20,"Ligesaa tog han og Kalken, efterat de havde holdt Nadvere, og sagde: denne Kalk er det Nye Testament i mit Blod, hvilket udgydes for Eder.","Ligesaa tog han og Kalken, efterat de havde holdt Nadvere, og sagde: denne Kalk er det Nye Testament i mit Blod, hvilket udgydes for Eder."],[22,21,"Dog see, hans Haand, som mig forraader, er over Bordet med mig.","Dog see, hans Haand, som mig forraader, er over Bordet med mig."],[22,22,"Og Menneskens Søn gaaer vel hen, som det er beskikket; dog vee det Menneske, ved hvem han bliver forraadt!","Og Menneskens Søn gaaer vel hen, som det er beskikket; dog vee det Menneske, ved hvem han bliver forraadt!"],[22,23,"Og de begyndte at bespørge sig indbyrdes om, hvo af dem det dog maatte være, som dette skulde gjøre?","Og de begyndte at bespørge sig indbyrdes om, hvo af dem det dog maatte være, som dette skulde gjøre?"],[22,24,"Der var og en Trætte iblandt dem derom, hvo af dem skulde holdes for at være den Største?","Der var og en Trætte iblandt dem derom, hvo af dem skulde holdes for at være den Største?"],[22,25,"Men han sagde til dem: Folkenes Konger herske over dem, og de, som have Magt over dem, kaldes naadige Herrer.","Men han sagde til dem: Folkenes Konger herske over dem, og de, som have Magt over dem, kaldes naadige Herrer."],[22,26,"I derimod ikke saaledes; men den Største iblandt Eder være som den Yngste, og den Øverste, som den, der tjener.","I derimod ikke saaledes; men den Største iblandt Eder være som den Yngste, og den Øverste, som den, der tjener."],[22,27,"Thi hvilken er størst: den, som sidder tilbords? eller den, som tjener? Mon ikke den, som sidder tilbords? Men jeg er i blandt Eder som den, der tjener.","Thi hvilken er størst: den, som sidder tilbords? eller den, som tjener? Mon ikke den, som sidder tilbords? Men jeg er i blandt Eder som den, der tjener."],[22,28,"Men I ere de, som ere blevne varagtige hos mig i mine Fristelser.","Men I ere de, som ere blevne varagtige hos mig i mine Fristelser."],[22,29,"Og jeg beskikker Eder Riget, ligesom min Fader beskikkede mig det,","Og jeg beskikker Eder Riget, ligesom min Fader beskikkede mig det,"],[22,30,"at I skulle æde og drikke ved mit Bord i mit Rige, og sidde paa Throner og dømme de tolv Israels Stammer.","at I skulle æde og drikke ved mit Bord i mit Rige, og sidde paa Throner og dømme de tolv Israels Stammer."],[22,31,"Men Herren sagde: Simon, Simon! see, Satanas begjerede Eder, at sigte Eder som Hvede.","Men Herren sagde: Simon, Simon! see, Satanas begjerede Eder, at sigte Eder som Hvede."],[22,32,"Men jeg bad for dig, at din Tro skal ikke aflade; og naar du engang omvender dig, da styrk dine Brødre.","Men jeg bad for dig, at din Tro skal ikke aflade; og naar du engang omvender dig, da styrk dine Brødre."],[22,33,"Men han sagde til ham: Herre! jeg er rede at gaae med dig, baade i Fængsel og i Døden.","Men han sagde til ham: Herre! jeg er rede at gaae med dig, baade i Fængsel og i Døden."],[22,34,"Men han sagde: Peter! jeg siger dig: Hanen skal ikke gale i Dag, førend du tre Gange haver negtet, at du kjender mig.","Men han sagde: Peter! jeg siger dig: Hanen skal ikke gale i Dag, førend du tre Gange haver negtet, at du kjender mig."],[22,35,"Og han sagde til dem; der jeg udsendte Eder uden Pung og Taske og Skoe, fattedes Eder Noget? Men de sagde: Intet.","Og han sagde til dem; der jeg udsendte Eder uden Pung og Taske og Skoe, fattedes Eder Noget? Men de sagde: Intet."],[22,36,"Da sagde han til dem: men nu, hvo som har en Pung, tage den, ligesaa og en Taske; og hvo som ikke haver Sværd, sælge sit Klædebon, og kjøbe et.","Da sagde han til dem: men nu, hvo som har en Pung, tage den, ligesaa og en Taske; og hvo som ikke haver Sværd, sælge sit Klædebon, og kjøbe et."],[22,37,"Thi jeg siger Eder: det bør endnu fuldkommes paa mig, hvad skrevet er: han er og regnet iblandt Overtrædere; thi hvad der er skrevet om mig, haver Ende.","Thi jeg siger Eder: det bør endnu fuldkommes paa mig, hvad skrevet er: han er og regnet iblandt Overtrædere; thi hvad der er skrevet om mig, haver Ende."],[22,38,"Men de sagde: Herre! see, her ere to Sværd. Men han sagde til dem: det er nok.","Men de sagde: Herre! see, her ere to Sværd. Men han sagde til dem: det er nok."],[22,39,"Og han gik ud, og gik efter Sædvane til Oliebjerget; men hans Disciple fulgte ham ogsaa.","Og han gik ud, og gik efter Sædvane til Oliebjerget; men hans Disciple fulgte ham ogsaa."],[22,40,"Men der han kom til Stedet, sagde han til dem: beder, at I ikke skulle falde i Fristelse.","Men der han kom til Stedet, sagde han til dem: beder, at I ikke skulle falde i Fristelse."],[22,41,"Og han sled sig fra dem omtrent et Steenkast, og faldt paa Knæ, bad og sagde:","Og han sled sig fra dem omtrent et Steenkast, og faldt paa Knæ, bad og sagde:"],[22,42,"Fader, vilde du tage denne Kalk, fra mig! dog skee ikke min Villie, men din!","Fader, vilde du tage denne Kalk, fra mig! dog skee ikke min Villie, men din!"],[22,43,"Men en Engel af Himmelen aabenbaredes for ham og styrkede ham.","Men en Engel af Himmelen aabenbaredes for ham og styrkede ham."],[22,44,"Og der han var i Dødsangest, bad han heftigere; men hans Sved blev som Blodsdraaber, der falde ned paa Jorden.","Og der han var i Dødsangest, bad han heftigere; men hans Sved blev som Blodsdraaber, der falde ned paa Jorden."],[22,45,"Og der han stod op fra Bønnen og kom til sine Disciple, fandt han dem sovende af Bedrøvelse.","Og der han stod op fra Bønnen og kom til sine Disciple, fandt han dem sovende af Bedrøvelse."],[22,46,"Og han sagde til dem: hvi sove I? Staaer op og beder, at I ikke skulle falde i Fristelse.","Og han sagde til dem: hvi sove I? Staaer op og beder, at I ikke skulle falde i Fristelse."],[22,47,"Men der han endnu talede, see, da kom Skaren; og een af de Tolv, ved Navn Judas, gik foran dem og nærmede sig til Jesus for at kysse ham.","Men der han endnu talede, see, da kom Skaren; og een af de Tolv, ved Navn Judas, gik foran dem og nærmede sig til Jesus for at kysse ham."],[22,48,"Men Jesus sagde til ham: Judas! forraader du Menneskens Søn med et Kys?","Men Jesus sagde til ham: Judas! forraader du Menneskens Søn med et Kys?"],[22,49,"Men der de, som vare omkring ham, saae, hvad der vilde skee, sagde de til ham: Herre! skulle vi slaae til med Sværd?","Men der de, som vare omkring ham, saae, hvad der vilde skee, sagde de til ham: Herre! skulle vi slaae til med Sværd?"],[22,50,"Og een af dem slog den Ypperstepræstes Tjener, og afhuggede hans høire Øre.","Og een af dem slog den Ypperstepræstes Tjener, og afhuggede hans høire Øre."],[22,51,"Men Jesus svarede og sagde: tillader dem saa vidt! Og han rørte ved hans Øre og lægte ham.","Men Jesus svarede og sagde: tillader dem saa vidt! Og han rørte ved hans Øre og lægte ham."],[22,52,"Men Jesus sagde til de Ypperstepræster og Høvedsmændene for Templet og de Ældste, som vare komne til ham: I ere udgangne som mod en Røver med Sværd og Stænger.","Men Jesus sagde til de Ypperstepræster og Høvedsmændene for Templet og de Ældste, som vare komne til ham: I ere udgangne som mod en Røver med Sværd og Stænger."],[22,53,"Der jeg var dagligen hos Eder i Templet, udrakte I ikke Hænder imod mig; men denne er Eders Time og Mørkets Magt.","Der jeg var dagligen hos Eder i Templet, udrakte I ikke Hænder imod mig; men denne er Eders Time og Mørkets Magt."],[22,54,"Men de grebe ham og førte ham bort og bragte ham ind i den Ypperstepræstes Huus; men Peter fulgte langtfra efter.","Men de grebe ham og førte ham bort og bragte ham ind i den Ypperstepræstes Huus; men Peter fulgte langtfra efter."],[22,55,"Men de tændte en Ild midt i Palladset, og satte sig tilsammen, og Peter sad midt iblandt dem.","Men de tændte en Ild midt i Palladset, og satte sig tilsammen, og Peter sad midt iblandt dem."],[22,56,"Men en Pige saae ham sidde ved Ilden, og stirrede paa ham og sagde: denne var og med ham.","Men en Pige saae ham sidde ved Ilden, og stirrede paa ham og sagde: denne var og med ham."],[22,57,"Men han fornegtede ham og sagde: Kvinde! jeg kjender ham ikke.","Men han fornegtede ham og sagde: Kvinde! jeg kjender ham ikke."],[22,58,"Og lidet derefter saae en Anden ham og sagde: du er og een af dem; men Peter sagde: Menneske! jeg er det ikke.","Og lidet derefter saae en Anden ham og sagde: du er og een af dem; men Peter sagde: Menneske! jeg er det ikke."],[22,59,"Og henved en Time derefter bekræftede en Anden hardt og sagde: i Sandhed, denne var og med ham; thi han er og en Galilæer.","Og henved en Time derefter bekræftede en Anden hardt og sagde: i Sandhed, denne var og med ham; thi han er og en Galilæer."],[22,60,"Men Peter sagde: Menneske! jeg veed ikke, hvad du siger. Og strax, der han endnu talede, goel Hanen.","Men Peter sagde: Menneske! jeg veed ikke, hvad du siger. Og strax, der han endnu talede, goel Hanen."],[22,61,"Og Herren vendte sig, og saae paa Peter; og Peter kom Herrens Ord ihu, hvorledes han havde sagt til ham: førend Hanen galer, skal du fornegte mig tre Gange.","Og Herren vendte sig, og saae paa Peter; og Peter kom Herrens Ord ihu, hvorledes han havde sagt til ham: førend Hanen galer, skal du fornegte mig tre Gange."],[22,62,"Og Peter gik udenfor og græd bitterligen.","Og Peter gik udenfor og græd bitterligen."],[22,63,"Og de Mænd, som holdt Jesus, bespottede ham og sloge ham.","Og de Mænd, som holdt Jesus, bespottede ham og sloge ham."],[22,64,"Og de kastede et Klæde over ham og sloge ham i Ansigtet, og spurgte ham og sagde: spaa, hvo er den, som dig slog?","Og de kastede et Klæde over ham og sloge ham i Ansigtet, og spurgte ham og sagde: spaa, hvo er den, som dig slog?"],[22,65,"Og mange andre Bespottelser sagde de imod ham.","Og mange andre Bespottelser sagde de imod ham."],[22,66,"Og der det blev Dag, forsamlede Folkets Ældste sig og de Ypperstepræster og Skriftkloge, og førte ham op for deres Raad,","Og der det blev Dag, forsamlede Folkets Ældste sig og de Ypperstepræster og Skriftkloge, og førte ham op for deres Raad,"],[22,67,"og sagde: er du Christus? siig os det. Men han sagde til dem: siger jeg Eder det, troe I det ikke.","og sagde: er du Christus? siig os det. Men han sagde til dem: siger jeg Eder det, troe I det ikke."],[22,68,"Men om jeg og spørger, svare I mig ikke, eller lade mig løs.","Men om jeg og spørger, svare I mig ikke, eller lade mig løs."],[22,69,"Fra nu af skal Menneskens Søn sidde hos Guds Krafts høire Haand.","Fra nu af skal Menneskens Søn sidde hos Guds Krafts høire Haand."],[22,70,"Men de sagde alle: er du da den Guds Søn? Men han sagde til dem: I sige det; thi jeg er det.","Men de sagde alle: er du da den Guds Søn? Men han sagde til dem: I sige det; thi jeg er det."],[22,71,"Men de sagde: hvad have vi ydermere Vidnesbyrd behov? thi vi have selv hørt det af hans Mund.","Men de sagde: hvad have vi ydermere Vidnesbyrd behov? thi vi have selv hørt det af hans Mund."],[23,1,"Og deres ganske Hob stod op og førte ham for Pilatus.","Og deres ganske Hob stod op og førte ham for Pilatus."],[23,2,"Men de begyndte at anklage ham og sagde: denne have vi fundet at forvende Folket og forbyde at give Keiseren Skat, og sige sig selv at være Christus, en Konge.","Men de begyndte at anklage ham og sagde: denne have vi fundet at forvende Folket og forbyde at give Keiseren Skat, og sige sig selv at være Christus, en Konge."],[23,3,"Men Pilatus spurgte ham og sagde: er du den Jødernes Konge? Men han svarede ham og sagde: du siger det.","Men Pilatus spurgte ham og sagde: er du den Jødernes Konge? Men han svarede ham og sagde: du siger det."],[23,4,"Men Pilatus sagde til de Ypperstepræster og til Folket: jeg finder ingen Skyld hos dette Menneske.","Men Pilatus sagde til de Ypperstepræster og til Folket: jeg finder ingen Skyld hos dette Menneske."],[23,5,"Men de holdt hardt ved og sagde: han Oprør Folket, idet han lærer over al Judæa, fra Galilæa af, hvor han begyndte.","Men de holdt hardt ved og sagde: han Oprør Folket, idet han lærer over al Judæa, fra Galilæa af, hvor han begyndte."],[23,6,"Men der Pilatus hørte om Galilæa spurgte han, om dette Menneske var en Galilæer.","Men der Pilatus hørte om Galilæa spurgte han, om dette Menneske var en Galilæer."],[23,7,"Og der han fik at vide, at han hørte under Herodes’ Magt, sendte han ham til Herodes, som og selv var i Jerusalem i de samme Dage.","Og der han fik at vide, at han hørte under Herodes’ Magt, sendte han ham til Herodes, som og selv var i Jerusalem i de samme Dage."],[23,8,"Men der Herodes saae Jesus, blev han meget glad: thi han havde længe siden gjerne villet see ham, fordi han havde hørt meget om ham, og haabede at skulle see et Tegn skee af ham.","Men der Herodes saae Jesus, blev han meget glad: thi han havde længe siden gjerne villet see ham, fordi han havde hørt meget om ham, og haabede at skulle see et Tegn skee af ham."],[23,9,"Og han gjorde ham mange Spørgsmaal; men han svarede ham Intet.","Og han gjorde ham mange Spørgsmaal; men han svarede ham Intet."],[23,10,"Men de Ypperstepræster og Skriftkloge stode og anklagede ham heftig.","Men de Ypperstepræster og Skriftkloge stode og anklagede ham heftig."],[23,11,"Men der Herodes med sine Krigsfolk havde forhaanet og bespottet ham, kastede han et hvidt Klædebon om ham og sendte ham til Pilatus igjen.","Men der Herodes med sine Krigsfolk havde forhaanet og bespottet ham, kastede han et hvidt Klædebon om ham og sendte ham til Pilatus igjen."],[23,12,"Paa den Dag bleve Pilatus og Herodes hinandens Venner; thi de var før i Fjendskab med hinanden.","Paa den Dag bleve Pilatus og Herodes hinandens Venner; thi de var før i Fjendskab med hinanden."],[23,13,"Men Pilatus sammenkaldte de Ypperstepræster og de Øverste og Folket,","Men Pilatus sammenkaldte de Ypperstepræster og de Øverste og Folket,"],[23,14,"og sagde til dem: I have ført dette Menneske til mig som den, der afvender Folket; og see, jeg haver forhørt ham for Eder, og finder ingen Skyld hos dette Menneske i det, som I anklage ham for.","og sagde til dem: I have ført dette Menneske til mig som den, der afvender Folket; og see, jeg haver forhørt ham for Eder, og finder ingen Skyld hos dette Menneske i det, som I anklage ham for."],[23,15,"Herodes ikke heller; thi jeg sendte Eder til ham, og see, han haver Intet gjort, som han er skyldig at døe for.","Herodes ikke heller; thi jeg sendte Eder til ham, og see, han haver Intet gjort, som han er skyldig at døe for."],[23,16,"Derfor vil jeg revse ham og lade ham løs.","Derfor vil jeg revse ham og lade ham løs."],[23,17,"Men han var forbunden til at lade dem Een løs ved Høitiden.","Men han var forbunden til at lade dem Een løs ved Høitiden."],[23,18,"Men de raabte i den ganske Hob og sagde: bort med denne, men lad os Barrabas løs!","Men de raabte i den ganske Hob og sagde: bort med denne, men lad os Barrabas løs!"],[23,19,"(Denne var Kastet i Fængsel for et Oprør, som skete i Staden, og var for et Mord.)","(Denne var Kastet i Fængsel for et Oprør, som skete i Staden, og var for et Mord.)"],[23,20,"Da raabte Pilatus atter til dem, og vilde lade Jesus løs.","Da raabte Pilatus atter til dem, og vilde lade Jesus løs."],[23,21,"Men de tilraabte ham og sagde: korsfæst, korsfæst ham!","Men de tilraabte ham og sagde: korsfæst, korsfæst ham!"],[23,22,"Men han sagde tredie Gang til dem: hvad Ondt haver da denne gjort? Jeg finder ingen Dødsskyld hos ham; derfor vil jeg revse ham og lade ham løs.","Men han sagde tredie Gang til dem: hvad Ondt haver da denne gjort? Jeg finder ingen Dødsskyld hos ham; derfor vil jeg revse ham og lade ham løs."],[23,23,"Men de trængte paa med stort Skrig og begjerede, at han skulde korsfæstes; og deres og de Ypperstepræsters Skrig fik Overhaand.","Men de trængte paa med stort Skrig og begjerede, at han skulde korsfæstes; og deres og de Ypperstepræsters Skrig fik Overhaand."],[23,24,"Og Pilatus dømte, at deres Begjering skulde skee.","Og Pilatus dømte, at deres Begjering skulde skee."],[23,25,"Men han løsgav dem den, de begjerede, som var kastet i Fængsel for Oprør og Mord; men Jesus overgav han til deres Villie.","Men han løsgav dem den, de begjerede, som var kastet i Fængsel for Oprør og Mord; men Jesus overgav han til deres Villie."],[23,26,"Og der de førte ham ud, toge de fat paa en vis Simon fra Cyrene, som kom fra Marken, og de lagde Korset paa ham, at han skulde bære det efter Jesus.","Og der de førte ham ud, toge de fat paa en vis Simon fra Cyrene, som kom fra Marken, og de lagde Korset paa ham, at han skulde bære det efter Jesus."],[23,27,"Men en stor Hob Folk og Kvinder fulgte ham, som baade beklagede og begræd ham.","Men en stor Hob Folk og Kvinder fulgte ham, som baade beklagede og begræd ham."],[23,28,"Men Jesus vendte sig om til dem og sagde: I Jerusalems Døttre! græder ikke over mig, men græder over Eder selv og over Eders Børn.","Men Jesus vendte sig om til dem og sagde: I Jerusalems Døttre! græder ikke over mig, men græder over Eder selv og over Eders Børn."],[23,29,"Thi see, de Dage komme, paa hvilke man skal sige: salige ere de Ufrugtsommelige og de Liv, som ikke fødte, og de Bryster, som ikke gave Die.","Thi see, de Dage komme, paa hvilke man skal sige: salige ere de Ufrugtsommelige og de Liv, som ikke fødte, og de Bryster, som ikke gave Die."],[23,30,"Da skulle de begynde at sige til Bjergene: falder over os! og til Høiene: skjuler os!","Da skulle de begynde at sige til Bjergene: falder over os! og til Høiene: skjuler os!"],[23,31,"Thi gjør man dette med det grønne Træ, hvad vil da skee med det tørre.","Thi gjør man dette med det grønne Træ, hvad vil da skee med det tørre."],[23,32,"Men der bleve og to andre Misdædere førte ud for at henrettes med ham.","Men der bleve og to andre Misdædere førte ud for at henrettes med ham."],[23,33,"Og der de vare komne til det Sted, som kaldes Hovedpandested, korsfæstede de ham der og Misdæderne, den ene ved den høire, men den anden ved den venstre Side.","Og der de vare komne til det Sted, som kaldes Hovedpandested, korsfæstede de ham der og Misdæderne, den ene ved den høire, men den anden ved den venstre Side."],[23,34,"Men Jesus sagde: Fader! forlad dem; thi de vide ikke, hvad de gjøre. Men de skiftede hans Klæder og kastede Lod derom.","Men Jesus sagde: Fader! forlad dem; thi de vide ikke, hvad de gjøre. Men de skiftede hans Klæder og kastede Lod derom."],[23,35,"Og Folket stod og saae til; men de Øverste spottede ham tilligemed dem og sagde: han haver frelst Andre, han frelse sig selv, dersom han er den Christus, den Guds Udvalgte.","Og Folket stod og saae til; men de Øverste spottede ham tilligemed dem og sagde: han haver frelst Andre, han frelse sig selv, dersom han er den Christus, den Guds Udvalgte."],[23,36,"Men og Stridsmændene spottede ham, traadte til og rakte ham Eddike og sagde:","Men og Stridsmændene spottede ham, traadte til og rakte ham Eddike og sagde:"],[23,37,"dersom du er den Jødernes Konge, da frels dig selv.","dersom du er den Jødernes Konge, da frels dig selv."],[23,38,"Men der var og sat en Overskrift over ham, skreven paa Græsk og Latin og Hebraisk: denne er den Jødernes Konge.","Men der var og sat en Overskrift over ham, skreven paa Græsk og Latin og Hebraisk: denne er den Jødernes Konge."],[23,39,"Men een af Misdæderne, som vare ophængte, bespottede ham og sagde: er du den Christus, da frels dig selv og os.","Men een af Misdæderne, som vare ophængte, bespottede ham og sagde: er du den Christus, da frels dig selv og os."],[23,40,"Men den anden svarede og straffede ham og sagde: frygter ei heller du for Gud, da du er under samme Dom?","Men den anden svarede og straffede ham og sagde: frygter ei heller du for Gud, da du er under samme Dom?"],[23,41,"Og vi vel med Rette, thi vi saae det, vore Gjerninger have forskyldt; men denne handlede intet Uskikkeligt.","Og vi vel med Rette, thi vi saae det, vore Gjerninger have forskyldt; men denne handlede intet Uskikkeligt."],[23,42,"Og han sagde til Jesus: Herre! kom mig i hu, naar du kommer i dit Rige.","Og han sagde til Jesus: Herre! kom mig i hu, naar du kommer i dit Rige."],[23,43,"Og Jesus sagde til ham: sandelig siger jeg dig, i Dag skal du være med mig i Paradiis.","Og Jesus sagde til ham: sandelig siger jeg dig, i Dag skal du være med mig i Paradiis."],[23,44,"Men det var ved den sjette Time, og der blev et Mørke over det ganske Land indtil den niende Time.","Men det var ved den sjette Time, og der blev et Mørke over det ganske Land indtil den niende Time."],[23,45,"Og Solen blev formørket, og Forhænget i Templet splittedes midt ad.","Og Solen blev formørket, og Forhænget i Templet splittedes midt ad."],[23,46,"Og Jesus raabte med høi Røst og sagde: Fader! i dine Hænder befaler jeg min Aand; og der han det sagde, udgav han Aanden.","Og Jesus raabte med høi Røst og sagde: Fader! i dine Hænder befaler jeg min Aand; og der han det sagde, udgav han Aanden."],[23,47,"Men der Høvedsmanden saae det, som skete, gav han Gud Æren og sagde: i Sandhed, dette Menneske var retfærdigt.","Men der Høvedsmanden saae det, som skete, gav han Gud Æren og sagde: i Sandhed, dette Menneske var retfærdigt."],[23,48,"Og alle de Folk, som vare komne sammen til dette Syn, der de saae, hvad der var skeet, sloge sig for deres Bryst, og vendte tilbage.","Og alle de Folk, som vare komne sammen til dette Syn, der de saae, hvad der var skeet, sloge sig for deres Bryst, og vendte tilbage."],[23,49,"Men alle hans Kyndinge stode langt borte, saa og de Kvinder, som havde fulgt med ham fra Galilæa, og saae dette.","Men alle hans Kyndinge stode langt borte, saa og de Kvinder, som havde fulgt med ham fra Galilæa, og saae dette."],[23,50,"Og see, en Mand ved Navn Joseph, som var en Raadsherre, en god og retfærdig Mand,","Og see, en Mand ved Navn Joseph, som var en Raadsherre, en god og retfærdig Mand,"],[23,51,"(denne havde ikke samtykt i deres Raad og Gjerning), han var fra Arimathæa, en jødisk Stad, og han ventede ogsaa selv Guds Rige;","(denne havde ikke samtykt i deres Raad og Gjerning), han var fra Arimathæa, en jødisk Stad, og han ventede ogsaa selv Guds Rige;"],[23,52,"han gik til Pilatus, og begjerede Jesu Legeme.","han gik til Pilatus, og begjerede Jesu Legeme."],[23,53,"Og han tog det ned, og svøbte det i et fiint Linklæde, og lagde det i en Grav, som var huggen i en Klippe, hvor endnu ikke Nogen var lagt.","Og han tog det ned, og svøbte det i et fiint Linklæde, og lagde det i en Grav, som var huggen i en Klippe, hvor endnu ikke Nogen var lagt."],[23,54,"Og det var Beredelsens Dag, og Sabbaten stundede til.","Og det var Beredelsens Dag, og Sabbaten stundede til."],[23,55,"Men og Kvinderne, som vare komne med ham fra Galilæa, fulgte efter og saae Graven, og hvorledes hans Legeme blev lagt.","Men og Kvinderne, som vare komne med ham fra Galilæa, fulgte efter og saae Graven, og hvorledes hans Legeme blev lagt."],[23,56,"Men de vendte tilbage og beredte vellugtende Urter og Salver; og Sabbaten over holdt de sig stille efter Loven.","Men de vendte tilbage og beredte vellugtende Urter og Salver; og Sabbaten over holdt de sig stille efter Loven."],[24,1,"Men paa den første Dag i Ugen meget aarle kom de til Graven, og bare de vellugtende Salver, som de havde beredt; og nogle Andre kom med dem.","Men paa den første Dag i Ugen meget aarle kom de til Graven, og bare de vellugtende Salver, som de havde beredt; og nogle Andre kom med dem."],[24,2,"Men de fandt Stenen afvæltet fra Graven.","Men de fandt Stenen afvæltet fra Graven."],[24,3,"Og de gik ind, og fandt ikke den Herre Jesu Legeme.","Og de gik ind, og fandt ikke den Herre Jesu Legeme."],[24,4,"Og det skete, der de vare tvivlraadige derover, see, da stode to Mænd for dem i skinnende Klæder.","Og det skete, der de vare tvivlraadige derover, see, da stode to Mænd for dem i skinnende Klæder."],[24,5,"Men der de bleve forfærdede og bøiede Ansigtet mod Jorden, sagde de til dem: hvi lede I efter den Levende iblandt de Døde?","Men der de bleve forfærdede og bøiede Ansigtet mod Jorden, sagde de til dem: hvi lede I efter den Levende iblandt de Døde?"],[24,6,"Han er ikke her, men han er opstanden; kommer i hu, hvorledes han talede til Eder, der han endnu var i Galilæa, og sagde:","Han er ikke her, men han er opstanden; kommer i hu, hvorledes han talede til Eder, der han endnu var i Galilæa, og sagde:"],[24,7,"det bør Menneskens Søn at overantvordes i syndige Menneskers Hænder, og korsfæstes og opstaae tredie Dag.","det bør Menneskens Søn at overantvordes i syndige Menneskers Hænder, og korsfæstes og opstaae tredie Dag."],[24,8,"Og de kom hans Ord i hu.","Og de kom hans Ord i hu."],[24,9,"Og de gik fra Graven igjen, og kundgjorde alle disse Ting for de Elleve og for alle de Andre.","Og de gik fra Graven igjen, og kundgjorde alle disse Ting for de Elleve og for alle de Andre."],[24,10,"Men det var Maria Magdalene og Johanna og Maria, Jakobus’ Moder, og de øvrige Kvinder med dem, som sagde Apostlerne disse Ting.","Men det var Maria Magdalene og Johanna og Maria, Jakobus’ Moder, og de øvrige Kvinder med dem, som sagde Apostlerne disse Ting."],[24,11,"Og deres Ord syntes for dem som en løs Tale, og de troede dem ikke.","Og deres Ord syntes for dem som en løs Tale, og de troede dem ikke."],[24,12,"Men Peter stod op og løb til Graven; og der han kigede derind, saae han Linklæderne liggende alene, og gik bort og forundrede sig over det, som skeet var.","Men Peter stod op og løb til Graven; og der han kigede derind, saae han Linklæderne liggende alene, og gik bort og forundrede sig over det, som skeet var."],[24,13,"Og see, to af dem gik paa den samme Dag til en By, som var tresindstyve Stadier fra Jerusalem, hvis Navn var Emaus.","Og see, to af dem gik paa den samme Dag til en By, som var tresindstyve Stadier fra Jerusalem, hvis Navn var Emaus."],[24,14,"Og de talede med hverandre om alle disse Ting, som vare skete.","Og de talede med hverandre om alle disse Ting, som vare skete."],[24,15,"Og det begav sig, der de talede og bespurgte sig med hverandre, kom og Jesus selv nær og vandrede med dem.","Og det begav sig, der de talede og bespurgte sig med hverandre, kom og Jesus selv nær og vandrede med dem."],[24,16,"Men deres Øine holdtes til, saa de ikke kjendte ham.","Men deres Øine holdtes til, saa de ikke kjendte ham."],[24,17,"Men han sagde til dem: hvad ere disse for Taler, som I føre med hverandre paa Veien, og hvi see I saa bedrøvede ud.","Men han sagde til dem: hvad ere disse for Taler, som I føre med hverandre paa Veien, og hvi see I saa bedrøvede ud."],[24,18,"Men een af dem, som hedte Cleophas, svarede og sagde til ham: er du alene fremmed i Jerusalem, og veed ikke de Ting, som ere skete i den i disse Dage?","Men een af dem, som hedte Cleophas, svarede og sagde til ham: er du alene fremmed i Jerusalem, og veed ikke de Ting, som ere skete i den i disse Dage?"],[24,19,"Og han sagde til dem: hvilke? Men de sagde til ham: angaaende Jesus af Nazareth, som var en Prophet, mægtig i Gjerning og Ord for Gud og alt Folket;","Og han sagde til dem: hvilke? Men de sagde til ham: angaaende Jesus af Nazareth, som var en Prophet, mægtig i Gjerning og Ord for Gud og alt Folket;"],[24,20,"og hvorledes de Ypperstepræster og vore Øverster have overantvordet ham til Dødsdom og korsfæstet ham.","og hvorledes de Ypperstepræster og vore Øverster have overantvordet ham til Dødsdom og korsfæstet ham."],[24,21,"Men vi haabede, at han var den, som skulde forløse Israel. Men med alt dette er det i Dag den tredie Dag, siden det skete.","Men vi haabede, at han var den, som skulde forløse Israel. Men med alt dette er det i Dag den tredie Dag, siden det skete."],[24,22,"Saa have og nogle af vore Kvinder, som vare aarle ved Graven, forfærdet os;","Saa have og nogle af vore Kvinder, som vare aarle ved Graven, forfærdet os;"],[24,23,"thi der de ikke fandt hans Legeme, kom de og sagde, at de havde og seet et Syn af Engle, hvilke sagde: han lever.","thi der de ikke fandt hans Legeme, kom de og sagde, at de havde og seet et Syn af Engle, hvilke sagde: han lever."],[24,24,"Og nogle af Vore gik hen til Graven og fandt det saaledes, som og Kvinderne havde sagt; men ham saae de ikke.","Og nogle af Vore gik hen til Graven og fandt det saaledes, som og Kvinderne havde sagt; men ham saae de ikke."],[24,25,"Og han sagde til dem: o I Daarer og Seenhjertede til at troe alt det, som Propheterne have sagt.","Og han sagde til dem: o I Daarer og Seenhjertede til at troe alt det, som Propheterne have sagt."],[24,26,"Burde det ikke Christus at lide dette og at indgaae til sin Herlighed?","Burde det ikke Christus at lide dette og at indgaae til sin Herlighed?"],[24,27,"Og han begyndte fra Moses og fra alle Propheter, og udlagde dem i alle Skrifterne det, som var skrevet om ham.","Og han begyndte fra Moses og fra alle Propheter, og udlagde dem i alle Skrifterne det, som var skrevet om ham."],[24,28,"Og de kom nær til Byen, som de gik til; og han lod, som han vilde gaae længere.","Og de kom nær til Byen, som de gik til; og han lod, som han vilde gaae længere."],[24,29,"Og de nødte ham meget og sagde: bliv hos os, thi det er mod Aften, og Dagen helder; og han gik ind for at blive hos dem.","Og de nødte ham meget og sagde: bliv hos os, thi det er mod Aften, og Dagen helder; og han gik ind for at blive hos dem."],[24,30,"Og det skete, da han sad med dem tilbords, tog han Brødet, velsignede, og brød det, og gav dem.","Og det skete, da han sad med dem tilbords, tog han Brødet, velsignede, og brød det, og gav dem."],[24,31,"Da bleve deres Øine aabnede, og de kjendte ham, og han blev usynlig for dem.","Da bleve deres Øine aabnede, og de kjendte ham, og han blev usynlig for dem."],[24,32,"Og de sagde til hverandre: brændte ikke vore Hjerter i os, der han talede til os paa Veien, og der han oplod os Skrifterne?","Og de sagde til hverandre: brændte ikke vore Hjerter i os, der han talede til os paa Veien, og der han oplod os Skrifterne?"],[24,33,"Og de stode op i den samme Time, og vendte tilbage til Jerusalem, og fandt forsamlede de Elleve og dem, som vare med dem, hvilke sagde:","Og de stode op i den samme Time, og vendte tilbage til Jerusalem, og fandt forsamlede de Elleve og dem, som vare med dem, hvilke sagde:"],[24,34,"Herren er sandelig opstanden, og seet af Simon.","Herren er sandelig opstanden, og seet af Simon."],[24,35,"Og de fortalte de Ting, som vare skete paa Veien, og hvorledes han blev kjendt af dem, idet han brød Brødet.","Og de fortalte de Ting, som vare skete paa Veien, og hvorledes han blev kjendt af dem, idet han brød Brødet."],[24,36,"Men der de talede dette, stod Jesus selv midt iblandt dem, og han sagde til dem: Fred være med Eder!","Men der de talede dette, stod Jesus selv midt iblandt dem, og han sagde til dem: Fred være med Eder!"],[24,37,"Da forfærdedes de, og betoges af Frygt, og meente, at de saae en Aand.","Da forfærdedes de, og betoges af Frygt, og meente, at de saae en Aand."],[24,38,"Og han sagde til dem: hvi ere I saa bestyrtede? og hvi opstige saadanne Tanker i Eders Hjerter?","Og han sagde til dem: hvi ere I saa bestyrtede? og hvi opstige saadanne Tanker i Eders Hjerter?"],[24,39,"Seer mine Hænder og mine Fødder, at det er mig selv; føler paa mig og seer; thi en Aand haver ikke Kjød og Been, som I see, at jeg haver.","Seer mine Hænder og mine Fødder, at det er mig selv; føler paa mig og seer; thi en Aand haver ikke Kjød og Been, som I see, at jeg haver."],[24,40,"Og der han det sagde, viste han dem Hænderne og Fødderne.","Og der han det sagde, viste han dem Hænderne og Fødderne."],[24,41,"Men der de for Glæde endnu ikke troede, og forundrede sig, sagde han til dem: have I her Noget at æde?","Men der de for Glæde endnu ikke troede, og forundrede sig, sagde han til dem: have I her Noget at æde?"],[24,42,"Men de gave ham et Stykke af en stegt Fisk og af en Honningkage.","Men de gave ham et Stykke af en stegt Fisk og af en Honningkage."],[24,43,"Og han tog det og aad det for deres Øine.","Og han tog det og aad det for deres Øine."],[24,44,"Men han sagde til dem: dette er, hvad jeg sagde Eder, der jeg endnu var hos Eder, at de Ting bør allesammen at fuldkommes, som ere skrevne i Moses’ Lov og Propheterne og Psalmerne om mig.","Men han sagde til dem: dette er, hvad jeg sagde Eder, der jeg endnu var hos Eder, at de Ting bør allesammen at fuldkommes, som ere skrevne i Moses’ Lov og Propheterne og Psalmerne om mig."],[24,45,"Da oplod han deres Forstand, at de forstode Skrifterne.","Da oplod han deres Forstand, at de forstode Skrifterne."],[24,46,"Og han sagde til dem: saaledes er skrevet, og saaledes burde det Christus at lide og at opstaae fra de Døde tredie Dag;","Og han sagde til dem: saaledes er skrevet, og saaledes burde det Christus at lide og at opstaae fra de Døde tredie Dag;"],[24,47,"og i hans Navn at prædikes Omvendelse og Syndernes Forladelse for alle Folk, hvilket skulde begynde fra Jerusalem.","og i hans Navn at prædikes Omvendelse og Syndernes Forladelse for alle Folk, hvilket skulde begynde fra Jerusalem."],[24,48,"Men I ere Vidner til disse Ting.","Men I ere Vidner til disse Ting."],[24,49,"Og see, jeg sender min Faders Forjættelse over Eder; men I skulle blive I Jerusalems Stad, indtil I blive iførte med Kraft af det Høie.","Og see, jeg sender min Faders Forjættelse over Eder; men I skulle blive I Jerusalems Stad, indtil I blive iførte med Kraft af det Høie."],[24,50,"Men han førte dem hen ud indtil Bethanien, og han opløftede sine Hænder og velsignede dem.","Men han førte dem hen ud indtil Bethanien, og han opløftede sine Hænder og velsignede dem."],[24,51,"Og det skete, der han velsignede dem, skiltes han fra dem og foer op til Himmelen.","Og det skete, der han velsignede dem, skiltes han fra dem og foer op til Himmelen."],[24,52,"Og de tilbade ham, og vendte tilbage til Jerusalem med stor Glæde.","Og de tilbade ham, og vendte tilbage til Jerusalem med stor Glæde."],[24,53,"Og de vare stedse i Templet og lovede og priste Gud. Amen.","Og de vare stedse i Templet og lovede og priste Gud. Amen."]],"epo-londona":[[1,1,"Ĉar multaj jam entreprenis aranĝi historion pri la faktoj, kiuj estas konstatitaj inter ni,","Ĉar multaj jam entreprenis aranĝi historion pri la faktoj, kiuj estas konstatitaj inter ni,"],[1,2,"kiel ilin transdonis al ni tiuj, kiuj de la komenco vidis mem kaj estis administrantoj de la vorto,","kiel ilin transdonis al ni tiuj, kiuj de la komenco vidis mem kaj estis administrantoj de la vorto,"],[1,3,"ŝajnis bone ankaŭ al mi, esplorinta ĉion atente de la komenco, skribi en ordo al vi, plej eminenta Teofilo,","ŝajnis bone ankaŭ al mi, esplorinta ĉion atente de la komenco, skribi en ordo al vi, plej eminenta Teofilo,"],[1,4,"por ke vi povu scii la certecon pri la aferoj, pri kiuj vi estas instruita.","por ke vi povu scii la certecon pri la aferoj, pri kiuj vi estas instruita."],[1,5,"En la tagoj de Herodo, reĝo de Judujo, estis pastro nomata Zeĥarja, el la deĵora grupo de Abija; kaj li havis edzinon el la filinoj de Aaron, kaj ŝia nomo estis Elizabeto.","En la tagoj de Herodo, reĝo de Judujo, estis pastro nomata Zeĥarja, el la deĵora grupo de Abija; kaj li havis edzinon el la filinoj de Aaron, kaj ŝia nomo estis Elizabeto."],[1,6,"Kaj ambaŭ estis justaj antaŭ Dio, irantaj laŭ ĉiuj ordonoj kaj instruoj de la Eternulo sen riproĉo.","Kaj ambaŭ estis justaj antaŭ Dio, irantaj laŭ ĉiuj ordonoj kaj instruoj de la Eternulo sen riproĉo."],[1,7,"Kaj ili ne havis infanon, ĉar Elizabeto estis senfrukta, kaj ili ambaŭ estis en profunda aĝo.","Kaj ili ne havis infanon, ĉar Elizabeto estis senfrukta, kaj ili ambaŭ estis en profunda aĝo."],[1,8,"Kaj dum li plenumis sian pastradon antaŭ Dio en la vico de sia grupo,","Kaj dum li plenumis sian pastradon antaŭ Dio en la vico de sia grupo,"],[1,9,"laŭ la kutimo de la pastra ofico estis lia loto eniri en la sanktejon de la Eternulo kaj incensadi.","laŭ la kutimo de la pastra ofico estis lia loto eniri en la sanktejon de la Eternulo kaj incensadi."],[1,10,"Kaj la tuta amaso de la popolo preĝis ekstere dum la horo de la incensado.","Kaj la tuta amaso de la popolo preĝis ekstere dum la horo de la incensado."],[1,11,"Kaj aperis antaŭ li anĝelo de la Eternulo, staranta dekstre de la altaro de incensado.","Kaj aperis antaŭ li anĝelo de la Eternulo, staranta dekstre de la altaro de incensado."],[1,12,"Kaj Zeĥarja maltrankviliĝis, kiam li vidis lin, kaj sur lin falis timo.","Kaj Zeĥarja maltrankviliĝis, kiam li vidis lin, kaj sur lin falis timo."],[1,13,"Sed la anĝelo diris al li: Ne timu, Zeĥarja; ĉar via preĝo estas aŭdita, kaj via edzino Elizabeto naskos al vi filon, kaj vi donos al li la nomon Johano.","Sed la anĝelo diris al li: Ne timu, Zeĥarja; ĉar via preĝo estas aŭdita, kaj via edzino Elizabeto naskos al vi filon, kaj vi donos al li la nomon Johano."],[1,14,"Kaj vi havos ĝojon kaj feliĉon, kaj multaj ĝojos pro lia naskiĝo.","Kaj vi havos ĝojon kaj feliĉon, kaj multaj ĝojos pro lia naskiĝo."],[1,15,"Ĉar li estos granda antaŭ la Sinjoro, kaj li ne trinkos vinon nek ebriigaĵon; kaj li estos plena de la Sankta Spirito jam de la ventro de sia patrino.","Ĉar li estos granda antaŭ la Sinjoro, kaj li ne trinkos vinon nek ebriigaĵon; kaj li estos plena de la Sankta Spirito jam de la ventro de sia patrino."],[1,16,"Kaj multajn el la filoj de Izrael li turnos al la Eternulo, ilia Dio.","Kaj multajn el la filoj de Izrael li turnos al la Eternulo, ilia Dio."],[1,17,"Kaj li iros antaŭ Lia vizaĝo en la spirito kaj potenco de Elija, por turni la korojn de la patroj al la infanoj kaj la malobeemajn al la saĝeco de la justuloj, por pretigi por la Sinjoro popolon preparitan.","Kaj li iros antaŭ Lia vizaĝo en la spirito kaj potenco de Elija, por turni la korojn de la patroj al la infanoj kaj la malobeemajn al la saĝeco de la justuloj, por pretigi por la Sinjoro popolon preparitan."],[1,18,"Kaj Zeĥarja diris al la anĝelo: Per kio mi scios tion? ĉar mi estas maljunulo, kaj mia edzino havas profundan aĝon.","Kaj Zeĥarja diris al la anĝelo: Per kio mi scios tion? ĉar mi estas maljunulo, kaj mia edzino havas profundan aĝon."],[1,19,"Kaj la anĝelo responde diris al li: Mi estas Gabriel, kiu staras antaŭ Dio; kaj mi estas sendita, por paroli al vi kaj fari al vi tiun bonan sciigon.","Kaj la anĝelo responde diris al li: Mi estas Gabriel, kiu staras antaŭ Dio; kaj mi estas sendita, por paroli al vi kaj fari al vi tiun bonan sciigon."],[1,20,"Kaj jen vi silentos kaj estos ne kapabla paroli, ĝis la tago, kiam tio okazos, ĉar vi ne kredis miajn vortojn, kiuj plenumiĝos siatempe.","Kaj jen vi silentos kaj estos ne kapabla paroli, ĝis la tago, kiam tio okazos, ĉar vi ne kredis miajn vortojn, kiuj plenumiĝos siatempe."],[1,21,"Kaj la popolo atendis Zeĥarjan, kaj miris pro lia restado en la sanktejo.","Kaj la popolo atendis Zeĥarjan, kaj miris pro lia restado en la sanktejo."],[1,22,"Kaj kiam li elvenis, li ne povis paroli al ili; kaj ili eksciis, ke li vidis vizion en la sanktejo; kaj li faradis signojn al ili, kaj restis muta.","Kaj kiam li elvenis, li ne povis paroli al ili; kaj ili eksciis, ke li vidis vizion en la sanktejo; kaj li faradis signojn al ili, kaj restis muta."],[1,23,"Kaj kiam finiĝis la tagoj de lia pastrado, li foriris en sian domon.","Kaj kiam finiĝis la tagoj de lia pastrado, li foriris en sian domon."],[1,24,"Kaj post tiuj tagoj lia edzino Elizabeto gravediĝis, kaj kaŝis sin kvin monatojn, dirante:","Kaj post tiuj tagoj lia edzino Elizabeto gravediĝis, kaj kaŝis sin kvin monatojn, dirante:"],[1,25,"Tiamaniere agis la Eternulo rilate al mi en la tagoj, kiam Li favore rigardis min, por forpreni mian riproĉon inter homoj.","Tiamaniere agis la Eternulo rilate al mi en la tagoj, kiam Li favore rigardis min, por forpreni mian riproĉon inter homoj."],[1,26,"Kaj en la sesa monato la anĝelo Gabriel estis sendita de Dio en urbon de Galileo, nomatan Nazaret,","Kaj en la sesa monato la anĝelo Gabriel estis sendita de Dio en urbon de Galileo, nomatan Nazaret,"],[1,27,"al virgulino fianĉinigita kun viro, kies nomo estis Jozef, el la domo de David; kaj la nomo de la virgulino estis Maria.","al virgulino fianĉinigita kun viro, kies nomo estis Jozef, el la domo de David; kaj la nomo de la virgulino estis Maria."],[1,28,"Kaj li venis al ŝi, kaj diris: Saluton al vi la grace favorita, la Eternulo estas kun vi.","Kaj li venis al ŝi, kaj diris: Saluton al vi la grace favorita, la Eternulo estas kun vi."],[1,29,"Sed ŝi tre maltrankviliĝis ĉe tiu diro, kaj konsideris, kia povas esti tiu saluto.","Sed ŝi tre maltrankviliĝis ĉe tiu diro, kaj konsideris, kia povas esti tiu saluto."],[1,30,"Kaj la anĝelo diris al ŝi: Ne timu, Maria; ĉar vi trovis gracon antaŭ Dio.","Kaj la anĝelo diris al ŝi: Ne timu, Maria; ĉar vi trovis gracon antaŭ Dio."],[1,31,"Kaj jen vi gravediĝos en via ventro kaj naskos filon, kaj vi nomos lin JESUO.","Kaj jen vi gravediĝos en via ventro kaj naskos filon, kaj vi nomos lin JESUO."],[1,32,"Li estos granda, kaj estos nomata Filo de la Plejaltulo; kaj Dio, la Eternulo, donos al li la tronon de lia patro David;","Li estos granda, kaj estos nomata Filo de la Plejaltulo; kaj Dio, la Eternulo, donos al li la tronon de lia patro David;"],[1,33,"kaj li reĝos super la domo de Jakob eterne, kaj lia regno ne havos finon.","kaj li reĝos super la domo de Jakob eterne, kaj lia regno ne havos finon."],[1,34,"Kaj Maria diris al la anĝelo: Kiel estos tio, ĉar mi ne konas viron?","Kaj Maria diris al la anĝelo: Kiel estos tio, ĉar mi ne konas viron?"],[1,35,"Kaj la anĝelo responde diris al ŝi: La Sankta Spirito venos sur vin, kaj la potenco de la Plejaltulo superombros vin; pro kio ankaŭ la naskotaĵo estos nomata sankta, la Filo de Dio.","Kaj la anĝelo responde diris al ŝi: La Sankta Spirito venos sur vin, kaj la potenco de la Plejaltulo superombros vin; pro kio ankaŭ la naskotaĵo estos nomata sankta, la Filo de Dio."],[1,36,"Kaj jen via parencino Elizabeto ankaŭ gravediĝis je filo en sia maljuneco, kaj la nuna monato estas la sesa por ŝi, kiun oni nomis senfrukta.","Kaj jen via parencino Elizabeto ankaŭ gravediĝis je filo en sia maljuneco, kaj la nuna monato estas la sesa por ŝi, kiun oni nomis senfrukta."],[1,37,"Ĉar ĉe Dio nenio estas neebla.","Ĉar ĉe Dio nenio estas neebla."],[1,38,"Kaj Maria diris: Jen la sklavino de la Eternulo; estu al mi laŭ via diro. Kaj la anĝelo foriris de ŝi.","Kaj Maria diris: Jen la sklavino de la Eternulo; estu al mi laŭ via diro. Kaj la anĝelo foriris de ŝi."],[1,39,"Kaj en tiuj tagoj Maria leviĝis kaj senprokraste vojaĝis en la montan regionon, en urbon de Judujo;","Kaj en tiuj tagoj Maria leviĝis kaj senprokraste vojaĝis en la montan regionon, en urbon de Judujo;"],[1,40,"kaj enirinte en la domon de Zeĥarja, ŝi salutis Elizabeton.","kaj enirinte en la domon de Zeĥarja, ŝi salutis Elizabeton."],[1,41,"Kaj kiam Elizabeto aŭdis la saluton de Maria, la infaneto eksaltis en ŝia ventro; kaj Elizabeto pleniĝis de la Sankta Spirito,","Kaj kiam Elizabeto aŭdis la saluton de Maria, la infaneto eksaltis en ŝia ventro; kaj Elizabeto pleniĝis de la Sankta Spirito,"],[1,42,"kaj ŝi levis sian voĉon per laŭta krio, kaj diris: Benata vi estas inter virinoj, kaj benata estas la frukto de via ventro.","kaj ŝi levis sian voĉon per laŭta krio, kaj diris: Benata vi estas inter virinoj, kaj benata estas la frukto de via ventro."],[1,43,"Kaj pro kio okazas al mi ĉi tio, ke la patrino de mia Sinjoro venas al mi?","Kaj pro kio okazas al mi ĉi tio, ke la patrino de mia Sinjoro venas al mi?"],[1,44,"Ĉar jen kiam la voĉo de via saluto venis en miajn orelojn, la infaneto ĝoje eksaltis en mia ventro.","Ĉar jen kiam la voĉo de via saluto venis en miajn orelojn, la infaneto ĝoje eksaltis en mia ventro."],[1,45,"Kaj feliĉa estas ŝi, kiu kredis, ĉar plenumiĝos tio, kio estas dirita al ŝi de la Eternulo.","Kaj feliĉa estas ŝi, kiu kredis, ĉar plenumiĝos tio, kio estas dirita al ŝi de la Eternulo."],[1,46,"Kaj Maria diris: Mia animo altigas la Eternulon,","Kaj Maria diris: Mia animo altigas la Eternulon,"],[1,47,"Kaj mia spirito ĝojis en Dio, mia Savanto,","Kaj mia spirito ĝojis en Dio, mia Savanto,"],[1,48,"Ĉar Li rigardis la humilecon de Sia sklavino; Ĉar jen de nun ĉiuj generacioj nomos min feliĉa.","Ĉar Li rigardis la humilecon de Sia sklavino; Ĉar jen de nun ĉiuj generacioj nomos min feliĉa."],[1,49,"Ĉar la Potenculo faris al mi grandaĵojn, Kaj sankta estas Lia nomo.","Ĉar la Potenculo faris al mi grandaĵojn, Kaj sankta estas Lia nomo."],[1,50,"Kaj Lia boneco estas por ĉiuj generacioj Al tiuj, kiuj Lin timas.","Kaj Lia boneco estas por ĉiuj generacioj Al tiuj, kiuj Lin timas."],[1,51,"Li montris forton per Sia brako, Li dispelis fierulojn en la penso de ilia koro.","Li montris forton per Sia brako, Li dispelis fierulojn en la penso de ilia koro."],[1,52,"Li malaltigis potenculojn de iliaj tronoj, Kaj Li altigis humilulojn.","Li malaltigis potenculojn de iliaj tronoj, Kaj Li altigis humilulojn."],[1,53,"Malsatulojn Li plenigis per bonaĵo, Kaj riĉulojn Li forsendis malplenaj.","Malsatulojn Li plenigis per bonaĵo, Kaj riĉulojn Li forsendis malplenaj."],[1,54,"Li helpis Sian servanton Izrael, Memorante Sian korfavoron.","Li helpis Sian servanton Izrael, Memorante Sian korfavoron."],[1,55,"Kiel Li parolis al niaj patroj, Al Abraham kaj al lia idaro eterne.","Kiel Li parolis al niaj patroj, Al Abraham kaj al lia idaro eterne."],[1,56,"Kaj Maria loĝis ĉi ŝi tri monatojn, kaj reiris al sia domo.","Kaj Maria loĝis ĉi ŝi tri monatojn, kaj reiris al sia domo."],[1,57,"Kaj venis por Elizabeto la tempo, en kiu ŝi devis naski; kaj ŝi naskis filon.","Kaj venis por Elizabeto la tempo, en kiu ŝi devis naski; kaj ŝi naskis filon."],[1,58,"Kaj ŝiaj najbaroj kaj ŝiaj parencoj aŭdis, ke la Eternulo pligrandigis Sian bonecon al ŝi; kaj ili ĝojis kun ŝi.","Kaj ŝiaj najbaroj kaj ŝiaj parencoj aŭdis, ke la Eternulo pligrandigis Sian bonecon al ŝi; kaj ili ĝojis kun ŝi."],[1,59,"Kaj en la oka tago oni venis, por cirkumcidi la infaneton; kaj ili eknomis lin Zeĥarja, laŭ la nomo de lia patro.","Kaj en la oka tago oni venis, por cirkumcidi la infaneton; kaj ili eknomis lin Zeĥarja, laŭ la nomo de lia patro."],[1,60,"Kaj lia patrino responde diris: Tute ne; sed li estos nomata Johano.","Kaj lia patrino responde diris: Tute ne; sed li estos nomata Johano."],[1,61,"Kaj ili diris al ŝi: El via parencaro estas neniu, kiu estas nomata per tiu nomo.","Kaj ili diris al ŝi: El via parencaro estas neniu, kiu estas nomata per tiu nomo."],[1,62,"Kaj ili faris signojn al lia patro pri tio, kiel li volas, ke li estu nomata.","Kaj ili faris signojn al lia patro pri tio, kiel li volas, ke li estu nomata."],[1,63,"Kaj li petis tabuleton, kaj skribis jene: Lia nomo estas Johano. Kaj ĉiuj miris.","Kaj li petis tabuleton, kaj skribis jene: Lia nomo estas Johano. Kaj ĉiuj miris."],[1,64,"Kaj tuj lia buŝo malfermiĝis, kaj lia lango liberiĝis; kaj li parolis, glorante Dion.","Kaj tuj lia buŝo malfermiĝis, kaj lia lango liberiĝis; kaj li parolis, glorante Dion."],[1,65,"Kaj timo venis sur ĉiujn, kiuj loĝis ĉirkaŭ ili, kaj tra la tuta monta regiono de Judujo disvastiĝis rakonto pri ĉio tio.","Kaj timo venis sur ĉiujn, kiuj loĝis ĉirkaŭ ili, kaj tra la tuta monta regiono de Judujo disvastiĝis rakonto pri ĉio tio."],[1,66,"Kaj ĉiuj aŭdantoj konservis tion en sia koro, dirante: Kia do estos ĉi tiu knabeto? Ĉar la mano de la Eternulo estis kun li.","Kaj ĉiuj aŭdantoj konservis tion en sia koro, dirante: Kia do estos ĉi tiu knabeto? Ĉar la mano de la Eternulo estis kun li."],[1,67,"Kaj lia patro Zeĥarja pleniĝis de la Sankta Spirito, kaj profetis, dirante:","Kaj lia patro Zeĥarja pleniĝis de la Sankta Spirito, kaj profetis, dirante:"],[1,68,"Benata estu la Eternulo, la Dio de Izrael, Ĉar Li vizitis Sian popolon kaj faris por ili elaĉeton,","Benata estu la Eternulo, la Dio de Izrael, Ĉar Li vizitis Sian popolon kaj faris por ili elaĉeton,"],[1,69,"Kaj levis kornon de savo por ni En la domo de Sia servanto David,","Kaj levis kornon de savo por ni En la domo de Sia servanto David,"],[1,70,"Kiel Li parolis per la buŝo de Siaj sanktaj profetoj, de post la komenco de la mondo,","Kiel Li parolis per la buŝo de Siaj sanktaj profetoj, de post la komenco de la mondo,"],[1,71,"Savadon el niaj malamikoj kaj el la mano de ĉiuj niaj malamantoj;","Savadon el niaj malamikoj kaj el la mano de ĉiuj niaj malamantoj;"],[1,72,"Por montri Sian bonecon ĉe niaj patroj, Kaj por memori Sian sanktan interligon;","Por montri Sian bonecon ĉe niaj patroj, Kaj por memori Sian sanktan interligon;"],[1,73,"La ĵuron, kiun Li ĵuris al nia patro Abraham;","La ĵuron, kiun Li ĵuris al nia patro Abraham;"],[1,74,"Ke Li donos al ni, ke, liberigite el la mano de niaj malamikoj, Ni servu Lin sentime,","Ke Li donos al ni, ke, liberigite el la mano de niaj malamikoj, Ni servu Lin sentime,"],[1,75,"En sankteco kaj justeco antaŭ Li ĉiujn niajn tagojn.","En sankteco kaj justeco antaŭ Li ĉiujn niajn tagojn."],[1,76,"Kaj vi, infano, estos nomata profeto de la Plejaltulo, Ĉar vi iros antaŭ la vizaĝo de la Sinjoro, por pretigi liajn vojojn,","Kaj vi, infano, estos nomata profeto de la Plejaltulo, Ĉar vi iros antaŭ la vizaĝo de la Sinjoro, por pretigi liajn vojojn,"],[1,77,"Por doni al lia popolo scion de savo En la pardonado de iliaj pekoj,","Por doni al lia popolo scion de savo En la pardonado de iliaj pekoj,"],[1,78,"Pro la kompata koro de nia Dio, Per kiu nin vizitis la sunleviĝo de supre,","Pro la kompata koro de nia Dio, Per kiu nin vizitis la sunleviĝo de supre,"],[1,79,"Por lumi sur tiujn, kiuj sidas en mallumo kaj en la ombro de morto, Por gvidi niajn piedojn en la vojojn de paco.","Por lumi sur tiujn, kiuj sidas en mallumo kaj en la ombro de morto, Por gvidi niajn piedojn en la vojojn de paco."],[1,80,"Kaj kreskis la infano kaj fortiĝis en spirito, kaj estis en la dezertoj ĝis la tago de sia ekmontriĝo al Izrael.","Kaj kreskis la infano kaj fortiĝis en spirito, kaj estis en la dezertoj ĝis la tago de sia ekmontriĝo al Izrael."],[2,1,"Kaj en tiuj tagoj eliris dekreto de Cezaro Aŭgusto, ke la tuta mondo estu registrita.","Kaj en tiuj tagoj eliris dekreto de Cezaro Aŭgusto, ke la tuta mondo estu registrita."],[2,2,"Ĉi tiu estis la unua registrado, farita, kiam Kirenio estis reganto de Sirio.","Ĉi tiu estis la unua registrado, farita, kiam Kirenio estis reganto de Sirio."],[2,3,"Kaj ĉiuj iris, por esti registritaj, ĉiu al sia urbo.","Kaj ĉiuj iris, por esti registritaj, ĉiu al sia urbo."],[2,4,"Kaj Jozef ankaŭ supreniris el Galileo, el la urbo Nazaret, en Judujon, al la urbo de David, kiu estas nomata Bet-Leĥem, ĉar li estis el la domo kaj familio de David,","Kaj Jozef ankaŭ supreniris el Galileo, el la urbo Nazaret, en Judujon, al la urbo de David, kiu estas nomata Bet-Leĥem, ĉar li estis el la domo kaj familio de David,"],[2,5,"por esti registrita kun sia fianĉino Maria, kiu estis graveda.","por esti registrita kun sia fianĉino Maria, kiu estis graveda."],[2,6,"Kaj dum ili estis tie, venis la tagoj por ŝia akuŝo.","Kaj dum ili estis tie, venis la tagoj por ŝia akuŝo."],[2,7,"Kaj ŝi naskis sian unuan filon, kaj ŝi ĉirkaŭvindis lin kaj kuŝigis lin en staltrogon, ĉar ne estis loko por ili en la gastejo.","Kaj ŝi naskis sian unuan filon, kaj ŝi ĉirkaŭvindis lin kaj kuŝigis lin en staltrogon, ĉar ne estis loko por ili en la gastejo."],[2,8,"Kaj en tiu sama regiono estis paŝtistoj, kiuj kamploĝis kaj nokte gardis sian gregon.","Kaj en tiu sama regiono estis paŝtistoj, kiuj kamploĝis kaj nokte gardis sian gregon."],[2,9,"Kaj anĝelo de la Eternulo alstaris apud ili, kaj la gloro de la Eternulo brilis ĉirkaŭ ili, kaj ili timis per granda timo.","Kaj anĝelo de la Eternulo alstaris apud ili, kaj la gloro de la Eternulo brilis ĉirkaŭ ili, kaj ili timis per granda timo."],[2,10,"Kaj la anĝelo diris al ili: Ne timu; ĉar jen mi venigas al vi bonan sciigon de granda ĝojo, kiu estos al la tuta popolo;","Kaj la anĝelo diris al ili: Ne timu; ĉar jen mi venigas al vi bonan sciigon de granda ĝojo, kiu estos al la tuta popolo;"],[2,11,"ĉar hodiaŭ estas naskita por vi, en la urbo de David, Savanto, kiu estas Kristo, la Sinjoro.","ĉar hodiaŭ estas naskita por vi, en la urbo de David, Savanto, kiu estas Kristo, la Sinjoro."],[2,12,"Kaj jen la signo por vi: vi trovos infaneton, ĉirkaŭvinditan kaj kuŝantan en staltrogo.","Kaj jen la signo por vi: vi trovos infaneton, ĉirkaŭvinditan kaj kuŝantan en staltrogo."],[2,13,"Kaj subite estis kun la anĝelo amaso de la ĉiela armeo, laŭdante Dion, kaj dirante:","Kaj subite estis kun la anĝelo amaso de la ĉiela armeo, laŭdante Dion, kaj dirante:"],[2,14,"Gloro al Dio en la supera alto, Kaj sur la tero paco, inter homoj Difavoro.","Gloro al Dio en la supera alto, Kaj sur la tero paco, inter homoj Difavoro."],[2,15,"Kaj kiam la anĝeloj foriris de ili en la ĉielon, la paŝtistoj diris unu al alia: Ni jam iru ĝis Bet-Leĥem, kaj vidu ĉi tiun okazintaĵon, kiun la Eternulo sciigis al ni.","Kaj kiam la anĝeloj foriris de ili en la ĉielon, la paŝtistoj diris unu al alia: Ni jam iru ĝis Bet-Leĥem, kaj vidu ĉi tiun okazintaĵon, kiun la Eternulo sciigis al ni."],[2,16,"Kaj rapidante, ili iris, kaj trovis Marian kaj Jozefon, kaj la infaneton kuŝantan en la staltrogo.","Kaj rapidante, ili iris, kaj trovis Marian kaj Jozefon, kaj la infaneton kuŝantan en la staltrogo."],[2,17,"Kaj tion vidinte, ili sciigis pri la diro, kiu estis parolita al ili pri ĉi tiu infano.","Kaj tion vidinte, ili sciigis pri la diro, kiu estis parolita al ili pri ĉi tiu infano."],[2,18,"Kaj ĉiuj aŭdintoj miris pri tio, kion rakontis al ili la paŝtistoj.","Kaj ĉiuj aŭdintoj miris pri tio, kion rakontis al ili la paŝtistoj."],[2,19,"Sed Maria konservis ĉiujn tiujn dirojn kaj pripensis ilin en sia koro.","Sed Maria konservis ĉiujn tiujn dirojn kaj pripensis ilin en sia koro."],[2,20,"Kaj la paŝtistoj revenis, glorante kaj laŭdante Dion pri ĉio, kion ili aŭdis kaj vidis, kiel estis parolite al ili.","Kaj la paŝtistoj revenis, glorante kaj laŭdante Dion pri ĉio, kion ili aŭdis kaj vidis, kiel estis parolite al ili."],[2,21,"Kaj kiam jam pasis ok tagoj por cirkumcidi lin, oni donis al li la nomon JESUO, kiel li estis nomita de la anĝelo, antaŭ ol li estis en la ventro.","Kaj kiam jam pasis ok tagoj por cirkumcidi lin, oni donis al li la nomon JESUO, kiel li estis nomita de la anĝelo, antaŭ ol li estis en la ventro."],[2,22,"Kaj kiam finiĝis la tagoj de ilia purigado laŭ la leĝo de Moseo, ili alportis lin al Jerusalem, por prezenti lin al la Eternulo,","Kaj kiam finiĝis la tagoj de ilia purigado laŭ la leĝo de Moseo, ili alportis lin al Jerusalem, por prezenti lin al la Eternulo,"],[2,23,"kiel estas skribite en la leĝo de la Eternulo: Ĉiu virseksulo, kiu malfermas la uteron, estu dediĉita al la Eternulo;","kiel estas skribite en la leĝo de la Eternulo: Ĉiu virseksulo, kiu malfermas la uteron, estu dediĉita al la Eternulo;"],[2,24,"kaj por alporti oferon laŭ tio, kio estas dirita en la leĝo de la Eternulo: Paron da turtoj, aŭ du kolombidojn.","kaj por alporti oferon laŭ tio, kio estas dirita en la leĝo de la Eternulo: Paron da turtoj, aŭ du kolombidojn."],[2,25,"Kaj jen en Jerusalem estis viro, kies nomo estis Simeon, kaj ĉi tiu estis justa kaj pia, atendanta la konsoladon de Izrael; kaj la Sankta Spirito estis kun li.","Kaj jen en Jerusalem estis viro, kies nomo estis Simeon, kaj ĉi tiu estis justa kaj pia, atendanta la konsoladon de Izrael; kaj la Sankta Spirito estis kun li."],[2,26,"Kaj estis montrite al li de la Sankta Spirito, ke li ne mortos, ĝis li vidos la Kriston de la Eternulo.","Kaj estis montrite al li de la Sankta Spirito, ke li ne mortos, ĝis li vidos la Kriston de la Eternulo."],[2,27,"Kaj li venis per la Spirito en la templon; kaj kiam la gepatroj enportis la infanon Jesuo, por fari pri li laŭ la kutimo de la leĝo,","Kaj li venis per la Spirito en la templon; kaj kiam la gepatroj enportis la infanon Jesuo, por fari pri li laŭ la kutimo de la leĝo,"],[2,28,"tiam li ricevis lin en siajn brakojn, kaj benis Dion, dirante:","tiam li ricevis lin en siajn brakojn, kaj benis Dion, dirante:"],[2,29,"Nun, ho Eternulo, Vi ellasas Vian servanton, Laŭ Via vorto, en paco,","Nun, ho Eternulo, Vi ellasas Vian servanton, Laŭ Via vorto, en paco,"],[2,30,"Ĉar miaj okuloj vidis Vian savon,","Ĉar miaj okuloj vidis Vian savon,"],[2,31,"Kiun Vi preparis antaŭ la vizaĝo de ĉiuj popoloj,","Kiun Vi preparis antaŭ la vizaĝo de ĉiuj popoloj,"],[2,32,"Lumon por malkaŝo al la gentoj, Kaj gloron de Via popolo Izrael.","Lumon por malkaŝo al la gentoj, Kaj gloron de Via popolo Izrael."],[2,33,"Kaj lia patro kaj lia patrino miris pri tio, kio estis parolita pri li;","Kaj lia patro kaj lia patrino miris pri tio, kio estis parolita pri li;"],[2,34,"kaj Simeon ilin benis, kaj diris al Maria, lia patrino: Jen ĉi tiu estas metita por la falo kaj leviĝo de multaj en Izrael, kaj por signo kontraŭparolata;","kaj Simeon ilin benis, kaj diris al Maria, lia patrino: Jen ĉi tiu estas metita por la falo kaj leviĝo de multaj en Izrael, kaj por signo kontraŭparolata;"],[2,35,"kaj ankaŭ vian animon glavo trapasos; por ke la pensoj de multaj koroj malkaŝiĝu.","kaj ankaŭ vian animon glavo trapasos; por ke la pensoj de multaj koroj malkaŝiĝu."],[2,36,"Kaj estis unu profetino, Anna, filino de Fanuel, el la tribo de Aŝer (ŝi estis grandaĝa, loĝinte sep jarojn kun sia edzo de post sia virgeco,","Kaj estis unu profetino, Anna, filino de Fanuel, el la tribo de Aŝer (ŝi estis grandaĝa, loĝinte sep jarojn kun sia edzo de post sia virgeco,"],[2,37,"kaj estinte vidvino okdek kvar jarojn), kiu neniam foriris el la templo, adorante per fastoj kaj preĝoj nokte kaj tage.","kaj estinte vidvino okdek kvar jarojn), kiu neniam foriris el la templo, adorante per fastoj kaj preĝoj nokte kaj tage."],[2,38,"Kaj alveninte ĝuste en tiu horo, ŝi dankis Dion, kaj parolis pri li al ĉiuj, kiuj atendadis la elaĉeton de Jerusalem.","Kaj alveninte ĝuste en tiu horo, ŝi dankis Dion, kaj parolis pri li al ĉiuj, kiuj atendadis la elaĉeton de Jerusalem."],[2,39,"Kaj kiam ili jam faris ĉion, konforme al la leĝo de la Eternulo, ili revenis en Galileon, al sia urbo Nazaret.","Kaj kiam ili jam faris ĉion, konforme al la leĝo de la Eternulo, ili revenis en Galileon, al sia urbo Nazaret."],[2,40,"Kaj la infano kreskadis kaj fortiĝis, pleniĝante de saĝeco; kaj la graco de Dio estis sur li.","Kaj la infano kreskadis kaj fortiĝis, pleniĝante de saĝeco; kaj la graco de Dio estis sur li."],[2,41,"Kaj liaj gepatroj iris ĉiujare al Jerusalem ĉe la Paska festo.","Kaj liaj gepatroj iris ĉiujare al Jerusalem ĉe la Paska festo."],[2,42,"Kaj kiam li estis dekdujara, ili supreniris laŭ la kutimo de la festo;","Kaj kiam li estis dekdujara, ili supreniris laŭ la kutimo de la festo;"],[2,43,"kaj kiam ili jam pasigis la tagojn, ĉe ilia returniĝo la knabo Jesuo restis en Jerusalem, kaj liaj gepatroj tion ne sciis;","kaj kiam ili jam pasigis la tagojn, ĉe ilia returniĝo la knabo Jesuo restis en Jerusalem, kaj liaj gepatroj tion ne sciis;"],[2,44,"sed supozante, ke li estas en la karavano, ili iris tagan vojaĝon, kaj serĉis lin inter siaj parencoj kaj konatoj;","sed supozante, ke li estas en la karavano, ili iris tagan vojaĝon, kaj serĉis lin inter siaj parencoj kaj konatoj;"],[2,45,"kaj ne trovinte lin, ili reiris al Jerusalem, serĉante lin.","kaj ne trovinte lin, ili reiris al Jerusalem, serĉante lin."],[2,46,"Kaj post tri tagoj ili trovis lin en la templo, kie li sidis meze de la instruistoj, aŭskultante ilin kaj metante al ili demandojn;","Kaj post tri tagoj ili trovis lin en la templo, kie li sidis meze de la instruistoj, aŭskultante ilin kaj metante al ili demandojn;"],[2,47,"kaj ĉiuj, kiuj aŭdis lin, miregis pro lia kompreno kaj liaj respondoj.","kaj ĉiuj, kiuj aŭdis lin, miregis pro lia kompreno kaj liaj respondoj."],[2,48,"Kaj ili miris, vidante lin, kaj lia patrino diris al li: Filo, kial vi tiel agis kontraŭ ni? jen via patro kaj mi serĉis vin kun malĝojo.","Kaj ili miris, vidante lin, kaj lia patrino diris al li: Filo, kial vi tiel agis kontraŭ ni? jen via patro kaj mi serĉis vin kun malĝojo."],[2,49,"Kaj li diris al ili: Kial vi serĉis min? ĉu vi ne sciis, ke mi devas esti en la domo de mia Patro?","Kaj li diris al ili: Kial vi serĉis min? ĉu vi ne sciis, ke mi devas esti en la domo de mia Patro?"],[2,50,"Kaj ili ne komprenis la diron, kiun li parolis al ili.","Kaj ili ne komprenis la diron, kiun li parolis al ili."],[2,51,"Kaj li malsupreniris kun ili, kaj venis en Nazareton, kaj li estis obeema al ili; kaj lia patrino konservis ĉiujn tiujn dirojn en sia koro.","Kaj li malsupreniris kun ili, kaj venis en Nazareton, kaj li estis obeema al ili; kaj lia patrino konservis ĉiujn tiujn dirojn en sia koro."],[2,52,"Kaj Jesuo progresis en saĝeco kaj staturo, kaj en graco ĉe Dio kaj homoj.","Kaj Jesuo progresis en saĝeco kaj staturo, kaj en graco ĉe Dio kaj homoj."],[3,1,"En la dek-kvina jaro de la regado de Tiberio Cezaro, kiam Pontio Pilato estis provincestro de Judujo, kaj Herodo estis tetrarĥo de Galileo, kaj lia frato Filipo tetrarĥo de la regiono Iturea kaj Traĥonitis, kaj Lisanio tetrarĥo de Abilene,","En la dek-kvina jaro de la regado de Tiberio Cezaro, kiam Pontio Pilato estis provincestro de Judujo, kaj Herodo estis tetrarĥo de Galileo, kaj lia frato Filipo tetrarĥo de la regiono Iturea kaj Traĥonitis, kaj Lisanio tetrarĥo de Abilene,"],[3,2,"dum la ĉefpastreco de Anas kaj Kajafas, venis la vorto de Dio al Johano, filo de Zeĥarja, en la dezerto.","dum la ĉefpastreco de Anas kaj Kajafas, venis la vorto de Dio al Johano, filo de Zeĥarja, en la dezerto."],[3,3,"Kaj li venis en la tutan regionon ĉirkaŭ Jordan, predikante la bapton de pento por la pardonado de pekoj,","Kaj li venis en la tutan regionon ĉirkaŭ Jordan, predikante la bapton de pento por la pardonado de pekoj,"],[3,4,"kiel estas skribite en la libro de la vortoj de la profeto Jesaja: Voĉo de krianto en la dezerto: Pretigu la vojon de la Eternulo, Rektigu Liajn irejojn.","kiel estas skribite en la libro de la vortoj de la profeto Jesaja: Voĉo de krianto en la dezerto: Pretigu la vojon de la Eternulo, Rektigu Liajn irejojn."],[3,5,"Ĉiu valo leviĝos, Kaj ĉiu monto kaj monteto malaltiĝos, Kaj la malebenaĵo fariĝos ebenaĵo, Kaj la malglataj vojoj glatiĝos;","Ĉiu valo leviĝos, Kaj ĉiu monto kaj monteto malaltiĝos, Kaj la malebenaĵo fariĝos ebenaĵo, Kaj la malglataj vojoj glatiĝos;"],[3,6,"Kaj ĉiu karno vidos la savon de Dio.","Kaj ĉiu karno vidos la savon de Dio."],[3,7,"Li do diris al la homamasoj, kiuj eliris, por esti baptitaj de li: Ho vipuridoj! kiu vin avertis forkuri de la venonta kolero?","Li do diris al la homamasoj, kiuj eliris, por esti baptitaj de li: Ho vipuridoj! kiu vin avertis forkuri de la venonta kolero?"],[3,8,"Donu do fruktojn taŭgajn por pento. Kaj ne komencu diri en vi: Ni havas Abrahamon kiel patron; ĉar mi diras al vi, ke Dio povas el ĉi tiuj ŝtonoj starigi idojn al Abraham.","Donu do fruktojn taŭgajn por pento. Kaj ne komencu diri en vi: Ni havas Abrahamon kiel patron; ĉar mi diras al vi, ke Dio povas el ĉi tiuj ŝtonoj starigi idojn al Abraham."],[3,9,"Kaj la hakilo jam kuŝas ĉe la radiko de la arboj; tial ĉiu arbo, kiu ne donas bonan frukton, estas dehakata, kaj ĵetata en fajron.","Kaj la hakilo jam kuŝas ĉe la radiko de la arboj; tial ĉiu arbo, kiu ne donas bonan frukton, estas dehakata, kaj ĵetata en fajron."],[3,10,"Kaj la homamasoj lin demandis, dirante: Kion do ni faru?","Kaj la homamasoj lin demandis, dirante: Kion do ni faru?"],[3,11,"Kaj responde li diris al ili: Kiu havas du tunikojn, tiu donu al la nehavanto; kaj kiu havas manĝaĵon, tiu faru tiel same.","Kaj responde li diris al ili: Kiu havas du tunikojn, tiu donu al la nehavanto; kaj kiu havas manĝaĵon, tiu faru tiel same."],[3,12,"Venis ankaŭ impostistoj, por esti baptitaj, kaj ili diris al li: Majstro, kion ni faru?","Venis ankaŭ impostistoj, por esti baptitaj, kaj ili diris al li: Majstro, kion ni faru?"],[3,13,"Kaj li diris al ili: Ne postulu pli multe, ol estas ordonite.","Kaj li diris al ili: Ne postulu pli multe, ol estas ordonite."],[3,14,"Kaj ankaŭ soldatoj lin demandis, dirante: Kaj kion ni faru? Kaj li diris al ili: Ne perfortu iun, nek maljuste ion postulu, kaj estu kontentaj je via salajro.","Kaj ankaŭ soldatoj lin demandis, dirante: Kaj kion ni faru? Kaj li diris al ili: Ne perfortu iun, nek maljuste ion postulu, kaj estu kontentaj je via salajro."],[3,15,"Kaj kiam la popolo atendis, kaj ĉiuj diskutis en siaj koroj pri Johano, ĉu eble li estas la Kristo,","Kaj kiam la popolo atendis, kaj ĉiuj diskutis en siaj koroj pri Johano, ĉu eble li estas la Kristo,"],[3,16,"Johano respondis al ĉiuj, dirante: Mi ja vin baptas per akvo, sed venas tiu, kiu estas pli potenca ol mi; la rimenon de liaj ŝuoj mi ne estas inda malligi; li vin baptos per la Sankta Spirito kaj per fajro;","Johano respondis al ĉiuj, dirante: Mi ja vin baptas per akvo, sed venas tiu, kiu estas pli potenca ol mi; la rimenon de liaj ŝuoj mi ne estas inda malligi; li vin baptos per la Sankta Spirito kaj per fajro;"],[3,17,"lia ventumilo estas en lia mano, por ke li elpurigu sian draŝejon, kaj kolektu la tritikon en sian grenejon; sed la grenventumaĵon li bruligos per fajro neestingebla.","lia ventumilo estas en lia mano, por ke li elpurigu sian draŝejon, kaj kolektu la tritikon en sian grenejon; sed la grenventumaĵon li bruligos per fajro neestingebla."],[3,18,"Kaj per multaj aliaj konsiloj li evangeliis al la popolo.","Kaj per multaj aliaj konsiloj li evangeliis al la popolo."],[3,19,"Sed Herodo, la tetrarĥo, riproĉite de li pri Herodias, la edzino de lia frato, kaj pri ĉiuj malbonaĵoj, kiujn Herodo faris,","Sed Herodo, la tetrarĥo, riproĉite de li pri Herodias, la edzino de lia frato, kaj pri ĉiuj malbonaĵoj, kiujn Herodo faris,"],[3,20,"aldonis al ĉio ankaŭ ĉi tion, ke li enŝlosis Johanon en malliberejo.","aldonis al ĉio ankaŭ ĉi tion, ke li enŝlosis Johanon en malliberejo."],[3,21,"Kaj kiam la tuta popolo estis baptata, Jesuo ankaŭ estis baptita, kaj dum li preĝis, la ĉielo malfermiĝis,","Kaj kiam la tuta popolo estis baptata, Jesuo ankaŭ estis baptita, kaj dum li preĝis, la ĉielo malfermiĝis,"],[3,22,"kaj la Sankta Spirito malsupreniris sur lin en korpa aspekto kiel kolombo; kaj venis voĉo el la ĉielo: Vi estas Mia Filo, la amata; en vi Mi havas plezuron.","kaj la Sankta Spirito malsupreniris sur lin en korpa aspekto kiel kolombo; kaj venis voĉo el la ĉielo: Vi estas Mia Filo, la amata; en vi Mi havas plezuron."],[3,23,"Kaj Jesuo mem, komencante, havis ĉirkaŭ tridek jarojn, estante filo (kiel oni supozis) de Jozef, de Eli,","Kaj Jesuo mem, komencante, havis ĉirkaŭ tridek jarojn, estante filo (kiel oni supozis) de Jozef, de Eli,"],[3,24,"de Mattat, de Levi, de Melĥi, de Janaj, de Jozef,","de Mattat, de Levi, de Melĥi, de Janaj, de Jozef,"],[3,25,"de Matatias, de Amos, de Naĥum, de Esli, de Nagaj,","de Matatias, de Amos, de Naĥum, de Esli, de Nagaj,"],[3,26,"de Maat, de Matatias, de Semein, de Jozef, de Joda,","de Maat, de Matatias, de Semein, de Jozef, de Joda,"],[3,27,"de Joĥanan, de Resa, de Zerubabel, de Ŝealtiel, de Neri,","de Joĥanan, de Resa, de Zerubabel, de Ŝealtiel, de Neri,"],[3,28,"de Melĥi, de Adi, de Kosam, de Elmodam, de Er,","de Melĥi, de Adi, de Kosam, de Elmodam, de Er,"],[3,29,"de Jesu, de Eliezer, de Jorim, de Mattat, de Levi,","de Jesu, de Eliezer, de Jorim, de Mattat, de Levi,"],[3,30,"de Simeon, de Jehuda, de Jozef, de Jonam, de Eljakim,","de Simeon, de Jehuda, de Jozef, de Jonam, de Eljakim,"],[3,31,"de Melea, de Mena, de Matata, de Natan, de David,","de Melea, de Mena, de Matata, de Natan, de David,"],[3,32,"de Jiŝaj, de Obed, de Boaz, de Salma, de Naĥŝon,","de Jiŝaj, de Obed, de Boaz, de Salma, de Naĥŝon,"],[3,33,"de Aminadab, de Ram, de Ĥecron, de Perec, de Jehuda,","de Aminadab, de Ram, de Ĥecron, de Perec, de Jehuda,"],[3,34,"de Jakob, de Isaak, de Abraham, de Teraĥ, de Naĥor,","de Jakob, de Isaak, de Abraham, de Teraĥ, de Naĥor,"],[3,35,"de Serug, de Reu, de Peleg, de Eber, de Ŝelaĥ,","de Serug, de Reu, de Peleg, de Eber, de Ŝelaĥ,"],[3,36,"de Kenan, de Arpaĥŝad, de Ŝem, de Noa, de Lemeĥ,","de Kenan, de Arpaĥŝad, de Ŝem, de Noa, de Lemeĥ,"],[3,37,"de Metuŝelaĥ, de Ĥanoĥ, de Jared, de Mahalalel, de Kenan,","de Metuŝelaĥ, de Ĥanoĥ, de Jared, de Mahalalel, de Kenan,"],[3,38,"de Enoŝ, de Set, de Adam, de Dio.","de Enoŝ, de Set, de Adam, de Dio."],[4,1,"Kaj Jesuo, plena de la Sankta Spirito, revenis de Jordan, kaj estis kondukata de la Spirito en la dezerton","Kaj Jesuo, plena de la Sankta Spirito, revenis de Jordan, kaj estis kondukata de la Spirito en la dezerton"],[4,2,"dum kvardek tagoj, tentate de la diablo. Kaj li manĝis nenion en tiuj tagoj; kaj kiam ili finiĝis, li malsatis.","dum kvardek tagoj, tentate de la diablo. Kaj li manĝis nenion en tiuj tagoj; kaj kiam ili finiĝis, li malsatis."],[4,3,"Kaj la diablo diris al li: Se vi estas Filo de Dio, ordonu al ĉi tiu ŝtono, ke ĝi fariĝu pano.","Kaj la diablo diris al li: Se vi estas Filo de Dio, ordonu al ĉi tiu ŝtono, ke ĝi fariĝu pano."],[4,4,"Kaj Jesuo respondis al li: Estas skribite: Ne per la pano sole vivos homo.","Kaj Jesuo respondis al li: Estas skribite: Ne per la pano sole vivos homo."],[4,5,"Kaj kondukinte lin supren, li montris al li ĉiujn regnojn de la mondo en momento da tempo.","Kaj kondukinte lin supren, li montris al li ĉiujn regnojn de la mondo en momento da tempo."],[4,6,"Kaj la diablo diris al li: Mi donos al vi la tutan ĉi tiun potencon kaj ilian gloron; ĉar ĝi estas transdonita al mi, kaj al kiu ajn mi volas, al tiu mi ĝin donas.","Kaj la diablo diris al li: Mi donos al vi la tutan ĉi tiun potencon kaj ilian gloron; ĉar ĝi estas transdonita al mi, kaj al kiu ajn mi volas, al tiu mi ĝin donas."],[4,7,"Se do vi adorkliniĝos antaŭ mi, ĉio estos via.","Se do vi adorkliniĝos antaŭ mi, ĉio estos via."],[4,8,"Kaj responde Jesuo diris al li: Estas skribite: Al la Eternulo, via Dio, adorkliniĝu, kaj al Li sola servu.","Kaj responde Jesuo diris al li: Estas skribite: Al la Eternulo, via Dio, adorkliniĝu, kaj al Li sola servu."],[4,9,"Kaj li kondukis lin al Jerusalem, kaj starigis lin sur la tegmenta pinto de la templo, kaj diris al li: Se vi estas Filo de Dio, ĵetu vin de ĉi tie malsupren;","Kaj li kondukis lin al Jerusalem, kaj starigis lin sur la tegmenta pinto de la templo, kaj diris al li: Se vi estas Filo de Dio, ĵetu vin de ĉi tie malsupren;"],[4,10,"ĉar estas skribite: Al siaj anĝeloj Li ordonos pri vi, ke ili vin gardu,","ĉar estas skribite: Al siaj anĝeloj Li ordonos pri vi, ke ili vin gardu,"],[4,11,"kaj: Sur la manoj ili vin portos, Por ke vi ne falpuŝiĝu sur ŝtono per via piedo.","kaj: Sur la manoj ili vin portos, Por ke vi ne falpuŝiĝu sur ŝtono per via piedo."],[4,12,"Kaj responde Jesuo diris al li: Estas dirite: Ne provu la Eternulon, vian Dion.","Kaj responde Jesuo diris al li: Estas dirite: Ne provu la Eternulon, vian Dion."],[4,13,"Kaj fininte la tutan tentadon, la diablo foriris de li ĝis estonta tempo.","Kaj fininte la tutan tentadon, la diablo foriris de li ĝis estonta tempo."],[4,14,"Kaj revenis Jesuo en la potenco de la Spirito en Galileon; kaj eliris famo pri li tra la tuta ĉirkaŭaĵo.","Kaj revenis Jesuo en la potenco de la Spirito en Galileon; kaj eliris famo pri li tra la tuta ĉirkaŭaĵo."],[4,15,"Kaj li instruadis en iliaj sinagogoj, glorate de ĉiuj.","Kaj li instruadis en iliaj sinagogoj, glorate de ĉiuj."],[4,16,"Kaj li venis al Nazaret, kie li estis edukita; kaj laŭ sia kutimo li eniris en la sinagogon en la sabata tago, kaj stariĝis, por legi.","Kaj li venis al Nazaret, kie li estis edukita; kaj laŭ sia kutimo li eniris en la sinagogon en la sabata tago, kaj stariĝis, por legi."],[4,17,"Kaj estis donita al li libro de la profeto Jesaja. Kaj, malferminte la libron, li trovis la lokon, kie estis skribite:","Kaj estis donita al li libro de la profeto Jesaja. Kaj, malferminte la libron, li trovis la lokon, kie estis skribite:"],[4,18,"La spirito de la Eternulo estas sur mi, Ĉar Li min sanktoleis, por bonanonci al malriĉuloj; Li sendis min, por anonci liberecon al kaptitoj Kaj vidpovon al blinduloj, Por meti la vunditojn en liberecon,","La spirito de la Eternulo estas sur mi, Ĉar Li min sanktoleis, por bonanonci al malriĉuloj; Li sendis min, por anonci liberecon al kaptitoj Kaj vidpovon al blinduloj, Por meti la vunditojn en liberecon,"],[4,19,"Por proklami favorjaron de la Eternulo.","Por proklami favorjaron de la Eternulo."],[4,20,"Kaj kunvolvinte la libron, kaj redoninte ĝin al la subulo, li sidiĝis; kaj la okuloj de ĉiuj en la sinagogo atente lin rigardis.","Kaj kunvolvinte la libron, kaj redoninte ĝin al la subulo, li sidiĝis; kaj la okuloj de ĉiuj en la sinagogo atente lin rigardis."],[4,21,"Kaj li ekparolis al ili: Hodiaŭ tiu skribo plenumiĝas en viaj oreloj.","Kaj li ekparolis al ili: Hodiaŭ tiu skribo plenumiĝas en viaj oreloj."],[4,22,"Kaj ĉiuj atestis pri li, kaj miris pro la vortoj de graco, kiuj eliris el lia buŝo; kaj ili diris: Ĉu ĉi tiu ne estas la filo de Jozef?","Kaj ĉiuj atestis pri li, kaj miris pro la vortoj de graco, kiuj eliris el lia buŝo; kaj ili diris: Ĉu ĉi tiu ne estas la filo de Jozef?"],[4,23,"Kaj li diris al ili: Sendube vi diros al mi la jenan sentencon: Kuracisto, sanigu vin mem; kiajn aferojn, pri kiuj ni aŭdis, en Kapernaum faritajn, tiajn faru ĉi tie en via patrujo.","Kaj li diris al ili: Sendube vi diros al mi la jenan sentencon: Kuracisto, sanigu vin mem; kiajn aferojn, pri kiuj ni aŭdis, en Kapernaum faritajn, tiajn faru ĉi tie en via patrujo."],[4,24,"Kaj li diris: Vere mi diras al vi: Neniu profeto estas akceptata en sia patrujo.","Kaj li diris: Vere mi diras al vi: Neniu profeto estas akceptata en sia patrujo."],[4,25,"Kun vereco mi diras al vi: Estis multaj vidvinoj en Izrael en la tagoj de Elija, kiam estis ŝlosita la ĉielo tri jarojn kaj ses monatojn, kiam okazis granda malsato sur la tuta lando;","Kun vereco mi diras al vi: Estis multaj vidvinoj en Izrael en la tagoj de Elija, kiam estis ŝlosita la ĉielo tri jarojn kaj ses monatojn, kiam okazis granda malsato sur la tuta lando;"],[4,26,"kaj al neniu el ili Elija estis sendita, krom al Carfat en la lando Cidon, al virino vidvino.","kaj al neniu el ili Elija estis sendita, krom al Carfat en la lando Cidon, al virino vidvino."],[4,27,"Kaj estis multaj lepruloj en Izrael en la tagoj de la profeto Eliŝa; sed neniu el ili estis purigita, krom Naaman, la Siriano.","Kaj estis multaj lepruloj en Izrael en la tagoj de la profeto Eliŝa; sed neniu el ili estis purigita, krom Naaman, la Siriano."],[4,28,"Kaj ĉiuj en la sinagogo pleniĝis de kolero, aŭdante tion;","Kaj ĉiuj en la sinagogo pleniĝis de kolero, aŭdante tion;"],[4,29,"kaj leviĝinte, ili elĵetis lin ekster la urbon, kaj kondukis lin ĝis la krutaĵo de la monteto, sur kiu ilia urbo estis konstruita, por ĵeti lin malsupren.","kaj leviĝinte, ili elĵetis lin ekster la urbon, kaj kondukis lin ĝis la krutaĵo de la monteto, sur kiu ilia urbo estis konstruita, por ĵeti lin malsupren."],[4,30,"Sed li foriris, trapasinte tra ilia mezo.","Sed li foriris, trapasinte tra ilia mezo."],[4,31,"Kaj li malsupreniris al Kapernaum, urbo Galilea. Kaj li instruis ilin en la sabato;","Kaj li malsupreniris al Kapernaum, urbo Galilea. Kaj li instruis ilin en la sabato;"],[4,32,"kaj oni miris pro lia instruado, ĉar kun aŭtoritato estis lia vorto.","kaj oni miris pro lia instruado, ĉar kun aŭtoritato estis lia vorto."],[4,33,"Kaj en la sinagogo estis viro, havanta spiriton de malpura demono; kaj li kriegis per laŭta voĉo,","Kaj en la sinagogo estis viro, havanta spiriton de malpura demono; kaj li kriegis per laŭta voĉo,"],[4,34,"dirante: Ha! kio estas inter ni kaj vi, Jesuo Nazaretano? Ĉu vi venis, por pereigi nin? Mi scias, kiu vi estas, la Sanktulo de Dio.","dirante: Ha! kio estas inter ni kaj vi, Jesuo Nazaretano? Ĉu vi venis, por pereigi nin? Mi scias, kiu vi estas, la Sanktulo de Dio."],[4,35,"Kaj Jesuo severe admonis lin, dirante: Silentu, kaj eliru el li. Kaj ĵetinte lin en la mezon, la demono eliris el li, neniel difektinte lin.","Kaj Jesuo severe admonis lin, dirante: Silentu, kaj eliru el li. Kaj ĵetinte lin en la mezon, la demono eliris el li, neniel difektinte lin."],[4,36,"Kaj falis miro sur ĉiujn, kaj ili kunparoladis inter si, dirante: Kia vorto estas ĉi tio? ĉar kun aŭtoritato kaj potenco li ordonas al la malpuraj spiritoj, kaj ili eliras.","Kaj falis miro sur ĉiujn, kaj ili kunparoladis inter si, dirante: Kia vorto estas ĉi tio? ĉar kun aŭtoritato kaj potenco li ordonas al la malpuraj spiritoj, kaj ili eliras."],[4,37,"Kaj famo pri li eliris al ĉiu loko de la tuta ĉirkaŭaĵo.","Kaj famo pri li eliris al ĉiu loko de la tuta ĉirkaŭaĵo."],[4,38,"Kaj leviĝinte el la sinagogo, li eniris en la domon de Simon. Kaj la bopatrino de Simon estis tenata de granda febro, kaj ili petis lin pri ŝi.","Kaj leviĝinte el la sinagogo, li eniris en la domon de Simon. Kaj la bopatrino de Simon estis tenata de granda febro, kaj ili petis lin pri ŝi."],[4,39,"Kaj starante super ŝi, li admonis la febron; kaj ĝi forlasis ŝin, kaj ŝi tuj leviĝis kaj servis al ili.","Kaj starante super ŝi, li admonis la febron; kaj ĝi forlasis ŝin, kaj ŝi tuj leviĝis kaj servis al ili."],[4,40,"Kaj ĉe la subiro de la suno ĉiuj, kiuj havis malsanulojn kun diversaj malsanoj, venigis ilin al li; kaj li metis sur ĉiun el ili la manojn, kaj sanigis ilin.","Kaj ĉe la subiro de la suno ĉiuj, kiuj havis malsanulojn kun diversaj malsanoj, venigis ilin al li; kaj li metis sur ĉiun el ili la manojn, kaj sanigis ilin."],[4,41,"Eliris ankaŭ demonoj el multaj, kriegante, kaj dirante: Vi estas la Filo de Dio. Kaj severe admonante, li ne permesis al ili paroli, ĉar ili sciis, ke li estas la Kristo.","Eliris ankaŭ demonoj el multaj, kriegante, kaj dirante: Vi estas la Filo de Dio. Kaj severe admonante, li ne permesis al ili paroli, ĉar ili sciis, ke li estas la Kristo."],[4,42,"Kaj kiam tagiĝis, li eliris, kaj venis en dezertan lokon; kaj la homamasoj lin serĉis, kaj venis al li, kaj lin detenis, ke li ne foriru de ili.","Kaj kiam tagiĝis, li eliris, kaj venis en dezertan lokon; kaj la homamasoj lin serĉis, kaj venis al li, kaj lin detenis, ke li ne foriru de ili."],[4,43,"Sed li diris al ili: Ankaŭ al la ceteraj urboj mi devas prediki la evangelion de la regno de Dio; ĉar por tio mi estas sendita.","Sed li diris al ili: Ankaŭ al la ceteraj urboj mi devas prediki la evangelion de la regno de Dio; ĉar por tio mi estas sendita."],[4,44,"Kaj li predikis en la sinagogoj de Galileo.","Kaj li predikis en la sinagogoj de Galileo."],[5,1,"Kaj dum la homamaso ĉirkaŭpremis lin kaj aŭskultis la vorton de Dio, li staris apud la lago Genesaret;","Kaj dum la homamaso ĉirkaŭpremis lin kaj aŭskultis la vorton de Dio, li staris apud la lago Genesaret;"],[5,2,"kaj li vidis du ŝipetojn starantajn apud la lago, sed la fiŝkaptistoj ĵus eliris el ili, kaj lavis la retojn.","kaj li vidis du ŝipetojn starantajn apud la lago, sed la fiŝkaptistoj ĵus eliris el ili, kaj lavis la retojn."],[5,3,"Kaj li eniris en unu el la ŝipetoj, kiu apartenis al Simon, kaj petis, ke li forŝovu iom for de la bordo. Kaj li sidiĝis, kaj instruis la homamason el la ŝipeto.","Kaj li eniris en unu el la ŝipetoj, kiu apartenis al Simon, kaj petis, ke li forŝovu iom for de la bordo. Kaj li sidiĝis, kaj instruis la homamason el la ŝipeto."],[5,4,"Kaj kiam li ĉesis paroli, li diris al Simon: Forŝovu ĝis la profundo, kaj mallevu la retojn por akirado.","Kaj kiam li ĉesis paroli, li diris al Simon: Forŝovu ĝis la profundo, kaj mallevu la retojn por akirado."],[5,5,"Kaj responde Simon diris: Estro, ni jam laboris la tutan nokton kaj kaptis nenion; tamen laŭ via diro mi mallevos la retojn.","Kaj responde Simon diris: Estro, ni jam laboris la tutan nokton kaj kaptis nenion; tamen laŭ via diro mi mallevos la retojn."],[5,6,"Kaj tion farinte, ili enfermis grandan amason da fiŝoj, kaj iliaj retoj ekrompiĝis;","Kaj tion farinte, ili enfermis grandan amason da fiŝoj, kaj iliaj retoj ekrompiĝis;"],[5,7,"kaj ili geste signis al siaj kompanianoj en la alia ŝipeto, ke ili venu kaj helpu ilin. Kaj ili venis, kaj plenigis ambaŭ ŝipetojn, ĝis ekprofundiĝo.","kaj ili geste signis al siaj kompanianoj en la alia ŝipeto, ke ili venu kaj helpu ilin. Kaj ili venis, kaj plenigis ambaŭ ŝipetojn, ĝis ekprofundiĝo."],[5,8,"Sed Simon Petro, tion vidinte, falis teren antaŭ la genuoj de Jesuo, dirante: Foriru de mi, ho Sinjoro, ĉar mi estas pekulo.","Sed Simon Petro, tion vidinte, falis teren antaŭ la genuoj de Jesuo, dirante: Foriru de mi, ho Sinjoro, ĉar mi estas pekulo."],[5,9,"Ĉar pro la preno de fiŝoj, kiun ili akiris, miro kaptis lin, kaj ĉiujn, kiuj estis kun li,","Ĉar pro la preno de fiŝoj, kiun ili akiris, miro kaptis lin, kaj ĉiujn, kiuj estis kun li,"],[5,10,"kaj tiel same Jakobon kaj Johanon, filojn de Zebedeo, kiuj estis kompanianoj de Simon. Kaj Jesuo diris al Simon: Ne timu; de nun vi estos kaptisto de homoj.","kaj tiel same Jakobon kaj Johanon, filojn de Zebedeo, kiuj estis kompanianoj de Simon. Kaj Jesuo diris al Simon: Ne timu; de nun vi estos kaptisto de homoj."],[5,11,"Kaj kiam ili surbordigis siajn ŝipetojn, ili forlasis ĉion, kaj sekvis lin.","Kaj kiam ili surbordigis siajn ŝipetojn, ili forlasis ĉion, kaj sekvis lin."],[5,12,"Kaj dum li estis en unu el la urboj, jen viro plena de lepro; kaj vidante Jesuon, li falis sur la vizaĝon kaj petegis lin, dirante: Sinjoro, se vi volas, vi povas min purigi.","Kaj dum li estis en unu el la urboj, jen viro plena de lepro; kaj vidante Jesuon, li falis sur la vizaĝon kaj petegis lin, dirante: Sinjoro, se vi volas, vi povas min purigi."],[5,13,"Kaj li etendis la manon kaj tuŝis lin, dirante: Mi volas; estu purigita. Kaj tuj la lepro foriris de li.","Kaj li etendis la manon kaj tuŝis lin, dirante: Mi volas; estu purigita. Kaj tuj la lepro foriris de li."],[5,14,"Kaj li ordonis al li, ke li diru al neniu: Sed foririnte, montru vin al la pastro kaj tiele oferu pro via purigado, kiel ordonis Moseo, por atesto al ili.","Kaj li ordonis al li, ke li diru al neniu: Sed foririnte, montru vin al la pastro kaj tiele oferu pro via purigado, kiel ordonis Moseo, por atesto al ili."],[5,15,"Sed la famo pri li des pli multe disvastiĝis; kaj grandaj homamasoj kunvenis, por aŭskulti kaj por esti sanigitaj je siaj malsanoj.","Sed la famo pri li des pli multe disvastiĝis; kaj grandaj homamasoj kunvenis, por aŭskulti kaj por esti sanigitaj je siaj malsanoj."],[5,16,"Sed li fortiris sin en la dezertojn, kaj preĝadis.","Sed li fortiris sin en la dezertojn, kaj preĝadis."],[5,17,"Kaj en unu el tiuj tagoj li estis instruanta; kaj ĉeestis Fariseoj kaj leĝinstruistoj, sidantaj, kiuj alvenis el ĉiu vilaĝo de Galileo kaj el Judujo kaj el Jerusalem; kaj la potenco de la Eternulo alestis, por sanigi ilin.","Kaj en unu el tiuj tagoj li estis instruanta; kaj ĉeestis Fariseoj kaj leĝinstruistoj, sidantaj, kiuj alvenis el ĉiu vilaĝo de Galileo kaj el Judujo kaj el Jerusalem; kaj la potenco de la Eternulo alestis, por sanigi ilin."],[5,18,"Kaj jen viroj alportis sur lito viron, kiu estis paralizita; kaj ili penis enporti lin kaj meti lin antaŭ li.","Kaj jen viroj alportis sur lito viron, kiu estis paralizita; kaj ili penis enporti lin kaj meti lin antaŭ li."],[5,19,"Kaj ne trovinte, kiamaniere ili povas enporti lin, pro la homamaso, ili supreniris sur la tegmenton, kaj mallevis lin tra la tegoloj, kun la liteto, en la mezon antaŭ Jesuo.","Kaj ne trovinte, kiamaniere ili povas enporti lin, pro la homamaso, ili supreniris sur la tegmenton, kaj mallevis lin tra la tegoloj, kun la liteto, en la mezon antaŭ Jesuo."],[5,20,"Kaj vidante ilian fidon, li diris: Ho viro, viaj pekoj estas al vi pardonitaj.","Kaj vidante ilian fidon, li diris: Ho viro, viaj pekoj estas al vi pardonitaj."],[5,21,"Kaj la skribistoj kaj Fariseoj komencis diskuti inter si, dirante: Kiu estas ĉi tiu, kiu parolas blasfemojn? kiu povas pardoni pekojn krom Dio sola?","Kaj la skribistoj kaj Fariseoj komencis diskuti inter si, dirante: Kiu estas ĉi tiu, kiu parolas blasfemojn? kiu povas pardoni pekojn krom Dio sola?"],[5,22,"Sed Jesuo, eksciante iliajn pensojn, responde diris al ili: Kial vi diskutas en viaj koroj?","Sed Jesuo, eksciante iliajn pensojn, responde diris al ili: Kial vi diskutas en viaj koroj?"],[5,23,"Kio estas pli facila, diri: Viaj pekoj estas al vi pardonitaj, aŭ diri: Leviĝu kaj piediru?","Kio estas pli facila, diri: Viaj pekoj estas al vi pardonitaj, aŭ diri: Leviĝu kaj piediru?"],[5,24,"Sed por ke vi sciu, ke la Filo de homo havas aŭtoritaton sur la tero pardoni pekojn — li diris al la paralizulo: Mi diras al vi: Leviĝu, kaj prenu vian liteton, kaj iru al via domo.","Sed por ke vi sciu, ke la Filo de homo havas aŭtoritaton sur la tero pardoni pekojn — li diris al la paralizulo: Mi diras al vi: Leviĝu, kaj prenu vian liteton, kaj iru al via domo."],[5,25,"Kaj tuj li leviĝis antaŭ ili, kaj prenis tion, sur kio li kuŝis, kaj iris al sia domo, glorante Dion.","Kaj tuj li leviĝis antaŭ ili, kaj prenis tion, sur kio li kuŝis, kaj iris al sia domo, glorante Dion."],[5,26,"Kaj mirego kaptis ĉiujn, kaj li gloris Dion; kaj ili pleniĝis de timo, dirante: Ni vidis mirindaĵojn hodiaŭ.","Kaj mirego kaptis ĉiujn, kaj li gloris Dion; kaj ili pleniĝis de timo, dirante: Ni vidis mirindaĵojn hodiaŭ."],[5,27,"Kaj post tio li eliris, kaj vidis impostiston, nomatan Levi, sidantan ĉe la impostejo, kaj diris al li: Sekvu min.","Kaj post tio li eliris, kaj vidis impostiston, nomatan Levi, sidantan ĉe la impostejo, kaj diris al li: Sekvu min."],[5,28,"Kaj li forlasis ĉion, kaj leviĝis, kaj sekvis lin.","Kaj li forlasis ĉion, kaj leviĝis, kaj sekvis lin."],[5,29,"Kaj Levi faris grandan festenon por li en sia domo, kaj estis granda amaso da impostistoj kaj aliaj, kiuj sidis ĉe manĝo kun ili.","Kaj Levi faris grandan festenon por li en sia domo, kaj estis granda amaso da impostistoj kaj aliaj, kiuj sidis ĉe manĝo kun ili."],[5,30,"Kaj la Fariseoj kaj iliaj skribistoj murmuris kontraŭ liaj disĉiploj, dirante: Kial vi manĝas kaj trinkas kun impostistoj kaj pekuloj?","Kaj la Fariseoj kaj iliaj skribistoj murmuris kontraŭ liaj disĉiploj, dirante: Kial vi manĝas kaj trinkas kun impostistoj kaj pekuloj?"],[5,31,"Kaj Jesuo responde diris al ili: Ne la sanuloj bezonas kuraciston, sed la malsanuloj.","Kaj Jesuo responde diris al ili: Ne la sanuloj bezonas kuraciston, sed la malsanuloj."],[5,32,"Mi venis, por alvoki ne justulojn, sed pekulojn al pento.","Mi venis, por alvoki ne justulojn, sed pekulojn al pento."],[5,33,"Kaj ili diris al li: La disĉiploj de Johano ofte fastas kaj faras preĝojn, kaj tiel same ankaŭ la disĉiploj de la Fariseoj; sed la viaj manĝas kaj trinkas.","Kaj ili diris al li: La disĉiploj de Johano ofte fastas kaj faras preĝojn, kaj tiel same ankaŭ la disĉiploj de la Fariseoj; sed la viaj manĝas kaj trinkas."],[5,34,"Kaj Jesuo diris al ili: Ĉu vi povas igi la filojn de la edziĝejo fasti, dum la fianĉo estas kun ili?","Kaj Jesuo diris al ili: Ĉu vi povas igi la filojn de la edziĝejo fasti, dum la fianĉo estas kun ili?"],[5,35,"Sed venos tagoj; kaj kiam la fianĉo estos prenita for de ili, tiam ili fastos en tiuj tagoj.","Sed venos tagoj; kaj kiam la fianĉo estos prenita for de ili, tiam ili fastos en tiuj tagoj."],[5,36,"Kaj li ankaŭ parolis al ili parabolon: Neniu ŝiras pecon el nova vesto kaj alkudras ĝin sur malnovan veston; ĉar alie li ŝirus la novan, kaj ankaŭ la flikaĵo el la nova ne harmonius kun la malnova.","Kaj li ankaŭ parolis al ili parabolon: Neniu ŝiras pecon el nova vesto kaj alkudras ĝin sur malnovan veston; ĉar alie li ŝirus la novan, kaj ankaŭ la flikaĵo el la nova ne harmonius kun la malnova."],[5,37,"Kaj neniu enverŝas novan vinon en malnovajn felsakojn; ĉar alie la nova vino krevigus la felsakojn, kaj ĝi mem elfluus, kaj la felsakoj detruiĝus.","Kaj neniu enverŝas novan vinon en malnovajn felsakojn; ĉar alie la nova vino krevigus la felsakojn, kaj ĝi mem elfluus, kaj la felsakoj detruiĝus."],[5,38,"Sed novan vinon oni devas enverŝi en novajn felsakojn.","Sed novan vinon oni devas enverŝi en novajn felsakojn."],[5,39,"Kaj neniu, trinkinte malnovan vinon, deziras novan; ĉar li diras: La malnova estas preferinda.","Kaj neniu, trinkinte malnovan vinon, deziras novan; ĉar li diras: La malnova estas preferinda."],[6,1,"Kaj en sabato li iris tra la grenkampoj, kaj liaj disĉiploj deŝiris la spikojn, kaj manĝis, frotante ilin en la manoj.","Kaj en sabato li iris tra la grenkampoj, kaj liaj disĉiploj deŝiris la spikojn, kaj manĝis, frotante ilin en la manoj."],[6,2,"Sed iuj el la Fariseoj diris: Kial vi faras tion, kion fari en sabato ne estas permesate?","Sed iuj el la Fariseoj diris: Kial vi faras tion, kion fari en sabato ne estas permesate?"],[6,3,"Kaj Jesuo, respondante al ili, diris: Ĉu vi eĉ ne legis, kion faris David, kiam malsatis li kaj liaj kunuloj?","Kaj Jesuo, respondante al ili, diris: Ĉu vi eĉ ne legis, kion faris David, kiam malsatis li kaj liaj kunuloj?"],[6,4,"ke li eniris en la domon de Dio, kaj prenis kaj manĝis kaj donis ankaŭ al siaj kunuloj la panojn de propono, kiujn manĝi ne estas permesate, krom nur al la pastroj?","ke li eniris en la domon de Dio, kaj prenis kaj manĝis kaj donis ankaŭ al siaj kunuloj la panojn de propono, kiujn manĝi ne estas permesate, krom nur al la pastroj?"],[6,5,"Kaj li diris al ili: La Filo de homo estas sinjoro de la sabato.","Kaj li diris al ili: La Filo de homo estas sinjoro de la sabato."],[6,6,"Kaj en alia sabato li eniris en la sinagogon kaj instruadis; kaj tie estis viro, kies dekstra mano estis velkinta.","Kaj en alia sabato li eniris en la sinagogon kaj instruadis; kaj tie estis viro, kies dekstra mano estis velkinta."],[6,7,"Kaj la skribistoj kaj Fariseoj observis lin atente, ĉu li sanigos en la sabato, por ke ili trovu, kiel lin akuzi.","Kaj la skribistoj kaj Fariseoj observis lin atente, ĉu li sanigos en la sabato, por ke ili trovu, kiel lin akuzi."],[6,8,"Sed li sciis iliajn pensojn, kaj li diris al la viro, kiu havis la manon velkintan: Leviĝu, kaj stariĝu en la mezo. Kaj li leviĝis kaj stariĝis.","Sed li sciis iliajn pensojn, kaj li diris al la viro, kiu havis la manon velkintan: Leviĝu, kaj stariĝu en la mezo. Kaj li leviĝis kaj stariĝis."],[6,9,"Kaj Jesuo diris al ili: Mi vin demandas: ĉu estas permesate bonfari en sabato, aŭ malbonfari? Savi vivon, al ĝin pereigi?","Kaj Jesuo diris al ili: Mi vin demandas: ĉu estas permesate bonfari en sabato, aŭ malbonfari? Savi vivon, al ĝin pereigi?"],[6,10,"Kaj ĉirkaŭrigardinte ĉiujn, li diris al li: Etendu vian manon. Kaj li tion faris, kaj lia mano resaniĝis.","Kaj ĉirkaŭrigardinte ĉiujn, li diris al li: Etendu vian manon. Kaj li tion faris, kaj lia mano resaniĝis."],[6,11,"Sed ili pleniĝis de frenezo, kaj interparoladis inter si, kion ili faru al Jesuo.","Sed ili pleniĝis de frenezo, kaj interparoladis inter si, kion ili faru al Jesuo."],[6,12,"Kaj en tiuj tagoj li foriris sur la monton, por preĝi; kaj li pasigis la tutan nokton en preĝado al Dio.","Kaj en tiuj tagoj li foriris sur la monton, por preĝi; kaj li pasigis la tutan nokton en preĝado al Dio."],[6,13,"Kaj kiam tagiĝis, li alvokis siajn disĉiplojn, kaj elektis el ili dek du, kiujn li ankaŭ nomis apostoloj:","Kaj kiam tagiĝis, li alvokis siajn disĉiplojn, kaj elektis el ili dek du, kiujn li ankaŭ nomis apostoloj:"],[6,14,"Simonon, kiun li ankaŭ nomis Petro, kaj Andreon, lian fraton, kaj Jakobon kaj Johanon kaj Filipon kaj Bartolomeon","Simonon, kiun li ankaŭ nomis Petro, kaj Andreon, lian fraton, kaj Jakobon kaj Johanon kaj Filipon kaj Bartolomeon"],[6,15,"kaj Mateon kaj Tomason, kaj Jakobon, filon de Alfeo, kaj Simonon, nomatan Fervorulo,","kaj Mateon kaj Tomason, kaj Jakobon, filon de Alfeo, kaj Simonon, nomatan Fervorulo,"],[6,16,"kaj Judason de Jakobo, kaj Judason Iskariotan, kiu fariĝis perfidulo.","kaj Judason de Jakobo, kaj Judason Iskariotan, kiu fariĝis perfidulo."],[6,17,"Kaj li malsupreniris kun ili, kaj staris sur ebena loko, kaj granda amaso de liaj disĉiploj, kaj granda nombro de la popolo el la tuta Judujo kaj Jerusalem, kaj el la marbordo de Tiro kaj Cidon, kiuj alvenis, por aŭskulti lin kaj saniĝi je siaj malsanoj;","Kaj li malsupreniris kun ili, kaj staris sur ebena loko, kaj granda amaso de liaj disĉiploj, kaj granda nombro de la popolo el la tuta Judujo kaj Jerusalem, kaj el la marbordo de Tiro kaj Cidon, kiuj alvenis, por aŭskulti lin kaj saniĝi je siaj malsanoj;"],[6,18,"kaj tiuj, kiuj estis turmentataj de malpuraj spiritoj, estis sanigitaj.","kaj tiuj, kiuj estis turmentataj de malpuraj spiritoj, estis sanigitaj."],[6,19,"Kaj la tuta homamaso volis tuŝi lin, ĉar potenco eliris el li kaj sanigis ĉiujn.","Kaj la tuta homamaso volis tuŝi lin, ĉar potenco eliris el li kaj sanigis ĉiujn."],[6,20,"Kaj li levis siajn okulojn al siaj disĉiploj, kaj diris: Feliĉaj estas vi malriĉuloj, ĉar via estas la regno de Dio.","Kaj li levis siajn okulojn al siaj disĉiploj, kaj diris: Feliĉaj estas vi malriĉuloj, ĉar via estas la regno de Dio."],[6,21,"Feliĉaj estas vi, kiuj nun malsatas, ĉar vi satiĝos. Feliĉaj estas vi, kiuj nun ploras, ĉar vi ridos.","Feliĉaj estas vi, kiuj nun malsatas, ĉar vi satiĝos. Feliĉaj estas vi, kiuj nun ploras, ĉar vi ridos."],[6,22,"Feliĉaj vi estas, kiam oni vin malamos kaj vin izolos kaj vin riproĉos, kaj elĵetos vian nomon kial malbonan, pro la Filo de homo.","Feliĉaj vi estas, kiam oni vin malamos kaj vin izolos kaj vin riproĉos, kaj elĵetos vian nomon kial malbonan, pro la Filo de homo."],[6,23,"Ĝoju en tiu tago, kaj pro ĝojo saltu, ĉar jen via rekompenco estas granda en la ĉielo; ĉar tiel same faris iliaj patroj kontraŭ la profetoj.","Ĝoju en tiu tago, kaj pro ĝojo saltu, ĉar jen via rekompenco estas granda en la ĉielo; ĉar tiel same faris iliaj patroj kontraŭ la profetoj."],[6,24,"Sed ve al vi riĉuloj! ĉar vi jam ricevis vian konsolon.","Sed ve al vi riĉuloj! ĉar vi jam ricevis vian konsolon."],[6,25,"Ve al vi satigitaj! ĉar vi malsatos. Ve al vi, kiuj nun ridas! ĉar vi malĝojos kaj ploros.","Ve al vi satigitaj! ĉar vi malsatos. Ve al vi, kiuj nun ridas! ĉar vi malĝojos kaj ploros."],[6,26,"Ve, kiam ĉiuj homoj parolos bone pri vi! ĉar tiel same faris iliaj patroj al la falsaj profetoj.","Ve, kiam ĉiuj homoj parolos bone pri vi! ĉar tiel same faris iliaj patroj al la falsaj profetoj."],[6,27,"Sed mi diras al vi, kiuj aŭdas: Amu viajn malamikojn, faru bonon al viaj malamantoj;","Sed mi diras al vi, kiuj aŭdas: Amu viajn malamikojn, faru bonon al viaj malamantoj;"],[6,28,"benu tiujn, kiuj vin malbenas; preĝu por tiuj, kiuj kun insulto vin atakas.","benu tiujn, kiuj vin malbenas; preĝu por tiuj, kiuj kun insulto vin atakas."],[6,29,"Al tiu, kiu frapas vin sur la vango, prezentu ankaŭ la alian; kaj de tiu, kiu prenas vian mantelon, ne detenu vian tunikon.","Al tiu, kiu frapas vin sur la vango, prezentu ankaŭ la alian; kaj de tiu, kiu prenas vian mantelon, ne detenu vian tunikon."],[6,30,"Donu al ĉiu, kiu petas de vi; kaj de tiu, kiu forprenas viajn posedaĵojn, ne repostulu ilin.","Donu al ĉiu, kiu petas de vi; kaj de tiu, kiu forprenas viajn posedaĵojn, ne repostulu ilin."],[6,31,"Kaj kiel vi volas, ke la homoj faru al vi, faru ankaŭ al ili tiel same.","Kaj kiel vi volas, ke la homoj faru al vi, faru ankaŭ al ili tiel same."],[6,32,"Kaj se vi amas tiujn, kiuj amas vin, kian dankon vi havas? ĉar eĉ la pekuloj amas tiujn, kiuj ilin amas.","Kaj se vi amas tiujn, kiuj amas vin, kian dankon vi havas? ĉar eĉ la pekuloj amas tiujn, kiuj ilin amas."],[6,33,"Kaj se vi bonfaras al viaj bonfarantoj, kian dankon vi havas? ĉar eĉ la pekuloj tiel same faras.","Kaj se vi bonfaras al viaj bonfarantoj, kian dankon vi havas? ĉar eĉ la pekuloj tiel same faras."],[6,34,"Kaj se vi pruntas al tiuj, de kiuj vi esperas ricevi, kian dankon vi havas? eĉ pekuloj pruntas al pekuloj, por egale rericevi.","Kaj se vi pruntas al tiuj, de kiuj vi esperas ricevi, kian dankon vi havas? eĉ pekuloj pruntas al pekuloj, por egale rericevi."],[6,35,"Sed amu viajn malamikojn, kaj bonfaru, kaj pruntedonu, pri neniu perdante esperon; kaj via rekompenco estos granda, kaj vi estos filoj de la Plejalta; ĉar Li estas bona al la nedankemuloj kaj malbonuloj.","Sed amu viajn malamikojn, kaj bonfaru, kaj pruntedonu, pri neniu perdante esperon; kaj via rekompenco estos granda, kaj vi estos filoj de la Plejalta; ĉar Li estas bona al la nedankemuloj kaj malbonuloj."],[6,36,"Estu kompatemaj, kiel via Patro estas kompatema.","Estu kompatemaj, kiel via Patro estas kompatema."],[6,37,"Kaj ne juĝu, kaj vi ne estos juĝitaj; kaj ne kondamnu, kaj vi ne estos kondamnitaj; liberigu, kaj vi estos liberigitaj;","Kaj ne juĝu, kaj vi ne estos juĝitaj; kaj ne kondamnu, kaj vi ne estos kondamnitaj; liberigu, kaj vi estos liberigitaj;"],[6,38,"donu, kaj estos donite al vi; bonan mezuron, premitan, kunskuitan, superfluantan, oni donos en vian sinon. Ĉar per kia mezuro vi mezuras, per tia oni remezuros al vi.","donu, kaj estos donite al vi; bonan mezuron, premitan, kunskuitan, superfluantan, oni donos en vian sinon. Ĉar per kia mezuro vi mezuras, per tia oni remezuros al vi."],[6,39,"Kaj li parolis ankaŭ al ili parabolon: Ĉu blindulo povas gvidi blindulon? ĉu ne falos ambaŭ en fosaĵon?","Kaj li parolis ankaŭ al ili parabolon: Ĉu blindulo povas gvidi blindulon? ĉu ne falos ambaŭ en fosaĵon?"],[6,40,"Disĉiplo ne estas super sia instruisto; sed perfektigite, ĉiu estos kiel lia instruisto.","Disĉiplo ne estas super sia instruisto; sed perfektigite, ĉiu estos kiel lia instruisto."],[6,41,"Kaj kial vi rigardas la lignereton, kiu estas en la okulo de via frato, kaj ne pripensas la trabon, kiu estas en via propra okulo?","Kaj kial vi rigardas la lignereton, kiu estas en la okulo de via frato, kaj ne pripensas la trabon, kiu estas en via propra okulo?"],[6,42,"Kiel vi povas diri al via frato: Frato, lasu min eltiri la lignereton, kiu estas en via okulo; dum vi ne pripensas la trabon en via propra okulo? Hipokritulo! eltiru unue la trabon el via okulo, kaj tiam vi klare vidos, por eltiri la lignereton, kiu estas en la okulo de via frato.","Kiel vi povas diri al via frato: Frato, lasu min eltiri la lignereton, kiu estas en via okulo; dum vi ne pripensas la trabon en via propra okulo? Hipokritulo! eltiru unue la trabon el via okulo, kaj tiam vi klare vidos, por eltiri la lignereton, kiu estas en la okulo de via frato."],[6,43,"Ĉar ne ekzistas bona arbo, kiu donas putran frukton; nek putra arbo, kiu donas bonan frukton.","Ĉar ne ekzistas bona arbo, kiu donas putran frukton; nek putra arbo, kiu donas bonan frukton."],[6,44,"Ĉar ĉiu arbo estas konata per sia propra frukto. Ĉar el dornarbetoj oni ne kolektas figojn, nek el rubusujo oni rikoltas vinberojn.","Ĉar ĉiu arbo estas konata per sia propra frukto. Ĉar el dornarbetoj oni ne kolektas figojn, nek el rubusujo oni rikoltas vinberojn."],[6,45,"Bona homo el la bona trezorejo de sia koro liveras bonon, kaj malbona homo el la malbona trezorejo liveras malbonon; ĉar el la abundo de la koro parolas lia buŝo.","Bona homo el la bona trezorejo de sia koro liveras bonon, kaj malbona homo el la malbona trezorejo liveras malbonon; ĉar el la abundo de la koro parolas lia buŝo."],[6,46,"Kaj kial vi min vokas: Sinjoro, Sinjoro; kaj ne faras tion, kion mi diras?","Kaj kial vi min vokas: Sinjoro, Sinjoro; kaj ne faras tion, kion mi diras?"],[6,47,"Pri ĉiu, kiu venas al mi, kaj aŭdas miajn parolojn, kaj plenumas ilin, mi montros al vi, al kiu li similas:","Pri ĉiu, kiu venas al mi, kaj aŭdas miajn parolojn, kaj plenumas ilin, mi montros al vi, al kiu li similas:"],[6,48,"li similas al viro, kiu, konstruante domon, fosis kaj profunde kavigis, kaj metis fundamenton sur la roko; kaj kiam okazis inundo, la rivero sin ĵetis kontraŭ tiun domon, kaj ne povis ĝin ŝanceli; ĉar ĝi estis bone konstruita.","li similas al viro, kiu, konstruante domon, fosis kaj profunde kavigis, kaj metis fundamenton sur la roko; kaj kiam okazis inundo, la rivero sin ĵetis kontraŭ tiun domon, kaj ne povis ĝin ŝanceli; ĉar ĝi estis bone konstruita."],[6,49,"Sed tiu, kiu aŭdas kaj ne plenumas, similas al viro, kiu konstruis sur la tero sen fundamento domon; kontraŭ kiun la rivero sin ĵetis, kaj ĝi tuj enfalis, kaj la ruino de tiu domo estis granda.","Sed tiu, kiu aŭdas kaj ne plenumas, similas al viro, kiu konstruis sur la tero sen fundamento domon; kontraŭ kiun la rivero sin ĵetis, kaj ĝi tuj enfalis, kaj la ruino de tiu domo estis granda."],[7,1,"Fininte ĉiujn siajn dirojn en la oreloj de la popolo, li eniris en Kapernaumon.","Fininte ĉiujn siajn dirojn en la oreloj de la popolo, li eniris en Kapernaumon."],[7,2,"Kaj sklavo de unu centestro, kiu estis kara por li, estis malsana kaj preskaŭ mortanta.","Kaj sklavo de unu centestro, kiu estis kara por li, estis malsana kaj preskaŭ mortanta."],[7,3,"Kaj aŭdinte pri Jesuo, tiu sendis al li pliaĝulojn de la Judoj, por peti, ke li venu, por savi lian sklavon.","Kaj aŭdinte pri Jesuo, tiu sendis al li pliaĝulojn de la Judoj, por peti, ke li venu, por savi lian sklavon."],[7,4,"Kaj veninte al Jesuo, ili insiste petegis, dirante: Li estas inda, ke vi faru al li tiun komplezon;","Kaj veninte al Jesuo, ili insiste petegis, dirante: Li estas inda, ke vi faru al li tiun komplezon;"],[7,5,"ĉar li amas nian nacion, kaj li mem konstruigis por ni la sinagogon.","ĉar li amas nian nacion, kaj li mem konstruigis por ni la sinagogon."],[7,6,"Kaj Jesuo ekiris kun ili. Kaj kiam li estis ne malproksime de la domo, la centestro sendis al li amikojn, por diri al li: Sinjoro, ne ĝenu vin; ĉar mi ne estas inda, ke vi venu sub mian tegmenton;","Kaj Jesuo ekiris kun ili. Kaj kiam li estis ne malproksime de la domo, la centestro sendis al li amikojn, por diri al li: Sinjoro, ne ĝenu vin; ĉar mi ne estas inda, ke vi venu sub mian tegmenton;"],[7,7,"pro tio mi ne opiniis min inda veni al vi. Sed vorton parolu, kaj mia knabo saniĝos.","pro tio mi ne opiniis min inda veni al vi. Sed vorton parolu, kaj mia knabo saniĝos."],[7,8,"Ĉar mi ankaŭ estas homo metita sub aŭtoritato, havante sub mi soldatojn; kaj mi diras al ĉi tiu: Iru; kaj li iras; kaj al alia: Venu; kaj li venas; kaj al mia sklavo: Faru ĉi tion; kaj li ĝin faras.","Ĉar mi ankaŭ estas homo metita sub aŭtoritato, havante sub mi soldatojn; kaj mi diras al ĉi tiu: Iru; kaj li iras; kaj al alia: Venu; kaj li venas; kaj al mia sklavo: Faru ĉi tion; kaj li ĝin faras."],[7,9,"Kaj kiam Jesuo tion aŭdis, li miris pri li, kaj sin turninte, diris al la homamaso, lin sekvanta: Mi diras al vi: Eĉ en Izrael mi ne trovis tiom da fido.","Kaj kiam Jesuo tion aŭdis, li miris pri li, kaj sin turninte, diris al la homamaso, lin sekvanta: Mi diras al vi: Eĉ en Izrael mi ne trovis tiom da fido."],[7,10,"Kaj la senditoj, reveninte al la domo, trovis la sklavon sana.","Kaj la senditoj, reveninte al la domo, trovis la sklavon sana."],[7,11,"Kaj post nelonge li iris al urbo nomata Nain, kaj akompanis lin liaj disĉiploj kaj granda homamaso.","Kaj post nelonge li iris al urbo nomata Nain, kaj akompanis lin liaj disĉiploj kaj granda homamaso."],[7,12,"Kaj kiam li alproksimiĝis al la pordego de la urbo, jen oni elportis mortinton, la solan filon de lia patrino, kaj ŝi estis vidvino; kaj granda homamaso el la urbo estis kun ŝi.","Kaj kiam li alproksimiĝis al la pordego de la urbo, jen oni elportis mortinton, la solan filon de lia patrino, kaj ŝi estis vidvino; kaj granda homamaso el la urbo estis kun ŝi."],[7,13,"Kaj kiam la Sinjoro ŝin vidis, li kortuŝiĝis pri ŝi, kaj diris al ŝi: Ne ploru.","Kaj kiam la Sinjoro ŝin vidis, li kortuŝiĝis pri ŝi, kaj diris al ŝi: Ne ploru."],[7,14,"Kaj li alproksimiĝis, kaj tuŝis la portilon, kaj la portantoj haltis. Kaj li diris: Junulo, mi diras al vi: Leviĝu.","Kaj li alproksimiĝis, kaj tuŝis la portilon, kaj la portantoj haltis. Kaj li diris: Junulo, mi diras al vi: Leviĝu."],[7,15,"Kaj la mortinto side leviĝis kaj komencis paroli. Kaj li donis lin al lia patrino.","Kaj la mortinto side leviĝis kaj komencis paroli. Kaj li donis lin al lia patrino."],[7,16,"Kaj timo kaptis ĉiujn; kaj ili gloris Dio, dirante: Granda profeto leviĝis inter ni; kaj: Dio vizitis Sian popolon.","Kaj timo kaptis ĉiujn; kaj ili gloris Dio, dirante: Granda profeto leviĝis inter ni; kaj: Dio vizitis Sian popolon."],[7,17,"Kaj ĉi tiu famo pri li eliris tra la tuta Judujo, kaj tra la tuta ĉirkaŭaĵo.","Kaj ĉi tiu famo pri li eliris tra la tuta Judujo, kaj tra la tuta ĉirkaŭaĵo."],[7,18,"Kaj la disĉiploj de Johano sciigis lin pri ĉio tio.","Kaj la disĉiploj de Johano sciigis lin pri ĉio tio."],[7,19,"Kaj Johano, alvokinte al si du el siaj disĉiploj, sendis ilin al la Sinjoro, por diri: Ĉu vi estas la venonto, aŭ ĉu ni atendu alian?","Kaj Johano, alvokinte al si du el siaj disĉiploj, sendis ilin al la Sinjoro, por diri: Ĉu vi estas la venonto, aŭ ĉu ni atendu alian?"],[7,20,"Kaj kiam la viroj alvenis al li, ili diris: Johano, la Baptisto, sendis nin al vi, por diri: Ĉu vi estas la venonto, aŭ ĉu ni atendu alian?","Kaj kiam la viroj alvenis al li, ili diris: Johano, la Baptisto, sendis nin al vi, por diri: Ĉu vi estas la venonto, aŭ ĉu ni atendu alian?"],[7,21,"En tiu horo li sanigis multajn je malsanoj kaj pestoj kaj malbonaj spiritoj; kaj al multaj blinduloj li redonis vidpovon.","En tiu horo li sanigis multajn je malsanoj kaj pestoj kaj malbonaj spiritoj; kaj al multaj blinduloj li redonis vidpovon."],[7,22,"Kaj li respondis kaj diris al ili: Iru kaj sciigu Johanon pri tio, kion vi vidis kaj aŭdis: blinduloj vidas, lamuloj marŝas, lepruloj estas purigitaj, kaj surduloj aŭdas, mortintoj leviĝas, al malriĉuloj evangelio estas predikata.","Kaj li respondis kaj diris al ili: Iru kaj sciigu Johanon pri tio, kion vi vidis kaj aŭdis: blinduloj vidas, lamuloj marŝas, lepruloj estas purigitaj, kaj surduloj aŭdas, mortintoj leviĝas, al malriĉuloj evangelio estas predikata."],[7,23,"Kaj feliĉa estas ĉiu, kiu ne falpuŝiĝas pro mi.","Kaj feliĉa estas ĉiu, kiu ne falpuŝiĝas pro mi."],[7,24,"Kaj kiam la senditoj de Johano foriris, li komencis paroli al la homamasoj pri Johano: Kion vi eliris en la dezerton, por rigardi? ĉu junkon skuatan de la vento?","Kaj kiam la senditoj de Johano foriris, li komencis paroli al la homamasoj pri Johano: Kion vi eliris en la dezerton, por rigardi? ĉu junkon skuatan de la vento?"],[7,25,"Sed kion vi eliris, por vidi? ĉu homon per mola vestaro vestitan? Jen tiuj, kiuj portas luksan vestaron kaj delikate vivadas, troviĝas en domoj de reĝoj.","Sed kion vi eliris, por vidi? ĉu homon per mola vestaro vestitan? Jen tiuj, kiuj portas luksan vestaron kaj delikate vivadas, troviĝas en domoj de reĝoj."],[7,26,"Sed kion vi eliris, por vidi? ĉu profeton? Jes, mi diras al vi, kaj multe pli ol profeton.","Sed kion vi eliris, por vidi? ĉu profeton? Jes, mi diras al vi, kaj multe pli ol profeton."],[7,27,"Ĉar li estas tiu, pri kiu estas skribite: Jen Mi sendos Mian anĝelon antaŭ via vizaĝo, Kaj li preparos antaŭ vi vian vojon.","Ĉar li estas tiu, pri kiu estas skribite: Jen Mi sendos Mian anĝelon antaŭ via vizaĝo, Kaj li preparos antaŭ vi vian vojon."],[7,28,"Mi diras al vi: Inter naskitoj de virinoj estas neniu pli granda ol Johano; tamen tiu, kiu estas nur malgranda en la regno de Dio, estas pli granda ol li.","Mi diras al vi: Inter naskitoj de virinoj estas neniu pli granda ol Johano; tamen tiu, kiu estas nur malgranda en la regno de Dio, estas pli granda ol li."],[7,29,"Kaj la tuta popolo kaj la impostistoj, aŭdinte, pravigis Dion, ĉar ili ricevis la bapton de Johano.","Kaj la tuta popolo kaj la impostistoj, aŭdinte, pravigis Dion, ĉar ili ricevis la bapton de Johano."],[7,30,"Sed la Fariseoj kaj la leĝistoj rifuzis por si la intencon de Dio, ĉar ili ne estis baptitaj de li.","Sed la Fariseoj kaj la leĝistoj rifuzis por si la intencon de Dio, ĉar ili ne estis baptitaj de li."],[7,31,"Al kio do mi komparos la homojn de ĉi tiu generacio? kaj al kio ili similas?","Al kio do mi komparos la homojn de ĉi tiu generacio? kaj al kio ili similas?"],[7,32,"Ili similas al infanoj, kiuj sidas sur la placo kaj vokas unu al alia, dirante: Ni flutis al vi, kaj vi ne dancis; ni lamentis, kaj vi ne ploris.","Ili similas al infanoj, kiuj sidas sur la placo kaj vokas unu al alia, dirante: Ni flutis al vi, kaj vi ne dancis; ni lamentis, kaj vi ne ploris."],[7,33,"Ĉar Johano, la Baptisto, venis, nek manĝante panon nek trinkante vinon; kaj vi diras: Li havas demonon.","Ĉar Johano, la Baptisto, venis, nek manĝante panon nek trinkante vinon; kaj vi diras: Li havas demonon."],[7,34,"La Filo de homo venis, manĝante kaj trinkante; kaj vi diras: Jen manĝegulo kaj vindrinkulo, amiko de impostistoj kaj pekuloj!","La Filo de homo venis, manĝante kaj trinkante; kaj vi diras: Jen manĝegulo kaj vindrinkulo, amiko de impostistoj kaj pekuloj!"],[7,35,"Kaj la saĝeco estas pravigita de ĉiuj siaj infanoj.","Kaj la saĝeco estas pravigita de ĉiuj siaj infanoj."],[7,36,"Kaj unu el la Fariseoj petis lin, ke li manĝu kun li. Kaj li eniris en la domon de la Fariseo, kaj sidiĝis ĉe manĝo.","Kaj unu el la Fariseoj petis lin, ke li manĝu kun li. Kaj li eniris en la domon de la Fariseo, kaj sidiĝis ĉe manĝo."],[7,37,"Kaj jen estis en la urbo virino pekulino; kaj kiam ŝi eksciis, ke Jesuo sidas ĉe manĝo en la domo de la Fariseo, ŝi alportis alabastran vazon da ŝmiraĵo,","Kaj jen estis en la urbo virino pekulino; kaj kiam ŝi eksciis, ke Jesuo sidas ĉe manĝo en la domo de la Fariseo, ŝi alportis alabastran vazon da ŝmiraĵo,"],[7,38,"kaj starante malantaŭe ĉe liaj piedoj, plorante, ŝi komencis priverŝi liajn piedojn per ŝiaj larmoj, kaj viŝis ilin per la haroj de sia kapo, kaj kisadis liajn piedojn, kaj ŝmiris ilin per la ŝmiraĵo.","kaj starante malantaŭe ĉe liaj piedoj, plorante, ŝi komencis priverŝi liajn piedojn per ŝiaj larmoj, kaj viŝis ilin per la haroj de sia kapo, kaj kisadis liajn piedojn, kaj ŝmiris ilin per la ŝmiraĵo."],[7,39,"Kaj kiam la Fariseo, kiu lin invitis, tion vidis, li parolis en si, dirante: Ĉi tiu, se li estus profeto, ja scius, kiu kaj kia virino lin tuŝas, ke ŝi estas pekulino.","Kaj kiam la Fariseo, kiu lin invitis, tion vidis, li parolis en si, dirante: Ĉi tiu, se li estus profeto, ja scius, kiu kaj kia virino lin tuŝas, ke ŝi estas pekulino."],[7,40,"Kaj responde Jesuo diris al li: Simon, mi havas ion diri al vi. Kaj li diris: Majstro, parolu.","Kaj responde Jesuo diris al li: Simon, mi havas ion diri al vi. Kaj li diris: Majstro, parolu."],[7,41,"Unu pruntedoninto havis du ŝuldantojn; unu ŝuldis kvincent denarojn, kaj la alia kvindek.","Unu pruntedoninto havis du ŝuldantojn; unu ŝuldis kvincent denarojn, kaj la alia kvindek."],[7,42,"Kiam ili havis nenion, per kio pagi, li pardonis al ambaŭ la ŝuldon. Kiu el ili do lin pli amos?","Kiam ili havis nenion, per kio pagi, li pardonis al ambaŭ la ŝuldon. Kiu el ili do lin pli amos?"],[7,43,"Simon responde diris: Tiu, mi supozas, al kiu li pardonis la pli grandan ŝuldon. Kaj li diris al li: Vi prave juĝis.","Simon responde diris: Tiu, mi supozas, al kiu li pardonis la pli grandan ŝuldon. Kaj li diris al li: Vi prave juĝis."],[7,44,"Kaj sin turnante al la virino, li diris al Simon: Ĉu vi vidas ĉi tiun virinon? Mi eniris en vian domon, vi ne donis al mi akvon por la piedoj; sed ŝi priverŝis miajn piedojn per siaj larmoj kaj viŝis ilin per siaj haroj.","Kaj sin turnante al la virino, li diris al Simon: Ĉu vi vidas ĉi tiun virinon? Mi eniris en vian domon, vi ne donis al mi akvon por la piedoj; sed ŝi priverŝis miajn piedojn per siaj larmoj kaj viŝis ilin per siaj haroj."],[7,45,"Vi ne donis al mi kison; sed ŝi, de la tempo, kiam mi eniris, ne ĉesis kisadi miajn piedojn.","Vi ne donis al mi kison; sed ŝi, de la tempo, kiam mi eniris, ne ĉesis kisadi miajn piedojn."],[7,46,"Vi ne ŝmiris mian kapon per oleo; sed ŝi ŝmiris miajn piedojn per ŝmiraĵo.","Vi ne ŝmiris mian kapon per oleo; sed ŝi ŝmiris miajn piedojn per ŝmiraĵo."],[7,47,"Pro tio mi diras al vi: Ŝiaj pekoj, kiuj estas multaj, estas pardonitaj; ĉar ŝi multe amis; sed al kiu malmulto estas pardonita, tiu malmulte amas.","Pro tio mi diras al vi: Ŝiaj pekoj, kiuj estas multaj, estas pardonitaj; ĉar ŝi multe amis; sed al kiu malmulto estas pardonita, tiu malmulte amas."],[7,48,"Kaj li diris al ŝi: Viaj pekoj estas pardonitaj.","Kaj li diris al ŝi: Viaj pekoj estas pardonitaj."],[7,49,"Kaj tiuj, kiuj sidis ĉe manĝo kun li, komencis diri inter si: Kiu estas ĉi tiu, kiu eĉ pardonas pekojn?","Kaj tiuj, kiuj sidis ĉe manĝo kun li, komencis diri inter si: Kiu estas ĉi tiu, kiu eĉ pardonas pekojn?"],[7,50,"Kaj li diris al la virino: Via fido vin savis; iru en pacon.","Kaj li diris al la virino: Via fido vin savis; iru en pacon."],[8,1,"Kaj post ne longe li vojiradis tra urboj kaj vilaĝoj, predikante kaj alportante la evangelion de la regno de Dio, kaj kun li la dek du,","Kaj post ne longe li vojiradis tra urboj kaj vilaĝoj, predikante kaj alportante la evangelion de la regno de Dio, kaj kun li la dek du,"],[8,2,"kaj iuj virinoj, kiuj estis resanigitaj je malbonaj spiritoj kaj malsanoj: Maria, kiu estis nomata Magdalena, el kiu eliris sep demonoj,","kaj iuj virinoj, kiuj estis resanigitaj je malbonaj spiritoj kaj malsanoj: Maria, kiu estis nomata Magdalena, el kiu eliris sep demonoj,"],[8,3,"kaj Joana, edzino de Ĥuzas, la ĉambelano de Herodo, kaj Susana, kaj multaj aliaj, kiuj faris al ili helpan servadon per sia havo.","kaj Joana, edzino de Ĥuzas, la ĉambelano de Herodo, kaj Susana, kaj multaj aliaj, kiuj faris al ili helpan servadon per sia havo."],[8,4,"Kaj kiam granda homamaso kolektiĝis, kaj homoj el ĉiu urbo venis al li, li diris per parabolo:","Kaj kiam granda homamaso kolektiĝis, kaj homoj el ĉiu urbo venis al li, li diris per parabolo:"],[8,5,"La semisto eliris, por semi sian semon; kaj dum li semis, iuj semoj falis apud la vojo kaj estis piedpremitaj, kaj la birdoj de la ĉielo formanĝis ilin.","La semisto eliris, por semi sian semon; kaj dum li semis, iuj semoj falis apud la vojo kaj estis piedpremitaj, kaj la birdoj de la ĉielo formanĝis ilin."],[8,6,"Kaj aliaj falis sur ŝtonan lokon, kaj kreskinte, velkis, ĉar ili ne havis malsekaĵon.","Kaj aliaj falis sur ŝtonan lokon, kaj kreskinte, velkis, ĉar ili ne havis malsekaĵon."],[8,7,"Kaj aliaj falis meze inter dornojn; kaj la dornoj kunkreskis, kaj sufokis ilin.","Kaj aliaj falis meze inter dornojn; kaj la dornoj kunkreskis, kaj sufokis ilin."],[8,8,"Kaj aliaj falis en la bonan teron, kaj kreskinte, produktis frukton centoble. Dirinte tion, li kriis: Kiu havas orelojn por aŭdi, tiu aŭdu.","Kaj aliaj falis en la bonan teron, kaj kreskinte, produktis frukton centoble. Dirinte tion, li kriis: Kiu havas orelojn por aŭdi, tiu aŭdu."],[8,9,"Kaj liaj disĉiploj demandis al li, kia estas ĉi tiu parabolo.","Kaj liaj disĉiploj demandis al li, kia estas ĉi tiu parabolo."],[8,10,"Kaj li diris: Al vi estas donite scii la misterojn de la regno de Dio; sed al la aliaj per paraboloj, por ke, vidante, ili ne rimarku, kaj aŭdante, ili ne komprenu.","Kaj li diris: Al vi estas donite scii la misterojn de la regno de Dio; sed al la aliaj per paraboloj, por ke, vidante, ili ne rimarku, kaj aŭdante, ili ne komprenu."],[8,11,"La parabolo estas jena: La semo estas la vorto de Dio.","La parabolo estas jena: La semo estas la vorto de Dio."],[8,12,"Kaj la falintaj apud la vojo estas tiuj, kiuj aŭdis; tiam venas la diablo, kaj forprenas la vorton el ilia koro, por ke ili ne kredu kaj ne estu savitaj.","Kaj la falintaj apud la vojo estas tiuj, kiuj aŭdis; tiam venas la diablo, kaj forprenas la vorton el ilia koro, por ke ili ne kredu kaj ne estu savitaj."],[8,13,"Kaj la falintaj sur la ŝtonan lokon estas tiuj, kiuj, aŭdinte, kun ĝojo akceptas la vorton; sed ili ne havas radikon, kaj kredas nur portempe, kaj en tempo de tento ili defalas.","Kaj la falintaj sur la ŝtonan lokon estas tiuj, kiuj, aŭdinte, kun ĝojo akceptas la vorton; sed ili ne havas radikon, kaj kredas nur portempe, kaj en tempo de tento ili defalas."],[8,14,"Kaj tio, kio falis inter dornojn, estas tiuj, kiuj aŭdis, kaj dum sia irado sufokiĝas per zorgoj kaj riĉo kaj plezuroj de la vivo, kaj ne perfektigas frukton.","Kaj tio, kio falis inter dornojn, estas tiuj, kiuj aŭdis, kaj dum sia irado sufokiĝas per zorgoj kaj riĉo kaj plezuroj de la vivo, kaj ne perfektigas frukton."],[8,15,"Kaj tio, kio falis en la bonan teron, estas tiuj, kiuj en bela kaj bona koro, aŭdinte la vorton, konservas ĝin, kaj kun pacienco donas frukton.","Kaj tio, kio falis en la bonan teron, estas tiuj, kiuj en bela kaj bona koro, aŭdinte la vorton, konservas ĝin, kaj kun pacienco donas frukton."],[8,16,"Kaj ekbruliginte lampon, oni ne kovras ĝin per vazo, aŭ forŝovas ĝin sub liton; sed metas ĝin sur lampingon, por ke la enirantoj povu vidi la lumon.","Kaj ekbruliginte lampon, oni ne kovras ĝin per vazo, aŭ forŝovas ĝin sub liton; sed metas ĝin sur lampingon, por ke la enirantoj povu vidi la lumon."],[8,17,"Ĉar estas kaŝita nenio, kio ne malkaŝiĝos; kaj ne estas io sekreta, kio ne koniĝos kaj klare elmontriĝos.","Ĉar estas kaŝita nenio, kio ne malkaŝiĝos; kaj ne estas io sekreta, kio ne koniĝos kaj klare elmontriĝos."],[8,18,"Atentu do, kiamaniere vi aŭdas; ĉar kiu ajn havas, al tiu estos donite; kaj kiu ajn ne havas, de tiu estos forprenita eĉ tio, kion li ŝajne havas.","Atentu do, kiamaniere vi aŭdas; ĉar kiu ajn havas, al tiu estos donite; kaj kiu ajn ne havas, de tiu estos forprenita eĉ tio, kion li ŝajne havas."],[8,19,"Kaj alvenis al li lia patrino kaj liaj fratoj, kaj ili ne povis lin atingi pro la homamaso.","Kaj alvenis al li lia patrino kaj liaj fratoj, kaj ili ne povis lin atingi pro la homamaso."],[8,20,"Kaj oni sciigis lin: Via patrino kaj viaj fratoj staras ekstere, kaj deziras vin vidi.","Kaj oni sciigis lin: Via patrino kaj viaj fratoj staras ekstere, kaj deziras vin vidi."],[8,21,"Sed respondante, li diris al ili: Mia patrino kaj miaj fratoj estas tiuj, kiuj aŭdas la vorton de Dio, kaj ĝin plenumas.","Sed respondante, li diris al ili: Mia patrino kaj miaj fratoj estas tiuj, kiuj aŭdas la vorton de Dio, kaj ĝin plenumas."],[8,22,"Kaj en unu el tiuj tagoj eniris en ŝipeton li kaj liaj disĉiploj; kaj li diris al ili: Ni transiru al la alia bordo de la lago; kaj ili surmariĝis.","Kaj en unu el tiuj tagoj eniris en ŝipeton li kaj liaj disĉiploj; kaj li diris al ili: Ni transiru al la alia bordo de la lago; kaj ili surmariĝis."],[8,23,"Sed dum ili veturis, li endormiĝis; kaj falis ventego sur la lagon; kaj ili tute pleniĝis de akvo, kaj estis en danĝero.","Sed dum ili veturis, li endormiĝis; kaj falis ventego sur la lagon; kaj ili tute pleniĝis de akvo, kaj estis en danĝero."],[8,24,"Kaj ili venis al li, kaj vekis lin, dirante: Estro, estro, ni pereas. Kaj li leviĝis, kaj admonis la venton kaj la furiozon de la akvo; kaj ili ĉesiĝis, kaj fariĝis sereno.","Kaj ili venis al li, kaj vekis lin, dirante: Estro, estro, ni pereas. Kaj li leviĝis, kaj admonis la venton kaj la furiozon de la akvo; kaj ili ĉesiĝis, kaj fariĝis sereno."],[8,25,"Kaj li diris al ili: Kie estas via fido? Kaj ili timis kaj miris, dirante unu al la alia: Kiu do estas ĉi tiu? ĉar li ordonas eĉ al la ventoj kaj al la akvo, kaj ili obeas al li.","Kaj li diris al ili: Kie estas via fido? Kaj ili timis kaj miris, dirante unu al la alia: Kiu do estas ĉi tiu? ĉar li ordonas eĉ al la ventoj kaj al la akvo, kaj ili obeas al li."],[8,26,"Kaj ili ŝipveturis al la lando de la Gerasenoj, kiu estas kontraŭ Galileo.","Kaj ili ŝipveturis al la lando de la Gerasenoj, kiu estas kontraŭ Galileo."],[8,27,"Kaj kiam li surbordiĝis, renkontis lin el la urbo viro, havanta demonojn; kaj jam de longe li ne portis vestojn, kaj loĝis ne en domo, sed en la tomboj.","Kaj kiam li surbordiĝis, renkontis lin el la urbo viro, havanta demonojn; kaj jam de longe li ne portis vestojn, kaj loĝis ne en domo, sed en la tomboj."],[8,28,"Kaj vidinte Jesuon, li ekkriis kaj falis antaŭ li, kaj laŭtvoĉe diris: Kio estas inter mi kaj vi, ho Jesuo, Filo de Dio Plejalta? mi petas vin, ne turmento min.","Kaj vidinte Jesuon, li ekkriis kaj falis antaŭ li, kaj laŭtvoĉe diris: Kio estas inter mi kaj vi, ho Jesuo, Filo de Dio Plejalta? mi petas vin, ne turmento min."],[8,29,"Ĉar li ordonis al la malpura spirito eliri el la homo. Ĉar ĝi ofte kaptis lin, kaj li estis sub gardantaro, kaj ligita per ĉenoj kaj katenoj; kaj disrompinte la ligilojn, li estis peladata de la demono en la dezertojn.","Ĉar li ordonis al la malpura spirito eliri el la homo. Ĉar ĝi ofte kaptis lin, kaj li estis sub gardantaro, kaj ligita per ĉenoj kaj katenoj; kaj disrompinte la ligilojn, li estis peladata de la demono en la dezertojn."],[8,30,"Kaj Jesuo demandis lin: Kia estas via nomo? Kaj li diris: Legio; ĉar multaj demonoj eniris en lin.","Kaj Jesuo demandis lin: Kia estas via nomo? Kaj li diris: Legio; ĉar multaj demonoj eniris en lin."],[8,31,"Kaj ili petegis lin, ke li ne ordonu al ili foriri en la abismon.","Kaj ili petegis lin, ke li ne ordonu al ili foriri en la abismon."],[8,32,"Kaj estis tie granda grego da porkoj, paŝtiĝantaj sur la monto; kaj ili petegis lin, ke li permesu al ili eniri en la porkojn. Kaj li tion permesis al ili.","Kaj estis tie granda grego da porkoj, paŝtiĝantaj sur la monto; kaj ili petegis lin, ke li permesu al ili eniri en la porkojn. Kaj li tion permesis al ili."],[8,33,"Kaj elirinte el la viro, la demonoj eniris en la porkojn; kaj la grego kuris de la krutaĵo en la lagon, kaj sufokiĝis.","Kaj elirinte el la viro, la demonoj eniris en la porkojn; kaj la grego kuris de la krutaĵo en la lagon, kaj sufokiĝis."],[8,34,"Kaj kiam iliaj paŝtistoj vidis la okazintaĵon, ili forkuris, kaj rakontis ĝin en la urbo kaj en la kamparo.","Kaj kiam iliaj paŝtistoj vidis la okazintaĵon, ili forkuris, kaj rakontis ĝin en la urbo kaj en la kamparo."],[8,35,"Kaj oni eliris por vidi, kio okazis; kaj ili venis al Jesuo, kaj trovis la viron, el kiu eliris la demonoj, sidanta, vestita kaj en sana prudento, ĉe la piedoj de Jesuo, kaj ili timis.","Kaj oni eliris por vidi, kio okazis; kaj ili venis al Jesuo, kaj trovis la viron, el kiu eliris la demonoj, sidanta, vestita kaj en sana prudento, ĉe la piedoj de Jesuo, kaj ili timis."],[8,36,"Kaj la vidintoj rakontis al ili, kiamaniere la demonhavinto saniĝis.","Kaj la vidintoj rakontis al ili, kiamaniere la demonhavinto saniĝis."],[8,37,"Kaj la tuta homamaso, el la ĉirkaŭaĵo de la Gerasenoj, petis lin foriri de ili; ĉar ili estis tenataj de granda timo; kaj li eniris en ŝipeton kaj returne veturis.","Kaj la tuta homamaso, el la ĉirkaŭaĵo de la Gerasenoj, petis lin foriri de ili; ĉar ili estis tenataj de granda timo; kaj li eniris en ŝipeton kaj returne veturis."],[8,38,"Sed la viro, el kiu eliris la demonoj, petis lin, ke li povu esti kun li; sed li forsendis lin, dirante:","Sed la viro, el kiu eliris la demonoj, petis lin, ke li povu esti kun li; sed li forsendis lin, dirante:"],[8,39,"Reiru al via domo, kaj rakontu ĉion, kion Dio faris por vi. Kaj li foriris, famigante tra la tuta urbo ĉion, kion Jesuo faris por li.","Reiru al via domo, kaj rakontu ĉion, kion Dio faris por vi. Kaj li foriris, famigante tra la tuta urbo ĉion, kion Jesuo faris por li."],[8,40,"Kaj kiam Jesuo revenis, la homamaso bonvenigis lin, ĉar ĉiuj atendis lin.","Kaj kiam Jesuo revenis, la homamaso bonvenigis lin, ĉar ĉiuj atendis lin."],[8,41,"Kaj jen venis viro, nomata Jairos, kaj li estis sinagogestro; kaj li sin ĵetis antaŭ la piedojn de Jesuo, kaj petegis lin, ke li venu en lian domon;","Kaj jen venis viro, nomata Jairos, kaj li estis sinagogestro; kaj li sin ĵetis antaŭ la piedojn de Jesuo, kaj petegis lin, ke li venu en lian domon;"],[8,42,"ĉar li havis unu solan filinon, proksimume dekdujaran, kaj ŝi estis mortanta. Kaj dum li iris, la homamaso ĉirkaŭpremis lin.","ĉar li havis unu solan filinon, proksimume dekdujaran, kaj ŝi estis mortanta. Kaj dum li iris, la homamaso ĉirkaŭpremis lin."],[8,43,"Kaj virino, kiu jam dek du jarojn havis sangofluon, kaj elspezis sian tutan havon por kuracistoj, kaj ne povis esti resanigita de iu,","Kaj virino, kiu jam dek du jarojn havis sangofluon, kaj elspezis sian tutan havon por kuracistoj, kaj ne povis esti resanigita de iu,"],[8,44,"venis malantaŭ lin, kaj tuŝis la randon de lia vestaĵo; kaj tuj ŝia sangofluo ĉesiĝis.","venis malantaŭ lin, kaj tuŝis la randon de lia vestaĵo; kaj tuj ŝia sangofluo ĉesiĝis."],[8,45,"Kaj Jesuo diris: Kiu min tuŝis? Kaj kiam ĉiuj neis, Petro diris: Estro, la homamaso ĉirkaŭas kaj premas vin.","Kaj Jesuo diris: Kiu min tuŝis? Kaj kiam ĉiuj neis, Petro diris: Estro, la homamaso ĉirkaŭas kaj premas vin."],[8,46,"Sed Jesuo diris: Iu min tuŝis; ĉar mi sentis, ke de mi eliris potenco.","Sed Jesuo diris: Iu min tuŝis; ĉar mi sentis, ke de mi eliris potenco."],[8,47,"Kaj kiam la virino ekvidis, ke ŝi ne estas kaŝita, ŝi venis tremanta, kaj, sin ĵetante antaŭ lin, sciigis antaŭ la tuta popolo, pro kia motivo ŝi tuŝis lin, kaj kiel ŝi estas tuj sanigita.","Kaj kiam la virino ekvidis, ke ŝi ne estas kaŝita, ŝi venis tremanta, kaj, sin ĵetante antaŭ lin, sciigis antaŭ la tuta popolo, pro kia motivo ŝi tuŝis lin, kaj kiel ŝi estas tuj sanigita."],[8,48,"Kaj li diris al ŝi: Filino, via fido vin savis; iru en pacon.","Kaj li diris al ŝi: Filino, via fido vin savis; iru en pacon."],[8,49,"Dum li ankoraŭ parolis, jen iu venis de la domo de la sinagogestro, dirante: Via filino jam mortis; ne ĝenu la instruiston.","Dum li ankoraŭ parolis, jen iu venis de la domo de la sinagogestro, dirante: Via filino jam mortis; ne ĝenu la instruiston."],[8,50,"Sed Jesuo, aŭdinte tion, respondis al li: Ne timu; nur kredu, kaj ŝi estos savita.","Sed Jesuo, aŭdinte tion, respondis al li: Ne timu; nur kredu, kaj ŝi estos savita."],[8,51,"Kaj kiam li venis al la domo, li permesis al neniu eniri kun li, krom Petro kaj Johano kaj Jakobo kaj la patro kaj la patrino de la knabino.","Kaj kiam li venis al la domo, li permesis al neniu eniri kun li, krom Petro kaj Johano kaj Jakobo kaj la patro kaj la patrino de la knabino."],[8,52,"Kaj ĉiuj ploris kaj ĝemis pro ŝi; sed li diris: Ne ploru; ĉar ŝi ne mortis, sed dormas.","Kaj ĉiuj ploris kaj ĝemis pro ŝi; sed li diris: Ne ploru; ĉar ŝi ne mortis, sed dormas."],[8,53,"Kaj ili mokridis lin, sciante, ke ŝi mortis.","Kaj ili mokridis lin, sciante, ke ŝi mortis."],[8,54,"Sed li, preninte ŝian manon, vokis ŝin, dirante: Knabino, leviĝu.","Sed li, preninte ŝian manon, vokis ŝin, dirante: Knabino, leviĝu."],[8,55,"Kaj ŝia spirito revenis, kaj ŝi tuj stariĝis; kaj li ordonis, ke oni donu al ŝi manĝi.","Kaj ŝia spirito revenis, kaj ŝi tuj stariĝis; kaj li ordonis, ke oni donu al ŝi manĝi."],[8,56,"Kaj ŝiaj gepatroj estis mirigitaj; sed li ordonis, ke ili diru al neniu tion, kio estis farita.","Kaj ŝiaj gepatroj estis mirigitaj; sed li ordonis, ke ili diru al neniu tion, kio estis farita."],[9,1,"Kaj li kunvokis la dek du, kaj donis al ili potencon kaj aŭtoritaton super ĉiuj demonoj, kaj por forigi malsanojn.","Kaj li kunvokis la dek du, kaj donis al ili potencon kaj aŭtoritaton super ĉiuj demonoj, kaj por forigi malsanojn."],[9,2,"Kaj li forsendis ilin, por prediki la regnon de Dio, kaj por sanigi la malsanulojn.","Kaj li forsendis ilin, por prediki la regnon de Dio, kaj por sanigi la malsanulojn."],[9,3,"Kaj li diris al ili: Portu nenion por la vojo — nek bastonon, nek saketon, nek panon, nek monon; kaj ne havu du tunikojn.","Kaj li diris al ili: Portu nenion por la vojo — nek bastonon, nek saketon, nek panon, nek monon; kaj ne havu du tunikojn."],[9,4,"Kaj en kiun ajn domon vi eniros, tie loĝu, kaj el tie ekvojaĝu.","Kaj en kiun ajn domon vi eniros, tie loĝu, kaj el tie ekvojaĝu."],[9,5,"Kaj se ie oni vin ne akceptos, tiam, forirante el tiu urbo, deskuu la polvon de viaj piedoj, por atesto kontraŭ ili.","Kaj se ie oni vin ne akceptos, tiam, forirante el tiu urbo, deskuu la polvon de viaj piedoj, por atesto kontraŭ ili."],[9,6,"Kaj ili, foririnte, trairis la vilaĝojn, ĉie predikante la evangelion kaj sanigante.","Kaj ili, foririnte, trairis la vilaĝojn, ĉie predikante la evangelion kaj sanigante."],[9,7,"Kaj la tetrarĥo Herodo aŭdis pri ĉio, kio fariĝis; kaj li embarasiĝis, ĉar iuj diris, ke Johano leviĝis el la mortintoj;","Kaj la tetrarĥo Herodo aŭdis pri ĉio, kio fariĝis; kaj li embarasiĝis, ĉar iuj diris, ke Johano leviĝis el la mortintoj;"],[9,8,"kaj aliaj, ke Elija aperis; kaj aliaj, ke unu el la antikvaj profetoj releviĝis.","kaj aliaj, ke Elija aperis; kaj aliaj, ke unu el la antikvaj profetoj releviĝis."],[9,9,"Kaj Herodo diris: Johanon mi senkapigis, sed kiu estas ĉi tiu, pri kiu mi aŭdas tiajn aferojn? Kaj li deziris vidi lin.","Kaj Herodo diris: Johanon mi senkapigis, sed kiu estas ĉi tiu, pri kiu mi aŭdas tiajn aferojn? Kaj li deziris vidi lin."],[9,10,"Kaj la apostoloj, reveninte, rakontis al li ĉion, kion ili faris. Kaj li kondukis ilin, kaj foriris aparte al urbo, nomata Betsaida.","Kaj la apostoloj, reveninte, rakontis al li ĉion, kion ili faris. Kaj li kondukis ilin, kaj foriris aparte al urbo, nomata Betsaida."],[9,11,"Sed la homamaso, eksciinte tion, sekvis lin; kaj li akceptis ilin, kaj parolis al ili pri la regno de Dio, kaj tiujn, kiuj bezonis kuracon, li resanigis.","Sed la homamaso, eksciinte tion, sekvis lin; kaj li akceptis ilin, kaj parolis al ili pri la regno de Dio, kaj tiujn, kiuj bezonis kuracon, li resanigis."],[9,12,"Kaj ekvesperiĝis; kaj la dek du, alveninte, diris al li: Forsendu la homamason, por ke ili iru en la ĉirkaŭajn vilaĝojn kaj kampojn, por trovi ripozejojn kaj nutraĵon; ĉar ĉi tie ni estas en dezerta loko.","Kaj ekvesperiĝis; kaj la dek du, alveninte, diris al li: Forsendu la homamason, por ke ili iru en la ĉirkaŭajn vilaĝojn kaj kampojn, por trovi ripozejojn kaj nutraĵon; ĉar ĉi tie ni estas en dezerta loko."],[9,13,"Sed li diris al ili: Vi donu al ili manĝi. Kaj ili diris: Ni havas ne pli ol kvin panojn kaj du fiŝojn, se ni ne irus kaj aĉetus manĝaĵon por ĉi tiu tuta homomulto.","Sed li diris al ili: Vi donu al ili manĝi. Kaj ili diris: Ni havas ne pli ol kvin panojn kaj du fiŝojn, se ni ne irus kaj aĉetus manĝaĵon por ĉi tiu tuta homomulto."],[9,14,"Ĉar ĉeestis proksimume kvin mil viroj. Kaj li diris al siaj disĉiploj: Sidigu ilin en aroj, po proksimume kvindek.","Ĉar ĉeestis proksimume kvin mil viroj. Kaj li diris al siaj disĉiploj: Sidigu ilin en aroj, po proksimume kvindek."],[9,15,"Kaj tion ili faris, kaj sidigis ĉiujn.","Kaj tion ili faris, kaj sidigis ĉiujn."],[9,16,"Kaj li prenis la kvin panojn kaj la du fiŝojn, kaj suprenrigardinte al la ĉielo, li ilin benis kaj dispecigis, kaj donis al la disĉiploj, por meti antaŭ la homamason.","Kaj li prenis la kvin panojn kaj la du fiŝojn, kaj suprenrigardinte al la ĉielo, li ilin benis kaj dispecigis, kaj donis al la disĉiploj, por meti antaŭ la homamason."],[9,17,"Kaj ili manĝis, kaj ĉiuj satiĝis; kaj oni kolektis da postrestintaj fragmentoj dek du korbojn.","Kaj ili manĝis, kaj ĉiuj satiĝis; kaj oni kolektis da postrestintaj fragmentoj dek du korbojn."],[9,18,"Kaj dum li preĝis en soleco, la disĉiploj estis kun li; kaj li demandis ilin, dirante: Kiu, diras la popolo, ke mi estas?","Kaj dum li preĝis en soleco, la disĉiploj estis kun li; kaj li demandis ilin, dirante: Kiu, diras la popolo, ke mi estas?"],[9,19,"Kaj ili responde diris: Laŭ iuj Johano, la Baptisto; sed laŭ aliaj: Elija; kaj laŭ aliaj, ke unu el la antikvaj profetoj releviĝis.","Kaj ili responde diris: Laŭ iuj Johano, la Baptisto; sed laŭ aliaj: Elija; kaj laŭ aliaj, ke unu el la antikvaj profetoj releviĝis."],[9,20,"Sed li diris al ili: Sed vi — kiu vi diras, ke mi estas? Kaj Petro responde diris: La Kristo de Dio.","Sed li diris al ili: Sed vi — kiu vi diras, ke mi estas? Kaj Petro responde diris: La Kristo de Dio."],[9,21,"Sed li per severa ordono admonis, ke ili diru ĉi tion al neniu;","Sed li per severa ordono admonis, ke ili diru ĉi tion al neniu;"],[9,22,"dirante: La Filo de homo devas multe suferi, kaj esti rifuzita de la pliaĝuloj kaj ĉefpastroj kaj skribistoj, kaj esti mortigita, kaj la trian tagon releviĝi.","dirante: La Filo de homo devas multe suferi, kaj esti rifuzita de la pliaĝuloj kaj ĉefpastroj kaj skribistoj, kaj esti mortigita, kaj la trian tagon releviĝi."],[9,23,"Kaj li diris al ĉiuj: Se iu volas veni post mi, li abnegaciu sin, kaj levu sian krucon ĉiutage, kaj sekvu min.","Kaj li diris al ĉiuj: Se iu volas veni post mi, li abnegaciu sin, kaj levu sian krucon ĉiutage, kaj sekvu min."],[9,24,"Ĉar kiu volos savi sian animon, tiu ĝin perdos; sed kiu perdos sian animon pro mi, tiu ĝin savos.","Ĉar kiu volos savi sian animon, tiu ĝin perdos; sed kiu perdos sian animon pro mi, tiu ĝin savos."],[9,25,"Ĉar kiel profitus homo, se li gajnus la tutan mondon kaj sin perdus aŭ pereigus?","Ĉar kiel profitus homo, se li gajnus la tutan mondon kaj sin perdus aŭ pereigus?"],[9,26,"Ĉar kiu hontos pri mi kaj pri miaj paroloj, pri tiu hontos la Filo de homo, kiam li venos en sia gloro, kaj la gloro de la Patro kaj de la sanktaj anĝeloj.","Ĉar kiu hontos pri mi kaj pri miaj paroloj, pri tiu hontos la Filo de homo, kiam li venos en sia gloro, kaj la gloro de la Patro kaj de la sanktaj anĝeloj."],[9,27,"Sed mi diras al vi certe: Inter la ĉi tie starantaj estas iuj, kiuj neniel gustumos morton, antaŭ ol ili vidos la regnon de Dio.","Sed mi diras al vi certe: Inter la ĉi tie starantaj estas iuj, kiuj neniel gustumos morton, antaŭ ol ili vidos la regnon de Dio."],[9,28,"Kaj pasis post tiuj diroj ĉirkaŭ ok tagoj, kaj li prenis kun si Petron kaj Johanon kaj Jakobon, kaj supreniris sur la monton, por preĝi.","Kaj pasis post tiuj diroj ĉirkaŭ ok tagoj, kaj li prenis kun si Petron kaj Johanon kaj Jakobon, kaj supreniris sur la monton, por preĝi."],[9,29,"Kaj dum li preĝis, la aspekto de lia vizaĝo aliiĝis, kaj lia vestaro fariĝis blanka kaj fulme brilanta.","Kaj dum li preĝis, la aspekto de lia vizaĝo aliiĝis, kaj lia vestaro fariĝis blanka kaj fulme brilanta."],[9,30,"Kaj jen interparolis kun li du viroj, kiuj estis Moseo kaj Elija,","Kaj jen interparolis kun li du viroj, kiuj estis Moseo kaj Elija,"],[9,31,"kiuj montriĝis en gloro, kaj parolis pri lia foriro, kiun li estis plenumonta en Jerusalem.","kiuj montriĝis en gloro, kaj parolis pri lia foriro, kiun li estis plenumonta en Jerusalem."],[9,32,"Sed Petro, kaj tiuj, kiuj estis kun li, estis subpremataj de dormo; sed vekiĝinte, ili vidis lian gloron, kaj la du virojn, kiuj staris kun li.","Sed Petro, kaj tiuj, kiuj estis kun li, estis subpremataj de dormo; sed vekiĝinte, ili vidis lian gloron, kaj la du virojn, kiuj staris kun li."],[9,33,"Kaj dum ili foriris de li, Petro diris al Jesuo: Estro, estas bone por ni esti ĉi tie; kaj ni faru tri laŭbojn: unu por vi, kaj unu por Moseo, kaj unu por Elija; li ne sciis, kion li diras.","Kaj dum ili foriris de li, Petro diris al Jesuo: Estro, estas bone por ni esti ĉi tie; kaj ni faru tri laŭbojn: unu por vi, kaj unu por Moseo, kaj unu por Elija; li ne sciis, kion li diras."],[9,34,"Kaj dum li tion diris, nubo venis kaj superombris ilin; kaj ili timis, kiam ili eniris en la nubon.","Kaj dum li tion diris, nubo venis kaj superombris ilin; kaj ili timis, kiam ili eniris en la nubon."],[9,35,"Kaj el la nubo venis voĉo, diranta: Ĉi tiu estas Mia Filo, Mia elektito; lin aŭskultu.","Kaj el la nubo venis voĉo, diranta: Ĉi tiu estas Mia Filo, Mia elektito; lin aŭskultu."],[9,36,"Kaj dum la voĉo ankoraŭ sonis, Jesuo troviĝis sola. Kaj ili silentis, kaj al neniu en tiuj tagoj rakontis ion, kion ili vidis.","Kaj dum la voĉo ankoraŭ sonis, Jesuo troviĝis sola. Kaj ili silentis, kaj al neniu en tiuj tagoj rakontis ion, kion ili vidis."],[9,37,"Kaj la sekvantan tagon, post kiam ili malsupreniris de la monto, granda homamaso renkontis lin.","Kaj la sekvantan tagon, post kiam ili malsupreniris de la monto, granda homamaso renkontis lin."],[9,38,"Kaj jen unu viro el la homamaso ekkriis, dirante: Majstro, mi petegas vin rigardi mian filon, ĉar li estas mia sola infano;","Kaj jen unu viro el la homamaso ekkriis, dirante: Majstro, mi petegas vin rigardi mian filon, ĉar li estas mia sola infano;"],[9,39,"kaj jen spirito kaptas lin, kaj subite li ekkrias, kaj ĝi konvulsiigas lin kun buŝa ŝaŭmo, kaj malfacile lasas lin, kontuzinte lin.","kaj jen spirito kaptas lin, kaj subite li ekkrias, kaj ĝi konvulsiigas lin kun buŝa ŝaŭmo, kaj malfacile lasas lin, kontuzinte lin."],[9,40,"Kaj mi petis viajn disĉiplojn, ke ili elpelu ĝin; sed ili ne povis.","Kaj mi petis viajn disĉiplojn, ke ili elpelu ĝin; sed ili ne povis."],[9,41,"Kaj Jesuo respondis kaj diris: Ho senfida kaj perversa generacio, ĝis kiam mi estos kun vi kaj vin toleros? venigu ĉi tien vian filon.","Kaj Jesuo respondis kaj diris: Ho senfida kaj perversa generacio, ĝis kiam mi estos kun vi kaj vin toleros? venigu ĉi tien vian filon."],[9,42,"Kaj dum li venis, la demono lin ĵetis sur la teron kaj lin konvulsiigis. Sed Jesuo severe admonis la malpuran spiriton, kaj sanigis la knabon kaj redonis lin al la patro.","Kaj dum li venis, la demono lin ĵetis sur la teron kaj lin konvulsiigis. Sed Jesuo severe admonis la malpuran spiriton, kaj sanigis la knabon kaj redonis lin al la patro."],[9,43,"Kaj ĉiuj miregis pro la majesto de Dio. Sed dum ĉiuj miris pri ĉio, kion li faris, li diris al siaj disĉiploj:","Kaj ĉiuj miregis pro la majesto de Dio. Sed dum ĉiuj miris pri ĉio, kion li faris, li diris al siaj disĉiploj:"],[9,44,"Penetrigu ĉi tiujn vortojn en viajn orelojn: ĉar la Filo de homo estos transdonita en la manojn de homoj.","Penetrigu ĉi tiujn vortojn en viajn orelojn: ĉar la Filo de homo estos transdonita en la manojn de homoj."],[9,45,"Sed ili ne komprenis tiun diron, kaj ĝi estis kaŝita for de ili, por ke ili ne sciu ĝian signifon; kaj ili timis demandi al li pri tiu diro.","Sed ili ne komprenis tiun diron, kaj ĝi estis kaŝita for de ili, por ke ili ne sciu ĝian signifon; kaj ili timis demandi al li pri tiu diro."],[9,46,"Kaj komenciĝis diskutado inter ili pri tio, kiu el ili estos la plej granda.","Kaj komenciĝis diskutado inter ili pri tio, kiu el ili estos la plej granda."],[9,47,"Sed Jesuo, vidinte la diskutadon de iliaj koroj, prenis infanon, kaj starigis lin apud si,","Sed Jesuo, vidinte la diskutadon de iliaj koroj, prenis infanon, kaj starigis lin apud si,"],[9,48,"kaj diris al ili: Kiu akceptos ĉi tiun infanon en mia nomo, tiu min akceptas; kaj kiu min akceptos, tiu akceptas Tiun, kiu min sendis; ĉar kiu estas plej malgranda inter vi ĉiuj, tiu estas granda.","kaj diris al ili: Kiu akceptos ĉi tiun infanon en mia nomo, tiu min akceptas; kaj kiu min akceptos, tiu akceptas Tiun, kiu min sendis; ĉar kiu estas plej malgranda inter vi ĉiuj, tiu estas granda."],[9,49,"Kaj Johano respondis kaj diris: Estro, ni vidis iun elpelantan demonojn en via nomo; kaj ni malpermesis lin, ĉar li ne sekvas kun ni.","Kaj Johano respondis kaj diris: Estro, ni vidis iun elpelantan demonojn en via nomo; kaj ni malpermesis lin, ĉar li ne sekvas kun ni."],[9,50,"Sed Jesuo diris al li: Ne malpermesu; ĉar tiu, kiu ne estas kontraŭ vi, estas por vi.","Sed Jesuo diris al li: Ne malpermesu; ĉar tiu, kiu ne estas kontraŭ vi, estas por vi."],[9,51,"Kaj kiam la tagoj maturiĝis por lia suprenakcepto, li firmigis sian vizaĝon, por iri al Jerusalem,","Kaj kiam la tagoj maturiĝis por lia suprenakcepto, li firmigis sian vizaĝon, por iri al Jerusalem,"],[9,52,"kaj sendis senditojn antaŭ sia vizaĝo; kaj ili iris, kaj eniris en vilaĝon de la Samarianoj, por pretigi por li.","kaj sendis senditojn antaŭ sia vizaĝo; kaj ili iris, kaj eniris en vilaĝon de la Samarianoj, por pretigi por li."],[9,53,"Kaj tiuj lin ne akceptis, ĉar lia vizaĝo estis direktata al Jerusalem.","Kaj tiuj lin ne akceptis, ĉar lia vizaĝo estis direktata al Jerusalem."],[9,54,"Kaj liaj disĉiploj Jakobo kaj Johano, tion vidinte, diris: Sinjoro, ĉu vi volas, ke ni ordonu fajron malsuprenveni el la ĉielo kaj ekstermi ilin?","Kaj liaj disĉiploj Jakobo kaj Johano, tion vidinte, diris: Sinjoro, ĉu vi volas, ke ni ordonu fajron malsuprenveni el la ĉielo kaj ekstermi ilin?"],[9,55,"Sed li sin turnis kaj admonis ilin; kaj li diris: Vi mem ne scias, laŭ kia spirito vi estas.","Sed li sin turnis kaj admonis ilin; kaj li diris: Vi mem ne scias, laŭ kia spirito vi estas."],[9,56,"Ĉar la Filo de homo venis, ne por pereigi animojn de homoj, sed por savi. Kaj ili iris en alian vilaĝon.","Ĉar la Filo de homo venis, ne por pereigi animojn de homoj, sed por savi. Kaj ili iris en alian vilaĝon."],[9,57,"Kaj dum ili vojaĝis, sur la vojo iu diris al li: Mi vin sekvos, kien ajn vi iros.","Kaj dum ili vojaĝis, sur la vojo iu diris al li: Mi vin sekvos, kien ajn vi iros."],[9,58,"Kaj Jesuo diris al li: La vulpoj havas kavojn, kaj la birdoj de la ĉielo havas ripozejojn; sed la Filo de homo ne havas, kie kuŝigi sian kapon.","Kaj Jesuo diris al li: La vulpoj havas kavojn, kaj la birdoj de la ĉielo havas ripozejojn; sed la Filo de homo ne havas, kie kuŝigi sian kapon."],[9,59,"Kaj li diris al alia: Sekvu min. Sed li diris: Sinjoro, permesu al mi unue iri kaj enterigi mian patron.","Kaj li diris al alia: Sekvu min. Sed li diris: Sinjoro, permesu al mi unue iri kaj enterigi mian patron."],[9,60,"Sed li diris al li: Lasu la mortintojn enterigi siajn mortintojn; sed vi iru kaj proklamu la regnon de Dio.","Sed li diris al li: Lasu la mortintojn enterigi siajn mortintojn; sed vi iru kaj proklamu la regnon de Dio."],[9,61,"Kaj ankoraŭ alia diris: Mi vin sekvos, Sinjoro; sed unue permesu al mi adiaŭi tiujn, kiuj estas en mia domo.","Kaj ankoraŭ alia diris: Mi vin sekvos, Sinjoro; sed unue permesu al mi adiaŭi tiujn, kiuj estas en mia domo."],[9,62,"Sed Jesuo diris al li: Neniu, metinte sian manon al la plugilo kaj rigardante malantaŭen, taŭgas por la regno de Dio.","Sed Jesuo diris al li: Neniu, metinte sian manon al la plugilo kaj rigardante malantaŭen, taŭgas por la regno de Dio."],[10,1,"Kaj post tio la Sinjoro elektis sepdek aliajn, kaj ilin forsendis duope antaŭ sia vizaĝo en ĉiun urbon kaj ĉiun lokon, kien li mem estis venonta.","Kaj post tio la Sinjoro elektis sepdek aliajn, kaj ilin forsendis duope antaŭ sia vizaĝo en ĉiun urbon kaj ĉiun lokon, kien li mem estis venonta."],[10,2,"Kaj li diris al ili: La rikolto estas granda, sed la laborantoj estas malmultaj; petu do la Estron de la rikolto, ke Li sendu laborantojn en Sian rikolton.","Kaj li diris al ili: La rikolto estas granda, sed la laborantoj estas malmultaj; petu do la Estron de la rikolto, ke Li sendu laborantojn en Sian rikolton."],[10,3,"Iru; jen mi sendas vin kiel ŝafidojn meze de lupoj.","Iru; jen mi sendas vin kiel ŝafidojn meze de lupoj."],[10,4,"Ne portu monujon, nek saketon, nek ŝuojn; kaj salutu neniun sur la vojo.","Ne portu monujon, nek saketon, nek ŝuojn; kaj salutu neniun sur la vojo."],[10,5,"Kaj en kiun ajn domon vi eniros, unue diru: Paco al ĉi tiu domo.","Kaj en kiun ajn domon vi eniros, unue diru: Paco al ĉi tiu domo."],[10,6,"Kaj se tie estos filo de paco, via paco restos sur li; sed se ne, ĝi revenos al vi.","Kaj se tie estos filo de paco, via paco restos sur li; sed se ne, ĝi revenos al vi."],[10,7,"Kaj en tiu sama domo restu, manĝante kaj trinkante tion, kion ili havas; ĉar la laboranto meritas sian salajron. Ne transiru de domo en domon.","Kaj en tiu sama domo restu, manĝante kaj trinkante tion, kion ili havas; ĉar la laboranto meritas sian salajron. Ne transiru de domo en domon."],[10,8,"Kaj en kiun ajn urbon vi eniros, kaj oni vin akceptos, manĝu tion, kion oni metos antaŭ vin;","Kaj en kiun ajn urbon vi eniros, kaj oni vin akceptos, manĝu tion, kion oni metos antaŭ vin;"],[10,9,"kaj sanigu la tieajn malsanulojn, kaj diru al ili: La regno de Dio alproksimiĝis al vi.","kaj sanigu la tieajn malsanulojn, kaj diru al ili: La regno de Dio alproksimiĝis al vi."],[10,10,"Sed en kiun ajn urbon vi eniros, kaj oni ne akceptos vin, eliru sur ĝiajn stratojn, kaj diru:","Sed en kiun ajn urbon vi eniros, kaj oni ne akceptos vin, eliru sur ĝiajn stratojn, kaj diru:"],[10,11,"Eĉ la polvon de via urbo, kiu sin tenas al niaj piedoj, ni deviŝas kontraŭ vin; tamen sciu, ke la regno de Dio alproksimiĝis al vi.","Eĉ la polvon de via urbo, kiu sin tenas al niaj piedoj, ni deviŝas kontraŭ vin; tamen sciu, ke la regno de Dio alproksimiĝis al vi."],[10,12,"Mi diras al vi: Estos pli elporteble en tiu tago por Sodom, ol por tiu urbo.","Mi diras al vi: Estos pli elporteble en tiu tago por Sodom, ol por tiu urbo."],[10,13,"Ve al vi, Ĥorazin! ve al vi, Betsaida! ĉar se en Tiro kaj Cidon estus faritaj tiuj potencaj faroj, kiuj fariĝis en vi, ili jam antaŭ longe pentus, sidante en sakaĵo kaj cindro.","Ve al vi, Ĥorazin! ve al vi, Betsaida! ĉar se en Tiro kaj Cidon estus faritaj tiuj potencaj faroj, kiuj fariĝis en vi, ili jam antaŭ longe pentus, sidante en sakaĵo kaj cindro."],[10,14,"Tamen estos pli elporteble por Tiro kaj Cidon en la juĝado, ol por vi.","Tamen estos pli elporteble por Tiro kaj Cidon en la juĝado, ol por vi."],[10,15,"Kaj vi, Kapernaum, ĉu vi estos altigita ĝis la ĉielo? vi ja malsupreniros ĝis Hades.","Kaj vi, Kapernaum, ĉu vi estos altigita ĝis la ĉielo? vi ja malsupreniros ĝis Hades."],[10,16,"Kiu vin aŭskultas, tiu min aŭskultas; kiu vin malŝatas, tiu min malŝatas; kaj kiu min malŝatas, tiu malŝatas Tiun, kiu min sendis.","Kiu vin aŭskultas, tiu min aŭskultas; kiu vin malŝatas, tiu min malŝatas; kaj kiu min malŝatas, tiu malŝatas Tiun, kiu min sendis."],[10,17,"Kaj la sepdek revenis kun ĝojo, dirante: Sinjoro, eĉ la demonoj submetiĝas al ni per via nomo.","Kaj la sepdek revenis kun ĝojo, dirante: Sinjoro, eĉ la demonoj submetiĝas al ni per via nomo."],[10,18,"Kaj li diris al ili: Mi vidis Satanon falanta de la ĉielo, kiel fulmo.","Kaj li diris al ili: Mi vidis Satanon falanta de la ĉielo, kiel fulmo."],[10,19,"Jen mi donis al vi aŭtoritaton piedpaŝi sur serpentoj kaj skorpioj, kaj sur la tuta potenco de la malamiko; kaj nenio iel vin difektos.","Jen mi donis al vi aŭtoritaton piedpaŝi sur serpentoj kaj skorpioj, kaj sur la tuta potenco de la malamiko; kaj nenio iel vin difektos."],[10,20,"Tamen ne ĝoju pri tio, ke la spiritoj submetiĝis al vi; sed ĝoju, ke viaj nomoj estas skribitaj en la ĉielo.","Tamen ne ĝoju pri tio, ke la spiritoj submetiĝis al vi; sed ĝoju, ke viaj nomoj estas skribitaj en la ĉielo."],[10,21,"En tiu sama horo li ĝojis en la Sankta Spirito, kaj diris: Mi Vin gloras, ho Patro, Estro de la ĉielo kaj la tero, ke Vi kaŝis ĉi tion for de saĝuloj kaj prudentuloj, kaj malkaŝis al infanetoj; jes, Patro, ĉar al Vi tio bone plaĉis.","En tiu sama horo li ĝojis en la Sankta Spirito, kaj diris: Mi Vin gloras, ho Patro, Estro de la ĉielo kaj la tero, ke Vi kaŝis ĉi tion for de saĝuloj kaj prudentuloj, kaj malkaŝis al infanetoj; jes, Patro, ĉar al Vi tio bone plaĉis."],[10,22,"Ĉio estas transdonita al mi de mia Patro; kaj neniu scias, kiu estas la Filo, krom la Patro; nek kiu estas la Patro, krom la Filo, kaj tiu, al kiu la Filo volas malkaŝi Lin.","Ĉio estas transdonita al mi de mia Patro; kaj neniu scias, kiu estas la Filo, krom la Patro; nek kiu estas la Patro, krom la Filo, kaj tiu, al kiu la Filo volas malkaŝi Lin."],[10,23,"Kaj sin turninte al la disĉiploj, li flanke diris: Feliĉaj estas la okuloj, kiuj vidas tion, kion vi vidas;","Kaj sin turninte al la disĉiploj, li flanke diris: Feliĉaj estas la okuloj, kiuj vidas tion, kion vi vidas;"],[10,24,"ĉar mi diras al vi, ke multaj profetoj kaj reĝoj deziris vidi tion, kion vi vidas, kaj ili ne vidis; kaj aŭdi tion, kion vi aŭdas, kaj ili ne aŭdis.","ĉar mi diras al vi, ke multaj profetoj kaj reĝoj deziris vidi tion, kion vi vidas, kaj ili ne vidis; kaj aŭdi tion, kion vi aŭdas, kaj ili ne aŭdis."],[10,25,"Kaj jen unu leĝisto stariĝis, kaj tentis lin, dirante: Majstro, kion mi faru, por heredi eternan vivon?","Kaj jen unu leĝisto stariĝis, kaj tentis lin, dirante: Majstro, kion mi faru, por heredi eternan vivon?"],[10,26,"Kaj li diris al li: Kio estas skribita en la leĝo? kiel vi legas?","Kaj li diris al li: Kio estas skribita en la leĝo? kiel vi legas?"],[10,27,"Kaj li responde diris: Amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta forto kaj per via tuta menso, kaj vian proksimulon kiel vin mem.","Kaj li responde diris: Amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta forto kaj per via tuta menso, kaj vian proksimulon kiel vin mem."],[10,28,"Kaj li diris al li: Vi prave respondis; tion faru, kaj vi vivos.","Kaj li diris al li: Vi prave respondis; tion faru, kaj vi vivos."],[10,29,"Sed li, dezirante pravigi sin, diris al Jesuo: Kaj kiu estas mia proksimulo?","Sed li, dezirante pravigi sin, diris al Jesuo: Kaj kiu estas mia proksimulo?"],[10,30,"Jesuo respondis kaj diris: Unu homo malsupreniris de Jerusalem al Jeriĥo; kaj li falis en la manojn de rabistoj, kiuj lin senvestigis kaj batis, kaj foriris, lasante lin duone senviva.","Jesuo respondis kaj diris: Unu homo malsupreniris de Jerusalem al Jeriĥo; kaj li falis en la manojn de rabistoj, kiuj lin senvestigis kaj batis, kaj foriris, lasante lin duone senviva."],[10,31,"Kaj laŭ okazo unu pastro malsupreniris la saman vojon; kaj lin vidinte, li preterpasis aliflanke.","Kaj laŭ okazo unu pastro malsupreniris la saman vojon; kaj lin vidinte, li preterpasis aliflanke."],[10,32,"Kaj tiel same unu Levido, veninte al la loko kaj lin vidinte, preterpasis aliflanke.","Kaj tiel same unu Levido, veninte al la loko kaj lin vidinte, preterpasis aliflanke."],[10,33,"Sed unu Samariano, vojaĝante, alvenis tien, kie li estis, kaj lin ekvidinte, li kortuŝiĝis,","Sed unu Samariano, vojaĝante, alvenis tien, kie li estis, kaj lin ekvidinte, li kortuŝiĝis,"],[10,34,"kaj alproksimiĝis, kaj bandaĝis liajn vundojn, kaj surverŝis oleon kaj vinon; kaj li metis lin sur sian beston, kaj kondukis lin al gastejo, kaj zorgis pri li.","kaj alproksimiĝis, kaj bandaĝis liajn vundojn, kaj surverŝis oleon kaj vinon; kaj li metis lin sur sian beston, kaj kondukis lin al gastejo, kaj zorgis pri li."],[10,35,"Kaj la morgaŭan tagon li elprenis du denarojn kaj donis ilin al la gastejestro, kaj diris: Zorgu pri li, kaj kion pli vi elspezos, mi tion repagos al vi, kiam mi revenos.","Kaj la morgaŭan tagon li elprenis du denarojn kaj donis ilin al la gastejestro, kaj diris: Zorgu pri li, kaj kion pli vi elspezos, mi tion repagos al vi, kiam mi revenos."],[10,36,"Kiu el tiuj tri, laŭ via opinio, sin montris proksimulo de tiu, kiu falis en la manojn de la rabistoj?","Kiu el tiuj tri, laŭ via opinio, sin montris proksimulo de tiu, kiu falis en la manojn de la rabistoj?"],[10,37,"Kaj li diris: Tiu, kiu faris al li kompaton. Kaj Jesuo diris al li: Iru vi, kaj faru tion saman.","Kaj li diris: Tiu, kiu faris al li kompaton. Kaj Jesuo diris al li: Iru vi, kaj faru tion saman."],[10,38,"Kaj dum ili vojaĝis, li eniris en unu vilaĝon; kaj virino, nomata Marta, akceptis lin en sian domon.","Kaj dum ili vojaĝis, li eniris en unu vilaĝon; kaj virino, nomata Marta, akceptis lin en sian domon."],[10,39,"Kaj ŝi havis fratinon, nomatan Maria, kaj ĉi tiu sidis apud la piedoj de la Sinjoro, kaj aŭskultis lian parolon.","Kaj ŝi havis fratinon, nomatan Maria, kaj ĉi tiu sidis apud la piedoj de la Sinjoro, kaj aŭskultis lian parolon."],[10,40,"Sed Marta estis distrata pro multo da servado; kaj ŝi alproksimiĝis, kaj diris: Sinjoro, ĉu vi ne zorgas pri tio, ke mia fratino lasis al mi servi sola? diru do al ŝi, ke ŝi min helpu.","Sed Marta estis distrata pro multo da servado; kaj ŝi alproksimiĝis, kaj diris: Sinjoro, ĉu vi ne zorgas pri tio, ke mia fratino lasis al mi servi sola? diru do al ŝi, ke ŝi min helpu."],[10,41,"Sed la Sinjoro respondis kaj diris al ŝi: Marta, Marta, vi zorgas kaj klopodadas pri multaj aferoj;","Sed la Sinjoro respondis kaj diris al ŝi: Marta, Marta, vi zorgas kaj klopodadas pri multaj aferoj;"],[10,42,"sed unu afero estas necesa; kaj Maria elektis la bonan parton, kiu ne estos prenita for de ŝi.","sed unu afero estas necesa; kaj Maria elektis la bonan parton, kiu ne estos prenita for de ŝi."],[11,1,"Kaj li preĝis en iu loko; kaj kiam li ĉesis preĝi, unu el liaj disĉiploj diris al li: Sinjoro, instruu nin preĝi, kiel ankaŭ Johano instruis siajn disĉiplojn.","Kaj li preĝis en iu loko; kaj kiam li ĉesis preĝi, unu el liaj disĉiploj diris al li: Sinjoro, instruu nin preĝi, kiel ankaŭ Johano instruis siajn disĉiplojn."],[11,2,"Kaj li diris al ili: Kiam vi preĝas, diru: Patro, Estu sanktigita Via nomo. Venu Via regno.","Kaj li diris al ili: Kiam vi preĝas, diru: Patro, Estu sanktigita Via nomo. Venu Via regno."],[11,3,"Donu al ni tagon post tago nian ĉiutagan panon.","Donu al ni tagon post tago nian ĉiutagan panon."],[11,4,"Kaj pardonu al ni niajn pekojn, ĉar ni ankaŭ pardonas al ĉiu, kiu ŝuldas al ni. Kaj ne konduku nin en tenton.","Kaj pardonu al ni niajn pekojn, ĉar ni ankaŭ pardonas al ĉiu, kiu ŝuldas al ni. Kaj ne konduku nin en tenton."],[11,5,"Kaj li diris al ili: Kiu el vi havos amikon, kaj iros al li noktomeze, kaj diros al li: Amiko, pruntu al mi tri panojn;","Kaj li diris al ili: Kiu el vi havos amikon, kaj iros al li noktomeze, kaj diros al li: Amiko, pruntu al mi tri panojn;"],[11,6,"ĉar amiko mia venis al mi post vojaĝo, kaj mi ne havas, kion meti antaŭ lin;","ĉar amiko mia venis al mi post vojaĝo, kaj mi ne havas, kion meti antaŭ lin;"],[11,7,"kaj tiu de interne respondos kaj diros: Ne ĝenu min; la pordo estas jam fermita, kaj miaj infanoj kun mi estas en lito; mi ne povas min levi kaj doni al vi?","kaj tiu de interne respondos kaj diros: Ne ĝenu min; la pordo estas jam fermita, kaj miaj infanoj kun mi estas en lito; mi ne povas min levi kaj doni al vi?"],[11,8,"Mi diras al vi: Kvankam li ne volos pro sia amikeco al li leviĝi kaj doni al li, tamen, pro ĉi ties persisteco li leviĝos kaj donos al li tiom, kiom li bezonas.","Mi diras al vi: Kvankam li ne volos pro sia amikeco al li leviĝi kaj doni al li, tamen, pro ĉi ties persisteco li leviĝos kaj donos al li tiom, kiom li bezonas."],[11,9,"Kaj mi diras al vi: Petu, kaj al vi estos donite; serĉu, kaj vi trovos; frapu, kaj al vi estos malfermite.","Kaj mi diras al vi: Petu, kaj al vi estos donite; serĉu, kaj vi trovos; frapu, kaj al vi estos malfermite."],[11,10,"Ĉar ĉiu petanto ricevas; kaj la serĉanto trovas; kaj al la frapanto estos malfermite.","Ĉar ĉiu petanto ricevas; kaj la serĉanto trovas; kaj al la frapanto estos malfermite."],[11,11,"Kaj de kiu el vi, kiu estas patro, filo petos panon, kaj li donos al li ŝtonon? aŭ se li petas fiŝon, ĉu li anstataŭ fiŝo donos al li serpenton?","Kaj de kiu el vi, kiu estas patro, filo petos panon, kaj li donos al li ŝtonon? aŭ se li petas fiŝon, ĉu li anstataŭ fiŝo donos al li serpenton?"],[11,12,"Aŭ se li petos ovon, ĉu li donos al li skorpion?","Aŭ se li petos ovon, ĉu li donos al li skorpion?"],[11,13,"Se vi do, estante malbonaj, scias doni bonajn donacojn al viaj infanoj, des pli via Patro ĉiela donos la Sanktan Spiriton al tiuj, kiuj petos al Li.","Se vi do, estante malbonaj, scias doni bonajn donacojn al viaj infanoj, des pli via Patro ĉiela donos la Sanktan Spiriton al tiuj, kiuj petos al Li."],[11,14,"Kaj li estis elpelanta demonon, kiu estis muta. Kaj kiam la demono eliris, la mutulo parolis; kaj la homamaso miregis.","Kaj li estis elpelanta demonon, kiu estis muta. Kaj kiam la demono eliris, la mutulo parolis; kaj la homamaso miregis."],[11,15,"Sed iuj el ili diris: Per Baal-Zebub, la estro de la demonoj, li elpelas demonojn.","Sed iuj el ili diris: Per Baal-Zebub, la estro de la demonoj, li elpelas demonojn."],[11,16,"Kaj aliaj, tentante lin, postulis de li signon el la ĉielo.","Kaj aliaj, tentante lin, postulis de li signon el la ĉielo."],[11,17,"Sed li, sciante iliajn pensojn, diris al ili: Ĉiu regno, dividita kontraŭ si, dezertiĝas; kaj domo, dividita kontraŭ domo, falas.","Sed li, sciante iliajn pensojn, diris al ili: Ĉiu regno, dividita kontraŭ si, dezertiĝas; kaj domo, dividita kontraŭ domo, falas."],[11,18,"Kaj se ankaŭ Satano dividiĝas kontraŭ si, kiel staros lia regno? ĉar vi diras, ke per Baal-Zebub mi elpelas demonojn.","Kaj se ankaŭ Satano dividiĝas kontraŭ si, kiel staros lia regno? ĉar vi diras, ke per Baal-Zebub mi elpelas demonojn."],[11,19,"Kaj se per Baal-Zebub mi elpelas demonojn, per kiu viaj filoj ilin elpelas? tial ili estos viaj juĝantoj.","Kaj se per Baal-Zebub mi elpelas demonojn, per kiu viaj filoj ilin elpelas? tial ili estos viaj juĝantoj."],[11,20,"Sed se per la fingro de Dio mi elpelas demonojn, tiam la regno de Dio jam venis sur vin.","Sed se per la fingro de Dio mi elpelas demonojn, tiam la regno de Dio jam venis sur vin."],[11,21,"Kiam fortulo plene armita gardas sian palacon, en paco estas liaj posedaĵoj;","Kiam fortulo plene armita gardas sian palacon, en paco estas liaj posedaĵoj;"],[11,22,"sed kiam venas iu pli forta ol li kaj venkos lin, li forprenas lian plenarmilaron, al kiu li fidis, kaj disdonas lian havon.","sed kiam venas iu pli forta ol li kaj venkos lin, li forprenas lian plenarmilaron, al kiu li fidis, kaj disdonas lian havon."],[11,23,"Kiu ne estas kun mi, tiu estas kontraŭ mi; kaj kiu ne kolektas kun mi, tiu disĵetas.","Kiu ne estas kun mi, tiu estas kontraŭ mi; kaj kiu ne kolektas kun mi, tiu disĵetas."],[11,24,"Kiam la malpura spirito eliris el homo, ĝi trairas tra senakvaj lokoj, serĉante ripozon; kaj ne trovante ĝin, diras: Mi reiros al mia domo, el kie mi eliris.","Kiam la malpura spirito eliris el homo, ĝi trairas tra senakvaj lokoj, serĉante ripozon; kaj ne trovante ĝin, diras: Mi reiros al mia domo, el kie mi eliris."],[11,25,"Kaj alveninte, ĝi trovas ĝin balaita kaj ornamita.","Kaj alveninte, ĝi trovas ĝin balaita kaj ornamita."],[11,26,"Tiam ĝi iras kaj alprenas al si sep aliajn spiritojn pli malbonajn ol ĝi mem, kaj ili, enirinte, loĝas tie; kaj la fina stato de tiu homo fariĝas pli malbona, ol la unua.","Tiam ĝi iras kaj alprenas al si sep aliajn spiritojn pli malbonajn ol ĝi mem, kaj ili, enirinte, loĝas tie; kaj la fina stato de tiu homo fariĝas pli malbona, ol la unua."],[11,27,"Kaj dum li ĉi tion parolis, unu virino el la homamaso levis sian voĉon, kaj diris al li: Feliĉaj estas la ventro, kiu naskis vin, kaj la mamoj, kiujn vi suĉis.","Kaj dum li ĉi tion parolis, unu virino el la homamaso levis sian voĉon, kaj diris al li: Feliĉaj estas la ventro, kiu naskis vin, kaj la mamoj, kiujn vi suĉis."],[11,28,"Sed li diris: Sed pli ĝuste, feliĉaj estas tiuj, kiuj aŭdas la vorton de Dio kaj observas ĝin.","Sed li diris: Sed pli ĝuste, feliĉaj estas tiuj, kiuj aŭdas la vorton de Dio kaj observas ĝin."],[11,29,"Kaj kiam la homamaso kolektiĝis al li, li ekparolis, dirante: Ĉi tiu generacio estas malbona generacio; ĝi serĉas signon, kaj signo ne estos donita al ĝi, krom la signo de Jona.","Kaj kiam la homamaso kolektiĝis al li, li ekparolis, dirante: Ĉi tiu generacio estas malbona generacio; ĝi serĉas signon, kaj signo ne estos donita al ĝi, krom la signo de Jona."],[11,30,"Ĉar kiel Jona estis signo por la Nineveanoj, tiel ankaŭ estos la Filo de homo por ĉi tiu generacio.","Ĉar kiel Jona estis signo por la Nineveanoj, tiel ankaŭ estos la Filo de homo por ĉi tiu generacio."],[11,31,"La reĝino de la sudo leviĝos en la juĝado kun la viroj de ĉi tiu generacio, kaj ilin kondamnos; ĉar ŝi venis el la finoj de la tero, por aŭskulti la saĝon de Salomono; kaj jen iu pli granda ol Salomono estas ĉi tie.","La reĝino de la sudo leviĝos en la juĝado kun la viroj de ĉi tiu generacio, kaj ilin kondamnos; ĉar ŝi venis el la finoj de la tero, por aŭskulti la saĝon de Salomono; kaj jen iu pli granda ol Salomono estas ĉi tie."],[11,32,"Viroj Nineveanoj staros en la juĝado kun ĉi tiu generacio, kaj ĝin kondamnos; ĉar ili pentis pro la predikado de Jona; kaj jen iu pli granda ol Jona estas ĉi tie.","Viroj Nineveanoj staros en la juĝado kun ĉi tiu generacio, kaj ĝin kondamnos; ĉar ili pentis pro la predikado de Jona; kaj jen iu pli granda ol Jona estas ĉi tie."],[11,33,"Kiam oni ekbruligis lampon, oni metas ĝin ne en kaŝejon, nek sub grenmezurilon, sed sur la lampingon, por ke la enirantoj povu vidi la lumon.","Kiam oni ekbruligis lampon, oni metas ĝin ne en kaŝejon, nek sub grenmezurilon, sed sur la lampingon, por ke la enirantoj povu vidi la lumon."],[11,34,"La lampo de via korpo estas via okulo; kiam via okulo estas sendifekta, via tuta korpo estas luma; sed kiam ĝi estas malbona, via korpo ankaŭ estas malluma.","La lampo de via korpo estas via okulo; kiam via okulo estas sendifekta, via tuta korpo estas luma; sed kiam ĝi estas malbona, via korpo ankaŭ estas malluma."],[11,35,"Tial viglu, ke la lumo, kiu estas en vi, ne estu mallumo.","Tial viglu, ke la lumo, kiu estas en vi, ne estu mallumo."],[11,36,"Tial, se via tuta korpo estas luma, havante nenian malluman parton, ĝi estos tute lumplena, kiel kiam la lampo lumas al vi per sia brilo.","Tial, se via tuta korpo estas luma, havante nenian malluman parton, ĝi estos tute lumplena, kiel kiam la lampo lumas al vi per sia brilo."],[11,37,"Kaj dum li parolis, unu Fariseo invitis lin matenmanĝi kun li; kaj li eniris kaj sidiĝis.","Kaj dum li parolis, unu Fariseo invitis lin matenmanĝi kun li; kaj li eniris kaj sidiĝis."],[11,38,"Kaj la Fariseo, ekvidinte, miris, ke li ne lavis sin antaŭ la matenmanĝo.","Kaj la Fariseo, ekvidinte, miris, ke li ne lavis sin antaŭ la matenmanĝo."],[11,39,"Kaj la Sinjoro diris al li: Vi Fariseoj purigas la eksteron de kaliko kaj plado, sed via interno estas plena de rabado kaj malvirto.","Kaj la Sinjoro diris al li: Vi Fariseoj purigas la eksteron de kaliko kaj plado, sed via interno estas plena de rabado kaj malvirto."],[11,40,"Malsaĝuloj! ĉu Tiu, kiu faris la eksteron, ne faris ankaŭ la internon?","Malsaĝuloj! ĉu Tiu, kiu faris la eksteron, ne faris ankaŭ la internon?"],[11,41,"Tamen, uzu por almozo la internaĵojn, kaj jen ĉio estas al vi pura.","Tamen, uzu por almozo la internaĵojn, kaj jen ĉio estas al vi pura."],[11,42,"Sed ve al vi, Fariseoj! ĉar vi pagas dekonaĵojn de mento kaj ruto kaj ĉiu vegetaĵo, kaj preterlasas juĝon kaj amon al Dio; ĉi tion vi devus fari, kaj tion ne preterlasi.","Sed ve al vi, Fariseoj! ĉar vi pagas dekonaĵojn de mento kaj ruto kaj ĉiu vegetaĵo, kaj preterlasas juĝon kaj amon al Dio; ĉi tion vi devus fari, kaj tion ne preterlasi."],[11,43,"Ve al vi, Fariseoj! ĉar vi amas la ĉefseĝojn en la sinagogoj, kaj la salutojn sur la placoj.","Ve al vi, Fariseoj! ĉar vi amas la ĉefseĝojn en la sinagogoj, kaj la salutojn sur la placoj."],[11,44,"Ve al vi! ĉar vi similas tombojn ne vidatajn; kaj la homoj, kiuj iras super ili, ne scias.","Ve al vi! ĉar vi similas tombojn ne vidatajn; kaj la homoj, kiuj iras super ili, ne scias."],[11,45,"Kaj unu el la leĝistoj responde diris al li: Majstro, dirante ĉi tion, vi ankaŭ nin riproĉas.","Kaj unu el la leĝistoj responde diris al li: Majstro, dirante ĉi tion, vi ankaŭ nin riproĉas."],[11,46,"Kaj li diris: Ve ankaŭ al vi, leĝistoj! ĉar vi ŝarĝas homojn per ŝarĝoj malfacile porteblaj, kaj vi mem ne tuŝas eĉ per unu el viaj fingroj la ŝarĝojn.","Kaj li diris: Ve ankaŭ al vi, leĝistoj! ĉar vi ŝarĝas homojn per ŝarĝoj malfacile porteblaj, kaj vi mem ne tuŝas eĉ per unu el viaj fingroj la ŝarĝojn."],[11,47,"Ve al vi! ĉar vi konstruas la tombojn de la profetoj, kiujn viaj patroj mortigis.","Ve al vi! ĉar vi konstruas la tombojn de la profetoj, kiujn viaj patroj mortigis."],[11,48,"Tial vi estas atestantoj, kaj konsentas al la faroj de viaj patroj; ĉar ili mortigis ilin, kaj vi konstruas la tombojn.","Tial vi estas atestantoj, kaj konsentas al la faroj de viaj patroj; ĉar ili mortigis ilin, kaj vi konstruas la tombojn."],[11,49,"Tial ankaŭ diris la saĝo de Dio: Mi sendos al ili profetojn kaj apostolojn, kaj iujn el tiuj ili mortigos kaj persekutos;","Tial ankaŭ diris la saĝo de Dio: Mi sendos al ili profetojn kaj apostolojn, kaj iujn el tiuj ili mortigos kaj persekutos;"],[11,50,"por ke la sango de ĉiuj profetoj, kiu estis elverŝita de post la komenco de la mondo, estu postulita el ĉi tiu generacio,","por ke la sango de ĉiuj profetoj, kiu estis elverŝita de post la komenco de la mondo, estu postulita el ĉi tiu generacio,"],[11,51,"de la sango de Habel ĝis la sango de Zeĥarja, kiu pereis inter la altaro kaj la sankta domo; jes, mi diras al vi: Ĝi estos postulita el ĉi tiu generacio.","de la sango de Habel ĝis la sango de Zeĥarja, kiu pereis inter la altaro kaj la sankta domo; jes, mi diras al vi: Ĝi estos postulita el ĉi tiu generacio."],[11,52,"Ve al vi, leĝistoj! ĉar vi forprenis la ŝlosilon de la scio; vi mem ne eniris, kaj vi malhelpis la enirantajn.","Ve al vi, leĝistoj! ĉar vi forprenis la ŝlosilon de la scio; vi mem ne eniris, kaj vi malhelpis la enirantajn."],[11,53,"Kaj kiam li eliris el tie, la skribistoj kaj la Fariseoj atakis lin insiste, kaj instigis lin paroli pri multaj aferoj;","Kaj kiam li eliris el tie, la skribistoj kaj la Fariseoj atakis lin insiste, kaj instigis lin paroli pri multaj aferoj;"],[11,54,"insidante kontraŭ li, por kapti ion el lia buŝo.","insidante kontraŭ li, por kapti ion el lia buŝo."],[12,1,"Dume, kiam la miriadoj de la homamaso kunkolektiĝis tiel, ke ili piedpremis unu la alian, li ekparolis al siaj disĉiploj, dirante unue: Gardu vin kontraŭ la fermentaĵo de la Fariseoj, kiu estas hipokriteco.","Dume, kiam la miriadoj de la homamaso kunkolektiĝis tiel, ke ili piedpremis unu la alian, li ekparolis al siaj disĉiploj, dirante unue: Gardu vin kontraŭ la fermentaĵo de la Fariseoj, kiu estas hipokriteco."],[12,2,"Sed estas nenio kovrita, kio ne estos elmontrita; kaj nenio kaŝita, kio ne estos sciata.","Sed estas nenio kovrita, kio ne estos elmontrita; kaj nenio kaŝita, kio ne estos sciata."],[12,3,"Tial, kion vi diris en la mallumo, tio estos aŭdita en la lumo; kaj kion vi parolis en orelon en internaj ĉambroj, tio estos proklamita sur la tegmentoj.","Tial, kion vi diris en la mallumo, tio estos aŭdita en la lumo; kaj kion vi parolis en orelon en internaj ĉambroj, tio estos proklamita sur la tegmentoj."],[12,4,"Kaj mi diras al vi, miaj amikoj: Ne timu tiujn, kiuj mortigas la korpon, kaj poste ne povas fari ion plu.","Kaj mi diras al vi, miaj amikoj: Ne timu tiujn, kiuj mortigas la korpon, kaj poste ne povas fari ion plu."],[12,5,"Sed mi montros al vi, kiun vi devas timi: Timu Tiun, kiu, mortiginte, plue havas aŭtoritaton enĵeti en Gehenan; jes, mi diras al vi: Tiun timu.","Sed mi montros al vi, kiun vi devas timi: Timu Tiun, kiu, mortiginte, plue havas aŭtoritaton enĵeti en Gehenan; jes, mi diras al vi: Tiun timu."],[12,6,"Ĉu oni ne vendas kvin paserojn por du asaroj? kaj eĉ unu el ili ne estas forgesita antaŭ Dio.","Ĉu oni ne vendas kvin paserojn por du asaroj? kaj eĉ unu el ili ne estas forgesita antaŭ Dio."],[12,7,"Sed eĉ la haroj de via kapo estas ĉiuj kalkulitaj. Ne timu; vi pli valoras ol multaj paseroj.","Sed eĉ la haroj de via kapo estas ĉiuj kalkulitaj. Ne timu; vi pli valoras ol multaj paseroj."],[12,8,"Kaj mi diras al vi: Ĉiun, kiu konfesos min antaŭ la homoj, la Filo de homo ankaŭ konfesos antaŭ la anĝeloj de Dio;","Kaj mi diras al vi: Ĉiun, kiu konfesos min antaŭ la homoj, la Filo de homo ankaŭ konfesos antaŭ la anĝeloj de Dio;"],[12,9,"sed kiu malkonfesos min antaŭ la homoj, tiu estos malkonfesita antaŭ la anĝeloj de Dio.","sed kiu malkonfesos min antaŭ la homoj, tiu estos malkonfesita antaŭ la anĝeloj de Dio."],[12,10,"Kaj por ĉiu, kiu parolos vorton kontraŭ la Filo de homo, estos pardono; sed por tiu, kiu blasfemas kontraŭ la Sankta Spirito, ne estos pardono.","Kaj por ĉiu, kiu parolos vorton kontraŭ la Filo de homo, estos pardono; sed por tiu, kiu blasfemas kontraŭ la Sankta Spirito, ne estos pardono."],[12,11,"Kaj kiam oni kondukos vin antaŭ la sinagogojn kaj regantojn kaj aŭtoritatulojn, ne zorgu, kiel aŭ kion respondi, aŭ kion diri;","Kaj kiam oni kondukos vin antaŭ la sinagogojn kaj regantojn kaj aŭtoritatulojn, ne zorgu, kiel aŭ kion respondi, aŭ kion diri;"],[12,12,"ĉar la Sankta Spirito instruos al vi en tiu horo mem tion, kion vi devas diri.","ĉar la Sankta Spirito instruos al vi en tiu horo mem tion, kion vi devas diri."],[12,13,"Kaj unu el la homamaso diris al li: Majstro, diru al mia frato, ke li dividu kun mi la heredaĵon.","Kaj unu el la homamaso diris al li: Majstro, diru al mia frato, ke li dividu kun mi la heredaĵon."],[12,14,"Sed li diris al li: Ho viro, kiu starigis min super vi kiel juĝanton aŭ dividanton?","Sed li diris al li: Ho viro, kiu starigis min super vi kiel juĝanton aŭ dividanton?"],[12,15,"Kaj li diris al ili: Zorgu, kaj gardu vin kontraŭ ĉia avideco, ĉar la vivo de homo ne konsistas en la abundeco de liaj posedaĵoj.","Kaj li diris al ili: Zorgu, kaj gardu vin kontraŭ ĉia avideco, ĉar la vivo de homo ne konsistas en la abundeco de liaj posedaĵoj."],[12,16,"Kaj li parolis al ili parabolon, dirante: La bieno de unu riĉulo donis abunde;","Kaj li parolis al ili parabolon, dirante: La bieno de unu riĉulo donis abunde;"],[12,17,"kaj li konsideris, dirante: Kion mi faru, ĉar mi ne havas lokon, kie mi povas amasigi miajn fruktojn?","kaj li konsideris, dirante: Kion mi faru, ĉar mi ne havas lokon, kie mi povas amasigi miajn fruktojn?"],[12,18,"Kaj li diris: Jen kion mi faros: mi disbatos miajn grenejojn kaj konstruos pli grandajn, kaj tie mi amasigos mian grenon kaj miajn posedaĵojn.","Kaj li diris: Jen kion mi faros: mi disbatos miajn grenejojn kaj konstruos pli grandajn, kaj tie mi amasigos mian grenon kaj miajn posedaĵojn."],[12,19,"Kaj mi diros al mia animo: Animo, vi havas multajn posedaĵojn, provizitajn por multaj jaroj; ripozu, manĝu, trinku, estu gaja.","Kaj mi diros al mia animo: Animo, vi havas multajn posedaĵojn, provizitajn por multaj jaroj; ripozu, manĝu, trinku, estu gaja."],[12,20,"Sed Dio diris al li: Ho senprudentulo! ĉi tiun nokton oni postulas de vi vian animon; kies estos tio, kion vi preparis?","Sed Dio diris al li: Ho senprudentulo! ĉi tiun nokton oni postulas de vi vian animon; kies estos tio, kion vi preparis?"],[12,21,"Tia estas tiu, kiu kolektas por si trezoron, kaj ne estas riĉa rilate Dion.","Tia estas tiu, kiu kolektas por si trezoron, kaj ne estas riĉa rilate Dion."],[12,22,"Kaj li diris al siaj disĉiploj: Tial mi diras al vi: Ne zorgu pri via vivo, kion vi manĝu; nek pri via korpo, kion vi surmetu.","Kaj li diris al siaj disĉiploj: Tial mi diras al vi: Ne zorgu pri via vivo, kion vi manĝu; nek pri via korpo, kion vi surmetu."],[12,23,"Ĉar la vivo estas pli ol nutraĵo, kaj la korpo pli ol vestaĵo.","Ĉar la vivo estas pli ol nutraĵo, kaj la korpo pli ol vestaĵo."],[12,24,"Pripensu la korvojn, ke ili ne semas, nek rikoltas, kaj ne havas provizejon nek grenejon; kaj Dio nutras ilin; kiom pli vi valoras, ol la birdoj!","Pripensu la korvojn, ke ili ne semas, nek rikoltas, kaj ne havas provizejon nek grenejon; kaj Dio nutras ilin; kiom pli vi valoras, ol la birdoj!"],[12,25,"Kaj kiu el vi per zorgado povas aldoni unu ulnon al sia staturo?","Kaj kiu el vi per zorgado povas aldoni unu ulnon al sia staturo?"],[12,26,"Se do vi ne povas fari eĉ la plej malgrandan aferon, kial vi zorgas pri la ceteraj?","Se do vi ne povas fari eĉ la plej malgrandan aferon, kial vi zorgas pri la ceteraj?"],[12,27,"Pripensu la liliojn, kiel ili kreskas; ili ne laboras, nek ŝpinas; tamen mi diras al vi: Eĉ Salomono en sia tuta gloro ne estis ornamita tiel, kiel unu el ĉi tiuj.","Pripensu la liliojn, kiel ili kreskas; ili ne laboras, nek ŝpinas; tamen mi diras al vi: Eĉ Salomono en sia tuta gloro ne estis ornamita tiel, kiel unu el ĉi tiuj."],[12,28,"Sed se Dio tiel vestas la kampan herbaĵon, kiu hodiaŭ ekzistas, kaj morgaŭ estos ĵetata en fornon, kiom pli certe Li vestos vin, ho malgrandfiduloj!","Sed se Dio tiel vestas la kampan herbaĵon, kiu hodiaŭ ekzistas, kaj morgaŭ estos ĵetata en fornon, kiom pli certe Li vestos vin, ho malgrandfiduloj!"],[12,29,"Kaj ne serĉu, kion vi manĝos, kaj kion vi trinkos, kaj ne estu dubemaj.","Kaj ne serĉu, kion vi manĝos, kaj kion vi trinkos, kaj ne estu dubemaj."],[12,30,"Ĉar pri ĉio tio serĉas la nacioj de la mondo; sed via Patro scias, ke vi tion bezonas.","Ĉar pri ĉio tio serĉas la nacioj de la mondo; sed via Patro scias, ke vi tion bezonas."],[12,31,"Sed celu Lian regnon, kaj ĉio tio estos aldonita al vi.","Sed celu Lian regnon, kaj ĉio tio estos aldonita al vi."],[12,32,"Ne timu, malgranda grego; ĉar bone plaĉis al la Patro doni al vi la regnon.","Ne timu, malgranda grego; ĉar bone plaĉis al la Patro doni al vi la regnon."],[12,33,"Vendu viajn posedaĵojn, kaj donu almozon; faru por vi monujojn, kiuj ne fariĝos malnovaj, trezoron ne mankontan en la ĉielo, kie ŝtelisto ne alproksimiĝas kaj tineo ne detruas.","Vendu viajn posedaĵojn, kaj donu almozon; faru por vi monujojn, kiuj ne fariĝos malnovaj, trezoron ne mankontan en la ĉielo, kie ŝtelisto ne alproksimiĝas kaj tineo ne detruas."],[12,34,"Ĉar kie estas via trezoro, tie estos ankaŭ via koro.","Ĉar kie estas via trezoro, tie estos ankaŭ via koro."],[12,35,"Viaj lumboj estu zonitaj, kaj viaj lampoj estu brulantaj;","Viaj lumboj estu zonitaj, kaj viaj lampoj estu brulantaj;"],[12,36,"kaj vi mem estu similaj al viroj, kiuj atendas sian sinjoron, kiam li revenos de la edziĝa festo; por ke ili tuj malfermu al li, kiam li venos kaj frapos.","kaj vi mem estu similaj al viroj, kiuj atendas sian sinjoron, kiam li revenos de la edziĝa festo; por ke ili tuj malfermu al li, kiam li venos kaj frapos."],[12,37,"Feliĉaj estas tiuj servistoj, kiujn la sinjoro, kiam li venos, trovos viglaj; vere mi diras al vi, ke li sin zonos, kaj sidigos ilin por manĝi, kaj mem venos kaj servos al ili.","Feliĉaj estas tiuj servistoj, kiujn la sinjoro, kiam li venos, trovos viglaj; vere mi diras al vi, ke li sin zonos, kaj sidigos ilin por manĝi, kaj mem venos kaj servos al ili."],[12,38,"Kaj se li alvenos nokte dum la dua gardoparto, aŭ dum la tria gardoparto, kaj tiel ilin trovos, feliĉaj estas tiuj servistoj.","Kaj se li alvenos nokte dum la dua gardoparto, aŭ dum la tria gardoparto, kaj tiel ilin trovos, feliĉaj estas tiuj servistoj."],[12,39,"Sed sciu, ke se la domomastro scius, je kioma horo la ŝtelisto venos, li maldormus kaj ne lasus sian domon trafosiĝi.","Sed sciu, ke se la domomastro scius, je kioma horo la ŝtelisto venos, li maldormus kaj ne lasus sian domon trafosiĝi."],[12,40,"Vi ankaŭ estu pretaj, ĉar en tiu horo, kiun vi ne pripensas, la Filo de homo venos.","Vi ankaŭ estu pretaj, ĉar en tiu horo, kiun vi ne pripensas, la Filo de homo venos."],[12,41,"Kaj Petro diris: Sinjoro, ĉu vi parolas ĉi tiun parabolon por ni, aŭ ankaŭ por ĉiuj?","Kaj Petro diris: Sinjoro, ĉu vi parolas ĉi tiun parabolon por ni, aŭ ankaŭ por ĉiuj?"],[12,42,"Kaj la Sinjoro diris: Kiu do estas la fidela kaj saĝa administranto, kiun lia sinjoro starigos super sia servantaro, por doni al ili ĝustatempe ilian porcion da nutraĵo?","Kaj la Sinjoro diris: Kiu do estas la fidela kaj saĝa administranto, kiun lia sinjoro starigos super sia servantaro, por doni al ili ĝustatempe ilian porcion da nutraĵo?"],[12,43,"Feliĉa estas tiu servisto, kiun lia sinjoro, veninte, trovos aganta tiel.","Feliĉa estas tiu servisto, kiun lia sinjoro, veninte, trovos aganta tiel."],[12,44,"Vere mi diras al vi, ke li starigos lin super ĉio, kion li havas.","Vere mi diras al vi, ke li starigos lin super ĉio, kion li havas."],[12,45,"Sed se tiu servisto diros en sia koro: Mia sinjoro prokrastas sian alvenon; kaj komencos bati la knabojn kaj la knabinojn, kaj manĝos kaj trinkos kaj ebriiĝos,","Sed se tiu servisto diros en sia koro: Mia sinjoro prokrastas sian alvenon; kaj komencos bati la knabojn kaj la knabinojn, kaj manĝos kaj trinkos kaj ebriiĝos,"],[12,46,"la sinjoro de tiu servisto alvenos en tago, kiam li ne atendas, kaj en horo, pri kiu li ne scias; kaj tranĉe skurĝos lin, kaj difinos por li parton kun la senfiduloj.","la sinjoro de tiu servisto alvenos en tago, kiam li ne atendas, kaj en horo, pri kiu li ne scias; kaj tranĉe skurĝos lin, kaj difinos por li parton kun la senfiduloj."],[12,47,"Kaj tiu servisto, kiu sciis la volon de sia sinjoro, kaj nenion pretigis, nek faris laŭ lia volo, suferos multajn batojn;","Kaj tiu servisto, kiu sciis la volon de sia sinjoro, kaj nenion pretigis, nek faris laŭ lia volo, suferos multajn batojn;"],[12,48,"sed tiu, kiu ne sciis, kaj laŭ siaj agoj meritis batojn, suferos malmultajn batojn. Kaj al kiu multo estas donita, el tiu estos multo postulata; kaj al kiu oni multon komisiis, el tiu oni des pli multon postulos.","sed tiu, kiu ne sciis, kaj laŭ siaj agoj meritis batojn, suferos malmultajn batojn. Kaj al kiu multo estas donita, el tiu estos multo postulata; kaj al kiu oni multon komisiis, el tiu oni des pli multon postulos."],[12,49,"Mi alvenis, por ĵeti fajron sur la teron; kaj kion mi volas, se jam ĝi ekbrulis?","Mi alvenis, por ĵeti fajron sur la teron; kaj kion mi volas, se jam ĝi ekbrulis?"],[12,50,"Sed mi havas bapton, per kiu esti baptita; kaj kiel mi premiĝas, ĝis ĝi estos plenumita!","Sed mi havas bapton, per kiu esti baptita; kaj kiel mi premiĝas, ĝis ĝi estos plenumita!"],[12,51,"Ĉu vi supozas, ke mi alvenis, por doni pacon sur la tero? Mi diras al vi: Ne; sed pli vere disigon;","Ĉu vi supozas, ke mi alvenis, por doni pacon sur la tero? Mi diras al vi: Ne; sed pli vere disigon;"],[12,52,"ĉar de nun estos kvin el unu domo disigitaj, tri kontraŭ du, kaj du kontraŭ tri.","ĉar de nun estos kvin el unu domo disigitaj, tri kontraŭ du, kaj du kontraŭ tri."],[12,53,"Estos disigitaj patro kontraŭ filo, kaj filo kontraŭ patro; patrino kontraŭ filino, kaj filino kontraŭ patrino; bopatrino kontraŭ bofilino, kaj bofilino kontraŭ bopatrino.","Estos disigitaj patro kontraŭ filo, kaj filo kontraŭ patro; patrino kontraŭ filino, kaj filino kontraŭ patrino; bopatrino kontraŭ bofilino, kaj bofilino kontraŭ bopatrino."],[12,54,"Kaj li diris al la homamasoj: Kiam vi vidas nubon leviĝantan en la okcidento, vi tuj diras: Venos pluveto; kaj tiel fariĝas.","Kaj li diris al la homamasoj: Kiam vi vidas nubon leviĝantan en la okcidento, vi tuj diras: Venos pluveto; kaj tiel fariĝas."],[12,55,"Kaj kiam blovas la suda vento, vi diras: Estos varmego; kaj tiel fariĝas.","Kaj kiam blovas la suda vento, vi diras: Estos varmego; kaj tiel fariĝas."],[12,56,"Ho hipokrituloj! vi scias esplori la aspekton de la tero kaj de la ĉielo; sed kial vi ne scias esplori ĉi tiun tempon?","Ho hipokrituloj! vi scias esplori la aspekton de la tero kaj de la ĉielo; sed kial vi ne scias esplori ĉi tiun tempon?"],[12,57,"Kaj kial eĉ per vi mem vi ne juĝas, kio estas justa?","Kaj kial eĉ per vi mem vi ne juĝas, kio estas justa?"],[12,58,"Ĉar dum vi iradas kun via kontraŭulo al la reganto, survoje klopodu liberiĝi de li; por ne lasi, ke li trenu vin al la juĝisto, kaj la juĝisto vin transdonu al la oficisto de la tribunalo, kaj la oficisto vin ĵetu en malliberejon.","Ĉar dum vi iradas kun via kontraŭulo al la reganto, survoje klopodu liberiĝi de li; por ne lasi, ke li trenu vin al la juĝisto, kaj la juĝisto vin transdonu al la oficisto de la tribunalo, kaj la oficisto vin ĵetu en malliberejon."],[12,59,"Mi diras al vi: Vi neniel el tie eliros, ĝis vi pagos la lastan lepton.","Mi diras al vi: Vi neniel el tie eliros, ĝis vi pagos la lastan lepton."],[13,1,"Kaj ĉeestis en tiu sama tempo iuj, kiuj rakontis al li pri tiuj Galileanoj, kies sangon Pilato miksis kun iliaj oferaĵoj.","Kaj ĉeestis en tiu sama tempo iuj, kiuj rakontis al li pri tiuj Galileanoj, kies sangon Pilato miksis kun iliaj oferaĵoj."],[13,2,"Kaj responde li diris al ili: Ĉu vi pensas, ke tiuj Galileanoj estis pekuloj pli ol ĉiuj Galileanoj, pro tio, ke ili tion suferis?","Kaj responde li diris al ili: Ĉu vi pensas, ke tiuj Galileanoj estis pekuloj pli ol ĉiuj Galileanoj, pro tio, ke ili tion suferis?"],[13,3,"Mi diras al vi: Neniel; sed se vi ne pentos, vi ĉiuj tiel same pereos.","Mi diras al vi: Neniel; sed se vi ne pentos, vi ĉiuj tiel same pereos."],[13,4,"Aŭ pri tiuj dek ok, sur kiujn falis la turo en Ŝiloaĥ kaj ilin mortigis, ĉu vi pensas, ke ili estis pekuloj pli ol ĉiuj homoj, kiuj loĝis en Jerusalem?","Aŭ pri tiuj dek ok, sur kiujn falis la turo en Ŝiloaĥ kaj ilin mortigis, ĉu vi pensas, ke ili estis pekuloj pli ol ĉiuj homoj, kiuj loĝis en Jerusalem?"],[13,5,"Neniel, mi diras al vi; sed se vi ne pentos, vi ĉiuj ankaŭ pereos.","Neniel, mi diras al vi; sed se vi ne pentos, vi ĉiuj ankaŭ pereos."],[13,6,"Kaj li parolis la jenan parabolon: Unu viro havis figarbon, plantitan en lia vinberĝardeno, kaj li venis, serĉante frukton sur ĝi, kaj ne trovis.","Kaj li parolis la jenan parabolon: Unu viro havis figarbon, plantitan en lia vinberĝardeno, kaj li venis, serĉante frukton sur ĝi, kaj ne trovis."],[13,7,"Kaj li diris al la vinberisto: Jen tri jarojn mi venas, serĉante frukton sur ĉi tiu figarbo, kaj mi ne trovas; elhaku ĝin; kial ĝi senutiligas ankaŭ la teron?","Kaj li diris al la vinberisto: Jen tri jarojn mi venas, serĉante frukton sur ĉi tiu figarbo, kaj mi ne trovas; elhaku ĝin; kial ĝi senutiligas ankaŭ la teron?"],[13,8,"Sed li responde diris: Sinjoro, lasu ĝin resti ankaŭ ĉi tiun jaron, ĝis mi fosos ĉirkaŭ ĝi kaj metos sterkon;","Sed li responde diris: Sinjoro, lasu ĝin resti ankaŭ ĉi tiun jaron, ĝis mi fosos ĉirkaŭ ĝi kaj metos sterkon;"],[13,9,"kaj se ĝi poste donos frukton, bone; sed se ne, vi elhakos ĝin.","kaj se ĝi poste donos frukton, bone; sed se ne, vi elhakos ĝin."],[13,10,"Kaj li instruadis en unu el la sinagogoj en la sabato.","Kaj li instruadis en unu el la sinagogoj en la sabato."],[13,11,"Kaj jen virino, kiu dum dek ok jaroj havis spiriton de malforteco; kaj ŝi estis kunkurbita kaj neniel povis leviĝi.","Kaj jen virino, kiu dum dek ok jaroj havis spiriton de malforteco; kaj ŝi estis kunkurbita kaj neniel povis leviĝi."],[13,12,"Kaj vidinte ŝin, Jesuo vokis ŝin, kaj diris: Virino, vi estas liberigita el via malforteco.","Kaj vidinte ŝin, Jesuo vokis ŝin, kaj diris: Virino, vi estas liberigita el via malforteco."],[13,13,"Kaj li metis sur ŝin la manojn, kaj ŝi tuj rektiĝis kaj gloris Dion.","Kaj li metis sur ŝin la manojn, kaj ŝi tuj rektiĝis kaj gloris Dion."],[13,14,"Kaj la sinagogestro, indignante, ke Jesuo resanigis en la sabato, respondis kaj diris al la homamaso: Ekzistas ses tagoj, en kiuj oni devas labori; en ili do venu, por esti resanigitaj, kaj ne en la sabata tago.","Kaj la sinagogestro, indignante, ke Jesuo resanigis en la sabato, respondis kaj diris al la homamaso: Ekzistas ses tagoj, en kiuj oni devas labori; en ili do venu, por esti resanigitaj, kaj ne en la sabata tago."],[13,15,"Sed la Sinjoro respondis al li kaj diris: Ho hipokrituloj! ĉu ne ĉiu el vi en la sabato malligas sian bovon aŭ sian azenon el la stalo, kaj forkondukas ĝin, por trinkigi?","Sed la Sinjoro respondis al li kaj diris: Ho hipokrituloj! ĉu ne ĉiu el vi en la sabato malligas sian bovon aŭ sian azenon el la stalo, kaj forkondukas ĝin, por trinkigi?"],[13,16,"Kaj ĉu ne devis ĉi tiu virino, estante filino de Abraham, ligite de Satano jen dek ok jarojn, esti malligita el ĉi tiu kateno en la sabata tago?","Kaj ĉu ne devis ĉi tiu virino, estante filino de Abraham, ligite de Satano jen dek ok jarojn, esti malligita el ĉi tiu kateno en la sabata tago?"],[13,17,"Kaj kiam li tion diris, ĉiuj liaj kontraŭuloj hontiĝis; kaj la tuta homamaso ĝojis pro ĉiuj gloraj agoj, faritaj de li.","Kaj kiam li tion diris, ĉiuj liaj kontraŭuloj hontiĝis; kaj la tuta homamaso ĝojis pro ĉiuj gloraj agoj, faritaj de li."],[13,18,"Kaj li diris: Al kio similas la regno de Dio? kaj al kio mi ĝin komparu?","Kaj li diris: Al kio similas la regno de Dio? kaj al kio mi ĝin komparu?"],[13,19,"Ĝi estas simila al sinapa semeto, kiun viro prenis kaj ĵetis en sian ĝardenon; kaj ĝi kreskis kaj fariĝis arbo; kaj la birdoj de la ĉielo loĝis en ĝiaj branĉoj.","Ĝi estas simila al sinapa semeto, kiun viro prenis kaj ĵetis en sian ĝardenon; kaj ĝi kreskis kaj fariĝis arbo; kaj la birdoj de la ĉielo loĝis en ĝiaj branĉoj."],[13,20,"Poste li diris: Al kio mi komparu la regnon de Dio?","Poste li diris: Al kio mi komparu la regnon de Dio?"],[13,21,"Ĝi estas simila al fermentaĵo, kiun virino prenis kaj kaŝis en tri mezuroj da faruno, ĝis la tuto fermentis.","Ĝi estas simila al fermentaĵo, kiun virino prenis kaj kaŝis en tri mezuroj da faruno, ĝis la tuto fermentis."],[13,22,"Kaj li iris tra urboj kaj vilaĝoj, instruante kaj irante ĉiam pluen al Jerusalem.","Kaj li iris tra urboj kaj vilaĝoj, instruante kaj irante ĉiam pluen al Jerusalem."],[13,23,"Kaj iu diris al li: Sinjoro, ĉu malmultaj estas la savataj? Kaj li diris al ili:","Kaj iu diris al li: Sinjoro, ĉu malmultaj estas la savataj? Kaj li diris al ili:"],[13,24,"Strebu eniri tra la mallarĝa pordo; ĉar multaj, mi diras al vi, deziros eniri kaj ne povos.","Strebu eniri tra la mallarĝa pordo; ĉar multaj, mi diras al vi, deziros eniri kaj ne povos."],[13,25,"Kiam la domomastro leviĝos kaj ŝlosos la pordon, kaj vi komencos stari ekstere kaj frapi sur la pordon, dirante: Sinjoro, malfermu al ni; kaj li respondos kaj diros al vi: Mi ne scias, de kie vi estas;","Kiam la domomastro leviĝos kaj ŝlosos la pordon, kaj vi komencos stari ekstere kaj frapi sur la pordon, dirante: Sinjoro, malfermu al ni; kaj li respondos kaj diros al vi: Mi ne scias, de kie vi estas;"],[13,26,"tiam vi ekparolos: Ni manĝis kaj trinkis antaŭ vi, kaj sur niaj stratoj vi instruadis;","tiam vi ekparolos: Ni manĝis kaj trinkis antaŭ vi, kaj sur niaj stratoj vi instruadis;"],[13,27,"kaj li parolos, kaj diros al vi: Mi ne scias, de kie vi estas; foriru de mi, ĉiuj farantoj de maljusteco.","kaj li parolos, kaj diros al vi: Mi ne scias, de kie vi estas; foriru de mi, ĉiuj farantoj de maljusteco."],[13,28,"Tie estos la plorado kaj la grincado de dentoj, kiam vi vidos Abrahamon kaj Isaakon kaj Jakobon kaj ĉiujn profetojn en la regno de Dio, kaj vin mem forpelitaj eksteren.","Tie estos la plorado kaj la grincado de dentoj, kiam vi vidos Abrahamon kaj Isaakon kaj Jakobon kaj ĉiujn profetojn en la regno de Dio, kaj vin mem forpelitaj eksteren."],[13,29,"Kaj oni venos el oriento kaj el okcidento, kaj el nordo kaj el sudo, kaj sidiĝos en la regno de Dio.","Kaj oni venos el oriento kaj el okcidento, kaj el nordo kaj el sudo, kaj sidiĝos en la regno de Dio."],[13,30,"Kaj jen estas lastaj, kiuj estos unuaj; kaj estas unuaj, kiuj estos lastaj.","Kaj jen estas lastaj, kiuj estos unuaj; kaj estas unuaj, kiuj estos lastaj."],[13,31,"En tiu sama horo alvenis iuj Fariseoj, kaj diris al li: Eliru kaj foriru de ĉi tie, ĉar Herodo volas mortigi vin.","En tiu sama horo alvenis iuj Fariseoj, kaj diris al li: Eliru kaj foriru de ĉi tie, ĉar Herodo volas mortigi vin."],[13,32,"Kaj li diris al ili: Iru, kaj diru al tiu vulpo: Jen mi elpelas demonojn kaj faras sanigojn hodiaŭ kaj morgaŭ, kaj la trian tagon mi estos perfektigita.","Kaj li diris al ili: Iru, kaj diru al tiu vulpo: Jen mi elpelas demonojn kaj faras sanigojn hodiaŭ kaj morgaŭ, kaj la trian tagon mi estos perfektigita."],[13,33,"Sed mi devas iradi hodiaŭ kaj morgaŭ kaj postmorgaŭ, ĉar ne povas esti, ke profeto pereos ekster Jerusalem.","Sed mi devas iradi hodiaŭ kaj morgaŭ kaj postmorgaŭ, ĉar ne povas esti, ke profeto pereos ekster Jerusalem."],[13,34,"Ho Jerusalem, Jerusalem, kiu pereigas la profetojn kaj ŝtonmortigas tiujn, kiuj estas senditaj al ĝi! kiom ofte mi deziris kolekti viajn infanojn, kiel kokino kolektas sian idaron sub la flugilojn, kaj vi ne volis!","Ho Jerusalem, Jerusalem, kiu pereigas la profetojn kaj ŝtonmortigas tiujn, kiuj estas senditaj al ĝi! kiom ofte mi deziris kolekti viajn infanojn, kiel kokino kolektas sian idaron sub la flugilojn, kaj vi ne volis!"],[13,35,"Jen via domo estas lasita al vi dezerta; kaj mi diras al vi: Vi min ne vidos, ĝis vi diros: Estu benata tiu, kiu venas en la nomo de la Eternulo.","Jen via domo estas lasita al vi dezerta; kaj mi diras al vi: Vi min ne vidos, ĝis vi diros: Estu benata tiu, kiu venas en la nomo de la Eternulo."],[14,1,"Kaj kiam li eniris en sabato en la domon de unu reganto de la Fariseoj, por manĝi panon, ili lin observis.","Kaj kiam li eniris en sabato en la domon de unu reganto de la Fariseoj, por manĝi panon, ili lin observis."],[14,2,"Kaj jen antaŭ li estis unu hidropsulo.","Kaj jen antaŭ li estis unu hidropsulo."],[14,3,"Kaj respondante, Jesuo parolis al la leĝistoj kaj la Fariseoj, kaj diris: Ĉu estas permesate sanigi en sabato, aŭ ne?","Kaj respondante, Jesuo parolis al la leĝistoj kaj la Fariseoj, kaj diris: Ĉu estas permesate sanigi en sabato, aŭ ne?"],[14,4,"Sed ili silentis. Kaj li prenis lin kaj sanigis lin, kaj forliberigis lin.","Sed ili silentis. Kaj li prenis lin kaj sanigis lin, kaj forliberigis lin."],[14,5,"Kaj li diris al ili: Kiu el vi havos azenon aŭ bovon, falintan en puton, kaj ne tuj eltiros ĝin en sabata tago?","Kaj li diris al ili: Kiu el vi havos azenon aŭ bovon, falintan en puton, kaj ne tuj eltiros ĝin en sabata tago?"],[14,6,"Kaj ili ne povis respondi al tio.","Kaj ili ne povis respondi al tio."],[14,7,"Kaj li parolis parabolon al la invititoj, vidinte, kiel ili elektas la ĉefajn sidlokojn; li diris al ili:","Kaj li parolis parabolon al la invititoj, vidinte, kiel ili elektas la ĉefajn sidlokojn; li diris al ili:"],[14,8,"Kiam vi estas invitita de iu al edziĝa festo, ne sidiĝu en la ĉefa loko, por ke ne okazu, ke iu, pli honorinda ol vi, estas de li invitita;","Kiam vi estas invitita de iu al edziĝa festo, ne sidiĝu en la ĉefa loko, por ke ne okazu, ke iu, pli honorinda ol vi, estas de li invitita;"],[14,9,"kaj tiu, kiu invitis vin kaj lin, venos, kaj diros al vi: Cedu lokon al ĉi tiu; kaj tiam vi komencos kun honto preni la lastan lokon.","kaj tiu, kiu invitis vin kaj lin, venos, kaj diros al vi: Cedu lokon al ĉi tiu; kaj tiam vi komencos kun honto preni la lastan lokon."],[14,10,"Sed kiam vi estas invitita, iru kaj sidiĝu en la lasta loko; kaj tiel, kiam venos tiu, kiu vin invitis, li diros al vi: Amiko, iru pli alten; tiam vi havos honoron antaŭ ĉiuj, kiuj sidas kun vi.","Sed kiam vi estas invitita, iru kaj sidiĝu en la lasta loko; kaj tiel, kiam venos tiu, kiu vin invitis, li diros al vi: Amiko, iru pli alten; tiam vi havos honoron antaŭ ĉiuj, kiuj sidas kun vi."],[14,11,"Ĉar ĉiu, kiu sin altigas, estos humiligita, kaj kiu sin humiligas, tiu estos altigita.","Ĉar ĉiu, kiu sin altigas, estos humiligita, kaj kiu sin humiligas, tiu estos altigita."],[14,12,"Kaj li diris al tiu, kiu lin invitis: Kiam vi faras tagmanĝon aŭ vespermanĝon, ne voku viajn amikojn, nek viajn fratojn, nek viajn parencojn, nek viajn riĉajn najbarojn, por ke ne okazu, ke ili ankaŭ invitos vin, kaj vi ricevos rekompencon.","Kaj li diris al tiu, kiu lin invitis: Kiam vi faras tagmanĝon aŭ vespermanĝon, ne voku viajn amikojn, nek viajn fratojn, nek viajn parencojn, nek viajn riĉajn najbarojn, por ke ne okazu, ke ili ankaŭ invitos vin, kaj vi ricevos rekompencon."],[14,13,"Sed kiam vi faras festenon, invitu malriĉulojn, kriplulojn, lamulojn, blindulojn;","Sed kiam vi faras festenon, invitu malriĉulojn, kriplulojn, lamulojn, blindulojn;"],[14,14,"kaj vi estos feliĉa, ĉar ili ne povas rekompenci vin, sed vi rekompenciĝos en la releviĝo de la justuloj.","kaj vi estos feliĉa, ĉar ili ne povas rekompenci vin, sed vi rekompenciĝos en la releviĝo de la justuloj."],[14,15,"Kaj aŭdinte tion, unu el la kunsidantoj diris al li: Feliĉa estas tiu, kiu manĝos panon en la regno de Dio.","Kaj aŭdinte tion, unu el la kunsidantoj diris al li: Feliĉa estas tiu, kiu manĝos panon en la regno de Dio."],[14,16,"Sed li diris al li: Unu viro faris grandan vespermanĝon, kaj invitis multajn;","Sed li diris al li: Unu viro faris grandan vespermanĝon, kaj invitis multajn;"],[14,17,"kaj en la horo de la festeno li elsendis sian serviston, por diri al la invititoj: Venu, ĉar ĉio estas jam preta.","kaj en la horo de la festeno li elsendis sian serviston, por diri al la invititoj: Venu, ĉar ĉio estas jam preta."],[14,18,"Kaj ĉiuj tiel same komencis peti pri indulgo. La unua diris al li: Mi aĉetis kampon, kaj mi nepre devas eliri, por ĝin vidi; mi petas, kalkulu al mi indulgon.","Kaj ĉiuj tiel same komencis peti pri indulgo. La unua diris al li: Mi aĉetis kampon, kaj mi nepre devas eliri, por ĝin vidi; mi petas, kalkulu al mi indulgon."],[14,19,"Alia diris: Mi aĉetis kvin jugojn da bovoj, kaj mi iras, por ilin provi; mi petas, kalkulu al mi indulgon.","Alia diris: Mi aĉetis kvin jugojn da bovoj, kaj mi iras, por ilin provi; mi petas, kalkulu al mi indulgon."],[14,20,"Kaj alia diris: Mi edziĝis kun edzino, kaj tial mi ne povas veni.","Kaj alia diris: Mi edziĝis kun edzino, kaj tial mi ne povas veni."],[14,21,"Kaj la servisto revenis, kaj rakontis tion al sia mastro. Tiam ekkoleris la mastro, kaj diris al sia servisto: Eliru rapide sur la stratojn kaj irejojn de la urbo, kaj alkonduku ĉi tien la malriĉulojn kaj kriplulojn kaj blindulojn kaj lamulojn.","Kaj la servisto revenis, kaj rakontis tion al sia mastro. Tiam ekkoleris la mastro, kaj diris al sia servisto: Eliru rapide sur la stratojn kaj irejojn de la urbo, kaj alkonduku ĉi tien la malriĉulojn kaj kriplulojn kaj blindulojn kaj lamulojn."],[14,22,"Kaj la servisto diris: Sinjoro, estas farita tio, kion vi ordonis, kaj ankoraŭ estas loko.","Kaj la servisto diris: Sinjoro, estas farita tio, kion vi ordonis, kaj ankoraŭ estas loko."],[14,23,"Kaj la sinjoro diris al la servisto: Eliru sur la vojojn kaj kamplimojn, kaj devigu ilin enveni, por ke mia domo pleniĝu.","Kaj la sinjoro diris al la servisto: Eliru sur la vojojn kaj kamplimojn, kaj devigu ilin enveni, por ke mia domo pleniĝu."],[14,24,"Ĉar mi diras al vi, ke neniu el tiuj viroj invititaj gustumos mian vespermanĝon.","Ĉar mi diras al vi, ke neniu el tiuj viroj invititaj gustumos mian vespermanĝon."],[14,25,"Kaj grandaj homamasoj iris kun li, kaj li sin turnis, kaj diris al ili:","Kaj grandaj homamasoj iris kun li, kaj li sin turnis, kaj diris al ili:"],[14,26,"Se iu venas al mi, kaj ne malamas sian patron kaj sian patrinon kaj sian edzinon kaj siajn infanojn kaj fratojn kaj fratinojn, kaj eĉ ankaŭ sian vivon, li ne povas esti mia disĉiplo.","Se iu venas al mi, kaj ne malamas sian patron kaj sian patrinon kaj sian edzinon kaj siajn infanojn kaj fratojn kaj fratinojn, kaj eĉ ankaŭ sian vivon, li ne povas esti mia disĉiplo."],[14,27,"Kiu ne portas sian krucon kaj ne sekvas min, tiu ne povas esti mia disĉiplo.","Kiu ne portas sian krucon kaj ne sekvas min, tiu ne povas esti mia disĉiplo."],[14,28,"Ĉar kiu el vi, dezirante konstrui turon, unue ne sidiĝas, por kalkuli la koston, ĉu li havas sufiĉe, por fini ĝin?","Ĉar kiu el vi, dezirante konstrui turon, unue ne sidiĝas, por kalkuli la koston, ĉu li havas sufiĉe, por fini ĝin?"],[14,29,"Por ke, kiam li metis la fundamenton kaj ne povas ĝin fini, ĉiuj vidantoj ne komencu moki lin,","Por ke, kiam li metis la fundamenton kaj ne povas ĝin fini, ĉiuj vidantoj ne komencu moki lin,"],[14,30,"dirante: Ĉi tiu homo komencis konstrui, sed ne povis fini.","dirante: Ĉi tiu homo komencis konstrui, sed ne povis fini."],[14,31,"Kaj kiu reĝo, ekirante, por renkonti en batalo alian reĝon, unue ne sidiĝos, por konsiliĝi, ĉu li povas kun dek mil renkonti tiun, kiu venas kontraŭ li kun dudek mil?","Kaj kiu reĝo, ekirante, por renkonti en batalo alian reĝon, unue ne sidiĝos, por konsiliĝi, ĉu li povas kun dek mil renkonti tiun, kiu venas kontraŭ li kun dudek mil?"],[14,32,"Aŭ alie, dum la alia estas tre malproksime, li alsendas ambasadorojn kaj demandas pri paco.","Aŭ alie, dum la alia estas tre malproksime, li alsendas ambasadorojn kaj demandas pri paco."],[14,33,"Kiu do el vi ne forlasas ĉiujn siajn posedaĵojn, tiu ne povas esti mia disĉiplo.","Kiu do el vi ne forlasas ĉiujn siajn posedaĵojn, tiu ne povas esti mia disĉiplo."],[14,34,"Salo do estas bona, sed se eĉ la salo sengustiĝis, per kio ĝi estos spicata?","Salo do estas bona, sed se eĉ la salo sengustiĝis, per kio ĝi estos spicata?"],[14,35,"Ĝi taŭgas nek por la tero nek por sterkejo; oni ĝin forĵetas. Kiu havas orelojn por aŭdi, tiu aŭdu.","Ĝi taŭgas nek por la tero nek por sterkejo; oni ĝin forĵetas. Kiu havas orelojn por aŭdi, tiu aŭdu."],[15,1,"Kaj ĉiuj impostistoj kaj pekuloj alproksimiĝis al li, por aŭskulti lin.","Kaj ĉiuj impostistoj kaj pekuloj alproksimiĝis al li, por aŭskulti lin."],[15,2,"Kaj murmuris la Fariseoj kaj la skribistoj, dirante: Ĉi tiu akceptas pekulojn kaj manĝas kun ili.","Kaj murmuris la Fariseoj kaj la skribistoj, dirante: Ĉi tiu akceptas pekulojn kaj manĝas kun ili."],[15,3,"Kaj li parolis al ili la jenan parabolon, dirante:","Kaj li parolis al ili la jenan parabolon, dirante:"],[15,4,"Kiu el vi, havante cent ŝafojn kaj perdinte unu el ili, ne forlasas la naŭdek naŭ sur la stepo, kaj iras, por serĉi tiun, kiun li perdis, ĝis li ĝin trovos?","Kiu el vi, havante cent ŝafojn kaj perdinte unu el ili, ne forlasas la naŭdek naŭ sur la stepo, kaj iras, por serĉi tiun, kiun li perdis, ĝis li ĝin trovos?"],[15,5,"Kaj trovinte, li ĝin metas sur siajn ŝultrojn, ĝojante.","Kaj trovinte, li ĝin metas sur siajn ŝultrojn, ĝojante."],[15,6,"Kaj reveninte domen, li kunvokas siajn amikojn kaj siajn najbarojn, dirante al ili: Ĝoju kun mi, ĉar mi trovis mian ŝafon, la perditan.","Kaj reveninte domen, li kunvokas siajn amikojn kaj siajn najbarojn, dirante al ili: Ĝoju kun mi, ĉar mi trovis mian ŝafon, la perditan."],[15,7,"Mi diras al vi, ke tiel same estos ĝojo en la ĉielo pro unu pekulo, kiu pentas, pli ol pro naŭdek naŭ justuloj, kiuj ne bezonas penton.","Mi diras al vi, ke tiel same estos ĝojo en la ĉielo pro unu pekulo, kiu pentas, pli ol pro naŭdek naŭ justuloj, kiuj ne bezonas penton."],[15,8,"Kiu virino, havante dek draĥmojn, se ŝi perdis unu draĥmon, ne ekbruligas lampon kaj balaas la domon kaj serĉas diligente, ĝis ŝi ĝin trovos?","Kiu virino, havante dek draĥmojn, se ŝi perdis unu draĥmon, ne ekbruligas lampon kaj balaas la domon kaj serĉas diligente, ĝis ŝi ĝin trovos?"],[15,9,"Kaj trovinte, ŝi kunvokas siajn amikinojn kaj siajn najbarinojn, dirante: Ĝoju kun mi, ĉar mi trovis la draĥmon, kiun mi perdis.","Kaj trovinte, ŝi kunvokas siajn amikinojn kaj siajn najbarinojn, dirante: Ĝoju kun mi, ĉar mi trovis la draĥmon, kiun mi perdis."],[15,10,"Tiel same, mi diras al vi, estas ĝojo antaŭ la anĝeloj de Dio pro unu pekulo, kiu pentas.","Tiel same, mi diras al vi, estas ĝojo antaŭ la anĝeloj de Dio pro unu pekulo, kiu pentas."],[15,11,"Kaj li diris: Unu viro havis du filojn;","Kaj li diris: Unu viro havis du filojn;"],[15,12,"kaj la pli juna diris al sia patro: Patro, donu al mi la heredotan parton de la havo. Kaj li dividis inter ili siajn vivrimedojn.","kaj la pli juna diris al sia patro: Patro, donu al mi la heredotan parton de la havo. Kaj li dividis inter ili siajn vivrimedojn."],[15,13,"Kaj post ne multaj tagoj la pli juna, kolektinte ĉion, forvojaĝis al malproksima lando; kaj tie li disperdis sian havon per diboĉa vivado.","Kaj post ne multaj tagoj la pli juna, kolektinte ĉion, forvojaĝis al malproksima lando; kaj tie li disperdis sian havon per diboĉa vivado."],[15,14,"Kaj kiam li jam elspezis ĉion, forta malsato okazis en tiu lando, kaj li komencis havi mankon.","Kaj kiam li jam elspezis ĉion, forta malsato okazis en tiu lando, kaj li komencis havi mankon."],[15,15,"Kaj li iris, kaj aliĝis al unu el la loĝantoj de tiu lando; kaj ĉi tiu lin sendis sur siajn kampojn, por paŝti porkojn.","Kaj li iris, kaj aliĝis al unu el la loĝantoj de tiu lando; kaj ĉi tiu lin sendis sur siajn kampojn, por paŝti porkojn."],[15,16,"Kaj li deziris plenigi sian ventron per la karoboj, kiujn la porkoj manĝis; kaj neniu donis al li.","Kaj li deziris plenigi sian ventron per la karoboj, kiujn la porkoj manĝis; kaj neniu donis al li."],[15,17,"Sed reveninte al si, li diris: Kiom da dungitoj de mia patro havas panon abunde, sed mi ĉi tie pereas de malsato!","Sed reveninte al si, li diris: Kiom da dungitoj de mia patro havas panon abunde, sed mi ĉi tie pereas de malsato!"],[15,18,"Mi leviĝos, kaj iros al mia patro, kaj mi diros al li: Patro, mi pekis kontraŭ la ĉielo kaj antaŭ vi;","Mi leviĝos, kaj iros al mia patro, kaj mi diros al li: Patro, mi pekis kontraŭ la ĉielo kaj antaŭ vi;"],[15,19,"mi jam ne meritas esti nomata via filo; faru min kiel unu el viaj dungitoj.","mi jam ne meritas esti nomata via filo; faru min kiel unu el viaj dungitoj."],[15,20,"Kaj li leviĝis, kaj iris al sia patro. Sed kiam li estis ankoraŭ malproksime, lia patro lin vidis kaj kortuŝiĝis, kaj kurinte, falis sur lian kolon kaj lin kisadis.","Kaj li leviĝis, kaj iris al sia patro. Sed kiam li estis ankoraŭ malproksime, lia patro lin vidis kaj kortuŝiĝis, kaj kurinte, falis sur lian kolon kaj lin kisadis."],[15,21,"Kaj la filo diris al li: Patro, mi pekis kontraŭ la ĉielo kaj antaŭ vi, kaj mi jam ne meritas esti nomata via filo.","Kaj la filo diris al li: Patro, mi pekis kontraŭ la ĉielo kaj antaŭ vi, kaj mi jam ne meritas esti nomata via filo."],[15,22,"Kaj diris la patro al siaj servistoj: Alportu rapide la ĉefan robon, kaj lin vestu, kaj metu ringon sur lian manon kaj ŝuojn sur liajn piedojn;","Kaj diris la patro al siaj servistoj: Alportu rapide la ĉefan robon, kaj lin vestu, kaj metu ringon sur lian manon kaj ŝuojn sur liajn piedojn;"],[15,23,"kaj alportu la grasigitan bovidon kaj buĉu ĝin, kaj ni manĝu kaj estu gajaj;","kaj alportu la grasigitan bovidon kaj buĉu ĝin, kaj ni manĝu kaj estu gajaj;"],[15,24,"ĉar ĉi tiu mia filo estis mortinta, kaj denove vivas; li estis perdita, kaj estas trovita. Kaj ili komencis esti gajaj.","ĉar ĉi tiu mia filo estis mortinta, kaj denove vivas; li estis perdita, kaj estas trovita. Kaj ili komencis esti gajaj."],[15,25,"Sed la pli maljuna filo estis sur la kampo; kaj kiam li venis kaj alproksimiĝis al la domo, li aŭdis muzikon kaj dancadon.","Sed la pli maljuna filo estis sur la kampo; kaj kiam li venis kaj alproksimiĝis al la domo, li aŭdis muzikon kaj dancadon."],[15,26,"Kaj li alvokis unu el la knaboj, kaj demandis lin, kio estas tio.","Kaj li alvokis unu el la knaboj, kaj demandis lin, kio estas tio."],[15,27,"Kaj li diris al li: Via frato venis, kaj via patro buĉis la grasigitan bovidon, ĉar li ricevis lin sana.","Kaj li diris al li: Via frato venis, kaj via patro buĉis la grasigitan bovidon, ĉar li ricevis lin sana."],[15,28,"Sed li koleris, kaj ne volis eniri; kaj lia patro elvenis, kaj lin petegis.","Sed li koleris, kaj ne volis eniri; kaj lia patro elvenis, kaj lin petegis."],[15,29,"Sed li responde diris al sia patro: Jen tiom da jaroj mi servas al vi, kaj neniam mi malobeis vian ordonon, tamen vi neniam donis al mi kapridon, por ke mi estu gaja kun miaj amikoj;","Sed li responde diris al sia patro: Jen tiom da jaroj mi servas al vi, kaj neniam mi malobeis vian ordonon, tamen vi neniam donis al mi kapridon, por ke mi estu gaja kun miaj amikoj;"],[15,30,"sed kiam venis ĉi tiu via filo, kiu formanĝis vian havon kun malĉastistinoj, vi buĉis por li la grasigitan bovidon.","sed kiam venis ĉi tiu via filo, kiu formanĝis vian havon kun malĉastistinoj, vi buĉis por li la grasigitan bovidon."],[15,31,"Kaj li diris al li: Filo, vi estas ĉiam kun mi, kaj ĉio mia estas via.","Kaj li diris al li: Filo, vi estas ĉiam kun mi, kaj ĉio mia estas via."],[15,32,"Sed konvenis esti gajaj kaj ĝoji; ĉar ĉi tiu via frato estis mortinta, kaj denove vivas; li estis perdita, kaj estas trovita.","Sed konvenis esti gajaj kaj ĝoji; ĉar ĉi tiu via frato estis mortinta, kaj denove vivas; li estis perdita, kaj estas trovita."],[16,1,"Kaj li diris ankaŭ al siaj disĉiploj: Estis unu riĉa homo, kiu havis administranton; kaj ĉi tiu estis denuncita al li, ke li disperdas lian havon.","Kaj li diris ankaŭ al siaj disĉiploj: Estis unu riĉa homo, kiu havis administranton; kaj ĉi tiu estis denuncita al li, ke li disperdas lian havon."],[16,2,"Kaj li alvokis lin, kaj diris al li: Kio estas tio, kion mi aŭdas pri vi? donu al mi konton de via administrado, ĉar vi ne plu povas administradi.","Kaj li alvokis lin, kaj diris al li: Kio estas tio, kion mi aŭdas pri vi? donu al mi konton de via administrado, ĉar vi ne plu povas administradi."],[16,3,"Tiam la administranto diris en si: Kion mi faru? ĉar mia sinjoro deprenas de mi la administradon; fosi mi ne povas, kaj mi hontas peti almozon.","Tiam la administranto diris en si: Kion mi faru? ĉar mia sinjoro deprenas de mi la administradon; fosi mi ne povas, kaj mi hontas peti almozon."],[16,4,"Mi decidis, kion mi faros, por ke oni akceptu min en siajn domojn, kiam mi estos eksigita el la administra ofico.","Mi decidis, kion mi faros, por ke oni akceptu min en siajn domojn, kiam mi estos eksigita el la administra ofico."],[16,5,"Kaj alvokinte al si ĉiun el la ŝuldantoj de sia sinjoro, li diris al la unua: Kiom vi ŝuldas al mia sinjoro?","Kaj alvokinte al si ĉiun el la ŝuldantoj de sia sinjoro, li diris al la unua: Kiom vi ŝuldas al mia sinjoro?"],[16,6,"Kaj li diris: Cent bat’ojn da oleo. Kaj li diris al li: Prenu vian kalkulon, kaj tuj sidiĝu kaj skribu kvindek.","Kaj li diris: Cent bat’ojn da oleo. Kaj li diris al li: Prenu vian kalkulon, kaj tuj sidiĝu kaj skribu kvindek."],[16,7,"Tiam li diris al alia: Kaj kiom vi ŝuldas? Kaj li diris: Cent kor’ojn da tritiko. Li diris al li: Prenu vian kalkulon, kaj skribu okdek.","Tiam li diris al alia: Kaj kiom vi ŝuldas? Kaj li diris: Cent kor’ojn da tritiko. Li diris al li: Prenu vian kalkulon, kaj skribu okdek."],[16,8,"Kaj tiu sinjoro laŭdis la maljustan administranton, ĉar li prudente agis; ĉar la filoj de ĉi tiu mondo estas en sia generacio pli prudentaj, ol la filoj de la lumo.","Kaj tiu sinjoro laŭdis la maljustan administranton, ĉar li prudente agis; ĉar la filoj de ĉi tiu mondo estas en sia generacio pli prudentaj, ol la filoj de la lumo."],[16,9,"Kaj mi diras al vi: Faru al vi amikojn per la mamono de maljusteco, por ke, kiam ĝi mankos, oni akceptu vin en eternajn loĝejojn.","Kaj mi diras al vi: Faru al vi amikojn per la mamono de maljusteco, por ke, kiam ĝi mankos, oni akceptu vin en eternajn loĝejojn."],[16,10,"Kiu estas fidela en la plej malgranda afero, tiu estas fidela ankaŭ en multo; kaj kiu estas maljusta en la plej malgranda, tiu estas ankaŭ maljusta en multo.","Kiu estas fidela en la plej malgranda afero, tiu estas fidela ankaŭ en multo; kaj kiu estas maljusta en la plej malgranda, tiu estas ankaŭ maljusta en multo."],[16,11,"Se do vi ne estis fidelaj en la maljusta mamono, kiu konfidos al vi la veran riĉon?","Se do vi ne estis fidelaj en la maljusta mamono, kiu konfidos al vi la veran riĉon?"],[16,12,"Kaj se vi ne estis fidelaj en tio, kio apartenas al alia homo, kiu donos al vi tion, kio estas via propra?","Kaj se vi ne estis fidelaj en tio, kio apartenas al alia homo, kiu donos al vi tion, kio estas via propra?"],[16,13,"Nenia servanto povas servi al du sinjoroj; ĉar aŭ li malamos unu kaj amos la alian, aŭ li aliĝos al unu kaj malestimos la alian. Vi ne povas servi al Dio kaj al Mamono!","Nenia servanto povas servi al du sinjoroj; ĉar aŭ li malamos unu kaj amos la alian, aŭ li aliĝos al unu kaj malestimos la alian. Vi ne povas servi al Dio kaj al Mamono!"],[16,14,"Kaj la Fariseoj ankaŭ, kiuj estis monavidaj, aŭdis ĉion tion, kaj ili lin mokis.","Kaj la Fariseoj ankaŭ, kiuj estis monavidaj, aŭdis ĉion tion, kaj ili lin mokis."],[16,15,"Kaj li diris al ili: Vi estas tiuj, kiuj ŝajnigas sin justaj antaŭ homoj, sed Dio scias viajn korojn; ĉar kio estas altigita inter homoj, tio estas abomenaĵo antaŭ Dio.","Kaj li diris al ili: Vi estas tiuj, kiuj ŝajnigas sin justaj antaŭ homoj, sed Dio scias viajn korojn; ĉar kio estas altigita inter homoj, tio estas abomenaĵo antaŭ Dio."],[16,16,"La leĝo kaj la profetoj estis ĝis Johano; de post tiu tempo la evangelio de la regno de Dio estas predikata, kaj ĉiu al ĝi sin perforte aligas.","La leĝo kaj la profetoj estis ĝis Johano; de post tiu tempo la evangelio de la regno de Dio estas predikata, kaj ĉiu al ĝi sin perforte aligas."],[16,17,"Sed estas pli facile por la ĉielo kaj la tero forpasi, ol por unu punkteto de la leĝo fali.","Sed estas pli facile por la ĉielo kaj la tero forpasi, ol por unu punkteto de la leĝo fali."],[16,18,"Ĉiu, kiu forsendas sian edzinon kaj edziĝas kun alia, adultas; kaj kiu edziĝas kun tiu, forsendita de sia edzo, tiu adultas.","Ĉiu, kiu forsendas sian edzinon kaj edziĝas kun alia, adultas; kaj kiu edziĝas kun tiu, forsendita de sia edzo, tiu adultas."],[16,19,"Estis unu riĉulo, kiu estis vestita per purpuro kaj bisino, kaj festis lukse ĉiutage;","Estis unu riĉulo, kiu estis vestita per purpuro kaj bisino, kaj festis lukse ĉiutage;"],[16,20,"kaj apud lia pordego estis kuŝigita almozulo, nomata Lazaro, kiu havis ulcerojn,","kaj apud lia pordego estis kuŝigita almozulo, nomata Lazaro, kiu havis ulcerojn,"],[16,21,"kaj deziris esti nutrata per la panpecetoj, kiuj falis de la tablo de la riĉulo; kaj eĉ venis la hundoj kaj lekis liajn ulcerojn.","kaj deziris esti nutrata per la panpecetoj, kiuj falis de la tablo de la riĉulo; kaj eĉ venis la hundoj kaj lekis liajn ulcerojn."],[16,22,"Kaj la almozulo mortis, kaj li estis forportita de la anĝeloj sur la sinon de Abraham; la riĉulo ankaŭ mortis, kaj estis enterigita.","Kaj la almozulo mortis, kaj li estis forportita de la anĝeloj sur la sinon de Abraham; la riĉulo ankaŭ mortis, kaj estis enterigita."],[16,23,"Kaj en Hades li levis siajn okulojn, estante en turmentoj, kaj vidis Abrahamon malproksime kaj Lazaron sur lia sino.","Kaj en Hades li levis siajn okulojn, estante en turmentoj, kaj vidis Abrahamon malproksime kaj Lazaron sur lia sino."],[16,24,"Kaj li ekkriis, kaj diris: Patro Abraham, kompatu min, kaj sendu Lazaron, por ke li trempu en akvon la pinton de sia fingro, por malvarmigi mian langon; ĉar mi tre suferas en ĉi tiu flamo.","Kaj li ekkriis, kaj diris: Patro Abraham, kompatu min, kaj sendu Lazaron, por ke li trempu en akvon la pinton de sia fingro, por malvarmigi mian langon; ĉar mi tre suferas en ĉi tiu flamo."],[16,25,"Sed Abraham diris: Filo, memoru, ke dum via vivo vi ricevis viajn bonaĵojn, kaj Lazaro tiel same malbonaĵojn; sed nun li ricevas konsolon, kaj vi suferas.","Sed Abraham diris: Filo, memoru, ke dum via vivo vi ricevis viajn bonaĵojn, kaj Lazaro tiel same malbonaĵojn; sed nun li ricevas konsolon, kaj vi suferas."],[16,26,"Kaj krom ĉio tio staras granda abismo inter ni kaj vi, tiel ke tiuj, kiuj volus iri de ĉi tie al vi, ne povas, kaj oni ne povas transiri de tie al ni.","Kaj krom ĉio tio staras granda abismo inter ni kaj vi, tiel ke tiuj, kiuj volus iri de ĉi tie al vi, ne povas, kaj oni ne povas transiri de tie al ni."],[16,27,"Kaj li diris: Tial mi petas, patro, ke vi sendu lin al la domo de mia patro,","Kaj li diris: Tial mi petas, patro, ke vi sendu lin al la domo de mia patro,"],[16,28,"ĉar mi havas kvin fratojn, por ke li atestu al ili, por ke ili ne venu ankaŭ en ĉi tiun lokon de turmento.","ĉar mi havas kvin fratojn, por ke li atestu al ili, por ke ili ne venu ankaŭ en ĉi tiun lokon de turmento."],[16,29,"Sed Abraham diris: Ili havas Moseon kaj la profetojn; ili aŭskultu ilin.","Sed Abraham diris: Ili havas Moseon kaj la profetojn; ili aŭskultu ilin."],[16,30,"Sed li diris: Ne, patro Abraham; sed se unu venos al ili el la mortintoj, ili pentos.","Sed li diris: Ne, patro Abraham; sed se unu venos al ili el la mortintoj, ili pentos."],[16,31,"Kaj li diris al li: Se ili ne aŭskultas Moseon kaj la profetojn, ili ne kredos, eĉ se iu leviĝus el la mortintoj.","Kaj li diris al li: Se ili ne aŭskultas Moseon kaj la profetojn, ili ne kredos, eĉ se iu leviĝus el la mortintoj."],[17,1,"Kaj li diris al siaj disĉiploj: Ne povas esti, ke faliloj ne venos, sed ve al tiu, per kiu ili venos!","Kaj li diris al siaj disĉiploj: Ne povas esti, ke faliloj ne venos, sed ve al tiu, per kiu ili venos!"],[17,2,"Pli bone estus por tiu, se muelŝtono estus pendigita ĉirkaŭ lia kolo, kaj se li estus ĵetita en la maron, ol se li metus falilon por unu el ĉi tiuj malgranduloj.","Pli bone estus por tiu, se muelŝtono estus pendigita ĉirkaŭ lia kolo, kaj se li estus ĵetita en la maron, ol se li metus falilon por unu el ĉi tiuj malgranduloj."],[17,3,"Gardu vin; se via frato pekos, admonu lin; kaj se li pentos, pardonu lin.","Gardu vin; se via frato pekos, admonu lin; kaj se li pentos, pardonu lin."],[17,4,"Kaj se li pekos kontraŭ vi sep fojojn en la tago, kaj sep fojojn turniĝos al vi, dirante: Mi pentas; vi lin pardonu.","Kaj se li pekos kontraŭ vi sep fojojn en la tago, kaj sep fojojn turniĝos al vi, dirante: Mi pentas; vi lin pardonu."],[17,5,"Kaj la apostoloj diris al la Sinjoro: Aldonu al ni fidon.","Kaj la apostoloj diris al la Sinjoro: Aldonu al ni fidon."],[17,6,"Kaj la Sinjoro diris: Se vi havus fidon kiel semeron de sinapo, vi dirus al ĉi tiu morusarbo: Estu elradikigita, kaj estu plantita en la maron; kaj ĝi obeus al vi.","Kaj la Sinjoro diris: Se vi havus fidon kiel semeron de sinapo, vi dirus al ĉi tiu morusarbo: Estu elradikigita, kaj estu plantita en la maron; kaj ĝi obeus al vi."],[17,7,"Sed kiu el vi, havante serviston plugantan aŭ paŝtantan, diros al li, kiam li envenis de la kampo: Tuj venu, kaj sidiĝu, por manĝi?","Sed kiu el vi, havante serviston plugantan aŭ paŝtantan, diros al li, kiam li envenis de la kampo: Tuj venu, kaj sidiĝu, por manĝi?"],[17,8,"Ĉu li ne diros al li prefere: Preparu ion, por ke mi verspermanĝu, kaj zonu vin, kaj servu al mi, dum mi manĝos kaj trinkos; kaj poste vi manĝos kaj trinkos?","Ĉu li ne diros al li prefere: Preparu ion, por ke mi verspermanĝu, kaj zonu vin, kaj servu al mi, dum mi manĝos kaj trinkos; kaj poste vi manĝos kaj trinkos?"],[17,9,"Ĉu li dankas la serviston, ĉar li faris tion, kio estis ordonita?","Ĉu li dankas la serviston, ĉar li faris tion, kio estis ordonita?"],[17,10,"Tiel ankaŭ vi, kiam vi faris ĉion, kio estas ordonita al vi, diru: Ni estas senutilaj servistoj; ni faris tion, kion fari estis nia devo.","Tiel ankaŭ vi, kiam vi faris ĉion, kio estas ordonita al vi, diru: Ni estas senutilaj servistoj; ni faris tion, kion fari estis nia devo."],[17,11,"Kaj dum ili vojiris al Jerusalem, li trapasis tra la mezo de Samario kaj de Galileo.","Kaj dum ili vojiris al Jerusalem, li trapasis tra la mezo de Samario kaj de Galileo."],[17,12,"Kaj kiam ili eniris en unu vilaĝon, renkontis lin dek lepruloj, kiuj staris malproksime;","Kaj kiam ili eniris en unu vilaĝon, renkontis lin dek lepruloj, kiuj staris malproksime;"],[17,13,"kaj ili levis sian voĉon, dirante: Jesuo, estro, kompatu nin.","kaj ili levis sian voĉon, dirante: Jesuo, estro, kompatu nin."],[17,14,"Kaj vidinte ilin, li diris al ili: Iru, kaj montru vin al la pastroj. Kaj dum ili iris, ili fariĝis puraj.","Kaj vidinte ilin, li diris al ili: Iru, kaj montru vin al la pastroj. Kaj dum ili iris, ili fariĝis puraj."],[17,15,"Kaj unu el ili, vidinte, ke li resaniĝis, revenis, glorante Dion per laŭta voĉo,","Kaj unu el ili, vidinte, ke li resaniĝis, revenis, glorante Dion per laŭta voĉo,"],[17,16,"kaj falis sur sian vizaĝon ĉe liaj piedoj kaj dankis lin; kaj li estis Samariano.","kaj falis sur sian vizaĝon ĉe liaj piedoj kaj dankis lin; kaj li estis Samariano."],[17,17,"Kaj Jesuo responde diris: Ĉu ne la dek estis purigitaj? sed kie estas la naŭ?","Kaj Jesuo responde diris: Ĉu ne la dek estis purigitaj? sed kie estas la naŭ?"],[17,18,"Ĉu ne troviĝis revenantoj, por doni gloron al Dio, krom ĉi tiu fremdulo?","Ĉu ne troviĝis revenantoj, por doni gloron al Dio, krom ĉi tiu fremdulo?"],[17,19,"Kaj li diris al li: Leviĝu kaj iru; via fido vin savis.","Kaj li diris al li: Leviĝu kaj iru; via fido vin savis."],[17,20,"Kaj kiam la Fariseoj demandis al li, kiam venos la regno de Dio, li respondis al ili, dirante: La regno de Dio ne venas kun observado;","Kaj kiam la Fariseoj demandis al li, kiam venos la regno de Dio, li respondis al ili, dirante: La regno de Dio ne venas kun observado;"],[17,21,"kaj oni ne diros: Jen ĉi tie, aŭ: Jen tie! ĉar jen la regno de Dio estas inter vi.","kaj oni ne diros: Jen ĉi tie, aŭ: Jen tie! ĉar jen la regno de Dio estas inter vi."],[17,22,"Kaj li diris al la disĉiploj: Venos tagoj, kiam vi deziros vidi unu el la tagoj de la Filo de homo, kaj vi ne vidos.","Kaj li diris al la disĉiploj: Venos tagoj, kiam vi deziros vidi unu el la tagoj de la Filo de homo, kaj vi ne vidos."],[17,23,"Kaj ili diros al vi: Jen tie! Jen ĉi tie! Ne foriru, nek sekvu;","Kaj ili diros al vi: Jen tie! Jen ĉi tie! Ne foriru, nek sekvu;"],[17,24,"ĉar kiel la fulmo, kiam ĝi fulmas el unu subĉiela flanko, lumas ĝis alia subĉiela flanko, tiel estos la Filo de homo en sia tago.","ĉar kiel la fulmo, kiam ĝi fulmas el unu subĉiela flanko, lumas ĝis alia subĉiela flanko, tiel estos la Filo de homo en sia tago."],[17,25,"Sed unue li devas multon suferi, kaj esti malŝatata de ĉi tiu generacio.","Sed unue li devas multon suferi, kaj esti malŝatata de ĉi tiu generacio."],[17,26,"Kaj kiel estis en la tagoj de Noa, tiel estos en la tagoj de la Filo de homo.","Kaj kiel estis en la tagoj de Noa, tiel estos en la tagoj de la Filo de homo."],[17,27,"Oni manĝis, trinkis, edziĝis, edziniĝis, ĝis la tago, kiam Noa eniris en la arkeon, kaj venis la diluvo kaj pereigis ĉiujn.","Oni manĝis, trinkis, edziĝis, edziniĝis, ĝis la tago, kiam Noa eniris en la arkeon, kaj venis la diluvo kaj pereigis ĉiujn."],[17,28,"Ankaŭ tiel same, kiel estis en la tagoj de Lot; oni manĝis, trinkis, aĉetis, vendis, plantis, konstruis;","Ankaŭ tiel same, kiel estis en la tagoj de Lot; oni manĝis, trinkis, aĉetis, vendis, plantis, konstruis;"],[17,29,"sed en la tago, kiam Lot eliris el Sodom, fajro kaj sulfuro falis el la ĉielo kaj pereigis ĉiujn;","sed en la tago, kiam Lot eliris el Sodom, fajro kaj sulfuro falis el la ĉielo kaj pereigis ĉiujn;"],[17,30,"tiel same estos en tiu tago, kiam la Filo de homo malkaŝiĝos.","tiel same estos en tiu tago, kiam la Filo de homo malkaŝiĝos."],[17,31,"Kiu estos sur la tegmento en tiu tago, kun liaj havaĵoj en la domo, tiu ne malsupreniru, por ilin forporti; kaj kiu estas sur la kampo, tiu ankaŭ ne revenu.","Kiu estos sur la tegmento en tiu tago, kun liaj havaĵoj en la domo, tiu ne malsupreniru, por ilin forporti; kaj kiu estas sur la kampo, tiu ankaŭ ne revenu."],[17,32,"Memoru la edzinon de Lot.","Memoru la edzinon de Lot."],[17,33,"Kiu penos gajni sian animon, tiu ĝin perdos; sed kiu ĝin perdos, tiu savos ĝin viva.","Kiu penos gajni sian animon, tiu ĝin perdos; sed kiu ĝin perdos, tiu savos ĝin viva."],[17,34,"Mi diras al vi: En tiu nokto estos du viroj sur unu lito; unu estos prenita, kaj la alia lasita.","Mi diras al vi: En tiu nokto estos du viroj sur unu lito; unu estos prenita, kaj la alia lasita."],[17,35,"Du virinoj estos muelantaj kune; unu estos prenita, kaj la alia lasita.","Du virinoj estos muelantaj kune; unu estos prenita, kaj la alia lasita."],[17,36,"Du viroj estos sur kampo; unu estos prenita, kaj la alia lasita.","Du viroj estos sur kampo; unu estos prenita, kaj la alia lasita."],[17,37,"Kaj ili responde diris al li: Kie, Sinjoro? Kaj li diris al ili: Kie estas la kadavro, tien ankaŭ kolektiĝos la agloj.","Kaj ili responde diris al li: Kie, Sinjoro? Kaj li diris al ili: Kie estas la kadavro, tien ankaŭ kolektiĝos la agloj."],[18,1,"Kaj li parolis al ili parabolon pri tio, ke oni devas ĉiam preĝi kaj ne laciĝi,","Kaj li parolis al ili parabolon pri tio, ke oni devas ĉiam preĝi kaj ne laciĝi,"],[18,2,"dirante: En unu urbo estis juĝisto, kiu ne timis Dion, nek respektis homon;","dirante: En unu urbo estis juĝisto, kiu ne timis Dion, nek respektis homon;"],[18,3,"kaj estis vidvino en tiu urbo, kaj ŝi venadis al li, dirante: Faru por mi justecon kontraŭ mia kontraŭulo.","kaj estis vidvino en tiu urbo, kaj ŝi venadis al li, dirante: Faru por mi justecon kontraŭ mia kontraŭulo."],[18,4,"Kaj li ne volis dum kelka tempo, sed poste li diris en si: Kvankam mi ne timas Dion, nek respektas homon,","Kaj li ne volis dum kelka tempo, sed poste li diris en si: Kvankam mi ne timas Dion, nek respektas homon,"],[18,5,"tamen, ĉar ĉi tiu vidvino min ĝenas, mi faros por ŝi justecon, por ke ŝi ne malfortigu min per sia ĉiama venado.","tamen, ĉar ĉi tiu vidvino min ĝenas, mi faros por ŝi justecon, por ke ŝi ne malfortigu min per sia ĉiama venado."],[18,6,"Kaj la Sinjoro diris: Aŭskultu, kion diras la maljusta juĝisto.","Kaj la Sinjoro diris: Aŭskultu, kion diras la maljusta juĝisto."],[18,7,"Kaj ĉu Dio ne faros justecon por Siaj elektitoj, kiuj tage kaj nokte krias al Li, kvankam Li longe pri ili paciencas?","Kaj ĉu Dio ne faros justecon por Siaj elektitoj, kiuj tage kaj nokte krias al Li, kvankam Li longe pri ili paciencas?"],[18,8,"Mi diras al vi: Rapide Li faros por ili justecon. Tamen kiam venos la Filo de homo, ĉu li trovos fidon sur la tero?","Mi diras al vi: Rapide Li faros por ili justecon. Tamen kiam venos la Filo de homo, ĉu li trovos fidon sur la tero?"],[18,9,"Kaj li parolis la jenan parabolon, ankaŭ por iuj, kiuj fidis al si, ke ili estas justuloj, kaj malestimis la ceterajn:","Kaj li parolis la jenan parabolon, ankaŭ por iuj, kiuj fidis al si, ke ili estas justuloj, kaj malestimis la ceterajn:"],[18,10,"Du homoj supreniris en la templon, por preĝi; unu estis Fariseo, kaj la alia estis impostisto.","Du homoj supreniris en la templon, por preĝi; unu estis Fariseo, kaj la alia estis impostisto."],[18,11,"La Fariseo, starante, preĝis kun si jene: Ho Dio, mi Vin dankas, ke mi ne estas kiel la ceteraj homoj, rabemaj, maljustaj, adultemaj, nek eĉ kiel ĉi tiu impostisto.","La Fariseo, starante, preĝis kun si jene: Ho Dio, mi Vin dankas, ke mi ne estas kiel la ceteraj homoj, rabemaj, maljustaj, adultemaj, nek eĉ kiel ĉi tiu impostisto."],[18,12,"Mi fastas dufoje en semajno; mi donas dekonaĵojn el ĉio, kion mi akiras.","Mi fastas dufoje en semajno; mi donas dekonaĵojn el ĉio, kion mi akiras."],[18,13,"Sed la impostisto, starante malproksime, ne volis eĉ levi la okulojn al la ĉielo, sed batadis sian bruston, dirante: Ho Dio, estu favora al mi pekulo.","Sed la impostisto, starante malproksime, ne volis eĉ levi la okulojn al la ĉielo, sed batadis sian bruston, dirante: Ho Dio, estu favora al mi pekulo."],[18,14,"Mi diras al vi: Ĉi tiu malsupreniris al sia domo, pravigita pli ol tiu; ĉar ĉiu, kiu sin altigas, estos humiligita; sed kiu sin humiligas, tiu estos altigita.","Mi diras al vi: Ĉi tiu malsupreniris al sia domo, pravigita pli ol tiu; ĉar ĉiu, kiu sin altigas, estos humiligita; sed kiu sin humiligas, tiu estos altigita."],[18,15,"Kaj oni venigis al li ankaŭ siajn infanetojn, por ke li tuŝu ilin; kaj la disĉiploj, vidinte, admonis ilin.","Kaj oni venigis al li ankaŭ siajn infanetojn, por ke li tuŝu ilin; kaj la disĉiploj, vidinte, admonis ilin."],[18,16,"Sed Jesuo alvokis ilin al si, dirante: Lasu la infanojn veni al mi, kaj ne malhelpu ilin; ĉar el tiaj estas la regno de Dio.","Sed Jesuo alvokis ilin al si, dirante: Lasu la infanojn veni al mi, kaj ne malhelpu ilin; ĉar el tiaj estas la regno de Dio."],[18,17,"Vere mi diras al vi: Kiu ne akceptos la regnon de Dio kiel infano, tiu neniel eniros en ĝin.","Vere mi diras al vi: Kiu ne akceptos la regnon de Dio kiel infano, tiu neniel eniros en ĝin."],[18,18,"Kaj unu reganto demandis al li, dirante: Bona Majstro, kion mi faru, por heredi eternan vivon?","Kaj unu reganto demandis al li, dirante: Bona Majstro, kion mi faru, por heredi eternan vivon?"],[18,19,"Kaj Jesuo diris al li: Kial vi nomas min bona? neniu estas bona krom Unu, nome Dio.","Kaj Jesuo diris al li: Kial vi nomas min bona? neniu estas bona krom Unu, nome Dio."],[18,20,"Vi scias la ordonojn: Ne adultu; Ne mortigu; Ne ŝtelu; Ne parolu malveran ateston; Respektu vian patron kaj vian patrinon.","Vi scias la ordonojn: Ne adultu; Ne mortigu; Ne ŝtelu; Ne parolu malveran ateston; Respektu vian patron kaj vian patrinon."],[18,21,"Kaj li diris: Ĉion tion mi observis detempe de mia juneco.","Kaj li diris: Ĉion tion mi observis detempe de mia juneco."],[18,22,"Kaj Jesuo, aŭdinte, diris al li: Ankoraŭ unu mankon vi havas: vendu ĉion, kion vi posedas, kaj disdonu al malriĉuloj, kaj vi havos trezoron en la ĉielo; kaj venu, sekvu min.","Kaj Jesuo, aŭdinte, diris al li: Ankoraŭ unu mankon vi havas: vendu ĉion, kion vi posedas, kaj disdonu al malriĉuloj, kaj vi havos trezoron en la ĉielo; kaj venu, sekvu min."],[18,23,"Sed aŭdinte tion, li fariĝis tre malĝoja; ĉar li estis tre riĉa.","Sed aŭdinte tion, li fariĝis tre malĝoja; ĉar li estis tre riĉa."],[18,24,"Kaj Jesuo, lin rigardante, diris: Kiel malfacile tiuj, kiuj havas riĉon, eniros en la regnon de Dio!","Kaj Jesuo, lin rigardante, diris: Kiel malfacile tiuj, kiuj havas riĉon, eniros en la regnon de Dio!"],[18,25,"Ĉar estas pli facile por kamelo iri tra trueton de kudrilo, ol por riĉulo eniri en la regnon de Dio.","Ĉar estas pli facile por kamelo iri tra trueton de kudrilo, ol por riĉulo eniri en la regnon de Dio."],[18,26,"Kaj tiuj, kiuj tion aŭdis, diris: Kiu do povos esti savita?","Kaj tiuj, kiuj tion aŭdis, diris: Kiu do povos esti savita?"],[18,27,"Sed li diris: Kio estas neebla ĉe homoj, tio estas ebla ĉe Dio.","Sed li diris: Kio estas neebla ĉe homoj, tio estas ebla ĉe Dio."],[18,28,"Kaj Petro diris: Jen ni forlasis niajn propraĵojn, kaj sekvis vin.","Kaj Petro diris: Jen ni forlasis niajn propraĵojn, kaj sekvis vin."],[18,29,"Kaj li diris al ili: Vere mi diras al vi: Estas neniu, kiu forlasis domon aŭ edzinon aŭ fratojn aŭ gepatrojn aŭ infanojn pro la regno de Dio,","Kaj li diris al ili: Vere mi diras al vi: Estas neniu, kiu forlasis domon aŭ edzinon aŭ fratojn aŭ gepatrojn aŭ infanojn pro la regno de Dio,"],[18,30,"kaj kiu ne ricevos multoble en ĉi tiu tempo, kaj en la venonta mondo vivon eternan.","kaj kiu ne ricevos multoble en ĉi tiu tempo, kaj en la venonta mondo vivon eternan."],[18,31,"Kaj preninte al si la dek du, li diris al ili: Jen ni supreniras al Jerusalem; kaj ĉio skribita per la profetoj estos plenumita al la Filo de homo.","Kaj preninte al si la dek du, li diris al ili: Jen ni supreniras al Jerusalem; kaj ĉio skribita per la profetoj estos plenumita al la Filo de homo."],[18,32,"Ĉar li estos transdonita al la nacianoj, kaj mokita kaj perfortita kaj surkraĉita;","Ĉar li estos transdonita al la nacianoj, kaj mokita kaj perfortita kaj surkraĉita;"],[18,33,"kaj ili skurĝos kaj mortigos lin; kaj la trian tagon li releviĝos.","kaj ili skurĝos kaj mortigos lin; kaj la trian tagon li releviĝos."],[18,34,"Kaj ili komprenis nenion el tio, kaj ĉi tiu parolo estis kaŝita for de ili, kaj ili ne sciis la dirojn.","Kaj ili komprenis nenion el tio, kaj ĉi tiu parolo estis kaŝita for de ili, kaj ili ne sciis la dirojn."],[18,35,"Kaj kiam li alproksimiĝis al Jeriĥo, unu blindulo sidis apud la vojo, petante almozojn;","Kaj kiam li alproksimiĝis al Jeriĥo, unu blindulo sidis apud la vojo, petante almozojn;"],[18,36,"kaj aŭdinte homamason preterirantan, li demandis, kio estas tio.","kaj aŭdinte homamason preterirantan, li demandis, kio estas tio."],[18,37,"Kaj oni diris al li, ke Jesuo, la Nazaretano, preteriras.","Kaj oni diris al li, ke Jesuo, la Nazaretano, preteriras."],[18,38,"Kaj li kriis, dirante: Jesuo, filo de David, kompatu min.","Kaj li kriis, dirante: Jesuo, filo de David, kompatu min."],[18,39,"Kaj la antaŭirantoj admonis lin, ke li silentu; sed li des pli forte kriis: Ho filo de David, kompatu min!","Kaj la antaŭirantoj admonis lin, ke li silentu; sed li des pli forte kriis: Ho filo de David, kompatu min!"],[18,40,"Kaj Jesuo haltis, kaj ordonis alkonduki lin; kaj kiam li alproksimiĝis, li lin demandis:","Kaj Jesuo haltis, kaj ordonis alkonduki lin; kaj kiam li alproksimiĝis, li lin demandis:"],[18,41,"Kion vi volas, ke mi faru al vi? Kaj li diris: Sinjoro, ke mi ricevu vidpovon.","Kion vi volas, ke mi faru al vi? Kaj li diris: Sinjoro, ke mi ricevu vidpovon."],[18,42,"Kaj Jesuo diris al li: Ricevu vidpovon; via fido vin savis.","Kaj Jesuo diris al li: Ricevu vidpovon; via fido vin savis."],[18,43,"Kaj li tuj ricevis vidpovon, kaj sekvis lin, glorante Dion; kaj la tuta popolo, vidinte tion, donis laŭdon al Dio.","Kaj li tuj ricevis vidpovon, kaj sekvis lin, glorante Dion; kaj la tuta popolo, vidinte tion, donis laŭdon al Dio."],[19,1,"Kaj li eniris en Jeriĥon kaj ĝin trapasis.","Kaj li eniris en Jeriĥon kaj ĝin trapasis."],[19,2,"Kaj jen viro, nomata Zakĥeo; kaj li estis ĉefimpostisto, kaj li estis riĉa.","Kaj jen viro, nomata Zakĥeo; kaj li estis ĉefimpostisto, kaj li estis riĉa."],[19,3,"Kaj li penis vidi Jesuon, kia homo li estas; kaj li ne povis pro la homamaso, ĉar li estis malgranda je staturo.","Kaj li penis vidi Jesuon, kia homo li estas; kaj li ne povis pro la homamaso, ĉar li estis malgranda je staturo."],[19,4,"Kaj antaŭkurinte antaŭen, li supreniris sur sikomorarbon, por lin vidi; ĉar li estis preterpasonta tie.","Kaj antaŭkurinte antaŭen, li supreniris sur sikomorarbon, por lin vidi; ĉar li estis preterpasonta tie."],[19,5,"Kaj kiam Jesuo venis al la loko, li suprenrigardis, kaj diris al li: Zakĥeo, rapide malsupreniru, ĉar hodiaŭ mi devas loĝi en via domo.","Kaj kiam Jesuo venis al la loko, li suprenrigardis, kaj diris al li: Zakĥeo, rapide malsupreniru, ĉar hodiaŭ mi devas loĝi en via domo."],[19,6,"Kaj li rapide malsupreniris, kaj akceptis lin ĝoje.","Kaj li rapide malsupreniris, kaj akceptis lin ĝoje."],[19,7,"Kaj vidinte, ĉiuj murmuris, dirante: Ĉe pekulo li eniris, por gasti.","Kaj vidinte, ĉiuj murmuris, dirante: Ĉe pekulo li eniris, por gasti."],[19,8,"Kaj Zakĥeo, starante, diris al la Sinjoro: Jen duonon de miaj posedaĵoj, Sinjoro, mi donacas al la malriĉuloj; kaj se el iu mi maljuste eldevigis ion, mi redonas kvaroblon.","Kaj Zakĥeo, starante, diris al la Sinjoro: Jen duonon de miaj posedaĵoj, Sinjoro, mi donacas al la malriĉuloj; kaj se el iu mi maljuste eldevigis ion, mi redonas kvaroblon."],[19,9,"Kaj Jesuo diris al li: Hodiaŭ venis savo al ĉi tiu domo, ĉar li ankaŭ estas filo de Abraham.","Kaj Jesuo diris al li: Hodiaŭ venis savo al ĉi tiu domo, ĉar li ankaŭ estas filo de Abraham."],[19,10,"Ĉar la Filo de homo venis, por serĉi kaj savi la perditaĵon.","Ĉar la Filo de homo venis, por serĉi kaj savi la perditaĵon."],[19,11,"Kaj kiam oni aŭdis tion, li parolis ankoraŭ parabolon, ĉar li estis proksime al Jerusalem, kaj oni supozis, ke la regno de Dio tuj aperos.","Kaj kiam oni aŭdis tion, li parolis ankoraŭ parabolon, ĉar li estis proksime al Jerusalem, kaj oni supozis, ke la regno de Dio tuj aperos."],[19,12,"Li do diris: Unu nobelo forvojaĝis en malproksiman landon, por ricevi al si regnon, kaj reveni.","Li do diris: Unu nobelo forvojaĝis en malproksiman landon, por ricevi al si regnon, kaj reveni."],[19,13,"Kaj vokinte al si dek siajn servistojn, li donis al ili dek min’ojn, kaj diris al ili: Negocadu, ĝis mi revenos.","Kaj vokinte al si dek siajn servistojn, li donis al ili dek min’ojn, kaj diris al ili: Negocadu, ĝis mi revenos."],[19,14,"Sed liaj regnanoj lin malamis, kaj sendis delegitaron post li, dirante: Ni ne volas, ke tiu viro reĝu super ni.","Sed liaj regnanoj lin malamis, kaj sendis delegitaron post li, dirante: Ni ne volas, ke tiu viro reĝu super ni."],[19,15,"Kaj kiam li revenis, ricevinte la regnon, li ordonis voki al li tiujn servistojn, al kiuj li donis la monon, por ke li sciiĝu, kiom ili gajnis per negocado.","Kaj kiam li revenis, ricevinte la regnon, li ordonis voki al li tiujn servistojn, al kiuj li donis la monon, por ke li sciiĝu, kiom ili gajnis per negocado."],[19,16,"Kaj venis la unua, kaj diris: Sinjoro, via min’o produktis dek min’ojn.","Kaj venis la unua, kaj diris: Sinjoro, via min’o produktis dek min’ojn."],[19,17,"Kaj li diris al li: Bonege, bona servisto; ĉar vi estis fidela en tre malgranda afero, havu aŭtoritaton super dek urboj.","Kaj li diris al li: Bonege, bona servisto; ĉar vi estis fidela en tre malgranda afero, havu aŭtoritaton super dek urboj."],[19,18,"Kaj venis la dua, kaj diris: Sinjoro, via min’o faris kvin min’ojn.","Kaj venis la dua, kaj diris: Sinjoro, via min’o faris kvin min’ojn."],[19,19,"Li diris ankaŭ al tiu: Vi ankaŭ estu super kvin urboj.","Li diris ankaŭ al tiu: Vi ankaŭ estu super kvin urboj."],[19,20,"Kaj alia venis, kaj diris: Sinjoro, jen via min’o, kiun mi konservis, flankemetitan en viŝtuko;","Kaj alia venis, kaj diris: Sinjoro, jen via min’o, kiun mi konservis, flankemetitan en viŝtuko;"],[19,21,"ĉar mi vin timis, ĉar vi estas homo severa; vi prenas tion, kion vi ne demetis, kaj rikoltas tion, kion vi ne semis.","ĉar mi vin timis, ĉar vi estas homo severa; vi prenas tion, kion vi ne demetis, kaj rikoltas tion, kion vi ne semis."],[19,22,"Li diris al li: El via propra buŝo mi vin juĝos, vi malbona servisto. Vi sciis, ke mi estas homo severa, kiu prenas tion, kion mi ne demetis, kaj rikoltas tion, kion mi ne semis;","Li diris al li: El via propra buŝo mi vin juĝos, vi malbona servisto. Vi sciis, ke mi estas homo severa, kiu prenas tion, kion mi ne demetis, kaj rikoltas tion, kion mi ne semis;"],[19,23,"kial do vi ne donis mian monon en bankon, por ke, reveninte, mi postulu ĝin kun procento?","kial do vi ne donis mian monon en bankon, por ke, reveninte, mi postulu ĝin kun procento?"],[19,24,"Kaj li diris al la apudstarantoj: Forprenu de li la min’on, kaj donu ĝin al tiu, kiu havas la dek min’ojn.","Kaj li diris al la apudstarantoj: Forprenu de li la min’on, kaj donu ĝin al tiu, kiu havas la dek min’ojn."],[19,25,"(Kaj ili diris al li: Sinjoro, li havas dek min’ojn.)","(Kaj ili diris al li: Sinjoro, li havas dek min’ojn.)"],[19,26,"Mi diras al vi, ke al ĉiu, kiu havas, estos donite; kaj for de tiu, kiu ne havas, estos prenita eĉ tio, kion li havas.","Mi diras al vi, ke al ĉiu, kiu havas, estos donite; kaj for de tiu, kiu ne havas, estos prenita eĉ tio, kion li havas."],[19,27,"Cetere tiujn miajn malamikojn, kiuj ne volis, ke mi reĝu super ili, konduku ĉi tien, kaj mortigu ilin antaŭ mi.","Cetere tiujn miajn malamikojn, kiuj ne volis, ke mi reĝu super ili, konduku ĉi tien, kaj mortigu ilin antaŭ mi."],[19,28,"Kaj tion dirinte, li ekiris antaŭe, suprenirante al Jerusalem.","Kaj tion dirinte, li ekiris antaŭe, suprenirante al Jerusalem."],[19,29,"Kaj kiam li alproksimiĝis al Betfage kaj Betania, apud la monto nomata Olivarba, li sendis du el siaj disĉiploj,","Kaj kiam li alproksimiĝis al Betfage kaj Betania, apud la monto nomata Olivarba, li sendis du el siaj disĉiploj,"],[19,30,"dirante: Iru en la kontraŭan vilaĝon, en kiu, enirante, vi trovos azenidon ligitan, sur kiu neniu iam ankoraŭ sidis; ĝin malligu kaj alkonduku.","dirante: Iru en la kontraŭan vilaĝon, en kiu, enirante, vi trovos azenidon ligitan, sur kiu neniu iam ankoraŭ sidis; ĝin malligu kaj alkonduku."],[19,31,"Kaj se iu demandos al vi: Kial vi ĝin malligas? parolu jene: La Sinjoro ĝin bezonas.","Kaj se iu demandos al vi: Kial vi ĝin malligas? parolu jene: La Sinjoro ĝin bezonas."],[19,32,"Kaj la senditoj foriris, kaj trovis, ĝuste kiel li diris al ili.","Kaj la senditoj foriris, kaj trovis, ĝuste kiel li diris al ili."],[19,33,"Kaj dum ili malligis la azenidon, ĝiaj posedantoj diris al ili: Kial vi malligas la azenidon?","Kaj dum ili malligis la azenidon, ĝiaj posedantoj diris al ili: Kial vi malligas la azenidon?"],[19,34,"Kaj ili diris: La Sinjoro ĝin bezonas.","Kaj ili diris: La Sinjoro ĝin bezonas."],[19,35,"Kaj ili alkondukis ĝin al Jesuo; kaj ĵetinte siajn vestojn sur la azenidon, ili sidigis Jesuon sur ĝin.","Kaj ili alkondukis ĝin al Jesuo; kaj ĵetinte siajn vestojn sur la azenidon, ili sidigis Jesuon sur ĝin."],[19,36,"Kaj dum li iris, ili sternis siajn vestojn sur la vojo.","Kaj dum li iris, ili sternis siajn vestojn sur la vojo."],[19,37,"Kaj kiam li jam alproksimiĝis, malsuprenironte la deklivon de la monto Olivarba, la tuta amaso de la disĉiploj komencis ĝoji kaj laŭdi Dion per laŭta voĉo pro ĉiuj potencaĵoj, kiujn ili vidis;","Kaj kiam li jam alproksimiĝis, malsuprenironte la deklivon de la monto Olivarba, la tuta amaso de la disĉiploj komencis ĝoji kaj laŭdi Dion per laŭta voĉo pro ĉiuj potencaĵoj, kiujn ili vidis;"],[19,38,"dirante: Estu benata la Reĝo, kiu venas en la nomo de la Eternulo; paco en la ĉielo kaj gloro en la supera alto.","dirante: Estu benata la Reĝo, kiu venas en la nomo de la Eternulo; paco en la ĉielo kaj gloro en la supera alto."],[19,39,"Kaj iuj Fariseoj el la homamaso diris al li: Majstro, admonu viajn disĉiplojn.","Kaj iuj Fariseoj el la homamaso diris al li: Majstro, admonu viajn disĉiplojn."],[19,40,"Kaj responde li diris: Mi diras al vi, ke se ĉi tiuj silentos, la ŝtonoj ekkrios.","Kaj responde li diris: Mi diras al vi, ke se ĉi tiuj silentos, la ŝtonoj ekkrios."],[19,41,"Kaj kiam li alproksimiĝis, li rigardis la urbon, kaj ploris pro ĝi,","Kaj kiam li alproksimiĝis, li rigardis la urbon, kaj ploris pro ĝi,"],[19,42,"dirante: Ho, se vi mem scius en ĉi tiu tago la aferojn apartenantajn al paco! sed nun ili estas kaŝitaj for de viaj okuloj.","dirante: Ho, se vi mem scius en ĉi tiu tago la aferojn apartenantajn al paco! sed nun ili estas kaŝitaj for de viaj okuloj."],[19,43,"Ĉar venos sur vin tagoj, kiam viaj malamikoj ĉirkaŭbaros vin per palisaro, kaj ronde ĉirkaŭos vin, kaj ĉiuflanke premos vin,","Ĉar venos sur vin tagoj, kiam viaj malamikoj ĉirkaŭbaros vin per palisaro, kaj ronde ĉirkaŭos vin, kaj ĉiuflanke premos vin,"],[19,44,"kaj detruos ĝis la tero vin, kaj viajn infanojn en vi, kaj ne lasos en vi ŝtonon sur ŝtono, pro tio, ke vi ne sciis la tempon de via vizitado.","kaj detruos ĝis la tero vin, kaj viajn infanojn en vi, kaj ne lasos en vi ŝtonon sur ŝtono, pro tio, ke vi ne sciis la tempon de via vizitado."],[19,45,"Kaj enirinte en la templon, li komencis elpeli la vendantojn,","Kaj enirinte en la templon, li komencis elpeli la vendantojn,"],[19,46,"dirante al ili: Estas skribite: Mia domo estos domo de preĝo; sed vi faris ĝin kaverno de rabistoj.","dirante al ili: Estas skribite: Mia domo estos domo de preĝo; sed vi faris ĝin kaverno de rabistoj."],[19,47,"Kaj li instruis tagon post tago en la templo. Sed la ĉefpastroj kaj la skribistoj kaj la ĉefoj de la popolo penadis lin pereigi,","Kaj li instruis tagon post tago en la templo. Sed la ĉefpastroj kaj la skribistoj kaj la ĉefoj de la popolo penadis lin pereigi,"],[19,48,"kaj ne trovis, kion fari, ĉar la tuta popolo tre atente aŭskultis lin.","kaj ne trovis, kion fari, ĉar la tuta popolo tre atente aŭskultis lin."],[20,1,"Kaj en unu el la tagoj, dum li instruis la popolon en la templo kaj predikis la evangelion, la ĉefpastroj kaj la skribistoj venis kun la pliaĝuloj;","Kaj en unu el la tagoj, dum li instruis la popolon en la templo kaj predikis la evangelion, la ĉefpastroj kaj la skribistoj venis kun la pliaĝuloj;"],[20,2,"kaj ili ekparolis, dirante al li: Diru al ni: Laŭ kia aŭtoritato vi ĉi tion faras? aŭ kiu estas tiu, kiu donis al vi tian aŭtoritaton?","kaj ili ekparolis, dirante al li: Diru al ni: Laŭ kia aŭtoritato vi ĉi tion faras? aŭ kiu estas tiu, kiu donis al vi tian aŭtoritaton?"],[20,3,"Kaj responde li diris al ili: Mi ankaŭ faros al vi demandon, kaj diru al mi:","Kaj responde li diris al ili: Mi ankaŭ faros al vi demandon, kaj diru al mi:"],[20,4,"La baptado de Johano, ĉu ĝi estis el la ĉielo, aŭ el homoj?","La baptado de Johano, ĉu ĝi estis el la ĉielo, aŭ el homoj?"],[20,5,"Kaj ili diskutis inter si, dirante: Se ni diros: El la ĉielo; li diros: Kial vi ne kredis al li?","Kaj ili diskutis inter si, dirante: Se ni diros: El la ĉielo; li diros: Kial vi ne kredis al li?"],[20,6,"Sed se ni diros: El homoj; la tuta popolo ŝtonmortigos nin, ĉar ili estas konvinkitaj, ke Johano estis profeto.","Sed se ni diros: El homoj; la tuta popolo ŝtonmortigos nin, ĉar ili estas konvinkitaj, ke Johano estis profeto."],[20,7,"Kaj ili respondis, ke ili ne scias, de kie ĝi estis.","Kaj ili respondis, ke ili ne scias, de kie ĝi estis."],[20,8,"Kaj Jesuo diris al ili: Kaj mi ne diras al vi, laŭ kia aŭtoritato mi faras ĉi tion.","Kaj Jesuo diris al ili: Kaj mi ne diras al vi, laŭ kia aŭtoritato mi faras ĉi tion."],[20,9,"Kaj li komencis paroli al la popolo la jenan parabolon: Unu viro plantis vinberĝardenon, kaj luigis ĝin al kultivistoj, kaj forvojaĝis por longa tempo.","Kaj li komencis paroli al la popolo la jenan parabolon: Unu viro plantis vinberĝardenon, kaj luigis ĝin al kultivistoj, kaj forvojaĝis por longa tempo."],[20,10,"Kaj en la ĝusta tempo li sendis sklavon al la kultivistoj, por ke ili donu al li el la frukto de la vinberejo; sed la kultivistoj skurĝis lin, kaj forsendis lin senhava.","Kaj en la ĝusta tempo li sendis sklavon al la kultivistoj, por ke ili donu al li el la frukto de la vinberejo; sed la kultivistoj skurĝis lin, kaj forsendis lin senhava."],[20,11,"Kaj li sendis ankoraŭ alian sklavon, kaj lin ankaŭ ili skurĝis kaj malhonoris, kaj forsendis lin senhava.","Kaj li sendis ankoraŭ alian sklavon, kaj lin ankaŭ ili skurĝis kaj malhonoris, kaj forsendis lin senhava."],[20,12,"Kaj li sendis ankoraŭ trian, kaj lin ankaŭ ili vundis kaj elĵetis.","Kaj li sendis ankoraŭ trian, kaj lin ankaŭ ili vundis kaj elĵetis."],[20,13,"Kaj la sinjoro de la vinberejo diris: Kion mi faru? Mi sendos mian amatan filon; eble lin ili respektos.","Kaj la sinjoro de la vinberejo diris: Kion mi faru? Mi sendos mian amatan filon; eble lin ili respektos."],[20,14,"Sed kiam la kultivistoj lin vidis, ili diskutis unu kun alia, dirante: Ĉi tiu estas la heredonto; ni lin mortigu, por ke la heredaĵo fariĝu nia.","Sed kiam la kultivistoj lin vidis, ili diskutis unu kun alia, dirante: Ĉi tiu estas la heredonto; ni lin mortigu, por ke la heredaĵo fariĝu nia."],[20,15,"Kaj ili elĵetis lin el la vinberejo kaj lin mortigis. Kion do faros al ili la sinjoro de la vinberejo?","Kaj ili elĵetis lin el la vinberejo kaj lin mortigis. Kion do faros al ili la sinjoro de la vinberejo?"],[20,16,"Li venos kaj pereigos ĉi tiujn kultivistojn, kaj donos la vinberejon al aliaj. Kaj aŭdinte tion, ili diris: Ne tiel estu.","Li venos kaj pereigos ĉi tiujn kultivistojn, kaj donos la vinberejon al aliaj. Kaj aŭdinte tion, ili diris: Ne tiel estu."],[20,17,"Sed li, rigardante ilin, diris: Kio do estas la jena skribitaĵo: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula?","Sed li, rigardante ilin, diris: Kio do estas la jena skribitaĵo: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula?"],[20,18,"Ĉiu, kiu falas sur tiun ŝtonon, rompiĝos; sed sur kiun ĝi falos, tiun ĝi polvigos.","Ĉiu, kiu falas sur tiun ŝtonon, rompiĝos; sed sur kiun ĝi falos, tiun ĝi polvigos."],[20,19,"Kaj la skribistoj kaj ĉefpastroj celis meti manojn sur lin en tiu sama horo, kaj ili timis la popolon; ĉar ili eksciis, ke kontraŭ ili li parolis ĉi tiun parabolon.","Kaj la skribistoj kaj ĉefpastroj celis meti manojn sur lin en tiu sama horo, kaj ili timis la popolon; ĉar ili eksciis, ke kontraŭ ili li parolis ĉi tiun parabolon."],[20,20,"Kaj ili observis lin, kaj elsendis spionojn, kiuj ŝajnigis sin justaj, por ke ili ekkaptu lian parolon, celante transdoni lin al la potenco kaj aŭtoritato de la provincestro.","Kaj ili observis lin, kaj elsendis spionojn, kiuj ŝajnigis sin justaj, por ke ili ekkaptu lian parolon, celante transdoni lin al la potenco kaj aŭtoritato de la provincestro."],[20,21,"Kaj ili demandis lin, dirante: Majstro, ni scias, ke vi prave parolas kaj instruas, kaj ne akceptas ies personon, sed instruas laŭ vero la vojon de Dio:","Kaj ili demandis lin, dirante: Majstro, ni scias, ke vi prave parolas kaj instruas, kaj ne akceptas ies personon, sed instruas laŭ vero la vojon de Dio:"],[20,22,"Ĉu konvenas al ni doni tributon al Cezaro, aŭ ne?","Ĉu konvenas al ni doni tributon al Cezaro, aŭ ne?"],[20,23,"Sed sciante ilian ruzecon, li diris al ili:","Sed sciante ilian ruzecon, li diris al ili:"],[20,24,"Montru al mi denaron. Kies bildon kaj surskribaĵon ĝi portas? Kaj ili respondis: De Cezaro.","Montru al mi denaron. Kies bildon kaj surskribaĵon ĝi portas? Kaj ili respondis: De Cezaro."],[20,25,"Kaj li diris al ili: Tial redonu al Cezaro la propraĵon de Cezaro, kaj al Dio la propraĵon de Dio.","Kaj li diris al ili: Tial redonu al Cezaro la propraĵon de Cezaro, kaj al Dio la propraĵon de Dio."],[20,26,"Kaj ili ne povis ekkapti la diron antaŭ la popolo; kaj ili miris pro lia respondo, kaj silentis.","Kaj ili ne povis ekkapti la diron antaŭ la popolo; kaj ili miris pro lia respondo, kaj silentis."],[20,27,"Kaj venis iuj el la Sadukeoj, kiuj diras, ke ne estas releviĝo; kaj ili demandis lin,","Kaj venis iuj el la Sadukeoj, kiuj diras, ke ne estas releviĝo; kaj ili demandis lin,"],[20,28,"dirante: Majstro, Moseo skribis por ni, ke, se ies frato mortos, havante edzinon, kaj li estas seninfana, lia frato prenu la edzinon kaj naskigu idaron al sia frato.","dirante: Majstro, Moseo skribis por ni, ke, se ies frato mortos, havante edzinon, kaj li estas seninfana, lia frato prenu la edzinon kaj naskigu idaron al sia frato."],[20,29,"Estis do sep fratoj; kaj la unua edziĝis, kaj mortis seninfana;","Estis do sep fratoj; kaj la unua edziĝis, kaj mortis seninfana;"],[20,30,"ankaŭ la dua;","ankaŭ la dua;"],[20,31,"kaj la tria ŝin prenis; kaj tiel same ankaŭ la sep ne lasis infanojn, kaj mortis.","kaj la tria ŝin prenis; kaj tiel same ankaŭ la sep ne lasis infanojn, kaj mortis."],[20,32,"Laste mortis ankaŭ la virino.","Laste mortis ankaŭ la virino."],[20,33,"En la releviĝo do por kiu el ili ŝi estos edzino? ĉar la sep havis ŝin kiel edzinon.","En la releviĝo do por kiu el ili ŝi estos edzino? ĉar la sep havis ŝin kiel edzinon."],[20,34,"Kaj Jesuo diris al ili: La filoj de ĉi tiu mondo edziĝas kaj estas edzigataj;","Kaj Jesuo diris al ili: La filoj de ĉi tiu mondo edziĝas kaj estas edzigataj;"],[20,35,"sed kiuj estas juĝitaj indaj atingi tiun mondon kaj la releviĝon el la mortintoj, tiuj nek edziĝas nek edziniĝas;","sed kiuj estas juĝitaj indaj atingi tiun mondon kaj la releviĝon el la mortintoj, tiuj nek edziĝas nek edziniĝas;"],[20,36,"ĉar ili ne plu povas morti; ĉar ili estas egalaj kun la anĝeloj, kaj estas filoj de Dio, estante filoj de la releviĝo.","ĉar ili ne plu povas morti; ĉar ili estas egalaj kun la anĝeloj, kaj estas filoj de Dio, estante filoj de la releviĝo."],[20,37,"Sed ke la mortintoj leviĝas, Moseo mem montris en la arbetaĵo, kiam li nomis la Eternulon la Dio de Abraham kaj la Dio de Isaak kaj la Dio de Jakob.","Sed ke la mortintoj leviĝas, Moseo mem montris en la arbetaĵo, kiam li nomis la Eternulon la Dio de Abraham kaj la Dio de Isaak kaj la Dio de Jakob."],[20,38,"Li estas Dio ne de mortintoj, sed de la vivantoj, ĉar ĉiuj vivas al Li.","Li estas Dio ne de mortintoj, sed de la vivantoj, ĉar ĉiuj vivas al Li."],[20,39,"Kaj iuj el la skribistoj responde diris: Majstro, vi bone diris.","Kaj iuj el la skribistoj responde diris: Majstro, vi bone diris."],[20,40,"Kaj ili ne plu kuraĝis fari al li demandon.","Kaj ili ne plu kuraĝis fari al li demandon."],[20,41,"Kaj li diris al ili: Kiel oni diras, ke la Kristo estas filo de David?","Kaj li diris al ili: Kiel oni diras, ke la Kristo estas filo de David?"],[20,42,"Ĉar David mem diras en la Psalmaro: La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi,","Ĉar David mem diras en la Psalmaro: La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi,"],[20,43,"Ĝis Mi faros viajn malamikojn benketo por viaj piedoj.","Ĝis Mi faros viajn malamikojn benketo por viaj piedoj."],[20,44,"Tial David nomas lin Sinjoro, kaj kiamaniere li estas lia filo?","Tial David nomas lin Sinjoro, kaj kiamaniere li estas lia filo?"],[20,45,"Kaj dum la tuta popolo aŭskultis, li diris al siaj disĉiploj:","Kaj dum la tuta popolo aŭskultis, li diris al siaj disĉiploj:"],[20,46,"Gardu vin kontraŭ la skribistoj, kiuj amas promenadi en roboj kaj amas salutojn sur la placoj, kaj ĉefseĝojn en la sinagogoj, kaj ĉeflokojn ĉe festenoj;","Gardu vin kontraŭ la skribistoj, kiuj amas promenadi en roboj kaj amas salutojn sur la placoj, kaj ĉefseĝojn en la sinagogoj, kaj ĉeflokojn ĉe festenoj;"],[20,47,"kaj kiuj formanĝas domojn de vidvinoj, kaj por preteksto longe preĝas. Ĉi tiuj ricevos pli severan kondamnon.","kaj kiuj formanĝas domojn de vidvinoj, kaj por preteksto longe preĝas. Ĉi tiuj ricevos pli severan kondamnon."],[21,1,"Kaj ekrigardante, li vidis riĉulojn enĵetantajn siajn donacojn en la monkeston.","Kaj ekrigardante, li vidis riĉulojn enĵetantajn siajn donacojn en la monkeston."],[21,2,"Kaj li vidis unu malriĉan vidvinon enĵetantan tien du leptojn.","Kaj li vidis unu malriĉan vidvinon enĵetantan tien du leptojn."],[21,3,"Kaj li diris: Vere mi diras al vi: Ĉi tiu malriĉa vidvino enĵetis pli multe ol ĉiuj;","Kaj li diris: Vere mi diras al vi: Ĉi tiu malriĉa vidvino enĵetis pli multe ol ĉiuj;"],[21,4,"ĉar ĉiuj tiuj el sia abundo enĵetis en la donacaron; sed ŝi el sia malmultego enĵetis la tutan vivrimedon, kiun ŝi havis.","ĉar ĉiuj tiuj el sia abundo enĵetis en la donacaron; sed ŝi el sia malmultego enĵetis la tutan vivrimedon, kiun ŝi havis."],[21,5,"Kaj kiam iuj parolis pri la templo, ke ĝi estas ornamita per belaj ŝtonoj kaj oferdonoj, li diris:","Kaj kiam iuj parolis pri la templo, ke ĝi estas ornamita per belaj ŝtonoj kaj oferdonoj, li diris:"],[21,6,"Rilate al tio, kion vi vidas, venos tagoj, en kiuj ne estos lasita ĉi tie ŝtono sur ŝtono, kiu ne estos deĵetita.","Rilate al tio, kion vi vidas, venos tagoj, en kiuj ne estos lasita ĉi tie ŝtono sur ŝtono, kiu ne estos deĵetita."],[21,7,"Kaj ili demandis lin, dirante: Majstro, kiam do tio estos? kaj kio estos la signo, kiam tio estos proksima?","Kaj ili demandis lin, dirante: Majstro, kiam do tio estos? kaj kio estos la signo, kiam tio estos proksima?"],[21,8,"Kaj li diris: Gardu vin, ke vi ne estu erarigitaj; ĉar multaj venos en mia nomo, dirante: Mi estas; kaj: La tempo proksimiĝis; ne sekvu ilin.","Kaj li diris: Gardu vin, ke vi ne estu erarigitaj; ĉar multaj venos en mia nomo, dirante: Mi estas; kaj: La tempo proksimiĝis; ne sekvu ilin."],[21,9,"Kaj kiam vi aŭdos pri militoj kaj tumultoj, ne teruriĝu; ĉar tio devas okazi unue, sed ne tuj estos la fino.","Kaj kiam vi aŭdos pri militoj kaj tumultoj, ne teruriĝu; ĉar tio devas okazi unue, sed ne tuj estos la fino."],[21,10,"Tiam li diris al ili: Leviĝos nacio kontraŭ nacio, kaj regno kontraŭ regno;","Tiam li diris al ili: Leviĝos nacio kontraŭ nacio, kaj regno kontraŭ regno;"],[21,11,"kaj estos grandaj tertremoj, kaj en diversaj lokoj malsatoj kaj pestoj; kaj estos teruraĵoj kaj grandaj signoj el la ĉielo.","kaj estos grandaj tertremoj, kaj en diversaj lokoj malsatoj kaj pestoj; kaj estos teruraĵoj kaj grandaj signoj el la ĉielo."],[21,12,"Sed antaŭ ĉio tio oni metos sur vin siajn manojn kaj persekutos vin, transdonante vin al la sinagogoj kaj malliberejoj, kaj kondukante vin antaŭ reĝojn kaj provincestrojn pro mia nomo.","Sed antaŭ ĉio tio oni metos sur vin siajn manojn kaj persekutos vin, transdonante vin al la sinagogoj kaj malliberejoj, kaj kondukante vin antaŭ reĝojn kaj provincestrojn pro mia nomo."],[21,13,"Tio fariĝos por vi atesto.","Tio fariĝos por vi atesto."],[21,14,"Decidu tial en viaj koroj, ne prizorgi antaŭe pri pleda respondo;","Decidu tial en viaj koroj, ne prizorgi antaŭe pri pleda respondo;"],[21,15,"ĉar mi donos al vi buŝon kaj saĝon, kiun ĉiuj viaj atakantoj ne povos rezisti nek kontraŭdiri.","ĉar mi donos al vi buŝon kaj saĝon, kiun ĉiuj viaj atakantoj ne povos rezisti nek kontraŭdiri."],[21,16,"Sed vi estos transdonitaj eĉ de gepatroj kaj fratoj kaj parencoj kaj amikoj; kaj iujn el vi oni mortigos.","Sed vi estos transdonitaj eĉ de gepatroj kaj fratoj kaj parencoj kaj amikoj; kaj iujn el vi oni mortigos."],[21,17,"Kaj vi estos malamataj de ĉiuj pro mia nomo.","Kaj vi estos malamataj de ĉiuj pro mia nomo."],[21,18,"Kaj eĉ unu haro de via kapo ne pereos.","Kaj eĉ unu haro de via kapo ne pereos."],[21,19,"Per via pacienco vi akiros viajn animojn.","Per via pacienco vi akiros viajn animojn."],[21,20,"Sed kiam vi vidos Jerusalemon ĉirkaŭitan de armeoj, tiam sciu, ke ĝia ruiniĝo alproksimiĝis.","Sed kiam vi vidos Jerusalemon ĉirkaŭitan de armeoj, tiam sciu, ke ĝia ruiniĝo alproksimiĝis."],[21,21,"Tiam, kiuj estas en Judujo, tiuj forkuru al la montoj; kaj kiuj estas en ĝia mezo, tiuj elmigru; kaj kiuj estas sur la kamparo, tiuj ne eniru tien.","Tiam, kiuj estas en Judujo, tiuj forkuru al la montoj; kaj kiuj estas en ĝia mezo, tiuj elmigru; kaj kiuj estas sur la kamparo, tiuj ne eniru tien."],[21,22,"Ĉar tiuj estas tagoj de punado, por ke plenumiĝu ĉio, kio estas skribita.","Ĉar tiuj estas tagoj de punado, por ke plenumiĝu ĉio, kio estas skribita."],[21,23,"Ve al la gravedulinoj kaj al la suĉigantinoj en tiuj tagoj! ĉar estos granda manko sur la tero, kaj kolero kontraŭ ĉi tiu popolo.","Ve al la gravedulinoj kaj al la suĉigantinoj en tiuj tagoj! ĉar estos granda manko sur la tero, kaj kolero kontraŭ ĉi tiu popolo."],[21,24,"Kaj ili falos per tranĉrando de glavo, kaj forkaptiĝos en ĉiujn naciojn; kaj Jerusalem estos piedpremata de la nacianoj, ĝis plenumiĝos la tempoj de la nacianoj.","Kaj ili falos per tranĉrando de glavo, kaj forkaptiĝos en ĉiujn naciojn; kaj Jerusalem estos piedpremata de la nacianoj, ĝis plenumiĝos la tempoj de la nacianoj."],[21,25,"Kaj estos signoj en la suno kaj la luno kaj la steloj, kaj sur la tero mizero de nacioj, konsternitaj de la muĝado de la maro kaj la ondegoj;","Kaj estos signoj en la suno kaj la luno kaj la steloj, kaj sur la tero mizero de nacioj, konsternitaj de la muĝado de la maro kaj la ondegoj;"],[21,26,"homoj malfortiĝos de timo kaj de atendado de tio, kio venos sur la mondon; ĉar la potencoj de la ĉielo ŝanceliĝos.","homoj malfortiĝos de timo kaj de atendado de tio, kio venos sur la mondon; ĉar la potencoj de la ĉielo ŝanceliĝos."],[21,27,"Kaj tiam oni vidos la Filon de homo, venantan en nubo kun potenco kaj granda gloro.","Kaj tiam oni vidos la Filon de homo, venantan en nubo kun potenco kaj granda gloro."],[21,28,"Sed kiam tio komencos okazi, rigardu supren kaj levu viajn kapojn, ĉar via elaĉeto alproksimiĝas.","Sed kiam tio komencos okazi, rigardu supren kaj levu viajn kapojn, ĉar via elaĉeto alproksimiĝas."],[21,29,"Kaj li parolis al ili parabolon: Rigardu la figarbon kaj ĉiujn arbojn;","Kaj li parolis al ili parabolon: Rigardu la figarbon kaj ĉiujn arbojn;"],[21,30,"kiam ili ekkreskigas foliojn, vi ekvidas, kaj el vi mem scias, ke la somero jam estas proksima.","kiam ili ekkreskigas foliojn, vi ekvidas, kaj el vi mem scias, ke la somero jam estas proksima."],[21,31,"Tiel same vi, kiam vi vidos, ke tio okazas, tiam sciu, ke la regno de Dio estas proksima.","Tiel same vi, kiam vi vidos, ke tio okazas, tiam sciu, ke la regno de Dio estas proksima."],[21,32,"Vere mi diras al vi: Ĉi tiu generacio ne forpasos, ĝis ĉio plenumiĝos.","Vere mi diras al vi: Ĉi tiu generacio ne forpasos, ĝis ĉio plenumiĝos."],[21,33,"La ĉielo kaj la tero forpasos, sed miaj vortoj ne forpasos.","La ĉielo kaj la tero forpasos, sed miaj vortoj ne forpasos."],[21,34,"Sed gardu vin, por ke viaj koroj ne estu ŝarĝitaj de trosatiĝo kaj ebrieco kaj zorgoj pri vivrimedoj, kaj por ke tiu tago ne venu al vi subite;","Sed gardu vin, por ke viaj koroj ne estu ŝarĝitaj de trosatiĝo kaj ebrieco kaj zorgoj pri vivrimedoj, kaj por ke tiu tago ne venu al vi subite;"],[21,35,"ĉar kiel kaptilo ĝi venos sur ĉiujn, kiuj loĝas sur la supraĵo de la tero.","ĉar kiel kaptilo ĝi venos sur ĉiujn, kiuj loĝas sur la supraĵo de la tero."],[21,36,"Sed viglu en ĉiu tempo, preĝante, ke prosperu al vi saviĝi de ĉio, kio okazos, kaj stari antaŭ la Filo de homo.","Sed viglu en ĉiu tempo, preĝante, ke prosperu al vi saviĝi de ĉio, kio okazos, kaj stari antaŭ la Filo de homo."],[21,37,"Kaj dum la tagoj li instruis en la templo, kaj ĉiunokte li eliris, kaj loĝis sur la monto nomata Olivarba.","Kaj dum la tagoj li instruis en la templo, kaj ĉiunokte li eliris, kaj loĝis sur la monto nomata Olivarba."],[21,38,"Kaj la tuta popolo venis al li frumatene en la templo, por aŭskulti lin.","Kaj la tuta popolo venis al li frumatene en la templo, por aŭskulti lin."],[22,1,"Jam alproksimiĝis la festo de macoj, kiu estas nomata la Pasko.","Jam alproksimiĝis la festo de macoj, kiu estas nomata la Pasko."],[22,2,"Kaj la ĉefpastroj kaj la skribistoj serĉis, kiamaniere ili povu mortigi lin, ĉar ili timis la popolon.","Kaj la ĉefpastroj kaj la skribistoj serĉis, kiamaniere ili povu mortigi lin, ĉar ili timis la popolon."],[22,3,"Kaj Satano eniris en Judason, nomatan Iskariota, kiu estis el la nombro de la dek du.","Kaj Satano eniris en Judason, nomatan Iskariota, kiu estis el la nombro de la dek du."],[22,4,"Kaj li foriris kaj interparolis kun la ĉefpastroj kaj kapitanoj, kiamaniere transdoni lin al ili.","Kaj li foriris kaj interparolis kun la ĉefpastroj kaj kapitanoj, kiamaniere transdoni lin al ili."],[22,5,"Kaj ili ĝojis, kaj konsentis doni al li monon.","Kaj ili ĝojis, kaj konsentis doni al li monon."],[22,6,"Kaj li promesis, kaj serĉis okazon transdoni lin al ili, for de la homamaso.","Kaj li promesis, kaj serĉis okazon transdoni lin al ili, for de la homamaso."],[22,7,"Kaj venis la tago de macoj, kiam oni devis buĉi la Paskon.","Kaj venis la tago de macoj, kiam oni devis buĉi la Paskon."],[22,8,"Kaj li sendis Petron kaj Johanon, dirante: Iru kaj pretigu por ni la Paskon, por ke ni ĝin manĝu.","Kaj li sendis Petron kaj Johanon, dirante: Iru kaj pretigu por ni la Paskon, por ke ni ĝin manĝu."],[22,9,"Kaj ili diris al li: Kie vi volas, ke ni pretigu?","Kaj ili diris al li: Kie vi volas, ke ni pretigu?"],[22,10,"Kaj li diris al ili: Jen kiam vi estos enirintaj en la urbon, vin renkontos viro, portanta kruĉon da akvo; lin sekvu en la domon, en kiun li eniros.","Kaj li diris al ili: Jen kiam vi estos enirintaj en la urbon, vin renkontos viro, portanta kruĉon da akvo; lin sekvu en la domon, en kiun li eniros."],[22,11,"Kaj vi diros al la domomastro: La Majstro diras: Kie estas la gastoĉambro, en kiu mi manĝos la Paskon kun miaj disĉiploj?","Kaj vi diros al la domomastro: La Majstro diras: Kie estas la gastoĉambro, en kiu mi manĝos la Paskon kun miaj disĉiploj?"],[22,12,"Kaj li montros al vi grandan supran ĉambron aranĝitan; tie pretigu.","Kaj li montros al vi grandan supran ĉambron aranĝitan; tie pretigu."],[22,13,"Kaj ili iris kaj trovis tiel, kiel li diris al ili; kaj ili pretigis la Paskon.","Kaj ili iris kaj trovis tiel, kiel li diris al ili; kaj ili pretigis la Paskon."],[22,14,"Kaj kiam alvenis la horo, li sidiĝis, kaj la apostoloj kun li.","Kaj kiam alvenis la horo, li sidiĝis, kaj la apostoloj kun li."],[22,15,"Kaj li diris al ili: Kun deziro mi deziris manĝi ĉi tiun Paskon kun vi, antaŭ ol mi suferos;","Kaj li diris al ili: Kun deziro mi deziris manĝi ĉi tiun Paskon kun vi, antaŭ ol mi suferos;"],[22,16,"ĉar mi diras al vi: Mi ne manĝos ĝin, antaŭ ol ĝi plenumiĝos en la regno de Dio.","ĉar mi diras al vi: Mi ne manĝos ĝin, antaŭ ol ĝi plenumiĝos en la regno de Dio."],[22,17,"Kaj ricevinte kalikon, kaj doninte dankon, li diris: Ĉi tion prenu kaj dividu inter vi;","Kaj ricevinte kalikon, kaj doninte dankon, li diris: Ĉi tion prenu kaj dividu inter vi;"],[22,18,"ĉar mi diras al vi: De nun mi ne trinkos el la frukto de la vinberarbo, ĝis venos la regno de Dio.","ĉar mi diras al vi: De nun mi ne trinkos el la frukto de la vinberarbo, ĝis venos la regno de Dio."],[22,19,"Kaj li prenis panon, kaj doninte dankon, li ĝin dispecigis kaj donis al ili, dirante: Ĉi tio estas mia korpo, kiu estas donita por vi; ĉi tion faru por memorigo pri mi.","Kaj li prenis panon, kaj doninte dankon, li ĝin dispecigis kaj donis al ili, dirante: Ĉi tio estas mia korpo, kiu estas donita por vi; ĉi tion faru por memorigo pri mi."],[22,20,"Sammaniere ankaŭ la kalikon post la vespermanĝo, dirante: Ĉi tiu kaliko estas la nova interligo en mia sango, kiu estas elverŝata por vi.","Sammaniere ankaŭ la kalikon post la vespermanĝo, dirante: Ĉi tiu kaliko estas la nova interligo en mia sango, kiu estas elverŝata por vi."],[22,21,"Sed jen la mano de tiu, kiu min perfidas, estas apud mi sur la tablo.","Sed jen la mano de tiu, kiu min perfidas, estas apud mi sur la tablo."],[22,22,"Ĉar la Filo de homo ja iros, laŭ la antaŭdecido; sed ve al tiu viro, de kiu li estos perfidata!","Ĉar la Filo de homo ja iros, laŭ la antaŭdecido; sed ve al tiu viro, de kiu li estos perfidata!"],[22,23,"Kaj ili komencis diskuti inter si: kiu el ili faros tion.","Kaj ili komencis diskuti inter si: kiu el ili faros tion."],[22,24,"Kaj fariĝis ankaŭ inter ili disputo: kiun el ili oni opinias la plej granda.","Kaj fariĝis ankaŭ inter ili disputo: kiun el ili oni opinias la plej granda."],[22,25,"Kaj li diris al ili: La reĝoj de la nacianoj faras sin sinjoroj super ili; kaj tiujn, kiuj potencas inter ili, oni nomas Bonfarantoj.","Kaj li diris al ili: La reĝoj de la nacianoj faras sin sinjoroj super ili; kaj tiujn, kiuj potencas inter ili, oni nomas Bonfarantoj."],[22,26,"Sed vi ne estu tiaj; sed kiu estas la pli granda el vi, tiu fariĝu kiel la pli juna; kaj tiu, kiu estas ĉefa, kiel la servanto.","Sed vi ne estu tiaj; sed kiu estas la pli granda el vi, tiu fariĝu kiel la pli juna; kaj tiu, kiu estas ĉefa, kiel la servanto."],[22,27,"Ĉar kiu estas la pli granda, la sidanto ĉe manĝo, aŭ la servanto? ĉu ne la sidanto ĉe manĝo? sed mi estas meze de vi kiel la servanto.","Ĉar kiu estas la pli granda, la sidanto ĉe manĝo, aŭ la servanto? ĉu ne la sidanto ĉe manĝo? sed mi estas meze de vi kiel la servanto."],[22,28,"Sed vi estas tiuj, kiuj restadis apud mi en miaj tentoj;","Sed vi estas tiuj, kiuj restadis apud mi en miaj tentoj;"],[22,29,"kaj mi difinas por vi regnon, kiel mia Patro difinis por mi;","kaj mi difinas por vi regnon, kiel mia Patro difinis por mi;"],[22,30,"por ke vi manĝu kaj trinku ĉe mia tablo en mia regno, kaj sidu sur tronoj, juĝante la dek du tribojn de Izrael.","por ke vi manĝu kaj trinku ĉe mia tablo en mia regno, kaj sidu sur tronoj, juĝante la dek du tribojn de Izrael."],[22,31,"Simon, Simon, jen Satano postulis vin ĉiujn, por kribri kiel tritikon;","Simon, Simon, jen Satano postulis vin ĉiujn, por kribri kiel tritikon;"],[22,32,"sed mi preĝis por vi, ke via fido ne ŝanceliĝu; kaj vi, kiam vi konvertiĝos, firmigu viajn fratojn.","sed mi preĝis por vi, ke via fido ne ŝanceliĝu; kaj vi, kiam vi konvertiĝos, firmigu viajn fratojn."],[22,33,"Kaj li diris al li: Sinjoro, vin mi estas preta akompani eĉ al malliberejo kaj al morto.","Kaj li diris al li: Sinjoro, vin mi estas preta akompani eĉ al malliberejo kaj al morto."],[22,34,"Kaj li diris: Mi diras al vi, Petro, koko ne krios hodiaŭ, antaŭ ol vi trifoje malkonfesos, ke vi min konas.","Kaj li diris: Mi diras al vi, Petro, koko ne krios hodiaŭ, antaŭ ol vi trifoje malkonfesos, ke vi min konas."],[22,35,"Kaj li diris al ili: Kiam mi vin elsendis sen monujo kaj sako kaj ŝuoj, ĉu io mankis al vi?","Kaj li diris al ili: Kiam mi vin elsendis sen monujo kaj sako kaj ŝuoj, ĉu io mankis al vi?"],[22,36,"Kaj ili diris: Nenio. Kaj li diris al ili: Sed nun kiu havas monujon, tiu prenu ĝin, kaj ankaŭ sakon; kaj kiu ne havas, tiu vendu sian mantelon kaj aĉetu glavon.","Kaj ili diris: Nenio. Kaj li diris al ili: Sed nun kiu havas monujon, tiu prenu ĝin, kaj ankaŭ sakon; kaj kiu ne havas, tiu vendu sian mantelon kaj aĉetu glavon."],[22,37,"Ĉar mi diras al vi, ke tio, kio estas skribita, devas plenumiĝi pri mi: Kaj li estis alkalkulita al krimuloj; ĉar tio, kio rilatas al mi, havas sian finon.","Ĉar mi diras al vi, ke tio, kio estas skribita, devas plenumiĝi pri mi: Kaj li estis alkalkulita al krimuloj; ĉar tio, kio rilatas al mi, havas sian finon."],[22,38,"Kaj ili diris: Sinjoro, jen estas du glavoj; kaj li diris al ili: Sufiĉas.","Kaj ili diris: Sinjoro, jen estas du glavoj; kaj li diris al ili: Sufiĉas."],[22,39,"Kaj elirinte, li iris laŭ sia kutimo al la monto Olivarba, kaj la disĉiploj lin sekvis.","Kaj elirinte, li iris laŭ sia kutimo al la monto Olivarba, kaj la disĉiploj lin sekvis."],[22,40,"Kaj veninte al la loko, li diris al ili: Preĝu, ke vi ne eniru en tenton.","Kaj veninte al la loko, li diris al ili: Preĝu, ke vi ne eniru en tenton."],[22,41,"Kaj li iris for de ili proksimume ŝtonĵeton, kaj li genuis, kaj preĝis,","Kaj li iris for de ili proksimume ŝtonĵeton, kaj li genuis, kaj preĝis,"],[22,42,"dirante: Patro, se Vi volas, formetu de mi ĉi tiun kalikon; tamen plenumiĝu ne mia volo, sed Via.","dirante: Patro, se Vi volas, formetu de mi ĉi tiun kalikon; tamen plenumiĝu ne mia volo, sed Via."],[22,43,"Kaj aperis antaŭ li anĝelo el la ĉielo, fortigante lin.","Kaj aperis antaŭ li anĝelo el la ĉielo, fortigante lin."],[22,44,"Kaj estante en agonio, li preĝis pli fervore, kaj lia ŝvito fariĝis kiel gutoj da sango, defalantaj sur la teron.","Kaj estante en agonio, li preĝis pli fervore, kaj lia ŝvito fariĝis kiel gutoj da sango, defalantaj sur la teron."],[22,45,"Kaj leviĝinte post la preĝo, li venis al la disĉiploj kaj trovis ilin dormantaj de malĝojo,","Kaj leviĝinte post la preĝo, li venis al la disĉiploj kaj trovis ilin dormantaj de malĝojo,"],[22,46,"kaj diris al ili: Kial vi dormas? leviĝu kaj preĝu, ke vi ne eniru en tenton.","kaj diris al ili: Kial vi dormas? leviĝu kaj preĝu, ke vi ne eniru en tenton."],[22,47,"Dum li ankoraŭ parolis, jen homamaso; kaj tiu, kiu estis nomata Judas, unu el la dek du, iris antaŭ ili, kaj alproksimiĝis al Jesuo, por kisi lin.","Dum li ankoraŭ parolis, jen homamaso; kaj tiu, kiu estis nomata Judas, unu el la dek du, iris antaŭ ili, kaj alproksimiĝis al Jesuo, por kisi lin."],[22,48,"Sed Jesuo diris al li: Judas, ĉu vi perfidas per kiso la Filon de homo?","Sed Jesuo diris al li: Judas, ĉu vi perfidas per kiso la Filon de homo?"],[22,49,"Kaj kiam tiuj, kiuj ĉirkaŭis lin, vidis, kio sekvos, ili diris: Sinjoro, ĉu ni frapu per glavo?","Kaj kiam tiuj, kiuj ĉirkaŭis lin, vidis, kio sekvos, ili diris: Sinjoro, ĉu ni frapu per glavo?"],[22,50,"Kaj unu el ili frapis la sklavon de la ĉefpastro, kaj detranĉis lian dekstran orelon.","Kaj unu el ili frapis la sklavon de la ĉefpastro, kaj detranĉis lian dekstran orelon."],[22,51,"Sed Jesuo responde diris: Permesu tiom. Kaj li tuŝis lian orelon kaj sanigis lin.","Sed Jesuo responde diris: Permesu tiom. Kaj li tuŝis lian orelon kaj sanigis lin."],[22,52,"Kaj Jesuo diris al la ĉefpastroj kaj kapitanoj de la templo kaj pliaĝuloj, kiuj venis kontraŭ lin: Ĉu vi elvenis kun glavoj kaj bastonoj, kvazaŭ kontraŭ rabiston?","Kaj Jesuo diris al la ĉefpastroj kaj kapitanoj de la templo kaj pliaĝuloj, kiuj venis kontraŭ lin: Ĉu vi elvenis kun glavoj kaj bastonoj, kvazaŭ kontraŭ rabiston?"],[22,53,"Kiam mi estis ĉiutage inter vi en la templo, vi ne etendis kontraŭ min viajn manojn; sed ĉi tiu estas via horo, kaj la potenco de mallumo.","Kiam mi estis ĉiutage inter vi en la templo, vi ne etendis kontraŭ min viajn manojn; sed ĉi tiu estas via horo, kaj la potenco de mallumo."],[22,54,"Kaj ili kaptis lin, kaj forkondukinte, venigis lin en la domon de la ĉefpastro. Sed Petro sekvis malproksime.","Kaj ili kaptis lin, kaj forkondukinte, venigis lin en la domon de la ĉefpastro. Sed Petro sekvis malproksime."],[22,55,"Kaj kiam oni ekbruligis fajron meze de la korto kaj sidis kune, Petro sidiĝis meze de ili.","Kaj kiam oni ekbruligis fajron meze de la korto kaj sidis kune, Petro sidiĝis meze de ili."],[22,56,"Kaj unu servantino, vidante lin sidantan en la fajrolumo, kaj fikse rigardinte lin, diris:","Kaj unu servantino, vidante lin sidantan en la fajrolumo, kaj fikse rigardinte lin, diris:"],[22,57,"Ĉi tiu ankaŭ estis kun li. Sed li malkonfesis, dirante: Virino, mi lin ne konas.","Ĉi tiu ankaŭ estis kun li. Sed li malkonfesis, dirante: Virino, mi lin ne konas."],[22,58,"Kaj post iom da tempo alia vidis lin, kaj diris: Vi ankaŭ estas el ili. Sed Petro diris: Viro, mi ne estas.","Kaj post iom da tempo alia vidis lin, kaj diris: Vi ankaŭ estas el ili. Sed Petro diris: Viro, mi ne estas."],[22,59,"Kaj post la daŭro de unu horo proksimume, alia asertis persiste, dirante: Vere, ĉi tiu ankaŭ estis kun li, ĉar li estas Galileano.","Kaj post la daŭro de unu horo proksimume, alia asertis persiste, dirante: Vere, ĉi tiu ankaŭ estis kun li, ĉar li estas Galileano."],[22,60,"Sed Petro diris: Viro, mi ne scias, kion vi diras. Kaj tuj, dum li ankoraŭ parolis, la koko kriis.","Sed Petro diris: Viro, mi ne scias, kion vi diras. Kaj tuj, dum li ankoraŭ parolis, la koko kriis."],[22,61,"Kaj la Sinjoro sin turnis, kaj alrigardis Petron. Kaj Petro ekmemoris la vorton de la Sinjoro, ke li diris al li: Antaŭ ol koko krios hodiaŭ, vi trifoje min malkonfesos.","Kaj la Sinjoro sin turnis, kaj alrigardis Petron. Kaj Petro ekmemoris la vorton de la Sinjoro, ke li diris al li: Antaŭ ol koko krios hodiaŭ, vi trifoje min malkonfesos."],[22,62,"Kaj li eliris, kaj maldolĉe ploris.","Kaj li eliris, kaj maldolĉe ploris."],[22,63,"Kaj tiuj, kiuj gardis Jesuon, lin mokis kaj batis.","Kaj tiuj, kiuj gardis Jesuon, lin mokis kaj batis."],[22,64,"Kaj ili ĉirkaŭkovris lin, kaj demandis lin, dirante: Profetu, kiu vin frapis?","Kaj ili ĉirkaŭkovris lin, kaj demandis lin, dirante: Profetu, kiu vin frapis?"],[22,65,"Kaj per multaj aliaj insultoj ili parolis kontraŭ li.","Kaj per multaj aliaj insultoj ili parolis kontraŭ li."],[22,66,"Kaj tuj kiam tagiĝis la pliaĝularo de la popolo kunvenis, kaj ĉefpastroj kaj skribistoj, kaj ili forkondukis lin antaŭ sian sinedrion, kaj diris:","Kaj tuj kiam tagiĝis la pliaĝularo de la popolo kunvenis, kaj ĉefpastroj kaj skribistoj, kaj ili forkondukis lin antaŭ sian sinedrion, kaj diris:"],[22,67,"Se vi estas la Kristo, diru al ni. Sed li diris al ili: Se mi diros al vi, vi ne kredos;","Se vi estas la Kristo, diru al ni. Sed li diris al ili: Se mi diros al vi, vi ne kredos;"],[22,68,"kaj se mi demandos, vi ne respondos.","kaj se mi demandos, vi ne respondos."],[22,69,"Tamen, de nun la Filo de homo sidos dekstre de la Potenco de Dio.","Tamen, de nun la Filo de homo sidos dekstre de la Potenco de Dio."],[22,70,"Kaj ili ĉiuj demandis: Ĉu vi do estas la Filo de Dio? Kaj li respondis: Vi diras, ke mi estas.","Kaj ili ĉiuj demandis: Ĉu vi do estas la Filo de Dio? Kaj li respondis: Vi diras, ke mi estas."],[22,71,"Kaj ili diris: Pro kio ni bezonas pluan atestadon? ĉar ni mem aŭdis el lia propra buŝo.","Kaj ili diris: Pro kio ni bezonas pluan atestadon? ĉar ni mem aŭdis el lia propra buŝo."],[23,1,"Kaj la tuta ĉeestantaro leviĝis, kaj kondukis lin antaŭ Pilaton.","Kaj la tuta ĉeestantaro leviĝis, kaj kondukis lin antaŭ Pilaton."],[23,2,"Kaj ili komencis akuzi lin, dirante: Ni trovis ĉi tiun viron erariganta nian nacion, kaj malpermesanta pagi tributon al Cezaro, kaj diranta, ke li mem estas Kristo, reĝo.","Kaj ili komencis akuzi lin, dirante: Ni trovis ĉi tiun viron erariganta nian nacion, kaj malpermesanta pagi tributon al Cezaro, kaj diranta, ke li mem estas Kristo, reĝo."],[23,3,"Kaj Pilato demandis lin, dirante: Ĉu vi estas la Reĝo de la Judoj? Kaj li responde al li diris: Vi diras.","Kaj Pilato demandis lin, dirante: Ĉu vi estas la Reĝo de la Judoj? Kaj li responde al li diris: Vi diras."],[23,4,"Kaj Pilato diris al la ĉefpastroj kaj homamasoj: Mi trovas nenian kulpon en ĉi tiu viro.","Kaj Pilato diris al la ĉefpastroj kaj homamasoj: Mi trovas nenian kulpon en ĉi tiu viro."],[23,5,"Sed ili insistis, dirante: Li malkvietigas la popolon, instruante tra la tuta Judujo, kaj komencante de Galileo, eĉ ĝis ĉi tie.","Sed ili insistis, dirante: Li malkvietigas la popolon, instruante tra la tuta Judujo, kaj komencante de Galileo, eĉ ĝis ĉi tie."],[23,6,"Sed kiam Pilato tion aŭdis, li demandis, ĉu la viro estas Galileano.","Sed kiam Pilato tion aŭdis, li demandis, ĉu la viro estas Galileano."],[23,7,"Kaj kiam li sciiĝis, ke li estas el sub la aŭtoritato de Herodo, li sendis lin al Herodo, kiu ankaŭ ĉeestis en Jerusalem en tiuj tagoj.","Kaj kiam li sciiĝis, ke li estas el sub la aŭtoritato de Herodo, li sendis lin al Herodo, kiu ankaŭ ĉeestis en Jerusalem en tiuj tagoj."],[23,8,"Sed Herodo, vidinte Jesuon, treege ĝojis; ĉar de longe li deziris vidi lin, ĉar li jam aŭdis pri li, kaj li esperis vidi ian signon, faritan de li.","Sed Herodo, vidinte Jesuon, treege ĝojis; ĉar de longe li deziris vidi lin, ĉar li jam aŭdis pri li, kaj li esperis vidi ian signon, faritan de li."],[23,9,"Kaj li demandis lin per multaj vortoj, sed li respondis al li nenion.","Kaj li demandis lin per multaj vortoj, sed li respondis al li nenion."],[23,10,"Kaj la ĉefpastroj kaj la skribistoj staris, forte lin akuzante.","Kaj la ĉefpastroj kaj la skribistoj staris, forte lin akuzante."],[23,11,"Kaj Herodo kaj liaj soldatoj malhonoris lin kaj mokis lin, kaj vestinte lin per brilaj vestoj, li resendis lin al Pilato.","Kaj Herodo kaj liaj soldatoj malhonoris lin kaj mokis lin, kaj vestinte lin per brilaj vestoj, li resendis lin al Pilato."],[23,12,"Kaj Herodo kaj Pilato fariĝis amikoj unu kun la alia en tiu sama tago; ĉar antaŭe ili havis inter si malamon.","Kaj Herodo kaj Pilato fariĝis amikoj unu kun la alia en tiu sama tago; ĉar antaŭe ili havis inter si malamon."],[23,13,"Kaj Pilato, kunvokinte la ĉefpastrojn kaj la regantojn kaj la popolon,","Kaj Pilato, kunvokinte la ĉefpastrojn kaj la regantojn kaj la popolon,"],[23,14,"diris al ili: Vi alkondukis antaŭ min ĉi tiun viron, kiel erarigantan la popolon; kaj jen ekzameninte lin antaŭ vi, mi trovis nenian kulpon en ĉi tiu viro rilate tion, pri kio vi lin akuzas;","diris al ili: Vi alkondukis antaŭ min ĉi tiun viron, kiel erarigantan la popolon; kaj jen ekzameninte lin antaŭ vi, mi trovis nenian kulpon en ĉi tiu viro rilate tion, pri kio vi lin akuzas;"],[23,15,"nek Herodo ankaŭ, ĉar li resendis lin al ni; kaj jen nenio inda je morto estas farita de li.","nek Herodo ankaŭ, ĉar li resendis lin al ni; kaj jen nenio inda je morto estas farita de li."],[23,16,"Tial mi lin skurĝos kaj liberigos.","Tial mi lin skurĝos kaj liberigos."],[23,17,"Ĉar li devis liberigi unu al ili dum la festo.","Ĉar li devis liberigi unu al ili dum la festo."],[23,18,"Sed amase ili kriis, dirante: Forigu lin, kaj liberigu al ni Barabason;","Sed amase ili kriis, dirante: Forigu lin, kaj liberigu al ni Barabason;"],[23,19,"kiu pro ribelado farita en la urbo, kaj pro mortigo, estis ĵetita en malliberejon.","kiu pro ribelado farita en la urbo, kaj pro mortigo, estis ĵetita en malliberejon."],[23,20,"Kaj Pilato, volante liberigi Jesuon, denove parolis al ili;","Kaj Pilato, volante liberigi Jesuon, denove parolis al ili;"],[23,21,"sed ili laŭte kriis, dirante: Krucumu, krucumu lin.","sed ili laŭte kriis, dirante: Krucumu, krucumu lin."],[23,22,"Kaj la trian fojon li diris al ili: Kial? kian malbonon faris ĉi tiu? mi trovis en li nenion indan je morto; mi do lin skurĝos kaj liberigos.","Kaj la trian fojon li diris al ili: Kial? kian malbonon faris ĉi tiu? mi trovis en li nenion indan je morto; mi do lin skurĝos kaj liberigos."],[23,23,"Sed ili insistis per grandaj krioj, postulante krucumi lin. Kaj iliaj krioj superfortis.","Sed ili insistis per grandaj krioj, postulante krucumi lin. Kaj iliaj krioj superfortis."],[23,24,"Kaj Pilato donis juĝon, ke plenumiĝu ilia postulo.","Kaj Pilato donis juĝon, ke plenumiĝu ilia postulo."],[23,25,"Kaj li liberigis tiun, kiu pro ribelado kaj mortigo estis ĵetita en malliberejon, kaj kiun ili postulis; sed Jesuon li transdonis al ilia volo.","Kaj li liberigis tiun, kiu pro ribelado kaj mortigo estis ĵetita en malliberejon, kaj kiun ili postulis; sed Jesuon li transdonis al ilia volo."],[23,26,"Kaj kiam ili forkondukis lin, ili kaptis Simonon, Kirenanon, venantan de la kamparo, kaj metis sur lin la krucon, por porti ĝin post Jesuo.","Kaj kiam ili forkondukis lin, ili kaptis Simonon, Kirenanon, venantan de la kamparo, kaj metis sur lin la krucon, por porti ĝin post Jesuo."],[23,27,"Kaj sekvis lin granda amaso de la popolo, kaj de virinoj, kiuj ĝemis kaj lamentis pro li.","Kaj sekvis lin granda amaso de la popolo, kaj de virinoj, kiuj ĝemis kaj lamentis pro li."],[23,28,"Sed Jesuo, turninte sin al ili, diris: Filinoj de Jerusalem, ne ploru pro mi, sed ploru pro vi kaj pro viaj infanoj.","Sed Jesuo, turninte sin al ili, diris: Filinoj de Jerusalem, ne ploru pro mi, sed ploru pro vi kaj pro viaj infanoj."],[23,29,"Ĉar jen venas tagoj, kiam oni diros: Feliĉaj estas la senfruktaj, kaj la ventroj ne naskintaj, kaj la mamoj ne nutrintaj.","Ĉar jen venas tagoj, kiam oni diros: Feliĉaj estas la senfruktaj, kaj la ventroj ne naskintaj, kaj la mamoj ne nutrintaj."],[23,30,"Tiam oni komencos diri al la montoj: Falu sur nin; kaj al la montetoj: Kovru nin.","Tiam oni komencos diri al la montoj: Falu sur nin; kaj al la montetoj: Kovru nin."],[23,31,"Ĉar se oni tiel agas en la suka ligno, kiel oni agos en la seka?","Ĉar se oni tiel agas en la suka ligno, kiel oni agos en la seka?"],[23,32,"Kaj estis kondukataj kun li ankaŭ aliaj du, krimuloj, por esti mortigitaj.","Kaj estis kondukataj kun li ankaŭ aliaj du, krimuloj, por esti mortigitaj."],[23,33,"Kaj kiam ili alvenis al la loko nomata Kranio, tie ili krucumis lin, kaj la krimulojn, unu dekstre kaj unu maldekstre.","Kaj kiam ili alvenis al la loko nomata Kranio, tie ili krucumis lin, kaj la krimulojn, unu dekstre kaj unu maldekstre."],[23,34,"Kaj Jesuo diris: Patro, pardonu ilin; ĉar ili ne scias, kion ili faras. Kaj dividante inter si liajn vestojn, ili ĵetis lotojn.","Kaj Jesuo diris: Patro, pardonu ilin; ĉar ili ne scias, kion ili faras. Kaj dividante inter si liajn vestojn, ili ĵetis lotojn."],[23,35,"Kaj la popolo staris, rigardanta. Kaj la regantoj ankaŭ mokis lin, dirante: Aliajn li savis: li savu sin mem, se ĉi tiu estas la Kristo de Dio, la elektito.","Kaj la popolo staris, rigardanta. Kaj la regantoj ankaŭ mokis lin, dirante: Aliajn li savis: li savu sin mem, se ĉi tiu estas la Kristo de Dio, la elektito."],[23,36,"Kaj ŝercis pri li ankaŭ la soldatoj, venante al li kaj proponante al li vinagron,","Kaj ŝercis pri li ankaŭ la soldatoj, venante al li kaj proponante al li vinagron,"],[23,37,"kaj dirante: Se vi estas la Reĝo de la Judoj, savu vin.","kaj dirante: Se vi estas la Reĝo de la Judoj, savu vin."],[23,38,"Kaj estis ankaŭ surskribo super li: ĈI TIU ESTAS LA REĜO DE LA JUDOJ.","Kaj estis ankaŭ surskribo super li: ĈI TIU ESTAS LA REĜO DE LA JUDOJ."],[23,39,"Kaj unu el la pendigitaj krimuloj insultis lin, dirante: Ĉu vi ne estas la Kristo? savu vin kaj nin.","Kaj unu el la pendigitaj krimuloj insultis lin, dirante: Ĉu vi ne estas la Kristo? savu vin kaj nin."],[23,40,"Sed la alia responde admonis lin, dirante: Ĉu vi eĉ ne timas Dion? ĉar vi estas en la sama kondamno.","Sed la alia responde admonis lin, dirante: Ĉu vi eĉ ne timas Dion? ĉar vi estas en la sama kondamno."],[23,41,"Kaj ni ja juste, ĉar ni ricevas rekompencon, merititan pro niaj faroj; sed ĉi tiu faris nenion malbonan.","Kaj ni ja juste, ĉar ni ricevas rekompencon, merititan pro niaj faroj; sed ĉi tiu faris nenion malbonan."],[23,42,"Kaj li diris: Jesuo, memoru min, kiam vi venos en vian regnon.","Kaj li diris: Jesuo, memoru min, kiam vi venos en vian regnon."],[23,43,"Kaj li diris al li: Vere mi diras al vi: Hodiaŭ vi estos kun mi en Paradizo.","Kaj li diris al li: Vere mi diras al vi: Hodiaŭ vi estos kun mi en Paradizo."],[23,44,"Kaj jam estis ĉirkaŭ la sesa horo, kaj fariĝis mallumo sur la tuta lando ĝis la naŭa, ĉar la sunlumo mankis;","Kaj jam estis ĉirkaŭ la sesa horo, kaj fariĝis mallumo sur la tuta lando ĝis la naŭa, ĉar la sunlumo mankis;"],[23,45,"kaj la kurteno de la sanktejo disŝiriĝis en la mezo.","kaj la kurteno de la sanktejo disŝiriĝis en la mezo."],[23,46,"Kaj kriinte per laŭta voĉo, Jesuo diris: Patro, en Viajn manojn mi transdonas mian spiriton; kaj tion dirinte, li ellasis for la spiriton.","Kaj kriinte per laŭta voĉo, Jesuo diris: Patro, en Viajn manojn mi transdonas mian spiriton; kaj tion dirinte, li ellasis for la spiriton."],[23,47,"Kaj kiam la centestro vidis la okazantaĵon, li gloris Dion, dirante: Ĉi tiu estis ja justulo.","Kaj kiam la centestro vidis la okazantaĵon, li gloris Dion, dirante: Ĉi tiu estis ja justulo."],[23,48,"Kaj ĉiuj homamasoj, kiuj kunvenis al ĉi tiu spektaklo, kiam ili vidis la okazintaĵojn, reiris, frapante al si la bruston.","Kaj ĉiuj homamasoj, kiuj kunvenis al ĉi tiu spektaklo, kiam ili vidis la okazintaĵojn, reiris, frapante al si la bruston."],[23,49,"Kaj ĉiuj liaj konantoj, kaj la virinoj, kiuj sekvis lin el Galileo, staris malproksime, vidante tion.","Kaj ĉiuj liaj konantoj, kaj la virinoj, kiuj sekvis lin el Galileo, staris malproksime, vidante tion."],[23,50,"Kaj jen viro nomata Jozef, kiu estis konsilanto, viro bona kaj justa","Kaj jen viro nomata Jozef, kiu estis konsilanto, viro bona kaj justa"],[23,51,"(li ne konsentis al ilia intenco kaj faro), el Arimateo, urbo de la Judoj, kiu atendis la regnon de Dio,","(li ne konsentis al ilia intenco kaj faro), el Arimateo, urbo de la Judoj, kiu atendis la regnon de Dio,"],[23,52,"irinte al Pilato, petis la korpon de Jesuo.","irinte al Pilato, petis la korpon de Jesuo."],[23,53,"Kaj li deprenis ĝin kaj envolvis ĝin en tolaĵo, kaj metis lin en tombo, elhakita el ŝtono, kie neniu antaŭe kuŝis.","Kaj li deprenis ĝin kaj envolvis ĝin en tolaĵo, kaj metis lin en tombo, elhakita el ŝtono, kie neniu antaŭe kuŝis."],[23,54,"Kaj estis la tago de la Preparado, kaj la sabato eklumis.","Kaj estis la tago de la Preparado, kaj la sabato eklumis."],[23,55,"Kaj la virinoj, kiuj venis kun li el Galileo, sekvis, kaj vidis la tombon, kaj kiamaniere la korpo estis metita.","Kaj la virinoj, kiuj venis kun li el Galileo, sekvis, kaj vidis la tombon, kaj kiamaniere la korpo estis metita."],[23,56,"Kaj ili reiris, kaj preparis aromaĵojn kaj ŝmiraĵojn. Kaj sabate ili ripozis laŭ la ordono.","Kaj ili reiris, kaj preparis aromaĵojn kaj ŝmiraĵojn. Kaj sabate ili ripozis laŭ la ordono."],[24,1,"Kaj la unuan tagon de la semajno, ĉe frua tagiĝo, ili venis al la tombo, alportante la aromaĵojn, kiujn ili preparis.","Kaj la unuan tagon de la semajno, ĉe frua tagiĝo, ili venis al la tombo, alportante la aromaĵojn, kiujn ili preparis."],[24,2,"Kaj ili trovis la ŝtonon derulita for de la tombo.","Kaj ili trovis la ŝtonon derulita for de la tombo."],[24,3,"Kaj enirinte, ili ne trovis la korpon de la Sinjoro Jesuo.","Kaj enirinte, ili ne trovis la korpon de la Sinjoro Jesuo."],[24,4,"Kaj dum ili embarasiĝis pri tio, jen apud ili staris du viroj en brilaj vestoj;","Kaj dum ili embarasiĝis pri tio, jen apud ili staris du viroj en brilaj vestoj;"],[24,5,"kaj dum ili timis kaj kliniĝis vizaĝaltere, tiuj demandis ilin: Kial vi serĉas la vivanton inter la mortintoj?","kaj dum ili timis kaj kliniĝis vizaĝaltere, tiuj demandis ilin: Kial vi serĉas la vivanton inter la mortintoj?"],[24,6,"Li ne estas ĉi tie, sed leviĝis; memoru, kiamaniere li parolis al vi, kiam li estis ankoraŭ en Galileo,","Li ne estas ĉi tie, sed leviĝis; memoru, kiamaniere li parolis al vi, kiam li estis ankoraŭ en Galileo,"],[24,7,"dirante, ke la Filo de homo devas esti transdonita en la manojn de pekuloj kaj esti krucumita, kaj la trian tagon releviĝi.","dirante, ke la Filo de homo devas esti transdonita en la manojn de pekuloj kaj esti krucumita, kaj la trian tagon releviĝi."],[24,8,"Kaj ili rememoris liajn vortojn;","Kaj ili rememoris liajn vortojn;"],[24,9,"kaj reveninte de la tombo, ili rakontis ĉion tion al la dek unu kaj al ĉiuj ceteraj.","kaj reveninte de la tombo, ili rakontis ĉion tion al la dek unu kaj al ĉiuj ceteraj."],[24,10,"Kaj ili estis Maria Magdalena, kaj Joana, kaj Maria, la patrino de Jakobo; kaj la ceteraj virinoj kun ili rakontis tion al la apostoloj.","Kaj ili estis Maria Magdalena, kaj Joana, kaj Maria, la patrino de Jakobo; kaj la ceteraj virinoj kun ili rakontis tion al la apostoloj."],[24,11,"Kaj tiuj vortoj ŝajnis al ili kiel babilado, kaj ili ne kredis al la virinoj.","Kaj tiuj vortoj ŝajnis al ili kiel babilado, kaj ili ne kredis al la virinoj."],[24,12,"Sed Petro leviĝis kaj kuris al la tombo, kaj kliniĝinte, vidis la tolaĵojn solajn, kaj li foriris, mirante en si pri tio, kio okazis.","Sed Petro leviĝis kaj kuris al la tombo, kaj kliniĝinte, vidis la tolaĵojn solajn, kaj li foriris, mirante en si pri tio, kio okazis."],[24,13,"Kaj jen du el ili iris en tiu sama tago al vilaĝo nomata Emaus, kiu estas malproksime de Jerusalem sesdek stadiojn.","Kaj jen du el ili iris en tiu sama tago al vilaĝo nomata Emaus, kiu estas malproksime de Jerusalem sesdek stadiojn."],[24,14,"Kaj ili interparolis inter si pri ĉio tio, kio okazis.","Kaj ili interparolis inter si pri ĉio tio, kio okazis."],[24,15,"Kaj dum ili interparolis kaj diskutis inter si, Jesuo mem alproksimiĝis kaj iris kun ili.","Kaj dum ili interparolis kaj diskutis inter si, Jesuo mem alproksimiĝis kaj iris kun ili."],[24,16,"Sed iliaj okuloj estis malhelpataj tiel, ke ili lin ne rekonis.","Sed iliaj okuloj estis malhelpataj tiel, ke ili lin ne rekonis."],[24,17,"Kaj li diris al ili: Kiaj vortoj estas tiuj, kiujn vi interŝanĝas, dum vi iras? Kaj ili haltis, kun malgaja mieno.","Kaj li diris al ili: Kiaj vortoj estas tiuj, kiujn vi interŝanĝas, dum vi iras? Kaj ili haltis, kun malgaja mieno."],[24,18,"Kaj unu el ili, nomata Kleopas, responde diris al li: Ĉu nur vi sola loĝas en Jerusalem, kaj ne scias tion, kio tie okazis en ĉi tiuj tagoj?","Kaj unu el ili, nomata Kleopas, responde diris al li: Ĉu nur vi sola loĝas en Jerusalem, kaj ne scias tion, kio tie okazis en ĉi tiuj tagoj?"],[24,19,"Kaj li diris al ili: Kion? Kaj ili diris al li: Pri Jesuo, la Nazaretano, kiu estis profeto potenca age kaj parole antaŭ Dio kaj la tuta popolo;","Kaj li diris al ili: Kion? Kaj ili diris al li: Pri Jesuo, la Nazaretano, kiu estis profeto potenca age kaj parole antaŭ Dio kaj la tuta popolo;"],[24,20,"kaj kiel la ĉefpastroj kaj niaj regantoj transdonis lin por kondamno al morto, kaj lin krucumis.","kaj kiel la ĉefpastroj kaj niaj regantoj transdonis lin por kondamno al morto, kaj lin krucumis."],[24,21,"Sed ni esperis, ke li estas tiu, kiu elaĉetos Izraelon. Kaj plie, krom ĉio tio, hodiaŭ estas jam la tria tago, de kiam tio okazis.","Sed ni esperis, ke li estas tiu, kiu elaĉetos Izraelon. Kaj plie, krom ĉio tio, hodiaŭ estas jam la tria tago, de kiam tio okazis."],[24,22,"Ankaŭ mirigis nin iuj virinoj el inter ni, kiuj estis frumatene apud la tombo,","Ankaŭ mirigis nin iuj virinoj el inter ni, kiuj estis frumatene apud la tombo,"],[24,23,"kaj ne trovinte lian korpon, revenis, dirante, ke ili ankaŭ vidis vizion de anĝeloj, kiuj diris, ke li vivas.","kaj ne trovinte lian korpon, revenis, dirante, ke ili ankaŭ vidis vizion de anĝeloj, kiuj diris, ke li vivas."],[24,24,"Kaj iuj el nia kunularo iris al la tombo, kaj trovis tiel, kiel diris la virinoj; sed lin ili ne vidis.","Kaj iuj el nia kunularo iris al la tombo, kaj trovis tiel, kiel diris la virinoj; sed lin ili ne vidis."],[24,25,"Kaj li diris al ili: Ho malsaĝuloj kaj kore malviglaj por kredi ĉion, kion la profetoj antaŭparolis!","Kaj li diris al ili: Ho malsaĝuloj kaj kore malviglaj por kredi ĉion, kion la profetoj antaŭparolis!"],[24,26,"Ĉu la Kristo ne devis suferi ĉion tion, kaj eniri en sian gloron?","Ĉu la Kristo ne devis suferi ĉion tion, kaj eniri en sian gloron?"],[24,27,"Kaj komencante de Moseo kaj de ĉiuj profetoj, li klarigis al ili el ĉiuj Skriboj la dirojn pri li mem.","Kaj komencante de Moseo kaj de ĉiuj profetoj, li klarigis al ili el ĉiuj Skriboj la dirojn pri li mem."],[24,28,"Kaj ili alproksimiĝis al la vilaĝo, kien ili iris, kaj li ŝajnigis al ili, kvazaŭ li pluen iros.","Kaj ili alproksimiĝis al la vilaĝo, kien ili iris, kaj li ŝajnigis al ili, kvazaŭ li pluen iros."],[24,29,"Kaj ili retenis lin, dirante: Restu ĉe ni, ĉar estas preskaŭ vespere, kaj la tago jam malkreskas. Kaj li eniris, por resti ĉe ili.","Kaj ili retenis lin, dirante: Restu ĉe ni, ĉar estas preskaŭ vespere, kaj la tago jam malkreskas. Kaj li eniris, por resti ĉe ili."],[24,30,"Kaj dum li sidis kun ili ĉe manĝo, li prenis panon, kaj ĝin benis kaj dispecigis kaj donis al ili.","Kaj dum li sidis kun ili ĉe manĝo, li prenis panon, kaj ĝin benis kaj dispecigis kaj donis al ili."],[24,31,"Kaj iliaj okuloj malfermiĝis, kaj ili rekonis lin, kaj li fariĝis nevidebla por ili.","Kaj iliaj okuloj malfermiĝis, kaj ili rekonis lin, kaj li fariĝis nevidebla por ili."],[24,32,"Kaj ili diris unu al alia: Ĉu nia koro ne brulis en ni, dum li parolis kun ni sur la vojo, dum li klarigis al ni la Skribojn?","Kaj ili diris unu al alia: Ĉu nia koro ne brulis en ni, dum li parolis kun ni sur la vojo, dum li klarigis al ni la Skribojn?"],[24,33,"Kaj leviĝinte en tiu sama horo, ili reiris al Jerusalem, kaj trovis la dek unu kunvenintaj, kun siaj kunuloj, kaj dirantaj:","Kaj leviĝinte en tiu sama horo, ili reiris al Jerusalem, kaj trovis la dek unu kunvenintaj, kun siaj kunuloj, kaj dirantaj:"],[24,34,"La Sinjoro vere leviĝis, kaj aperis al Simon.","La Sinjoro vere leviĝis, kaj aperis al Simon."],[24,35,"Kaj ili rakontis tion, kio okazis sur la vojo, kaj kiamaniere li rekoniĝis al ili en la dispecigo de pano.","Kaj ili rakontis tion, kio okazis sur la vojo, kaj kiamaniere li rekoniĝis al ili en la dispecigo de pano."],[24,36,"Kaj dum ili priparolis tion, li mem staris meze de ili, kaj diris al ili: Paco al vi.","Kaj dum ili priparolis tion, li mem staris meze de ili, kaj diris al ili: Paco al vi."],[24,37,"Sed terurite kaj timigite, ili supozis, ke ili vidas spiriton.","Sed terurite kaj timigite, ili supozis, ke ili vidas spiriton."],[24,38,"Kaj li diris al ili: Kial vi maltrankviliĝas? kaj kial diskutoj leviĝas en viaj koroj?","Kaj li diris al ili: Kial vi maltrankviliĝas? kaj kial diskutoj leviĝas en viaj koroj?"],[24,39,"Vidu miajn manojn kaj miajn piedojn, ke ĝi estas mi mem; palpu min kaj vidu; ĉar spirito ne havas karnon kaj ostojn, kiel vi vidas min havanta.","Vidu miajn manojn kaj miajn piedojn, ke ĝi estas mi mem; palpu min kaj vidu; ĉar spirito ne havas karnon kaj ostojn, kiel vi vidas min havanta."],[24,40,"Kaj tion dirinte, li montris al ili siajn manojn kaj siajn piedojn.","Kaj tion dirinte, li montris al ili siajn manojn kaj siajn piedojn."],[24,41,"Kaj dum ili ankoraŭ ne kredis pro ĝojo, kaj miris, li demandis ilin: Ĉu vi havas ian manĝaĵon ĉi tie?","Kaj dum ili ankoraŭ ne kredis pro ĝojo, kaj miris, li demandis ilin: Ĉu vi havas ian manĝaĵon ĉi tie?"],[24,42,"Kaj ili donis al li pecon de rostita fiŝo.","Kaj ili donis al li pecon de rostita fiŝo."],[24,43,"Kaj li prenis, kaj manĝis antaŭ ili.","Kaj li prenis, kaj manĝis antaŭ ili."],[24,44,"Kaj li diris al ili: Jen estas miaj vortoj, kiujn mi parolis al vi, kiam mi ankoraŭ estis ĉe vi, ke devas plenumiĝi ĉio, kio estas skribita pri mi en la leĝo de Moseo kaj en la profetoj kaj en la psalmoj.","Kaj li diris al ili: Jen estas miaj vortoj, kiujn mi parolis al vi, kiam mi ankoraŭ estis ĉe vi, ke devas plenumiĝi ĉio, kio estas skribita pri mi en la leĝo de Moseo kaj en la profetoj kaj en la psalmoj."],[24,45,"Tiam li malfermis ilian menson, por ke ili komprenu la Skribojn;","Tiam li malfermis ilian menson, por ke ili komprenu la Skribojn;"],[24,46,"kaj li diris al ili: Tiel estas skribite, ke la Kristo devas suferi, kaj leviĝi el la mortintoj la trian tagon;","kaj li diris al ili: Tiel estas skribite, ke la Kristo devas suferi, kaj leviĝi el la mortintoj la trian tagon;"],[24,47,"kaj ke pento kaj pardonado de pekoj estu predikataj en lia nomo al ĉiuj nacioj, komencante ĉe Jerusalem.","kaj ke pento kaj pardonado de pekoj estu predikataj en lia nomo al ĉiuj nacioj, komencante ĉe Jerusalem."],[24,48,"Vi estas atestantoj pri tio.","Vi estas atestantoj pri tio."],[24,49,"Kaj jen mi elsendos sur vin la promeson de mia Patro; sed restu en la urbo, ĝis vi vestiĝos per potenco de supre.","Kaj jen mi elsendos sur vin la promeson de mia Patro; sed restu en la urbo, ĝis vi vestiĝos per potenco de supre."],[24,50,"Kaj li elkondukis ilin ĝis apud Betania, kaj, levinte siajn manojn, li benis ilin.","Kaj li elkondukis ilin ĝis apud Betania, kaj, levinte siajn manojn, li benis ilin."],[24,51,"Kaj dum li benis ilin, li foriĝis de ili kaj estis suprenportita en la ĉielon.","Kaj dum li benis ilin, li foriĝis de ili kaj estis suprenportita en la ĉielon."],[24,52,"Kaj adorkliniĝinte al li, ili revenis al Jerusalem kun granda ĝojo;","Kaj adorkliniĝinte al li, ili revenis al Jerusalem kun granda ĝojo;"],[24,53,"kaj estis konstante en la templo, glorante Dion.","kaj estis konstante en la templo, glorante Dion."]]}};